/* 24 đề luyện thi TỐT NGHIỆP lấy NGUYÊN VĂN từ đề nguồn của giáo viên (20 đề «CUỐI NĂM» lớp 12 + 4 đề thi thử tốt nghiệp/khảo sát HK II chuyển từ danh sách HSG). Khoá = gạch chân / chữ Đúng-Sai trong ý / file ĐÁP ÁN; mức em đã tự giải lại ghi ở từng đề. BẢN NHÁP — chờ giáo viên duyệt. */
SC.data.de = SC.data.de || {};
SC.data.de.tn = [{"id": "TN-D01", "loai": "tn", "khoi": 12, "hoc_ki": 2, "so_de": 1, "ten": "Đề luyện thi tốt nghiệp số 1", "pham_vi": "Đề nguồn của giáo viên, giữ NGUYÊN chữ của đề (chỉ bỏ lỗi sao chép) · Thi thử 4, mã 100 · file nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm 4 lựa chọn + 4 câu đúng/sai (mỗi câu 4 ý)", "cham": {"tong": 10, "tn": 0.25, "ds": [0, 0.1, 0.25, 0.5, 1.0]}, "status": "cho_duyet", "khoa": {"đã giải lại, khớp khoá": 28}, "sua": "CẦN CÔ XEM (em chưa chắc, KHÔNG sửa khoá): (1) Câu 23: khoá B «Quyền kinh doanh», nhưng việc ghi chép đầy đủ sổ kế toán và báo cáo tài chính thường được xem là thực hiện NGHĨA VỤ (A) — em chưa chắc, giữ khoá của đề nguồn (gạch chân và file ĐÁP ÁN khớp nhau).", "cau": [{"id": "TN-D01-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong nền kinh tế xã hội, hoạt động đóng vai trò cơ bản nhất, quyết định các hoạt động khác của đời sống xã hội là hoạt động", "o": ["sản xuất", "phân phối.", "tiêu dùng", "trao đổi."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D01-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong sản xuất, chủ thể trung gian không có vai trò nào dưới đây ?", "o": ["Cầu nối giữa sản xuất và tiêu dùng.", "Phân phối hàng hóa đến tay người tiêu dùng.", "Thúc đẩy sản xuất và tiêu dùng hiệu quả", "Tạo ra sản phẩm hàng hóa cho người tiêu dùng."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx · Phần I câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D01-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong nền kinh tế nước ta, chủ thể nhà nước có vai trò quản lý toàn bộ nền kinh tế quốc dân thông qua việc thực hiện chức năng quản lý nhà nước về lĩnh vực nào dưới đây?", "o": ["Giáo dục.", "Kinh tế.", "Văn hóa.", "Xã hội."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D01-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chủ thể sản xuất là những người DH2", "o": ["phân phối hàng hóa, dịch vụ.", "hỗ trợ sản xuất hàng hóa, dịch vụ.", "trao đổi hàng hóa, dịch vụ.", "sản xuất ra hàng hóa, dịch vụ"], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx · Phần I câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D01-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong nền kinh tế, khi lạm phát ở mức độ phi mã thể hiện ở mức độ tăng của giá cả hàng hóa, dịch vụ từ", "o": ["một con số trở lên.", "hai con số trở lên.", "ba con số trở lên.", "bốn con số trở lên."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx · Phần I câu 5 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D01-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong nền kinh tế, căn cứ vào tính chất của thất nghiệp thì thất nghiệp được chia thành thất nghiệp tự nguyện và thất nghiệp", "o": ["tự giác.", "quyền lực.", "không tự nguyện.", "luôn bắt buộc."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx · Phần I câu 6 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D01-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nguyên nhân nào dưới đây là nguyên nhân khách quan dẫn đến người lao động có nguy cơ lâm vào tình trạng thất nghiệp?", "o": ["Bị cho nghỉ việc vì vi phạm kỉ luật.", "Cơ sở sản xuất kinh doanh đóng cửa", "Tự thôi việc do không hài lòng với mức lương.", "Bị thôi việc do thiếu kĩ năng làm việc."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D01-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong nền kinh tế, việc cơ quan quản lý phát hành thừa tiền trong lưu thông có thể là nguyên nhân gây ra hiện tượng", "o": ["lạm phát.", "thất nghiệp.", "cạnh tranh.", "khủng hoảng."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D01-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bất kỳ công dân nào nếu có đủ các điều kiện theo quy định của pháp luật đều bình đẳng về cơ hội học tập là thể hiện công dân bình đẳng về", "o": ["tập tục.", "quyền.", "trách nhiệm.", "nghĩa vụ."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D01-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật nam, nữ bình đẳng trong lĩnh vực kinh tế là đều được", "o": ["bầu cử.", "kinh doanh.", "khiếu nại.", "tố cáo."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D01-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tại thời điểm bầu cử đại biểu Hội đồng nhân dân các cấp, công dân vi phạm nghĩa vụ bầu cử khi", "o": ["nghiên cứu lí lịch ứng cử viên.", "kiểm tra niêm phong hòm phiếu.", "bỏ phiếu thay cử tri vắng mặt.", "giám sát hoạt động bầu cử."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D01-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không phản ánh đúng những dấu hiệu nhận diện một cơ hội kinh doanh tốt?", "o": ["Tính thời điểm.", "Tính ổn định.", "Tính hấp dẫn.", "Tính trừu tượng."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx · Phần I câu 12 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D01-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Yếu tố nào dưới đây là tiêu chí để đánh giá tính khả thi của một cơ hội kinh doanh?", "o": ["Tính nhân đạo.", "Tính hiệu quả.", "Tính phổ biến.", "Tính trìu tượng."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx · Phần I câu 13 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D01-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Anh K thành lập công ty trách nhiệm hữu hạn một thành viên với số vốn 5 tỷ đồng để kinh doanh vật liệu xây dựng. Trong quá trình hoạt động, anh đã ký kết và thực hiện hợp đồng cung ứng vật tư, vật liệu với nhiều đối tác. Công ty của anh K đã bị cơ quan thuế phát hiện không xuất hóa đơn bán hàng cho nhiều công trình nhằm trốn thuế. Trong trường hợp này, công ty của anh K đã vi phạm nghĩa vụ nào dưới đây về nộp thuế?", "o": ["Chấp hành quyết định kiểm tra thuế.", "Tôn trọng quyền nộp thuế của công dân.", "Kê khai nộp thuế đúng quy định.", "Giữ bí mật thông tin về nộp thuế."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D01-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chị M được bố mẹ tặng cho một mảnh đất để xây nhà và được cơ quan có thẩm quyền cấp giấy chứng nhận quyền sử dụng đất, giấy phép xây dựng nhà ở. Tuy nhiên, anh H là anh trai của chị khi biết chuyện đã bày tỏ thái độ bất mãn, phản đối việc làm của bố mẹ vì cho rằng mảnh đất đó là phần của mình, chị M là con gái nên không có quyền hưởng. Ngày chị M khởi công xây nhà, anh H đã dẫn theo một số người đến ngăn cản, đe dọa cấm chị tiếp tục xây dựng. Hành vi của anh H đã vi phạm qui định nào dưới đây của pháp luật về tài sản?", "o": ["Tôn trọng tài sản của người khác.", "Phá hoại tài sản của người khác.", "Sử dụng tài sản của người khác.", "Định đoạt tài sản của người khác."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D01-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong dịp nghỉ lễ 30/4 Anh T cho anh X thuê xe ô tô để đi du lịch. Tuy nhiên, đã quá thời hạn cho thuê xe mà anh X vẫn không trả xe. Khi biết tin anh X đã đem xe đi cầm cố tại tiệm cầm đồ trong thành phố, anh T liên lạc với anh X nhưng anh X không nghe điện thoại. Anh T nhiều lần đến nhà anh X để đòi xe nhưng đều không gặp được anh X. Hành vi cầm cố xe ô tô của anh X là vi phạm quyền nào dưới đây về tài sản?", "o": ["sở hữu tài sản.", "định đoạt tài sản.", "sử dụng tài sản.", "cho thuê tài sản."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D01-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 17, 18, 19\nBà N là Giám đốc Công ty trách nhiệm hữu hạn một thành viên T chuyên cung cấp dịch vụ du lịch và lưu trú. Trong điều hành công ty, bà N tự quyết định đối với toàn bộ hoạt động kinh doanh của công ty, từ việc tổ chức bộ máy hoạt động kinh doanh, đầu tư tài chính, kí hợp đồng bán các chương trình du lịch, tuyển nhân làm việc ở các bộ phận… Bà cũng quyết định sử dụng lợi nhuận sau thuế để mở rộng hoạt động kinh doanh, xây dựng thêm khu nghỉ dưỡng sử dụng vật liệu xanh. Để tăng vốn đầu tư, bà N đã chỉ đạo bộ phận kế toán của công ty không nhập sổ sách một số nguồn thu của doanh nghiệp, không tham gia bảo hiểm xã hội. Khi cơ quan thuế kiểm tra, phát hiện các sai phạm, đình chỉ hoạt động kinh doanh của công ty T 1 tháng và buộc khắc phục, nộp đủ số thuế thu nhập doanh nghiệp, bà N đã nghiêm chỉnh chấp hành yêu cầu của cơ quan thuế.\nBà N đã sử dụng quyền nào dưới đây của công dân về kinh doanh?", "o": ["Kinh doanh mặt hàng pháp luật không cấm.", "Khắc phục sai phạm trốn thuế trong kinh doanh.", "Chấp hành quyết định kiểm tra, thanh tra thuế.", "Chỉ đạo người lao động kê khai sai hồ sơ thuế."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D01-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 17, 18, 19\nBà N là Giám đốc Công ty trách nhiệm hữu hạn một thành viên T chuyên cung cấp dịch vụ du lịch và lưu trú. Trong điều hành công ty, bà N tự quyết định đối với toàn bộ hoạt động kinh doanh của công ty, từ việc tổ chức bộ máy hoạt động kinh doanh, đầu tư tài chính, kí hợp đồng bán các chương trình du lịch, tuyển nhân làm việc ở các bộ phận… Bà cũng quyết định sử dụng lợi nhuận sau thuế để mở rộng hoạt động kinh doanh, xây dựng thêm khu nghỉ dưỡng sử dụng vật liệu xanh. Để tăng vốn đầu tư, bà N đã chỉ đạo bộ phận kế toán của công ty không nhập sổ sách một số nguồn thu của doanh nghiệp, không tham gia bảo hiểm xã hội. Khi cơ quan thuế kiểm tra, phát hiện các sai phạm, đình chỉ hoạt động kinh doanh của công ty T 1 tháng và buộc khắc phục, nộp đủ số thuế thu nhập doanh nghiệp, bà N đã nghiêm chỉnh chấp hành yêu cầu của cơ quan thuế.\nBà N không vi phạm nghĩa vụ nào dưới đây trong kinh doanh du lịch và lưu trú?", "o": ["Bảo vệ quyền lợi người lao động.", "Bảo vệ tài nguyên, môi trường.", "Thực hiện pháp luật về thuế.", "Quyết định lợi nhuận thường niên."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D01-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 17, 18, 19\nBà N là Giám đốc Công ty trách nhiệm hữu hạn một thành viên T chuyên cung cấp dịch vụ du lịch và lưu trú. Trong điều hành công ty, bà N tự quyết định đối với toàn bộ hoạt động kinh doanh của công ty, từ việc tổ chức bộ máy hoạt động kinh doanh, đầu tư tài chính, kí hợp đồng bán các chương trình du lịch, tuyển nhân làm việc ở các bộ phận… Bà cũng quyết định sử dụng lợi nhuận sau thuế để mở rộng hoạt động kinh doanh, xây dựng thêm khu nghỉ dưỡng sử dụng vật liệu xanh. Để tăng vốn đầu tư, bà N đã chỉ đạo bộ phận kế toán của công ty không nhập sổ sách một số nguồn thu của doanh nghiệp, không tham gia bảo hiểm xã hội. Khi cơ quan thuế kiểm tra, phát hiện các sai phạm, đình chỉ hoạt động kinh doanh của công ty T 1 tháng và buộc khắc phục, nộp đủ số thuế thu nhập doanh nghiệp, bà N đã nghiêm chỉnh chấp hành yêu cầu của cơ quan thuế.\nMột trong các nghĩa vụ bà N phải thực hiện trong kinh doanh được đề cập ở thông tin trên là", "o": ["đảm bảo lợi ích hợp pháp của khách du lịch.", "tạo công ăn, việc làm cho người lao động.", "đóng góp quỹ phúc lợi xã hội.", "nộp thuế thu nhập doanh nghiệp."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D01-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Người kinh doanh phải tuân theo quy định của pháp luật và sự quản lí của Nhà nước về kinh doanh. Khi kinh doanh các mặt hàng như xăng dầu, hoá chất (trừ loại hoá chất cấm), rượu, thuốc lá phải đáp ứng các điều kiện mà pháp luật quy định. Ngành, nghề kinh doanh được đề cập trong thông tin là ngành, nghề nào dưới đây?", "o": ["Ngành, nghề kinh doanh có điều kiện.", "Ngành, nghề pháp luật cấm kinh doanh.", "Ngành, nghề không cho phép kinh doanh.", "Ngành, nghề kinh doanh không điều kiện."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx · Phần I câu 20 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D01-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nhà nước đã dành 21% ngân sách cho phúc lợi xã hội, là mức cao nhất trong số các nước ASEAN, nhờ đó đã cơ bản thực hiện thành công các mục tiêu, nhiệm vụ đặt ra. Thông qua chính sách hỗ trợ trực tiếp của Chính phủ và chính sách bảo hiểm xã hội, bảo hiểm thất nghiệp, đã hỗ trợ hơn 14,4 triệu người với tổng kinh phí hơn 33.000 tỷ đồng. Trong 5 năm qua, đời sống người có công không ngừng được nâng lên; hằng năm ngân sách Nhà nước dành hơn 32.000 tỷ đồng để thực hiện các chế độ ưu đãi người có công và thân nhân. Chính sách bảo hiểm xã hội, bảo hiểm y tế từng bước trở thành trụ cột chính trong hệ thống an sinh xã hội. Nội dung nào dưới đây trong thông tin trên thể hiện ý nghĩa của chính sách an sinh xã hội?", "o": ["Hỗ trợ bảo hiểm, bảo hiểm thất nghiệp.", "Dành 21% ngân sách cho phúc lợi xã hội.", "Đời sống người có công được nâng cao.", "Đưa bảo hiểm xã hội là trụ cột trong an sinh."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D01-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nước thành viên X đánh thuế nhập khẩu rất cao đối với rượu vang nhập khẩu từ các nước thành viên khác của WTO. Điều này khiến cho rượu vang nhập khẩu vào nước X không thể cạnh tranh được về giá cả so với rượu vang sản xuất trong nước. Trong trường hợp này, nước X đã vi phạm nguyên tắc cơ bản nào của WTO?", "o": ["Nguyên tắc thương mại công bằng.", "Nguyên tắc không phân biệt đối xử.", "Nguyên tắc minh bạch.", "Nguyên tắc mở cửa thị trường."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D01-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 23,24\nAnh P đăng kí thành lập công ty tư nhân XM, chuyên sản xuất hàng may mặc. Khi đăng kí thành lập công ty, anh kê khai đầy đủ nội dung hồ sơ đăng kí doanh nghiệp. Sau 5 năm hoạt động, công ty sản xuất, kinh doanh hiệu quả, mang lại lợi nhuận, nộp thuế, đóng góp vào ngân sách nhà nước, giải quyết việc làm, tăng thu nhập và thực hiện tốt chế độ cho người lao động ở địa phương. Trong suốt 5 năm qua, vốn và tài sản của công ty được sử dụng vào hoạt động kinh doanh luôn được ghi chép đầy đủ vào số kế toán và báo cáo tài chính của công ty. Sau khi cân nhắc, anh quyết định mở rộng kinh doanh thông qua việc tăng vốn và điều lệ và xem xét chuyển sang mô hình công ty cổ phần.\nHoạt động ghi chép đầy đủ vào sổ kế toán và báo cáo tài chính của công ty là thể hiện nội dung nào dưới đây của việc thực hiện quyền và nghĩa vụ của công dân về kinh doanh?", "o": ["Nghĩa vụ kinh doanh.", "Quyền kinh doanh.", "Trách nhiệm pháp lý.", "Trách nhiệm từ thiện."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D01-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 23,24\nAnh P đăng kí thành lập công ty tư nhân XM, chuyên sản xuất hàng may mặc. Khi đăng kí thành lập công ty, anh kê khai đầy đủ nội dung hồ sơ đăng kí doanh nghiệp. Sau 5 năm hoạt động, công ty sản xuất, kinh doanh hiệu quả, mang lại lợi nhuận, nộp thuế, đóng góp vào ngân sách nhà nước, giải quyết việc làm, tăng thu nhập và thực hiện tốt chế độ cho người lao động ở địa phương. Trong suốt 5 năm qua, vốn và tài sản của công ty được sử dụng vào hoạt động kinh doanh luôn được ghi chép đầy đủ vào số kế toán và báo cáo tài chính của công ty. Sau khi cân nhắc, anh quyết định mở rộng kinh doanh thông qua việc tăng vốn và điều lệ và xem xét chuyển sang mô hình công ty cổ phần.\nViệc nộp thuế và đóng góp đầy đủ vào ngân sách nhà nước là thể hiện trách nhiệm xã hội nào dưới đây của công ty XM?", "o": ["Trách nhiệm kinh tế.", "Trách nhiệm từ thiện.", "Trách nhiệm pháp lý.", "Trách nhiệm đạo đức."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D01-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Anh H thành lập công ty chuyên cung cấp vật liệu xây dựng cho các cửa hàng trong thành phố X. Ngay khi nhận được hợp đồng đầu tiên anh đã chủ động tìm hiểu thông tin về việc nộp thuế để thực hiện nghĩa vụ của mình. Anh H trực tiếp đến cơ quan thuế đề nghị hỗ trợ và được cán bộ cơ quan thuế cung cấp đầy đủ các thông tin liên quan đến quyền và nghĩa vụ nộp thuế. Sau khi nắm được thông tin, anh H đăng kí mã số thuế cá nhân, kê khai đầy đủ thông tin về thu nhập và nộp đủ số tiền thuế theo quy định của pháp luật. Thời gian sau đó, mỗi khi đến kì nộp thuế, anh H luôn chủ động khai thuế và nộp thuế đầy đủ, đúng hạn. Trong nhiều năm qua, công ty của anh còn thường xuyên thực hiện hoạt động quyên góp từ thiện giúp đỡ nhân dân các vùng gặp khó khăn, hoạn nạn ở địa phương.", "o": ["Anh H vừa thực hiện tốt nghĩa vụ kinh doanh vừa thực hiện tốt nghĩa vụ nộp thuế.", "Việc anh H được cung cấp đầy đủ các thông tin liên quan đến việc nộp thuế thể hiện cơ quan thuế đã thực hiện tốt nghĩa vụ của mình.", "Việc công ty thường xuyên hoạt động quyên góp từ thiện giúp đỡ nhân dân các vùng gặp khó khăn, hoạn nạn là thể hiện trách nhiệm pháp lí của công ty.", "Việc đăng ký mã số thuế của anh H là thực hiện quyền của công dân về nộp thuế."], "a": [true, true, false, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Sai.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx · Phần II câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D01-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Sau khi kết thúc 2 tháng thử việc của công nhân T, ông V chủ doanh nghiệp X liên tục đưa ra nhiều lí do khác nhau để trì hoãn việc kí hợp đồng và đóng bảo hiểm y tế, bảo hiểm xã hội cho anh T theo quy định của pháp luật. Sau khi nhiều lần anh T gửi đơn đề nghị doanh nghiệp thực hiện quy định của pháp luật, ông V kí hợp đồng rồi chuyển tiền đóng bảo hiểm xã hội của anh yêu cầu anh tự liên hệ để đóng nhưng anh T không đồng ý. Đồng thời, ông V cũng không đầu tư trang bị bảo hộ lao động cho các công nhân khác làm việc trong xưởng sản xuất để đảm bảo an toàn và sức khoẻ cho họ.", "o": ["Ông V vừa vi phạm quyền và nghĩa vụ của công dân trong bảo vệ, chăm sóc sức khỏe và đảm bảo an sinh xã hội.", "Người lao động trong công ty của ông V có quyền khiếu nại tới cơ quan chức năng để yêu cầu ông V bồi thường thiệt hại.", "Ông V chuyển trực tiếp số tiền phải đóng bảo hiểm xã hội cho anh T và yêu cầu anh T tự đóng là phù hợp với quy định của pháp luật.", "Ông V chưa thực hiện đúng trách nhiệm pháp lý và trách nhiệm từ thiện của doanh nghiệp."], "a": [true, false, false, false], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Sai.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx · Phần II câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D01-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Vợ chồng anh B, chị A cùng 2 con gái chung sống với mẹ đẻ của anh B là bà C làm giám đốc một công ty tư nhân. Do không ép được chị A sinh thêm con thứ 3 với hi vọng có được cháu trai, bà C đã bịa đặt chị A ngoại tình rồi gửi đơn ra tòa án đề nghị xem xét cho anh B li hôn vợ. Bức xúc với mẹ chồng, chị A đã bí mật rút tiền tiết kiệm của 2 vợ chồng rồi bỏ việc công ty của bà C về kinh doanh cùng mẹ đẻ của chị là bà H. Trong thời gian chị A đi vắng, được bà C hứa sẽ hỗ trợ một khoản tiền lớn, chị M nhân viên của bà C cũng vừa ly hôn đồng ý mang thai hộ cho anh B. Khi phát hiện mình đã có thai với anh B, chị M đã thông tin tới chị A và yêu cầu chị ly hôn để anh B kết hôn với chị và được chị A đồng ý. Sau khi biết chị gái mình ly hôn, anh Q là em trai chị A đã dùng hung khí uy hiếp và đánh anh B bị thương.", "o": ["Bà C có quyền đề nghị tòa án xem xét ly hôn cho anh B và chị A vì chị A đã vi phạm nghiêm trọng đời sống hôn nhân.", "Chị M mang thai hộ cho anh B nên không vi phạm quyền và nghĩa vụ của công dân trong hôn nhân và gia đình.", "Anh Q uy hiếp và đánh anh B bị thương là vi phạm quyền và nghĩa vụ trong quan hệ dân sự không phải quan hệ giữa các thành viên trong gia đình.", "Chị A rút tiền tiết kiệm của hai vợ chồng để kinh doanh là phù hợp."], "a": [false, false, true, false], "e": "Đáp án: a) Sai; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx · Phần II câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D01-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Công ty X chuyên sản xuất máy móc phục vụ cho nông nghiệp. Từ khi sản xuất kinh doanh có hiệu quả, công ty luôn chú trọng bảo vệ môi trường, thực hiện các biện pháp giảm lượng chất thải như rác, khói bụi, nước xả thải các chất thải rắn. Công ty còn hợp tác với tổ chức bảo tồn thiên nhiên quốc tế và Uỷ ban nhân dân tỉnh T để bảo tồn các vùng đất ngập nước tự nhiên và các môi trường sống khác. Công ty đầu tư xây dựng ba công trình công công cho cộng đồng, đáp ứng các tiêu chí công trình xanh, được công nhận là sản phẩm xanh.", "o": ["Biện pháp giảm chất thải, xử lý rác, khói bụi và chất thải rắn là phù hợp với trách nhiệm pháp lý mà mỗi doanh nghiệp phải thực hiện khi kinh doanh.", "Quá trình công ty hợp tác với các tổ chức bảo tồn thiên nhiên quốc tế là thể hiện hình thức hội nhâp kinh tế quốc tế.", "Hoạt động hợp tác với tổ chức quốc tế và chính quyền địa phương để bảo tồn vùng đất ngập nước tự nhiên là thể hiện trách nhiệm kinh tế của doanh nghiệp.", "Việc đóng góp xây dựng các công trình công cộng cho cộng đồng là việc làm phù hợp với trách nhiệm nhân văn của doanh nghiệp."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - THI THỬ 4 - MÃ 100.docx · Phần II câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}]}, {"id": "TN-D02", "loai": "tn", "khoi": 12, "hoc_ki": 2, "so_de": 2, "ten": "Đề luyện thi tốt nghiệp số 2", "pham_vi": "Đề nguồn của giáo viên, giữ NGUYÊN chữ của đề (chỉ bỏ lỗi sao chép) · mã 809, Bắc Giang · file nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm 4 lựa chọn + 4 câu đúng/sai (mỗi câu 4 ý)", "cham": {"tong": 10, "tn": 0.25, "ds": [0, 0.1, 0.25, 0.5, 1.0]}, "status": "cho_duyet", "khoa": {"đã giải lại, khớp khoá": 24, "1 nguồn": 4}, "sua": "Câu đúng/sai 1: khoá lấy từ file «ĐỀ SỐ 02» (cùng đoạn dẫn, cùng bốn ý, khoá gạch chân của giáo viên); file ĐÁP ÁN của đề này ghi toàn «S» nên không dùng. Câu đúng/sai 2: khoá lấy từ file «ĐỀ SỐ 02» (cùng đoạn dẫn, cùng bốn ý); file ĐÁP ÁN của đề này ghi toàn «S» nên không dùng. Câu đúng/sai 3: khoá lấy từ file «ĐỀ SỐ 02» (cùng đoạn dẫn, cùng bốn ý); file ĐÁP ÁN của đề này ghi toàn «S» nên không dùng. Câu đúng/sai 4: khoá lấy từ file «ĐỀ SỐ 02» (cùng đoạn dẫn, cùng bốn ý); file ĐÁP ÁN của đề này ghi toàn «S» nên không dùng. CẦN CÔ XEM (em chưa chắc, KHÔNG sửa khoá): (1) Câu 2 (trắc nghiệm): phương án B và D cùng ghi «Chủ tịch nước» (lỗi của đề nguồn); đáp án A «Quốc hội» không bị ảnh hưởng, em giữ nguyên chữ. (2) Bốn câu trắc nghiệm này cũng có ở file «810 Bắc Giang» / «ĐỀ SỐ 02» với khoá KHÁC khoá của đề 809; em giữ khoá 809 (gạch chân, khớp file ĐÁP ÁN) và chưa chắc dưới 80%: câu 14 (anh M khiếu nại: 809 ghi C «Tự mình khiếu nại», Đề số 02 ghi A «Cung cấp thông tin khiếu nại»), câu 19 (cấp phép thành lập doanh nghiệp âm nhạc: 809 ghi A «Kinh tế», Đề số 02 ghi B «Văn hóa»), câu 21 (không phải chỉ tiêu đánh giá phát triển kinh tế: 809 ghi B «Số năm đi học», 810 ghi D «Quy mô nền kinh tế»), câu 24 (ai vi phạm quyền và nghĩa vụ trong hôn nhân: 809 ghi C «Anh K», 810 ghi D «Anh K và bà Y»). (3) Bốn câu đúng/sai của đề này: file ĐÁP ÁN của đề 809 ghi toàn «S» (không phải khoá thật), nên khoá lấy từ «ĐỀ SỐ 02» có cùng đoạn dẫn và cùng ý; chưa có người đối chiếu thứ hai.", "cau": [{"id": "TN-D02-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không thể hiện vai trò của bảo hiểm đối với sự phát triển kinh tế - xã hội?", "o": ["Huy động vốn dài hạn.", "Ổn định tài chính cá nhân.", "Giảm lao động thất nghiệp.", "Thúc đẩy tín dụng đen."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D02-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của Hiến pháp 2013, cơ quan thực hiện quyền lập hiến và quyền lập pháp là", "o": ["Quốc Hội.", "Chủ tịch nước.", "Chính phủ.", "Chủ tịch nước."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx · Phần I câu 2 · khoá: file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D02-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không phải là nguyên nhân dẫn đến lạm phát?", "o": ["Chi phí sản xuất tăng lên.", "Thu nhập người dân tăng.", "Lượng tiền lưu thông tăng.", "Cầu có xu hướng tăng lên."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D02-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong nền kinh tế hàng hóa, khi thu nhập trung bình của người tiêu dùng tăng thì cầu về hàng hóa, dịch vụ sẽ có xu hướng", "o": ["không đổi.", "tăng.", "giảm.", "cân bằng."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx · Phần I câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D02-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Giữ gìn, bảo quản tài sản mượn, không được tự ý thay đổi tình trạng của tài sản; nếu tài sản bị hư hỏng thông thường thì phải sửa chữa là công dân đã thực hiện tốt nghĩa vụ nào dưới đây?", "o": ["Tôn trọng sở hữu trí tuệ người khác.", "Thực hiện quyền chiếm hữu tài sản.", "Tôn trọng tài sản của người khác.", "Thực hiện quyền định đoạt tài sản."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx · Phần I câu 5 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D02-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi tham gia ký kết các hợp đồng thương mại quốc tế, ngoài việc các chủ thể được tự do giao kết hợp đồng; các bên cần có thiện chí và trung thực cũng như phải", "o": ["ưu tiên các nước kém phát triển.", "tuân thủ hợp đồng đã giao kết.", "tôn trọng quyền của nước lớn.", "áp dụng quy chế đãi ngộ đặc biệt."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx · Phần I câu 6 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D02-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong nền kinh tế xã hội, chủ thể nào đóng vai trò là người mua hàng hóa, dịch vụ để thỏa nhu cầu cho sinh hoạt và sản xuất?", "o": ["Chủ thể tiêu dùng.", "Chủ thể nhà nước.", "Chủ thể sản xuất.", "Chủ thể trung gian."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D02-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào dưới đây là đúng về phát triển kinh tế?", "o": ["Muốn phát triển kinh tế chỉ cần thúc đẩy tăng trưởng kinh tế với tốc độ cao.", "Mục tiêu cuối cùng của phát triển kinh tế là xây dựng được cơ cấu kinh tế hiện đại.", "Phát triển kinh tế là quá trình tăng trưởng kinh tế gắn liền với tiến bộ xã hội.", "Phát triển kinh tế là quá trình biến đổi về lượng của nền kinh tế"], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D02-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hệ thống các chính sách can thiệp của Nhà nước và các lực lượng xã hội thực hiện nhằm giảm mức độ nghèo đói, nâng cao năng lực tự bảo vệ của người dân và xã hội trước những rủi ro hay nguy cơ giảm hoặc mất thu nhập, bảo đảm ổn định, phát triển và công bằng xã hội là nội dung của khái niệm nào dưới đây?", "o": ["Bảo hiểm xã hội.", "Thượng tầng xã hội.", "Chất lượng cuộc sống.", "An sinh xã hội."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D02-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Anh B viết bài đăng báo kiến nghị về tình trạng một số hộ kinh doanh không tuân thủ quy định bảo vệ môi trường. Việc làm của anh B là thực hiện quyền nào dưới đây của công dân?", "o": ["Quyền bảo đảm bí mật thư tín, điện thoại.", "Quyền tự do ngôn luận, tự do báo chí.", "Quyền được pháp luật bảo hộ về tính mạng, sức khỏe.", "Quyền được pháp luật bảo hộ về danh dự, nhân phẩm."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D02-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nhờ có pháp luật, Nhà nước có thể kiểm tra, kiểm soát hoạt động của cá nhân, tổ chức trong phạm vi lãnh thổ của mình từ đó giúp Nhà nước thực hiện chức năng", "o": ["gia tăng ngân sách.", "quản lý biên giới.", "mở rộng lãnh thổ.", "quản lý xã hội."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D02-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Những hoạt động lao động tạo ra thu nhập mà pháp luật không cấm là nội dung của khái niệm", "o": ["việc làm.", "thất nghiệp.", "sức lao động.", "lao động."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx · Phần I câu 12 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D02-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bất kì công dân nào đủ điều kiện theo quy định của pháp luật đều được", "o": ["sở hữu mọi tài sản công cộng.", "chia đều của cải trong xã hội.", "hưởng các quyền công dân.", "bài trừ quyền tự do tín ngưỡng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx · Phần I câu 13 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D02-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Cho rằng chính quyền xã X cố tình làm sai lệch kết quả đền bù giải phóng mặt bằng dự án đường cao tốc cho gia đình mình, anh M đã làm đơn khiếu nại tới cơ quan chức năng. Vì anh M không cung cấp đầy đủ thông tin liên quan đến khiếu nại nên cơ quan chức năng đã hủy đơn khiếu nại của anh M. Anh M đã thực hiện quyền khiếu nại ở nội dung nào dưới đây?", "o": ["Cung cấp thông tin khiếu nại.", "Khôi phục quyền lợi ban đầu.", "Tự mình khiếu nại.", "Ủy quyền khiếu nại."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D02-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mô hình sản xuất kinh doanh nào dưới đây do một cá nhân làm chủ và tự chịu trách nhiệm bằng toàn bộ tài sản của mình về mọi hoạt động của doanh nghiệp đó?", "o": ["Liên minh hợp tác xã.", "Công ty hợp danh.", "Công ty cổ phần", "Doanh nghiệp tư nhân."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D02-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quá trình liên kết hợp tác giữa các quốc gia trong một phạm vi không gian nhất định trên cơ sở tương đồng về địa lý, văn hóa, xã hội hoặc có chung mục tiêu, lợi ích phát triển là thể hiện hình thức hội nhập kinh tế quốc tế nào dưới đây?", "o": ["Hội nhập song phương.", "Hội nhập khu vực.", "Hội nhập toàn cầu.", "Hội nhập quốc gia."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D02-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những đặc điểm của ý tưởng kinh doanh là ý tưởng đó phải có", "o": ["tính nhân đạo.", "tính phi lợi nhuận.", "tính sáng tạo.", "tính xã hội."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D02-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, công dân có quyền bình đẳng về cơ hội học tập; có quyền được học", "o": ["bất kỳ ngành nghề nào.", "bất kỳ cơ sở nào.", "không phải đóng phí.", "không hạn chế."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D02-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc anh D và chị H đều được cơ quan có thẩm quyền cấp phép thành lập doanh nghiệp kinh doanh trong lĩnh vực hoạt động âm nhạc là thể hiện quyền bình đẳng giữa nam và nữ trong lĩnh vực nào dưới đây?", "o": ["Kinh tế.", "Văn hóa.", "Lao động.", "Chính trị."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D02-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 20, 21\nTheo số liệu của Tổng cục thống kê, từ năm 2002 – 2020, GDP bình quân đầu người của Việt Nam tăng 3,6 lần. Năm 2021, GDP/người đạt 3694 USD. Năm 2022, GDP của nước ta đạt 9,513 triệu tỉ đồng, tương đương 409 tỉ USD, quy mô nền kinh tế Việt Nam đã tăng hơn 10 lần so với năm 2000. Tăng trưởng kinh tế đã tạo tiền đề vật chất cho sự thay đổi chất lượng cuộc sống của người dân. Số năm đi học bình quân của người Việt Nam là 10,2 năm, đứng thứ hai chỉ sau Singapore theo xếp hạng của ASEAN. Chỉ số phát triển con người của Việt Nam là 0,69 trên thang cao nhất là 1, xếp hạng cao nhất trong các nền kinh tế có thu nhập trung bình thấp.\nTừ các số liệu trong thông tin trên, nhận định nào sau đây thể hiện mối quan hệ giữa tăng trưởng kinh tế với phát triển bền vững?", "o": ["Số năm đi học bình quân của người Việt Nam là 10,2 năm, đứng thứ hai trong khu vực ASEAN.", "Tăng trưởng kinh tế đã tạo tiền đề vật chất cho sự thay đổi chất lượng cuộc sống của người dân.", "Từ năm 2002 – 2020 GDP bình quân đầu người của Việt Nam tăng 3,6 lần.", "Quy mô nền kinh tế Việt Nam đã tăng hơn 10 lần so với năm 2000."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx · Phần I câu 20 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D02-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 20, 21\nTheo số liệu của Tổng cục thống kê, từ năm 2002 – 2020, GDP bình quân đầu người của Việt Nam tăng 3,6 lần. Năm 2021, GDP/người đạt 3694 USD. Năm 2022, GDP của nước ta đạt 9,513 triệu tỉ đồng, tương đương 409 tỉ USD, quy mô nền kinh tế Việt Nam đã tăng hơn 10 lần so với năm 2000. Tăng trưởng kinh tế đã tạo tiền đề vật chất cho sự thay đổi chất lượng cuộc sống của người dân. Số năm đi học bình quân của người Việt Nam là 10,2 năm, đứng thứ hai chỉ sau Singapore theo xếp hạng của ASEAN. Chỉ số phát triển con người của Việt Nam là 0,69 trên thang cao nhất là 1, xếp hạng cao nhất trong các nền kinh tế có thu nhập trung bình thấp.\nTrong thông tin trên, nội dung nào không phải là chỉ tiêu để đánh giá sự phát triển kinh tế?", "o": ["GDP bình quân trên đầu người.", "Số năm đi học của người dân.", "Chỉ số phát triển con người.", "Quy mô của nền kinh tế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D02-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22, 23,24\nVợ chồng anh K và chị P cùng con nhỏ một năm tuổi sống chung với mẹ chồng là bà Y đồng thời là giám đốc một doanh nghiệp tư nhân. Trong thời gian ở nhà một mình, chị P bị đối tượng trốn lệnh truy nã tên M uy hiếp buộc chị phải cho hắn ẩn nấp trong nhà chị. Do ghen tuông, lại bị bà Y xúi giục, anh K ép chị P phải kí vào đơn ly hôn. Vì chị P không đồng ý để anh K nuôi con, anh K nhờ bạn thân là anh X ghép ảnh phản cảm nhằm hạ uy tín của vợ trên mạng xã hội. Vốn có ý coi thường anh K và bà Y, sau khi có được những bằng chứng về việc bà Y ngoài việc sử dụng công nhân không thông qua ký kết hợp đồng lao động và thường xuyên cung cấp các thực phẩm không rõ nguồn gốc bán cho khách hàng, anh H em trai chị P đã làm đơn tố cáo tới cơ quan chức năng, khiến bà Y bị thiệt hại nặng.\nTheo quy định của pháp luật, bà Y đã thực hiện chưa đúng những nghĩa vụ nào dưới đây khi tiến hành hoạt động kinh doanh?", "o": ["Kinh doanh đúng ngành nghề đăng ký.", "Xâm phạm quyền lợi của người lao động và người tiêu dùng.", "Kê khai và nộp thuế không đúng hạn.", "Kinh doanh khi chưa có giấy phép và vi phạm quy địn thuế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D02-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22, 23,24\nVợ chồng anh K và chị P cùng con nhỏ một năm tuổi sống chung với mẹ chồng là bà Y đồng thời là giám đốc một doanh nghiệp tư nhân. Trong thời gian ở nhà một mình, chị P bị đối tượng trốn lệnh truy nã tên M uy hiếp buộc chị phải cho hắn ẩn nấp trong nhà chị. Do ghen tuông, lại bị bà Y xúi giục, anh K ép chị P phải kí vào đơn ly hôn. Vì chị P không đồng ý để anh K nuôi con, anh K nhờ bạn thân là anh X ghép ảnh phản cảm nhằm hạ uy tín của vợ trên mạng xã hội. Vốn có ý coi thường anh K và bà Y, sau khi có được những bằng chứng về việc bà Y ngoài việc sử dụng công nhân không thông qua ký kết hợp đồng lao động và thường xuyên cung cấp các thực phẩm không rõ nguồn gốc bán cho khách hàng, anh H em trai chị P đã làm đơn tố cáo tới cơ quan chức năng, khiến bà Y bị thiệt hại nặng.\nTrong quá trình sản xuất kinh doanh, bà Y đã vi phạm những loại trách nhiệm nào dưới đây?", "o": ["Trách nhiệm pháp lý và kinh tế.", "Trách nhiệm pháp lý và nhân văn.", "Trách nhiệm đạo đức và nhân văn.", "Trách nhiệm kinh tế và đạo đức."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D02-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22, 23,24\nVợ chồng anh K và chị P cùng con nhỏ một năm tuổi sống chung với mẹ chồng là bà Y đồng thời là giám đốc một doanh nghiệp tư nhân. Trong thời gian ở nhà một mình, chị P bị đối tượng trốn lệnh truy nã tên M uy hiếp buộc chị phải cho hắn ẩn nấp trong nhà chị. Do ghen tuông, lại bị bà Y xúi giục, anh K ép chị P phải kí vào đơn ly hôn. Vì chị P không đồng ý để anh K nuôi con, anh K nhờ bạn thân là anh X ghép ảnh phản cảm nhằm hạ uy tín của vợ trên mạng xã hội. Vốn có ý coi thường anh K và bà Y, sau khi có được những bằng chứng về việc bà Y ngoài việc sử dụng công nhân không thông qua ký kết hợp đồng lao động và thường xuyên cung cấp các thực phẩm không rõ nguồn gốc bán cho khách hàng, anh H em trai chị P đã làm đơn tố cáo tới cơ quan chức năng, khiến bà Y bị thiệt hại nặng.\nTrong thông tin trên những ai đã vi phạm quyền và nghĩa vụ của công dân trong quan hệ hôn nhân?", "o": ["Chị P.", "Anh K và chị P.", "Anh K.", "Anh K và bà Y."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D02-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Nước Y và nước P đã ký kết hiệp định thương mại từ nhiều năm trước và cả hai nước đều là thành viên của WTO. Trong một lần tàu X là tàu thương mại của nước Y đi qua lãnh hải của nước P không phải xin phép, trên cơ sở quyền qua lại vô hại. Đang đi theo tuyến hành lang mà nước P ấn định cho tàu thuyền nước ngoài, tàu X bỗng thay đổi hành trình, không đi theo tuyến đường ấn định nữa. Tại một khu vực khác trong lãnh hải nước P, tàu X dừng lại, chuyển xăng dầu buôn lậu từ tàu của mình sang hai tàu khác. Lực lượng cảnh sát biển nước P đã đuổi theo, bắt giữ tàu X cùng toàn bộ thuỷ thủ trên tàu. Tàu X được đưa vào bờ biển nước P để Xử lí vi phạm.", "o": ["Chỉ các nước có ký hiệp định thương mại với nhau thì tàu thuyền thương mại của hai nước này mới được đi vào khu vực lãnh hải của nhau.", "Nước Y có quyền khởi kiện lên tổ chức WTO để kiện nước P về hành vi bắt giữ tàu thương mại đã vi phạm nguyên tắc tự do hóa thương mại của WTO.", "Việc bắt giữ tàu X cùng toàn bộ thủy thủ tàu là phù hợp với quyền chủ quyền của quốc gia ven biển.", "Hiệp định thương mại giữa nước Y và nước P không phải là căn cứ để giải quyết vấn đề xâm phạm chủ quyền quốc gia giữa nước Y và nước P."], "a": [false, false, false, true], "e": "Đáp án: a) Sai; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx · Phần II câu 1 · khoá: KHOÁ: khoá lấy từ file «ĐỀ SỐ 02» (cùng đoạn dẫn, cùng bốn ý, khoá gạch chân của giáo viên); file ĐÁP ÁN của đề này ghi toàn «S» nên không dùng"}, {"id": "TN-D02-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Vợ chồng anh M và chị T là cán bộ công chức xã, sống cùng hai con là cháu H và cháu N trong đó cháu H hiện đang học lớp 12. Để chuẩn bị cho con vào học Đại học, anh chị đã quyết định mua một căn chung cư tại trung tâm thành phố. Trong thời gian chưa sử dụng, nhận thấy nhu cầu về thuê phòng trọ nguyên căn có xu hướng tăng cao, anh M đã cho một số sinh viên thuê làm nơi học tập vừa tăng thu nhập cho gia đình vừa đỡ chi phí trông coi bảo dưỡng. Do có niềm đam mê nấu ăn từ nhỏ, lại có kinh nghiệm nhiều năm trong lĩnh vực này, chị T đã làm và bán thực phẩm nấu chín nhờ đó đã góp phần bổ sung vào nguồn thu nhập của gia đình. Dù thu nhập ổn định nhưng anh chị luôn dành 50% số tiền thu nhập để tiết kiệm nhằm nuôi con cái ăn học và dự phòng những lúc cần thiết sau này.", "o": ["Nguồn thu nhập từ lương công chức xã là căn cứ để xác định nguồn thu nhập trong gia đình, còn thu nhập từ kinh doanh của anh M và chị T là thu nhập ngoài.", "Anh M đã phân tích các điều kiện thực hiện ý tưởng kinh doanh để từ đó đưa ra quyết định kinh doanh phù hợp.", "Dành 50% từ các nguồn thu nhập để tiết kiệm là không phù hợp với nguyên tắc phân chia các khoản thu chi trong kế hoạch tài chính gia đình.", "Lợi thế nội tại chính là yếu tố quyết định việc xây dựng và thực hiện kế hoạch kinh doanh của chị T."], "a": [false, true, false, true], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx · Phần II câu 2 · khoá: KHOÁ: khoá lấy từ file «ĐỀ SỐ 02» (cùng đoạn dẫn, cùng bốn ý); file ĐÁP ÁN của đề này ghi toàn «S» nên không dùng"}, {"id": "TN-D02-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Trên cùng địa bàn một huyện có anh D là chủ doanh nghiệp kinh doanh thức ăn chăn nuôi; anh K là giám đốc một công ty tư nhân. Để tăng vốn kinh doanh, anh K chỉ đạo chị P là kế toán kê khai không đầy đủ số tiền thuế phải nộp của công ty nên anh K đã bị cơ quan chức năng xử phạt. Nghi ngờ anh V là nhân viên tố cáo hành vi của mình, anh K cố tình trì hoãn đóng bảo hiểm xã hội cho anh V như đã cam kết. Bức xúc, anh V tự ý nghỉ việc ở công ty của anh K và sang làm việc cho anh D. Một lần chứng kiến anh D bị cơ quan chức năng xử phạt về hành vi cung cấp sản phẩm không đảm bảo đúng tiêu chuẩn đã công bố, anh V đã kể lại sự việc cho vợ mình là chị T. Sau đó chị T đã viết bài đăng lên mạng xã hội vu khống công ty anh D vi phạm Luật lao động không tổ chức khám sức khỏe định kỳ cho công nhân khiến uy tín của công ty bị ảnh hưởng.", "o": ["Hành vi cố tình không đóng bảo hiểm xã hội của anh K cho anh V là vi phạm quyền của công dân về đảm bảo an sinh xã hội.", "Chị P không vi phạm nghĩa vụ của công dân trong việc thực hiện pháp luật về thuế.", "Anh D và anh K đều phải chịu trách nhiệm pháp lý về hành vi vi phạm của mình trong kinh doanh.", "Anh D cung cấp sản phẩm không đảm bảo đúng tiêu chuẩn đã công bố là vi phạm trách nhiệm xã hội về pháp lý và kinh tế."], "a": [true, false, true, true], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx · Phần II câu 3 · khoá: KHOÁ: khoá lấy từ file «ĐỀ SỐ 02» (cùng đoạn dẫn, cùng bốn ý); file ĐÁP ÁN của đề này ghi toàn «S» nên không dùng"}, {"id": "TN-D02-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Kể từ khi chính thức gia nhập WTO, Việt Nam đã ghi nhận những thành tựu về phát triển kinh tế. Việt Nam trở thành nền kinh tế có độ mở cao, tới 200% GDP và cải thiện cán cân thương mại hàng hóa, chuyển từ nhập siêu sang xuất siêu trong giai đoạn 2016 - 2020. Đến năm 2020 nhiều hiệp định thương mại tự do song phương và đã phương đã có hiệu lực, thúc đẩy hoạt động xuất khẩu hàng hóa của nước ta ngày càng mở rộng. Theo Tổng cục Thống kê, từ năm 2016 đến năm 2022, cán cân thương mại của Việt Nam luôn đạt thặng dư với mức xuất siêu tăng dần qua các năm. Năm 2022, cán cân thương mại xuất siêu đạt 12,4 tỷ USD, là năm thứ 7 liên tiếp cán cân thương mại hàng hóa ở mức thặng dự mặc dù gặp nhiều khó khăn sau ảnh hưởng nặng nề của dịch bệnh COVID-19. Trở thành một trong 20 nền thương mại lớn nhất thế giới.", "o": ["Việt Nam gia nhập WTO là biểu hiện của hình thức hội nhập kinh tế quốc tế ở phạm vi toàn cầu.", "Khi gia nhập WTO cán cân thương mại của Việt Nam chuyển từ nhập siêu sang xuất siêu là vi phạm nguyên tắc cạnh tranh công bằng của WTO.", "Việt Nam trở thành một trong 20 nền thương mại lớn nhất thế giới thể hiện vai trò của hội nhập kinh tế quốc tế đối với sự phát triển của mỗi quốc gia.", "Gia nhập WTO chỉ giúp Việt Nam mở rộng về thị trường, muốn thu hút nguồn vốn đầu tư nước ngoài chúng ta phải hợp tác song phương."], "a": [true, false, true, false], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 809 - BẮC GIANG.docx · Phần II câu 4 · khoá: KHOÁ: khoá lấy từ file «ĐỀ SỐ 02» (cùng đoạn dẫn, cùng bốn ý); file ĐÁP ÁN của đề này ghi toàn «S» nên không dùng"}]}, {"id": "TN-D03", "loai": "tn", "khoi": 12, "hoc_ki": 2, "so_de": 3, "ten": "Đề luyện thi tốt nghiệp số 3", "pham_vi": "Đề nguồn của giáo viên, giữ NGUYÊN chữ của đề (chỉ bỏ lỗi sao chép) · mã 0821, Thanh Hóa · file nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm 4 lựa chọn + 4 câu đúng/sai (mỗi câu 4 ý)", "cham": {"tong": 10, "tn": 0.25, "ds": [0, 0.1, 0.25, 0.5, 1.0]}, "status": "cho_duyet", "khoa": {"đã giải lại, khớp khoá": 28}, "sua": "CẦN CÔ XEM (em chưa chắc, KHÔNG sửa khoá): (1) Câu 7 («công dân không thi hành pháp luật khi thực hiện hành vi nào»): đề này ghi khoá C «Xả thải trực tiếp ra môi trường», file lớp 10 «TN theo bài» ghi B «Công khai danh tính người mắc bệnh» — cả hai đều là hành vi bị cấm nên câu mơ hồ (đã ghi ở LENH-TIEP mục A1); giữ khoá của đề nguồn, cô quyết. (2) Câu 17 (cử tri độc lập lựa chọn người trong danh sách ứng cử): khoá C «Nghĩa vụ» — em chưa chắc, có thể là «Quyền»; giữ khoá của đề nguồn. (3) Câu đúng/sai 3 ý d (Tổng công ty M «thể hiện sự thống nhất trong nhận thức và hành động từ lãnh đạo đến nhân viên»): khoá Đ, nhưng thông tin không nêu — em chưa chắc, giữ khoá của đề nguồn.", "cau": [{"id": "TN-D03-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào sau đây không phản ánh chính sách dịch vụ xã hội cơ bản trong hệ thống an sinh xã hội ở nước ta?", "o": ["Dịch vụ giáo dục tối thiếu.", "Công tác văn hóa, thông tin.", "Dịch vụ việc làm tối thiếu.", "Dịch vụ y tế tối thiếu."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D03-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào sau đây là biểu hiện của đạo đức kinh doanh?", "o": ["nhân nhượng.", "tư lợi", "trách nhiệm.", "vô tư."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx · Phần I câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D03-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Pháp luật được đảm bảo thực hiện bằng", "o": ["quyền lực xã hội.", "quyền lực nhân dân.", "quyền lực chính trị.", "quyền lực nhà nước."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D03-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Vợ chồng anh D và chị H dự định năm tới sẽ mua nhà trên thành phố phục vụ việc học tập của các con, anh chị yêu cầu các thành viên trong gia đình đều có trách nhiệm chi tiêu hợp lý để thực hiện ý định trên. Anh D và chị H đã thực hiện nội dung nào sau đây của xây dựng kế hoạch quản lý thu chi trong gia đình?", "o": ["Thống nhất các khoản chi thiết yếu.", "Thực hiện các khoản thu, chi đã định.", "Xác định mục tiêu tài chính gia đình.", "Thống nhất các nguồn thu nhập cơ bản."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx · Phần I câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D03-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tiêu chí nào sau đây biểu thị thu nhập của nền kinh tế trong một thời kỳ nhất định được tính bằng tổng thu nhập từ hàng hóa, dịch vụ cuối cùng do công dân của quốc gia đó tạo ra trong một năm ?", "o": ["tổng thu nhập quốc dân trên đầu người.", "tổng thu nhập quốc dân (GNI).", "tổng thu nhập quốc nội (GDP).", "tổng thu nhập quốc nội trên đầu người."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx · Phần I câu 5 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D03-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chị Q mở một cửa hàng quần áo và cho rằng phong cách thời trang mà chị Q yêu thích thì khách hàng cũng sẽ thích. Việc làm của chị Q đã bỏ qua bước nào trong lập kế hoạch kinh doanh?", "o": ["Phân tích điều kiện thực hiện ý tưởng kinh doanh.", "Phân tích rủi ro tiềm ẩn và biện pháp xử lí.", "Xác định ý tưởng kinh doanh.", "Xác định kế hoạch tài chính."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx · Phần I câu 6 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D03-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, công dân không thi hành pháp luật khi thực hiện hành vi nào sau đây?", "o": ["Gửi đơn tố cáo hành vi vi phạm pháp luật.", "Công khai danh tính người mắc bệnh.", "Xả thải trực tiếp ra môi trường.", "Giao nộp người nhập cảnh trái phép."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D03-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những tác dụng to lớn của bình đẳng giới không thể hiện ở việc tạo điều kiện để nam và nữ", "o": ["ngày càng chênh lệch về trình độ.", "phát huy năng lực của mình.", "đóng góp vào sự phát triển của xã hội.", "hỗ trợ nhau trong đời sống gia đình."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D03-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào sau đây thể hiện vai trò của ngân sách nhà nước?", "o": ["tạo lập quỹ phòng chống thiên tai", "tạo lập quỹ dự trữ quốc gia .", "công cụ để đẩy mạnh xuất khẩu.", "công cụ để Nhà nước điều tiết thị trường."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D03-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc xây dựng ý tưởng kinh doanh rất cần thiết, giúp người kinh doanh xác định được những vấn đề cơ bản nào sau đây khi tiến hành hoạt động sản xuất kinh doanh?", "o": ["Hồ sơ kinh doanh.", "Cách thức kinh doanh.", "Phản hồi của khách hàng.", "Giá trị thặng dư sản phẩm."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D03-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi người lao động tham gia bảo hiểm thất nghiệp bị mất việc nếu đủ điều kiện họ sẽ được nhận quyền lợi nào sau đây?", "o": ["Tiền trợ cấp thất nghiệp.", "Lương hưu hàng tháng.", "Phí bảo hiểm đã đóng.", "Trợ cấp khám chữa bệnh."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D03-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát hiện chiếc xe đạp của mình bị mất cách đây 2 ngày trong sân nhà bà H, bà M cùng cháu gái của mình là Q xông vào nhà bà H để lấy về. Thấy bà M và Q tự vào nhà mình, bà H đã lớn tiếng mắng chửi rồi cùng con trai của mình là S khống chế bắt giữ Q nhốt vào nhà kho khiến cháu vô cùng hoảng loạn. Trong lúc giằng co, anh S vô tình đẩy bà M ngã bị gãy chân phải nhập viện điều trị. Biết chuyện, chồng bà M là ông X đã sang nhà bà H đập phá đồ đạc, giải cứu cháu Q rồi đưa vợ đi cấp cứu. Những ai sau đây vi phạm quyền bất khả xâm phạm về thân thể của công dân?", "o": ["Anh S và ông X.", "Ông X, bà H và anh S.", "Bà H, ông X và bà M.", "Anh S và bà H."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx · Phần I câu 12 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D03-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Doanh nghiệp hoạt động hiệu quả, có lợi nhuận, tạo ra việc làm có mức lương tương xứng là thể hiện hình thức trách nhiệm xã hội nào của doanh nghiệp?", "o": ["Đạo đức.", "Pháp lý.", "Kinh tế.", "Nhân văn."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx · Phần I câu 13 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D03-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong nền kinh tế xã hội, hoạt động đóng vai trò cơ bản nhất, quyết định các hoạt động khác của đời sống xã hội là hoạt động", "o": ["sản xuất", "tiêu dùng", "trao đổi.", "phân phối."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D03-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi hàng hóa và dịch vụ có mức tăng ở một con số điều đó thể hiện nền kinh tế lạm phát ở mức độ nào sau đây ?", "o": ["Lạm phát phi mã.", "Lạm phát vừa phải.", "Không đáng kể.", "Siêu lạm phát."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D03-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Ngày 25/12/2008, Việt Nam và Nhật Bản đã chính thức ký kết Hiệp định Đối tác Kinh tế Việt Nam - Nhật Bản, xét về cấp độ hợp tác đây là hình thức hợp tác", "o": ["toàn cầu.", "song phương.", "khu vực.", "châu lục."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D03-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong quá trình bầu cử Hội đồng nhân dân các cấp, cử tri được độc lập lựa chọn người trong danh sách ứng cử viên là thực hiện đúng nội dung nào sau đây của quyền và nghĩa vụ bầu cử?", "o": ["Quyền.", "Quyền và nghĩa vụ.", "Nghĩa vụ.", "Quyền và trách nhiệm."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D03-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đặc trưng cơ bản nào sau đây phản ánh sự cạnh tranh giữa các chủ thể kinh tế ?", "o": ["Tranh đua.", "Thỏa mãn.", "Thỏa hiệp.", "Ký kết."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D03-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, công dân bình đẳng về thực hiện nghĩa vụ khi thực hiện hành vi nào sau đây?", "o": ["Thay đổi địa bàn cư trú.", "Nộp hồ sơ xin cấp phép kinh doanh.", "Thống nhất địa điểm cư trú.", "Thành lập quỹ bảo trợ xã hội."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D03-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 20, 21\nTheo Cổng thông tin điện tử Quốc hội Việt Nam ngày 09/ 11/ 2023. Tại kì họp thứ 6, Quốc hội khóa XV đã biểu quyết thông qua Nghị quyết về Kế hoạch phát triển kinh tế - xã hội năm 2024, theo đó các chỉ tiêu chủ yếu, gồm: Tốc độ tăng tổng sản phẩm trong nước khoảng 6% - 6,5%; GDP bình quân đầu người đạt khoảng 4.700 - 4.730 USD.\nTỉ trọng công nghiệp chế biến, chế tạo trong GDP đạt khoảng 24,1%  - 24,2% . Tốc độ tăng năng suất lao động xã hội bình quân khoảng 4,8% - 5,3%. Tỉ trọng lao động nông nghiệp trong tổng lao động xã hội đạt 26,5%. Tỉ lệ lao động qua đào tạo đạt 69%, trong đó có bằng, chứng chỉ đạt khoảng 28,5%. Tỉ lệ thất nghiệp ở khu vực thành thị dưới 4%. Ti lệ hộ nghèo (theo chuẩn nghèo đa chiều) giảm trên 1%.\nCác chỉ tiêu: tỉ lệ thất nghiệp ở khu vực thành thị dưới 4%, tỉ lệ hộ nghèo (theo chuẩn nghèo đa chiều) giảm trên 1% thuộc chỉ tiêu nào của phát triển kinh tế?", "o": ["Chuyển dịch cơ cấu ngành kinh tế.", "Tổng thu nhập quốc dân bình quân đầu người.", "Tổng thu nhập quốc dân.", "Chỉ tiêu về tiến bộ xã hội."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx · Phần I câu 20 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D03-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 20, 21\nTheo Cổng thông tin điện tử Quốc hội Việt Nam ngày 09/ 11/ 2023. Tại kì họp thứ 6, Quốc hội khóa XV đã biểu quyết thông qua Nghị quyết về Kế hoạch phát triển kinh tế - xã hội năm 2024, theo đó các chỉ tiêu chủ yếu, gồm: Tốc độ tăng tổng sản phẩm trong nước khoảng 6% - 6,5%; GDP bình quân đầu người đạt khoảng 4.700 - 4.730 USD.\nTỉ trọng công nghiệp chế biến, chế tạo trong GDP đạt khoảng 24,1%  - 24,2% . Tốc độ tăng năng suất lao động xã hội bình quân khoảng 4,8% - 5,3%. Tỉ trọng lao động nông nghiệp trong tổng lao động xã hội đạt 26,5%. Tỉ lệ lao động qua đào tạo đạt 69%, trong đó có bằng, chứng chỉ đạt khoảng 28,5%. Tỉ lệ thất nghiệp ở khu vực thành thị dưới 4%. Ti lệ hộ nghèo (theo chuẩn nghèo đa chiều) giảm trên 1%.\nNội dung nào sau đây phản ánh chỉ tiêu tăng trưởng kinh tế?", "o": ["Tỉ lệ thất nghiệp ở khu vực thành thị dưới 4%.", "Tổng sản phẩm quốc nội bình quân đầu người đạt khoảng 4.700 - 4.730 USD", "Tỉ trọng công nghiệp chế biến, chế tạo trong GDP đạt khoảng 24,1%-24,2%", "Tỉ trọng lao động nông nghiệp trong tổng lao động xã hội đạt 26,5%."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D03-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22, 23, 24\nLà một doanh nghiệp nhỏ ngành dệt may ở một xã thuần nông, doanh nghiệp V đã cung ứng cho thị trường nhiều sản phẩm có chất lượng cao, thân thiện với môi trường. Công ty đã thu hút được những lao động là thanh niên trong xã, đào tạo họ trở thành những người thợ lành nghề, có việc làm và thu nhập ổn định. Hằng năm, doanh nghiệp còn hỗ trợ kinh phí cho học sinh có hoàn cảnh đặc biệt khó khăn trong xã được đi học đại học, tham gia nhiều hoạt động cộng đồng trong xã. Bên cạnh đó công ty rất quan tâm đến đời sống người lao động, ngoài việc thực hiện tốt các chế độ theo quy định, công ty còn chủ động tìm các nguồn kinh phí hợp pháp để hỗ trợ người lao động gặp khó khăn ổn định cuộc sống. Nhờ vậy, uy tín của doanh nghiệp đối với khách hàng, người lao động và xã hội ngày càng tăng, công việc kinh doanh ngày càng phát triển. Năm qua doanh nghiệp được cơ quan thuế tặng bằng khen vì thành tích thực hiện tốt nghĩa vụ nộp thuế trên địa bàn.\nViệc hỗ trợ kinh phí cho học sinh có hoàn cảnh đặc biệt khó khăn trong xã được đi học đại học và tham gia các hoạt động cộng đồng trong xã là thể hiện trách nhiệm xã hội nào sau đây của doanh nghiệp?", "o": ["Trách nhiệm kinh tế.", "Trách nhiệm pháp lý.", "Trách nhiệm địa phương.", "Trách nhiệm nhân văn."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D03-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22, 23, 24\nLà một doanh nghiệp nhỏ ngành dệt may ở một xã thuần nông, doanh nghiệp V đã cung ứng cho thị trường nhiều sản phẩm có chất lượng cao, thân thiện với môi trường. Công ty đã thu hút được những lao động là thanh niên trong xã, đào tạo họ trở thành những người thợ lành nghề, có việc làm và thu nhập ổn định. Hằng năm, doanh nghiệp còn hỗ trợ kinh phí cho học sinh có hoàn cảnh đặc biệt khó khăn trong xã được đi học đại học, tham gia nhiều hoạt động cộng đồng trong xã. Bên cạnh đó công ty rất quan tâm đến đời sống người lao động, ngoài việc thực hiện tốt các chế độ theo quy định, công ty còn chủ động tìm các nguồn kinh phí hợp pháp để hỗ trợ người lao động gặp khó khăn ổn định cuộc sống. Nhờ vậy, uy tín của doanh nghiệp đối với khách hàng, người lao động và xã hội ngày càng tăng, công việc kinh doanh ngày càng phát triển. Năm qua doanh nghiệp được cơ quan thuế tặng bằng khen vì thành tích thực hiện tốt nghĩa vụ nộp thuế trên địa bàn.\nDanh hiệu thực hiện tốt nghĩa vụ nộp thuế mà công ty đạt được phản ánh việc thực hiện tốt trách nhiệm nào sau đây của doanh nghiệp?", "o": ["Trách nhiệm pháp lý.", "Trách nhiệm đạo đức.", "Trách nhiệm kinh tế.", "Trách nhiệm nhân văn."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D03-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22, 23, 24\nLà một doanh nghiệp nhỏ ngành dệt may ở một xã thuần nông, doanh nghiệp V đã cung ứng cho thị trường nhiều sản phẩm có chất lượng cao, thân thiện với môi trường. Công ty đã thu hút được những lao động là thanh niên trong xã, đào tạo họ trở thành những người thợ lành nghề, có việc làm và thu nhập ổn định. Hằng năm, doanh nghiệp còn hỗ trợ kinh phí cho học sinh có hoàn cảnh đặc biệt khó khăn trong xã được đi học đại học, tham gia nhiều hoạt động cộng đồng trong xã. Bên cạnh đó công ty rất quan tâm đến đời sống người lao động, ngoài việc thực hiện tốt các chế độ theo quy định, công ty còn chủ động tìm các nguồn kinh phí hợp pháp để hỗ trợ người lao động gặp khó khăn ổn định cuộc sống. Nhờ vậy, uy tín của doanh nghiệp đối với khách hàng, người lao động và xã hội ngày càng tăng, công việc kinh doanh ngày càng phát triển. Năm qua doanh nghiệp được cơ quan thuế tặng bằng khen vì thành tích thực hiện tốt nghĩa vụ nộp thuế trên địa bàn.\nViệc làm nào sau đây của doanh nghiệp V không thể hiện trách nhiệm kinh tế của doanh nghiệp khi tiến hành sản xuất, kinh doanh?", "o": ["Sản xuất sản phẩm thân thiện với môi trường.", "Giải quyết việc làm cho lao động địa phương.", "Cung cấp các sản phẩm có chất lượng cao.", "Hỗ trợ kinh phí cho học sinh theo học đại học."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D03-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Theo Báo cáo Phát triển bền vững của Nielsen (2017), 86% người tiêu dùng Việt Nam sẵn sàng chi trả cao hơn để mua sản phẩm, dịch vụ từ các công ty có ảnh hưởng tích cực đến xã hội và môi trường. Khảo sát của National Forest (2017) cho thấy 81% khách hàng lựa chọn sản phẩm bảo vệ môi trường và 73% người lao động trung thành với ông chủ tham gia các hoạt động từ thiện.", "o": ["Người điều hành doanh nghiệp phải đối mặt với thách thức khi vừa phải đảm bảo kinh doanh có lãi vừa phải đáp ứng kì vọng của người tiêu dùng.", "73% người lao động sẽ trung thành với ông chủ tích cực tham gia các hoạt động từ thiện là vì doanh nghiệp đã thực hiện tốt trách nhiệm kinh tế.", "Doanh nghiệp chỉ tập trung vào lợi nhuận, bỏ qua các tác động tiêu cực đến môi trường sẽ không thể duy trì được lòng tin và sự trung thành của khách hàng.", "Việc người tiêu dùng sẵn sàng chỉ trả cao hơn để mua sản phẩm, dịch vụ từ các doanh nghiệp thực hiện tốt trách nhiệm xã hội sẽ giúp mọi doanh nghiệp kinh doanh có lãi."], "a": [true, false, true, false], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx · Phần II câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D03-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Một doanh nghiệp nhỏ phân tích điều kiện thực hiện ý tưởng kinh doanh thực phẩm hữu cơ. Qua khảo sát thị trường, sản phẩm, khách hàng và các đối thủ cạnh tranh cho thấy: Xu hướng của người tiêu dùng ở khu vực này đang quan tâm đến việc ăn uống lành mạnh và thực phẩm hữu cơ. Thị trường ở đây đã có một vài doanh nghiệp kinh doanh thực phẩm, nhưng chưa có doanh nghiệp nào tập trung hoàn toàn vào thực phẩm hữu cơ.", "o": ["Khi xác định ý tưởng kinh doanh chỉ cần lưu ý đến vấn đề tài chính.", "Thông tin nói về ý tưởng kinh doanh thực phẩm hữu cơ.", "Xu hướng tiêu dùng là một trong những cơ sở để xác định ý tưởng kinh doanh.", "Trong khu vực chưa có doanh nghiệp tập trung vào sản phẩm hữu cơ là lợi thế cạnh tranh của sản phẩm."], "a": [false, true, true, true], "e": "Đáp án: a) Sai; b) Đúng; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx · Phần II câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D03-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Hiện nay, các doanh nghiệp không chỉ kinh doanh đơn thuần mà phải hướng đến kinh doanh có trách nhiệm, hướng đến tăng trưởng bền vững. Việc Việt Nam tham gia sâu vào các hiệp định thương mại tự do mở ra cơ hội rất lớn song cũng đặt ra yêu cầu, doanh nghiệp phải biết tận dụng và am hiểu các tiêu chuẩn, hàng rào kĩ thuật, sản xuất xanh. Đáp ứng yêu cầu xuất khẩu, ông V (Tổng Giám đốc Tổng Công ty M) cho biết, đến năm 2026. Tổng Công ty đặt mục tiêu chuyển đổi sử dụng nguyên liệu có nguồn gốc tự nhiên, nguyên liệu tái chế, nhằm đáp ứng sản xuất xanh và tuần hoàn, để bắt kịp xu thế mà các nhà nhập khẩu từ châu Âu hay Mỹ, Nhật Bản yêu cầu.", "o": ["Tổng Giám đốc Tổng Công ty M đặt mục tiêu chuyển đổi sử dụng nguyên liệu có nguồn gốc tự nhiên, nguyên liệu tái chế đã thực hiện tốt chủ trương của Đảng và Nhà nước về phát triển bền vững.", "Việc Việt Nam tham gia sâu vào các hiệp định thương mại tự do thuộc hình thức hội nhập ở mức độ song phương.", "Hội nhập kinh tế quốc tế là một trong những động lực quan trọng để các doanh nghiệp nghiên cứu ứng dụng các tiêu chuẩn, hàng rào kĩ thuật, sản xuất xanh nhằm hướng tới tăng trưởng và phát triển bền vững.", "Tổng Công ty M đặt mục tiêu đến năm 2026 chuyển đổi sử dụng nguyên liệu có nguồn gốc tự nhiên, nguyên liệu tái chế thể hiện sự thống nhất trong nhận thức và hành động từ lãnh đạo đến nhân viên công ty."], "a": [true, false, true, true], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx · Phần II câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D03-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Trước những thách thức lớn vì cạnh tranh trong hội nhập, tác động của cuộc Cách mạng 4.0, cũng như xu hướng già hóa dân số và tác động của biến đổi khí hậu, dịch bệnh... Việt Nam đang tích cực nâng cao hiệu quả hoạt động của hệ thống an sinh xã hội vì mục tiêu phát triển con người. Tại Việt Nam, hệ thống an sinh xã hội được hình thành từ các trụ cột cơ bản, bao gồm: giảm nghèo bền vững, đào tạo nghề, lao động, việc làm, bảo hiểm xã hội và các loại bảo hiểm khác, bảo trợ xã hội và các dịch vụ xã hội cơ bản. Mô hình an sinh xã hội của Việt Nam đã đem lại những thành quả đáng khích lệ, được thể giới công nhận như thành tích xoá đói, giảm nghèo, giáo dục, y tế, thể hiện rõ quan điểm tăng trưởng kinh tế gắn liền với sự tiến bộ và công bằng xã hội.", "o": ["Các thành tựu về an sinh xã hội ở Việt Nam thể hiện mối quan hệ giữa tăng trưởng kinh tế và sự phát triển bền vững.", "Các trụ cột của hệ thống an sinh xã hội ở Việt Nam nhằm thực hiện ba chức năng: phòng ngừa rủi ro, giảm thiểu rủi ro và khắc phục rủi ro.", "An sinh xã hội là sự che chắn, bảo vệ cho các thành viên trong xã hội trước các thách thức trong cuộc sống như già hoá dân số, biến đổi khí hậu, dịch bệnh...", "Bảo hiểm thất nghiệp không phải là một thành phần của hệ thống an sinh xã hội."], "a": [true, true, true, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 0821 - THANH HÓA.docx · Phần II câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}]}, {"id": "TN-D04", "loai": "tn", "khoi": 12, "hoc_ki": 2, "so_de": 4, "ten": "Đề luyện thi tốt nghiệp số 4", "pham_vi": "Đề nguồn của giáo viên, giữ NGUYÊN chữ của đề (chỉ bỏ lỗi sao chép) · mã 1003, Bến Tre · file nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm 4 lựa chọn + 4 câu đúng/sai (mỗi câu 4 ý)", "cham": {"tong": 10, "tn": 0.25, "ds": [0, 0.1, 0.25, 0.5, 1.0]}, "status": "cho_duyet", "khoa": {"đã giải lại, khớp khoá": 28}, "sua": "Câu đúng/sai 4: file ĐÁP ÁN ghi ĐĐSS, gạch chân đọc ra khác vì ý a dính vào đoạn dẫn; em giải lại theo SGK cũng ra ĐĐSS. Bỏ dòng dẫn nguồn web («Theo https://…») dính cuối đoạn thông tin ở 3 câu (lỗi sao chép; chữ còn lại giữ nguyên). CẦN CÔ XEM (em chưa chắc, KHÔNG sửa khoá): (1) Câu 6 (đoạn thông tin về CPI): khoá A «chỉ số giá tiêu dùng tăng» — CPI tăng là biểu hiện chứ không phải nguyên nhân, đoạn thông tin cũng không nêu nguyên nhân nào; câu có vẻ khuyết, em giữ khoá của đề nguồn. (2) Câu đúng/sai 1 ý c và ý d: hai ý cùng cấu trúc («vì họ không tham gia BHXH») nhưng khoá khác nhau (c Sai, d Đúng) và đoạn thông tin chỉ nói doanh nghiệp chậm đóng BHXH — em chưa chắc ý d, giữ khoá của đề nguồn.", "cau": [{"id": "TN-D04-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, công dân thực hiện quyền tự do ngôn luận khi thực hiện hành vi nào dưới đây?", "o": ["Xúc phạm nhằm hạ uy tín người khác.", "Tham gia phát biểu ý kiến tại cuộc họp.", "Truy tìm các đối tượng phản động.", "Viết bài nói xấu người khác đăng trên báo."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D04-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, cơ quan nhà nước có thẩm quyền vi phạm quyền được pháp luật bảo hộ về tính mạng, sức khỏe của công dân khi thực hiện hành vi nào sau đây?", "o": ["Áp giải bị cáo.", "Hành hung bị can.", "Thay đổi cáo trạng", "Giam giữ bị can."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx · Phần I câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D04-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Vợ, chồng có nghĩa vụ tôn trọng, giữ gìn nhân phẩm và danh dự của nhau là thể hiện quyền bình đẳng trong hôn nhân và gia đình ở mối quan hệ nào?", "o": ["Huyết thống.", "Tài sản.", "Nhân thân.", "Tín ngưỡng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D04-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đâu là sai lầm thường mắc phải trong quá trình lập kế hoạch thu, chi trong gia đình?", "o": ["Liệt kê các nguồn thu trong gia đình.", "Cứng nhắc khi thực hiện kế hoạch.", "Xác định mục tiêu tài chính trong gia đình.", "Thực hiện các khoản thu chi theo kế hoạch."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx · Phần I câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D04-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 5, 6\nChỉ số giá tiêu dùng (CPI) tháng 9/2024 tăng 0,29% so với tháng trước. So với tháng 12/2023, CPI tháng 9 tăng 2,18% và so với cùng kỳ năm trước tăng 2,63%. CPI bình quân quý III/2024 tăng 3,48% so với quý III/2023. Tính chung 9 tháng năm nay, CPI tăng 3,88% so với cùng kỳ năm trước; lạm phát cơ bản tăng 2,69%. (Báo cáo tình hình kinh tế - xã hội tháng 9 và 9 tháng năm 2024 của Tổng cục Thống kê)\nLạm phát cơ bản tăng 2,69% trong 9 tháng của năm 2024 thuộc loại lạm phát nào dưới đây?", "o": ["Lạm phát nghiêm trọng.", "Siêu lạm phát.", "Lạm phát vừa phải.", "Lạm phát phi mã."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx · Phần I câu 5 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D04-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 5, 6\nChỉ số giá tiêu dùng (CPI) tháng 9/2024 tăng 0,29% so với tháng trước. So với tháng 12/2023, CPI tháng 9 tăng 2,18% và so với cùng kỳ năm trước tăng 2,63%. CPI bình quân quý III/2024 tăng 3,48% so với quý III/2023. Tính chung 9 tháng năm nay, CPI tăng 3,88% so với cùng kỳ năm trước; lạm phát cơ bản tăng 2,69%. (Báo cáo tình hình kinh tế - xã hội tháng 9 và 9 tháng năm 2024 của Tổng cục Thống kê)\nNguyên nhân chủ yếu làm cho lạm phát tăng trong đoạn thông tin trên là", "o": ["chỉ số giá tiêu dùng tăng.", "sản xuất kinh doanh của các doanh nghiệp tăng.", "sự khủng hoảng của kinh tế - xã hội.", "giá nguyên vật liệu tăng."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx · Phần I câu 6 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D04-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tự tiện bóc mở, thu giữ, tiêu hủy thư tín của người khác là xâm phạm quyền nào dưới đây của công dân?", "o": ["Quyền được đảm bảo an toàn nơi cư trú của công dân.", "Quyền bất khả xâm phạm về thân thể của công dân.", "Quyền đảm bảo an toàn thư tín, điện thoại, điện tín.", "Quyền bất khả xâm phạm về chỗ ở của công dân."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D04-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Kế hoạch kinh doanh không bao gồm nội dung nào sau đây?", "o": ["Nâng cao năng lực cạnh tranh với các chủ thể kinh tế khác.", "Xác định được định hướng, ý tưởng kinh doanh.", "Các điều kiện thực hiện hoạt động kinh doanh.", "Kế hoạch hoạt động; rủi ro tiềm ẩn và biện pháp xử lý."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D04-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin sau và trả lời các câu hỏi 9, 10\nThị trường sữa Việt Nam ngày càng đa dạng về loại hình sản phẩm, từ sữa thực vật và các sản phẩm sữa kết hợp với các nguyên liệu khác như trái cây, ngũ cốc, rau củ, thảo mộc sữa bột, sữa tươi, sữa đặc, sữa chua, đến các sản phẩm sữa chức năng, sữa hữu cơ, sữa không lactose, ...Thực tế hiện nay, sự đa dạng của doanh nghiệp cùng nhu cầu tiêu dùng tăng cao đã dẫn đến sự cạnh tranh khốc liệt trên thị trường sữa, thậm chí là cạnh tranh không lành mạnh. Một số doanh nghiệp có dấu hiệu lợi dụng \"truyền thông bẩn\" để tấn công đối thủ nhằm chiếm thị phần với nhiều cách thức khác nhau như đưa thông tin sai, phiến diện chưa được kiểm chứng, nhắc đi nhắc lại những lỗi sai dù đã bị xử lý...\nMột trong những nguyên nhân dẫn đến hiện tượng cạnh tranh giữa các doanh nghiệp sữa là do có sự khác nhau về", "o": ["hệ thống khách hàng sữa.", "chính sách tiếp thị.", "sự tồn tại nhiều hãng sữa.", "chính sách đầu tư."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D04-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin sau và trả lời các câu hỏi 9, 10\nThị trường sữa Việt Nam ngày càng đa dạng về loại hình sản phẩm, từ sữa thực vật và các sản phẩm sữa kết hợp với các nguyên liệu khác như trái cây, ngũ cốc, rau củ, thảo mộc sữa bột, sữa tươi, sữa đặc, sữa chua, đến các sản phẩm sữa chức năng, sữa hữu cơ, sữa không lactose, ...Thực tế hiện nay, sự đa dạng của doanh nghiệp cùng nhu cầu tiêu dùng tăng cao đã dẫn đến sự cạnh tranh khốc liệt trên thị trường sữa, thậm chí là cạnh tranh không lành mạnh. Một số doanh nghiệp có dấu hiệu lợi dụng \"truyền thông bẩn\" để tấn công đối thủ nhằm chiếm thị phần với nhiều cách thức khác nhau như đưa thông tin sai, phiến diện chưa được kiểm chứng, nhắc đi nhắc lại những lỗi sai dù đã bị xử lý...\nTrong sản xuất và kinh doanh cửa hàng sữa, nội dung nào dưới đây không phản ánh mặt tích cực của cạnh tranh?", "o": ["Thông tin sai lệch về sản phẩm sữa.", "Sự đa dạng của doanh nghiệp sữa.", "Giành nguồn nguyên nhiên vật liệu.", "Hạ giá thành sản phẩm sữa."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D04-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quyền chuyển giao quyền sở hữu tài sản cho người khác, từ bỏ quyền sở hữu tiêu dùng hoặc tiêu hủy tài sản là quyền", "o": ["sử dụng tài sản.", "quản lí tài sản.", "định đoạt tài sản.", "chiếm hữu tài sản."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D04-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trước những biểu hiện thiếu trách nhiệm xã hội của doanh nghiệp mỗi công dân cần", "o": ["lên án, phê phán.", "khuyến khích, cổ vũ.", "học tập, nêu gương.", "thờ ơ, vô cảm."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx · Phần I câu 12 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D04-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trách nhiệm xã hội của doanh nghiệp là toàn bộ trách nhiệm bắt buộc và tự nguyện mà doanh nghiệp thực hiện đối với xã hội bằng những", "o": ["chính sách và việc làm cụ thể.", "biệp pháp và phương hướng cụ thể.", "chủ trương và quyết sách cụ thể.", "giải pháp và hành động cụ thể."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx · Phần I câu 13 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D04-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào dưới đây thể hiện đúng trách nhiệm của công dân về hội nhập kinh tế quốc tế?", "o": ["Ông H giao sai số lượng hàng hóa so với thỏa thuận trong hợp đồng đã kí kết với đối tác nước ngoài.", "Ông K tháo thiết bị giám sát hành trình trên tàu cá của mình để khai thác bất hợp pháp tại vùng biển nước ngoài.", "Doanh nghiệp thủy sản X tuân thủ đúng quy định về dán nhãn, giấy tờ chứng minh nguồn gốc và các giấy chứng thư vệ sinh cần thiết khi xuất khẩu hàng hoá vào EU.", "Công ty Y thay đổi mẫu mã ghế gỗ khác với mô tả sản phẩm trong hợp đồng với đối tác nước ngoài."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D04-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trên đường đi học về, gặp trời mưa to, cháu B học sinh lớp 10 đã chủ động thu dọn rác thải tích tụ tại miệng cống thoát nước để giảm tình trạng ngập úng. Cháu B đã thực hiện pháp luật theo hình thức nào sau đây?", "o": ["Phổ cập pháp luật.", "Thi hành pháp luật.", "Áp dụng pháp luật.", "Sử dụng pháp luật."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D04-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc công dân biểu quyết các vấn đề trọng đại khi được Nhà nước trưng cầu ý dân là thực hiện quyền nào dưới đây?", "o": ["Quyền bảo vệ các lợi ích quốc gia, dân tộc.", "Quyền tự quyết mang tính dân tộc.", "Quyền quyết định công việc địa phương.", "Quyền tham gia quản lý nhà nước và xã hội."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D04-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo điều 8 luật hôn nhân và gia đình năm 2014 quy định về độ tuổi kết hôn như thế nào?", "o": ["Nam từ 18 tuổi trở lên, nữ từ đủ 20 tuổi trở lên.", "Nam từ đủ 20 tuổi trở lên, nữ từ 18 tuổi trở lên.", "Nam từ đủ 18 tuổi trở lên, nữ từ đủ 20 tuổi trở lên.", "Nam từ đủ 20 tuổi trở lên, nữ từ đủ 18 tuổi trở lên."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D04-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong nền kinh tế nước ta, chủ thể nào sau đây đóng vai trò quản lý toàn bộ nền kinh tế quốc dân?", "o": ["Chủ thể tiêu dùng.", "Chủ thể nhà nước.", "Chủ thể sản xuất.", "Chủ thể trung gian."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D04-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tín dụng có vai trò như thế nào trong đời sống xã hội", "o": ["Là công cụ giảm lạm phát.", "Là công cụ giảm tỉ lệ ô nhiễm môi trường.", "Là công cụ giảm tỉ lệ mắc bệnh.", "Là công cụ điều tiết kinh tế - xã hội của Nhà nước."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D04-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hộ kinh doanh của bà M có giấy phép kinh doanh mặt hàng rượu nội, bia và nước giải khát các loại. Nhưng khi bán hàng, bà M lại bán thêm rượu ngoại và các loại trà, thuốc lá là những mặt hàng hộ kinh doanh của bà chưa kê khai đăng ký khi nộp hồ sơ đăng ký kinh doanh. Sau khi lực lượng chức năng phát hiện, đã lập biên bản, xử phạt đối với sai phạm của bà M đồng thời yêu cầu bà đăng kí bổ sung mặt hàng kinh doanh. Bà M phải chịu trách nhiệm pháp lí nào về hành vi vi phạm pháp luật trong kinh doanh?", "o": ["Trách nhiệm kỉ luật.", "Trách nhiệm dân sự.", "Trách nhiệm hành chính.", "Trách nhiệm hình sự."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx · Phần I câu 20 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D04-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây là biểu hiện nghĩa vụ học tập của công dân?", "o": ["Công dân bình đẳng về cơ hội học tập.", "Được bảo vệ và được tôn trọng trong học tập.", "Thực hiện đúng nội quy của các cơ sở giáo dục.", "Phải được tạo điều kiện để phát triển tài năng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D04-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quy định các nước thành viên WTO phải cam kết xoá bỏ các rào cản trong thương mại quốc tế là nội dung của nguyên tắc nào dưới đây?", "o": ["Nguyên tắc ưu đãi cho các nước đang phát triển.", "Nguyên tắc không phân biệt đối xử.", "Nguyên tắc minh bạch, ổn định trong thương mại.", "Nguyên tắc mở cửa thị trường."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D04-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tổng hợp những người sinh sống, cư trú trên lãnh thổ của quốc gia, chịu sự quản lý bằng pháp luật của nhà nước ở quốc gia đó được gọi là", "o": ["Dân số thổ cư.", "Dân số nội địa.", "Dân cư địa phương.", "Dân cư quốc gia."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D04-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây thể hiện ý nghĩa của việc thực hiện trách nhiệm xã hội của doanh nghiệp đối với xã hội?", "o": ["Giảm chi phí, tăng năng suất lao động trong sản xuất.", "Tạo dựng niềm tin đối với công chúng.", "Nâng cao chất lượng sản phẩm của mình", "Chung sức hỗ trợ cộng đồng vượt qua khó khăn."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D04-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Theo số liệu thống kê của cơ quan bảo hiểm xã hội (BHXH), số tiền chậm đóng BHXH tăng dần qua các năm, trong đó, số tiền chậm đóng BHXH từ 3 năm trở lên chiếm trên 34% tổng số chậm đóng, trốn đóng BHXH. Số tiền chậm đóng BHXH khó thu có xu hướng ngày càng tăng, năm 2020 là 2.564 tỷ đồng, chiếm 22% tổng số chậm đóng BHXH, gấp 1,6 lần so với năm 2016 tương ứng tăng 1.000 tỷ, số đơn vị là 9.263 đơn vị; số lao động bị ảnh hưởng là trên 62.654 lao động. Tình trạng nợ BHXH của nhiều doanh nghiệp khiến cho hàng trăm ngàn người lao động lao đao, có gia đình lâm vào cảnh khốn cùng. Nhiều nữ công nhân sinh nở không được hưởng tiền thai sản, có bạn công nhân con đã 8 tuổi mẹ vẫn không được hưởng chế độ gì… nhiều người lao động thất nghiệp lâm vào cảnh ốm đau, chết mà không có được trợ cấp thất nghiệp; có người nghỉ hưu 7-8 năm mà vẫn chưa được cầm sổ hưu...", "o": ["Việc chậm đóng BHXH gây ảnh hưởng nghiêm trọng đến quyền, lợi ích an sinh hợp pháp, chính đáng người lao động.", "Số tiền chậm đóng BHXH khó thu có xu hướng ngày càng tăng, gấp 1,6 lần so với năm 2016 tương ứng tăng 1.000 tỷ.", "Nhiều doanh nghiệp cả nước đã phải chứng kiến nhiều nữ công nhân sinh nở không được hưởng tiền thai sản vì họ không tham gia BHXH.", "Nhiều người lao động thất nghiệp lâm vào cảnh ốm đau, chết mà không có được trợ cấp thất nghiệp vì họ không tham gia BHXH."], "a": [true, true, false, true], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx · Phần II câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D04-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Theo số liệu Tổng cục Thống kê, tổng sản phẩm trong nước (GDP) 6 tháng đầu năm 2024 tăng 6,42%, cao hơn mức tăng 6 tháng đầu năm của các năm 2020, 2021 và 2023. Tình hình đời sống dân cư trong 6 tháng đầu năm nay được cải thiện hơn. Theo kết quả sơ bộ Khảo sát Mức sống dân cư 2024, ước tính thu nhập bình quân đầu người 1 tháng trong 6 tháng đầu năm nay ước đạt 5,3 triệu đồng, tăng 8,2% so với cùng kỳ năm 2023. Về cơ cấu nền kinh tế sáu tháng đầu năm 2024, khu vực nông, lâm nghiệp và thủy sản chiếm tỷ trọng 11,55%; khu vực công nghiệp và xây dựng chiếm 36,44%; khu vực dịch vụ chiếm 43,35%. Công tác bảo đảm an sinh xã hội luôn được các cấp, ngành thực hiện kịp thời, hiệu quả. Cơ sở hạ tầng thiết yếu ở các huyện nghèo, xã nghèo, vùng đồng bào dân tộc thiểu số được tăng cường. Thực hiện nhiều giải pháp tạo việc làm nâng cao thu nhập cho người lao động. (Báo cáo tình hình kinh tế xã hội 6 tháng năm 2024 của Tổng cục Thống kê)", "o": ["Sự chuyển dịch của cơ cấu nền kinh tế trong sáu tháng đầu năm 2024 theo hướng tích cực là tiêu chí đánh giá tăng trưởng kinh tế.", "Thành tựu về tăng trưởng kinh tế là điều kiện tiên quyết để giảm khoảng cách giàu nghèo, giảm bớt chênh lệch trình độ phát triển giữa các vùng.", "Thu nhập bình quân đầu người tăng trong 6 tháng đầu năm ước đạt 5,3 triệu đồng, tăng 8,2% so với cùng kỳ năm 2023 điều đó góp phần làm cho hệ số Gini tăng.", "Người lao động chủ động tìm việc làm nâng cao thu nhập cho bản thân sẽ góp phần phát triển kinh tế."], "a": [false, false, false, true], "e": "Đáp án: a) Sai; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx · Phần II câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D04-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Công ty TNHH X là doanh nghiệp hoạt động trong lĩnh vực sản xuất thực phẩm đóng hộp. Công ty luôn đảm bảo hoạt động kinh doanh hiệu quả, tạo công ăn việc làm ổn định cho nhiều lao động và chế độ phúc lợi hợp lý. Đồng thời, công ty cũng chú trọng đến chất lượng sản phẩm, cung cấp thực phẩm an toàn, đạt tiêu chuẩn vệ sinh thực phẩm. Công ty luôn tuân thủ đầy đủ quy định của pháp luật về nộp thuế đúng hạn, thực hiện đúng nghĩa vụ bảo vệ môi trường. Đặc biệt, công ty luôn đối xử công bằng với tất cả nhân viên. Không dừng lại ở đó, Công ty X còn thường xuyên tổ chức các hoạt động tặng thực phẩm cho người nghèo, hỗ trợ các bữa ăn miễn phí cho trẻ em vùng sâu, tài trợ học bổng cho học sinh có hoàn cảnh khó khăn. Nhờ những hoạt động trách nhiệm xã hội này, Công ty X đã nâng cao uy tín thương hiệu, tạo niềm tin với khách hàng.", "o": ["Công ty TNHH X chỉ thực hiện trách nhiệm xã hội dưới hình thức đóng góp từ thiện.", "Các hoạt động từ thiện của Công ty X không ảnh hưởng đến lợi ích kinh doanh của công ty.", "Công ty X không thực hiện chế độ bảo hiểm xã hội cho nhân viên.", "Trách nhiệm xã hội của Công ty X mang lại lợi ích cho doanh nghiệp."], "a": [false, false, false, true], "e": "Đáp án: a) Sai; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx · Phần II câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D04-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Nhờ chủ trương, chính sách phát triển kinh tế của Đảng và Nhà nước cùng với nỗ lực của người dân địa phương, quê hương của Q đã đạt chuẩn nông thôn mới. Cuộc sống của nhiều hộ dân đang gặp khó khăn đã được ổn định nhờ những chính sách trợ giúp xã hội. Q và các bạn được học trong ngôi trường khang trang hơn, các dịch vụ y tế, văn hoá xã hội của địa phương cũng được cải thiện rõ rệt. Mô hình sản xuất kinh doanh của gia đình Q cũng nhờ đó mà có nhiều thuận lợi, thu nhập gia đình ngày càng tăng. Gia đình Q không chỉ chia sẻ kinh nghiệm, cách làm ăn của mình mà còn tạo công ăn việc làm cho nhiều hộ dân xung quanh.", "o": ["Các dịch vụ y tế, văn hoá xã hội của quê hương Q được cải thiện là minh chứng cho vai trò của phát triển kinh tế.", "Việc gia đình Q chia sẻ kinh nghiệm là việc làm thúc đẩy tăng trưởng kinh tế, phát triển kinh tế.", "Địa phương của Q không nên sử dụng các chính sách trợ giúp xã hội để hỗ trợ các hộ dân gặp khó khăn vì sẽ làm tăng gánh nặng cho ngân sách nhà nước.", "Gia đình Q tạo công ăn việc làm cho nhiều hộ dân xung quanh là thể hiện trách nhiệm công dân trong việc thực hiện chính sách bảo hiểm xã hội."], "a": [true, true, false, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Sai.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 1003 - BẾN TRE.docx · Phần II câu 4 · khoá: KHOÁ: file ĐÁP ÁN ghi ĐĐSS, gạch chân đọc ra khác vì ý a dính vào đoạn dẫn; em giải lại theo SGK cũng ra ĐĐSS · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}]}, {"id": "TN-D05", "loai": "tn", "khoi": 12, "hoc_ki": 2, "so_de": 5, "ten": "Đề luyện thi tốt nghiệp số 5", "pham_vi": "Đề nguồn của giáo viên, giữ NGUYÊN chữ của đề (chỉ bỏ lỗi sao chép) · mã 1011, Thanh Hóa · file nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm 4 lựa chọn + 4 câu đúng/sai (mỗi câu 4 ý)", "cham": {"tong": 10, "tn": 0.25, "ds": [0, 0.1, 0.25, 0.5, 1.0]}, "status": "cho_duyet", "khoa": {"đã giải lại, khớp khoá": 28}, "sua": "Câu đúng/sai 2: câu đúng/sai 2 của đề nguồn chỉ hỏi «nhận định nào đúng, nhận định nào sai» với bốn nhận định rời, không có thông tin hoặc tình huống (trái lời dặn 16/11/2026); thay bằng câu đúng/sai 2 của đề «8 TUẦN KÌ 1» (có thông tin, khoá khớp gạch chân và file ĐÁP ÁN). CẦN CÔ XEM (em chưa chắc, KHÔNG sửa khoá): (1) Câu 4 (đếm nhận định đúng về cung, cầu): khoá A «2 nhận định», nhưng em đếm được 3 nhận định đúng (1, 2, 5; còn 3 và 4 sai); có thể đề nguồn coi ý 1 hoặc ý 5 sai vì dùng «lượng cung» — em chưa chắc đủ 80% nên KHÔNG đổi khoá (nếu đáp án là 3 thì khoá đúng là C).", "cau": [{"id": "TN-D05-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Anh Q chiếm hữu tài sản mà không có căn cứ pháp luật, nhưng đã ngay tình, công khai, liên tục trong suốt 10 năm đối với một động sản. Theo quy định của Bộ luật Dân sự 2015 anh Q", "o": ["trở thành chủ sở hữu hợp pháp của tài sản theo thời hiệu.", "chỉ là người chiếm hữu, không có quyền sở hữu tài sản.", "chỉ có quyền sử dụng, không có quyền định đoạt động sản.", "buộc phải trả lại tài sản cho chủ sở hữu ban đầu sau 10 năm."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D05-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong quan hệ thương mại với Trung Quốc, Việt Nam đã ký kết các thỏa thuận quan trọng như: Hiệp định khu vực Mậu dịch tự do ASEAN - Trung Quôc (ACFTA) và Hiệp định đối tác kinh tế toàn diện khu vực (RCEP). Năm 2018, tổng kim ngạch thương mại song phương Việt Nam - Trung Quốc lần đầu tiên vượt mốc 100 tỉ USD. Kể từ đó, kim ngạch thương mại giữa hai nước không ngừng tăng, cụ thể: Năm 2019 đạt 111,86 tỉ USD, năm 2020 đạt 133,1 tỉ USD và những năm đại dịch Covid-19 cũng đạt mức cao với 165,88 ti USD năm 2021 và 175,56 tỉ USD năm 2022; năm 2023, tổng kim ngạch thương mại song phương đạt gần 171,2 tỉ USD, chiếm hơn 25% tổng kim ngạch xuất, nhập khẩu cả nước. Trong 9 tháng năm 2024, giá trị xuất khẩu của Việt Nam sang Trung Quốc đạt 44,39 tỉ USD, tăng 4,1%, tương ứng tăng 1,75 tỉ USD so với cùng kỳ năm trước. Tổng giá trị nhập khẩu từ thị trường này đạt 104,81 tỉ USD, đã tăng mạnh tới 32,4%, tương ứng tăng 25,63 tỉ USD so với cùng kỳ năm trước, chiếm 35% trong tổng giá trị nhập khẩu của cả nước. Những phương án nào sau đây là sai với thông tin trên? 1. Kim ngạch xuất nhập khẩu hàng hóa Việt Nam - Trung Quốc đã ghi nhận thành công của quá trình hội nhập kinh tế về thanh toán và tín dụng quốc tế. 2. Trung Quốc là thị trường xuất khẩu lớn nhất của Việt Nam về thương mại quốc tế giai đoạn 2019-2024. 3. Hiệp định khu vực Mậu dịch tự do ASEAN - Trung Quốc (ACFTA) mà Việt Nam đã ký kết là hình thức hội nhập kinh tế khu vực. 4. Quan hệ thương mại giữa Việt Nam và Trung Quốc hiện nay đã đạt tới mức độ liên minh thuế quan.", "o": ["Phương án 1 và 4.", "Phương án 1.2 và 4.", "Phương án 1,2 và 3.", "Phương án 2 và 4."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx · Phần I câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D05-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quốc gia X bước vào năm 2025 với con số tăng trưởng GDP ấn tượng đạt 8,1%. Tuy nhiên, phân tích sâu cho thấy: 72% giá trị gia tăng đến từ việc mở rộng khai thác khoáng sản thô và tăng thời gian lao động; tỷ lệ hộ nghèo đa chiều giảm nhưng khoảng cách thu nhập giữa nhóm 20% giàu nhất và 20% nghèo nhất tăng từ 8 lần lên 12 lần; diện tích rừng nguyên sinh giảm 5% do dự án công nghiệp nặng, chỉ số HDI tăng nhẹ nhờ phổ cập giáo dục, nhưng GNI bình quân đầu người vẫn thấp hơn nhiêu so với GDP do lợi nhuận chủ yếu thuộc về các tập đoàn nước ngoài. Dựa trên các chỉ số về HDI, GNI và khoảng cách thu nhập, nhận định nào sau đây phản ánh đúng nhất bản chất phát triển kinh tế của quốc gia X?", "o": ["Quốc gia X có sự tăng trưởng kinh tế nhưng hoàn toàn không có sự phát triển kinh tế.", "Sự gia tăng GDP đã trực tiếp tạo ra sự bình đẳng trong thu nhập dân cư.", "Quốc gia X đang trong quá trình phát triển nhưng thiếu tính tự chủ và công bằng trong phân phối.", "Quốc gia X đang trong quá trình chuyển đổi sang kinh tế tri thức lấy con người làm trung tâm."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D05-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Cho các nhận định sau về cung, cầu. Có bao nhiêu nhận định đúng? 1) Giá nguyên liệu đầu vào tăng, lượng cung có xu hướng giảm. 2) Thu nhập của người dân tăng, cầu đối với hàng hóa xa xỉ sẽ tăng. 3) Tăng giá yếu tố đầu vào sẽ làm giảm chi phí sản xuất và giảm cung. 4) Giá của một hàng hóa giảm, cầu đối với hàng hóa đó cũng giảm theo. 5) Nhà nước giảm thuế cho mặt hàng nào đó, lượng cung hàng hóa đó tăng.", "o": ["Có 2 nhận định.", "Có 5 nhận định.", "Có 3 nhận định.", "Có 4 nhận định."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx · Phần I câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D05-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Cho các nhận định sau về Bảo hiểm. Có bao nhiêu nhận định đúng? 1) Người từ đủ 80 tuổi không có lương hưu thì được hưởng trợ cấp hưu trí xã hội hàng tháng. 2) Người lao động đóng BHXH bắt buộc được hưởng chế độ thai sản, ốm đau, hưu trí. 3) Người thuộc hộ nghèo, hộ cận nghèo được hỗ trợ 100% mức đóng Bảo hiêm y tế. 4) Người lao động bị mất việc làm được hưởng trợ cấp thất nghiệp để ổn định cuộc sống. 5) Người khuyết tật nặng được nhận trợ cấp bảo trợ xã hội và cấp thẻ BHYT.", "o": ["4 nhận định.", "2 nhận định.", "3 nhận định.", "5 nhận định."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx · Phần I câu 5 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D05-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, nam nữa bình đẳng về tiêu chuẩn, độ tuổi khi được đề bạt, bổ nhiệm giữ các chức danh trong các ngành nghề có tiêu chuẩn chức danh là bình đẳng giới trong lĩnh vực nào sau đây?", "o": ["Bình đẳng giới trong lĩnh vực giáo dục.", "Bình đẳng giới trong lĩnh vực lao động.", "Bình đẳng giới trong lĩnh vực chính trị.", "Bình đẳng giới trong lĩnh vực kinh tế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx · Phần I câu 6 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D05-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Anh L là người đang làm việc tại công ty G nhưng do hạn chế về năng lực nên bị sa thải. Xét về nguồn gốc thất nghiệp, anh L rơi vào loại hình thất nghiệp nào sau đây?", "o": ["Thất nghiệp tạm thời.", "Thất nghiệp tự nguyện.", "Thất nghiệp cơ cấu.", "Thất nghiệp chu kỳ."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D05-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong giai đoạn 2010–2020, kinh tế Việt Nam chuyển biến tích cực: Cơ cấu lao động chuyển dịch từ khu vực năng suất lao động thấp sang khu vực năng suất lao động cao hơn. Tỉ trọng lao động nông, lâm nghiệp và thuỷ sản trong tổng số lao động cả nước giảm từ 48,6% năm 2010 xuống còn 34% năm 2020. Tỉ trọng lao động ngành công nghiệp và xây dựng tăng từ 21,7% lên 30,3%; ngành dịch vụ từ 29,7% lên khoảng 35,7% trong cùng giai đoạn. Đời sống người dân không ngừng được cải thiện; tạo sinh kế và nâng cao khả năng tiếp cận các dịch vụ xã hội cơ bản. Thu nhập bình quân đầu người tăng 3,1 lần, từ 16,6 triệu đồng năm 2010 lên 51,5 triệu đồng năm 2019. Thực hiện nhiều giải pháp tạo việc làm, nâng cao thu nhập cho người lao động. Mạng lưới cơ sở y tế phát triển rộng khắp, chất lượng khám, chữa bệnh và y đức được nâng lên; y tế cơ sở được chú trọng. Tuổi thọ trung bình tăng từ 72,9 tuổi năm 2010 lên 73,7 tuổi vào năm 2020. Nội dung nào sau đây không phải là chỉ tiêu để đánh giá sự phát triển kinh tế của nước ta?", "o": ["Năng suất lao động xã hội.", "Vấn đề việc làm và thu nhập.", "Chuyển dịch cơ cấu lao động.", "Chuyển dịch cơ cấu ngành."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D05-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Anh M nghỉ học từ năm lớp 9, đến năm 30 tuổi anh đăng ký học tại Trung tâm Giáo dục thường xuyên để lấy bằng THPT. Trong trường hợp này anh M", "o": ["chỉ được học tuần tự từ mầm non đến trung học phổ thông.", "không còn quyền học vì đã quá tuổi phổ cập.", "vẫn có quyền học vì pháp luật bảo đảm quyền học suốt đời.", "chỉ được học nếu xin được trường hợp đặc biệt."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D05-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chủ thể đóng vai trò quan trọng trong việc tạo ra hàng hoá, dịch vụ cho xã hội là", "o": ["chủ thể sản xuất.", "chủ thể phân phối.", "chủ thể nhà nước.", "chủ thể trung gian."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D05-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Người bán, trao đổi, tặng, cho, cho vay, để thừa kế, tiêu huỷ tài sản là thuộc quyền và chủ thể nào sau đây?", "o": ["Quyền tài phán của chủ sở hữu.", "Quyền sử dụng của chủ sở hữu.", "Quyền định đoạt của chủ sở hữu.", "Quyền định đoạt của nhà nước."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D05-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hội nhập kinh tế là quá trình một quốc gia thực hiện việc gắn kết nền kinh tế của mình với", "o": ["doanh nhân nước ngoài.", "các quốc gia khác.", "các doanh nghiệp trong nước.", "thủ tướng chính phủ."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx · Phần I câu 12 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D05-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của Luật ngân sách nhà nước năm 2015, hoạt động thu, chi của ngân sách nhà nước được thực hiện theo nguyên tắc", "o": ["chi nhưng không thu.", "không hoàn trả trực tiếp.", "hoàn trả trực tiếp.", "có thể hoàn trả trực tiếp."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx · Phần I câu 13 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D05-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Loại thuế nào sau đây có đặc điểm người nộp thuế đồng thời là người chịu thuế?", "o": ["Thuế trực thu.", "Thuế xuất khẩu.", "Thuế gián thu.", "Thuế nhập khẩu."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D05-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hiến pháp nước Cộng hòa Xã hội Chủ Nghĩa Việt Nam năm 2013 quy định mọi công dân đều", "o": ["bình đẳng trước công dân.", "bình đẳng về quyền lợi.", "bình đẳng về nghĩa vụ.", "bình đẳng trước pháp luật."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D05-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nghĩa vụ nào sau đây của công dân về bảo vệ môi trường và tài nguyên thiên nhiên thể hiện tính chủ động, bắt buộc và liên tục trong đời sống hàng ngày, đồng thời là cơ sở để cơ quan nhà nước áp dụng các chế tài xử phạt khi không tuân thủ?", "o": ["Ngăn chặn và kịp thời báo tin cho cơ quan có thẩm quyền về các hành vi gây ô nhiễm, sự cố môi trường.", "Đóng góp ý kiến về các biện pháp bảo vệ môi trường, giảm thiểu chất thải trong quá trình sản xuất và tiêu thụ.", "Chủ động tham gia hoạt động bảo vệ môi trường tại cộng đồng dân cư nơi mình sinh sống, tổ chức và hoạt động.", "Thực hiện nghiêm chỉnh các quy định của pháp luật về bảo vệ môi trường, giữ gìn vệ sinh, bảo vệ cảnh quan."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D05-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nghị định số 84/2020/NĐ-CP ngày 17/7/2020 của Chính phủ ban hành phù hợp với Hiến pháp và Luật Giáo dục năm 2019 là thể hiện đặc điểm nào sau đây của pháp luật?", "o": ["Tính xác định chặt chẽ về nội dung.", "Tinh quy phạm phổ biến.", "Tính quyền lực băt buộc chung.", "Tính xác định chặt chẽ về mặt hình thức."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D05-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công ty V đầu tư hơn 33 tỷ đồng xây dựng nhà ở tặng bà con bị ảnh hưởng lũ lụt. Việc làm đã thể hiện chính sách an sinh xã hội và trách nhiệm xã hội nào sau đây của doanh nghiệp?", "o": ["Đảm bảo dịch vụ xã hội cơ bản và trách nhiệm nhân văn.", "Trợ giúp xã hội và trách nhiệm nhân văn.", "Việc làm, thu nhập, giảm nghèo và trách nhiệm kinh tế.", "Trợ giúp thường xuyên và trách nhiệm đao đức."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D05-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong sản xuất và lưu thông hàng hóa, khi một hàng hóa đem ra thị trường và được thị trường chấp nhận, khi đó thị trường thực hiện chức năng nào sau đây?", "o": ["Điều tiết sản xuất và lưu thông.", "Thông tin cho người tiêu dùng.", "Thông tin cho người sản xuất.", "Thừa nhận giá trị của hàng hóa."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D05-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Những nhận định nào sau đây đúng về lạm phát? 1) Lạm phát do cầu kéo xảy ra khi chi phí của các yếu tố sản xuất đầu vào tăng lên đồng loạt. 2) Lạm phát do chi phí đẩy xảy ra khi Chính phủ phát hành thêm tiền mặt để bù đắp thâm hụt ngân sách. 3) Nhà nước có thể áp dụng các biện pháp như: Giảm thuế nhập khẩu nguyên liệu, hỗ trợ chi phí sản xuất và bình ổn giá các mặt hàng thiết yếu trong trường hợp lạm phát do chi phí đẩy. 4) Để kiểm soát lạm phát do cầu kéo, nhà nước thực hiện chính sách tài khóa thắt chặt thông qua việc giảm thuế và giảm chỉ tiêu công. 5) Để kiềm chế lạm phát do cầu kéo, ngân hàng Trung ương có thể thực hiện chính sách tiên tệ mở rộng như hạ lãi suất và mua trái phiếu chính phủ. 6) Việc tăng lương danh nghĩa cho công nhân nhưng năng suất lao động không tăng có thể dẫn đến lạm phát. 7) Lạm phát do cầu kéo xảy ra khi tổng cầu trong nền kinh tế tăng quá nhanh so với khả năng cung ứng hàng hóa, dịch vụ.", "o": ["Nhận định 4,5 và 7.", "Nhận định 3. 6 và 7.", "Nhận định 3,5 và 7.", "Nhận định 2, 3 và 4."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx · Phần I câu 20 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D05-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn văn\ndưới đây và chọn A, B, C, hoặc D chỉ ra câu trả lời đúng nhất cho mỗi câu hỏi từ 21 đến 22.\nTừ nãm 2018, ông M thành lập Công ty Trách nhiệm hữu hạn thýõng mại và sản xuất G với ngành nghề kinh doanh dầu nhớt, phụ tùng xe gắn máy. Trong thời gian kinh doanh, ông M nhận thấy khách hàng ýa chuộng các phụ tùng xe gắn máy hiệu H và dầu nhớt hiệu K nên nảy sinh ý ðịnh làm giả sản phẩm của các thýõng hiệu này bán cho khách hàng ðể thu lợi. Ông M chỉ ðạo nhân viên thiết kế các mẫu tem xác nhận hàng chính hãng và thuê ngýời in nhiều mẫu tem ðể sử dụng, sau ðó ông cùng vợ ðến một số chợ trong khu vực tìm mua các phụ tùng xe gắn máy, dầu nhớt chất lýợng kém ðem về ðóng gói, dán tem làm giả sản phẩm của các thýõng hiệu nổi tiếng, bán ra thị trýờng cho khách với giá thấp hõn hàng chính hãng từ 10% - 15%. Bằng thủ ðoạn ðó, trong thời gian gần 2 nãm, vợ chồng ông M ðã sản xuất số lýợng hàng giả có giá trị týõng ðýõng hàng thật hõn 750 triệu ðồng, thu lợi khoảng 300 triệu ðồng.\nHành vi của vợ chồng ông M sẽ phải chịu trách nhiệm pháp lí nào sau ðây?", "o": ["Hình sự và kỉ luật.", "Dân sự và hành chính.", "Hình sự.", "Hành chính."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D05-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Ông M thành lập công ty trách nhiệm hữu hạn là thực hiện quyền tự do kinh doanh ở nội dung nào sau ðây?", "o": ["Tự do lựa chọn ðối týợng kinh doanh.", "Chủ ðộng mở rộng thị trýờng kinh doanh.", "Ðiều chỉnh quy mô mặt hàng kinh doanh.", "Tự do lựa chọn loại hình kinh doanh."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D05-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn văn\ndưới đây và chọn A, B, C, hoặc D chỉ ra câu trả lời đúng nhất cho mỗi câu hỏi từ 23 đến 24.\nÔng M và bà L là vợ chồng hợp pháp, có hai người con là H và T. Năm 2010, ông M mua một căn nhà, trong đó 2/3 giá trị là tiền chung của vợ chồng, 1/3 là tiền ông M được cha mẹ tặng riêng (có công chứng). Giấy chứng nhận quyền sử dụng đất đứng tên riêng ông M. Năm 2018, ông M qua đời, không để lại di chúc. Sau khi ông mất, bà L và hai con vẫn sinh sống trong căn nhà này.Nãm 2023, T tự ý bán toàn bộ cãn nhà cho ngýời khác mà chýa có sự ðồng ý của bà L và H.\nCăn nhà ông M mua được xác định là loại tài sản nào sau đây?", "o": ["Toàn bộ là di sản thừa kế sau khi ông M mất.", "Tài sản chung nhưng có phần tài sản riêng của ông M.", "Tài sản riêng của của ông M vì đứng tên sử dụng đất.", "Tài sản chung của vợ chồng ông M và bà L."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D05-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc T tự ý bán toàn bộ căn nhà khi chưa có sự đồng ý của bà L và H là hành vi", "o": ["xâm phạm quyền sở hữu của đồng thừa kế, làm giao dịch vô hiệu.", "thực hiện chưa đúng quyền định đoạt tài sản được cha mẹ để lại.", "thực hiện quyền thừa kế hợp pháp của mình nhưng thiếu sự đồng ý.", "sử dụng tài sản chung của gia đình đúng quy định pháp luật."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D05-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Công ty cổ phần B sản xuất hàng đồ chơi trẻ em. Từ nhiều năm nay, công ty đã thực hiện đầy đủ quy định pháp luật về bảo vệ môi trường trong sản xuất, kinh doanh, hàng năm đầu tư hàng tỉ đồng để xây dựng hệ thống xử lí nước thải bảo vệ môi trường và sản xuất đồ chơi không ảnh hưởng đến sức khoẻ của trẻ em. Đồng thời, công ty còn thực hiện đúng nghĩa vụ kê khai và nộp thuế cho Nhà nước theo đúng quy định của pháp luật.", "o": ["Thực hiện quy định của pháp luật về bảo vệ môi trường là công ty đã thực hiện tốt trách nhiệm xã hội ở hình thức pháp lý và kinh tế.", "Việc sản xuất đồ chơi không ảnh hưởng đến sức khỏe của trẻ em là phù hợp với trách nhiệm xã hội của doanh nghiệp ở hình thức đạo đức.", "Thực hiện tốt nghĩa vụ nộp thuế cho nhà nước gắn liền với trách nhiệm kinh tế của doanh nghiệp.", "Thông qua việc tạo ra những sản phẩm không ảnh hưởng đến sức khỏe của trẻ em, công ty B đã thể hiện trách nhiệm của mình trong việc thúc đẩy phát triển bền vững."], "a": [false, true, false, true], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx · Phần II câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D05-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Tuổi trẻ với bản chất năng động, sáng tạo, nhiệt huyết, nhanh nhạy là đối tượng lí tưởng để tiếp thu các công nghệ mới, tham gia giao lưu, hội nhập quốc tế. Song cũng cần phải lưu ý rằng, trong quá trình hội nhập, phải luôn tỉnh táo để không đánh mất bản sắc văn hóa của dân tộc, phải dung hòa được nếp sống hiện đại với những giá trị truyền thống. Nhiệm vụ học tập khoa học, công nghệ và hội nhập quốc tế đòi hỏi lớp thanh niên hiện nay phải nhanh chóng trang bị cho mình năng lực hội nhập như bản lĩnh, kiến thức, trình độ ngoại ngữ, tin học, kĩ năng, tác phong công nghiệp, hiểu biết văn hóa dân tộc, đất nước mình, đồng thời phải hiểu biết tình hình kinh tế, chính trị, xã hội và văn hóa thế giới.", "o": ["Hội nhập kinh tế quốc tế sẽ chỉ mang lại những tác động tích cực đến với thế hệ trẻ.", "Trách nhiệm của thanh niên là phải trang bị những năng lực hội nhập quốc tế.", "Để hội nhập quốc tế, mỗi thanh niên phải tự mình phát huy tinh thần học tập, rèn luyện.", "Việc trau dồi các kiến thức tin học và ngoại ngữ là yếu tố tiên quyết đối với thanh niên khi đất nước hội nhập kinh tế quốc tế."], "a": [false, true, true, false], "e": "Đáp án: a) Sai; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx · Phần II câu 2 · khoá: CÂU THAY (từ «17_ĐỀ GV (có đáp án) - 8 TUẦN KÌ 1.docx» câu đúng/sai 2) · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D05-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Sau khi sinh con được sáu tháng, chị K phát hiện chồng mình là anh B đã tự ý sử dụng tiền tiết kiệm của hai vợ chồng để kinh doanh và bị thua lỗ. Để có tiền trả nợ, chị K đã bí mật bán mảnh đất mà bố mẹ chị tặng trước khi kết hôn. Sau khi chuyển 100 triệu đồng cho anh B để trả nợ. Số tiền còn lại chị K gửi ngân hàng và dành lại một phần để đi học. Khi chị K đề xuất nguyện vọng muốn vừa đi làm vừa tiếp tục học để nâng cao trình độ thì anh B nhất quyết không đồng ý. Bức xúc chị đã đăng bài nói xấu anh trên mạng xã hội và được rất nhiều chị em phụ nữ đồng tình.", "o": ["Việc anh B đã tự ý sử dụng tiền tiết kiệm của hai vợ chồng để kinh doanh là không vi phạm quyền và nghĩa vụ của công dân trong hôn nhân và gia đình.", "Anh B không đồng ý cho vợ đi học để nâng cao trình độ là vi phạm quan hệ nhân thân.", "Chị K đã bí mật bán mảnh đất mà bố mẹ chị tặng trước khi kết hôn là vi phạm quyền và nghĩa vụ của công dân trong hôn nhân và gia đình.", "Cả chị K và anh B đều vi phạm bình đẳng giữa vợ và chồng trong quan hệ nhân thân."], "a": [false, true, false, true], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx · Phần II câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D05-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Tính chung thời kì thực hiện chiến lược phát triển kinh tế xã hội 10 năm (2011 - 2020), tăng trưởng GDP của Việt Nam đạt khoảng 5,9%/năm, thuộc nhóm các nước tăng trưởng cao trong khu vực. Quy mô GDP tăng gấp 2,4 lần, từ 116 tỉ USD năm 2010 lên 268,4 tỉ USD vào năm 2020. GDP bình quân đầu người tăng từ 1.331 USD năm 2010 lên khoảng 2.750 USD năm 2020. Tỉ lệ hộ nghèo cả nước giảm nhanh, từ 14,2% năm 2010 xuống còn 7% năm 2015 (theo chuẩn nghèo giai đoạn 2011 - 2015) và giảm từ 9,2% năm 2016 xuống dưới 3% vào năm 2020 (theo chuẩn nghèo đa chiều). Cơ sở hạ tầng thiết yếu ở các xã nghèo, vùng đồng bào dân tộc thiểu số được tăng cường. Thực hiện nhiều giải pháp tạo việc làm, nâng cao thu nhập cho người lao động.", "o": ["Trong giai đoạn 2011 – 2020 Việt Nam luôn duy trì được tốc độ tăng trưởng kinh tế cao.", "Phát triển kinh tế góp phần giúp nước ta thực hiện tốt các vấn đề xã hội.", "Việc nhà nước đầu tư nhiều cho phát triển xã hội sẽ kéo giảm tốc độ tăng trưởng kinh tế.", "Trong quá trình phát triển, Việt Nam luôn đặt con người vào vị trí trung tâm của sự phát triển."], "a": [true, true, false, true], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 1011 - THANH HÓA.docx · Phần II câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}]}, {"id": "TN-D06", "loai": "tn", "khoi": 12, "hoc_ki": 2, "so_de": 6, "ten": "Đề luyện thi tốt nghiệp số 6", "pham_vi": "Đề nguồn của giáo viên, giữ NGUYÊN chữ của đề (chỉ bỏ lỗi sao chép) · Đề số 01 · file nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm 4 lựa chọn + 4 câu đúng/sai (mỗi câu 4 ý)", "cham": {"tong": 10, "tn": 0.25, "ds": [0, 0.1, 0.25, 0.5, 1.0]}, "status": "cho_duyet", "khoa": {"đã giải lại, khớp khoá": 28}, "sua": "CẦN CÔ XEM (em chưa chắc, KHÔNG sửa khoá): (1) Câu 6 («người lao động và người sử dụng lao động gặp gỡ, trao đổi mua bán hàng hóa việc làm ở nơi nào»): khoá B «Thị trường việc làm» — tên thường gặp là «thị trường lao động» (A); em chưa chắc, giữ khoá của đề nguồn.", "cau": [{"id": "TN-D06-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hoạt động kinh tế nào dưới đây thúc đẩy việc mở rộng các hoạt động kinh tế khác của con người, làm phong phú đời sống vật chất tinh thần của xã hội?", "o": ["Hoạt động sản xuất.", "Hoạt động tiêu dùng.", "Hoạt động trao đổi.", "Hoạt động phân phối."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D06-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Là hình thức tổ chức kinh tế thể hiện sự hợp tác, tương trợ lẫn nhau trong quá trình sản xuất kinh doanh vừa đáp ứng nhu cầu chung của các thành viên, trên cơ sở tự chủ, tự chịu trách nhiệm là đặc điểm cơ bản của mô hình sản xuất kinh doanh nào dưới đây?", "o": ["Hộ sản xuất kinh doanh.", "Doanh nghiệp nhà nước.", "Doanh nghiệp.", "Hợp tác xã"], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx · Phần I câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D06-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hình thức thực hiện pháp luật nào trong đó cá nhân, tổ chức được thực hiện các quyền của mình, làm những gì mà pháp luật cho phép làm?", "o": ["Thi hành pháp luật.", "Sử dụng pháp luật.", "Tuân thủ pháp luật.", "Áp dụng pháp luật."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D06-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của Hiến pháp 2013, Nước Cộng hòa xã hội chủ nghĩa Việt Nam là một nước độc lập, có chủ quyền, thống nhất và toàn vẹn lãnh thổ bao gồm đất liền, hải đảo, vùng biển v�", "o": ["khu tự trị.", "khu xâm lược.", "vùng trời.", "vùng lòng đất."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx · Phần I câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D06-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mức độ tăng của giá cả ở một con số hằng năm ( 0% - dưới 10%) phản ánh nền kinh tế đang ở mức độ lạm phát", "o": ["vừa phải.", "phi mã.", "siêu lạm phát.", "mất kiểm soát."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx · Phần I câu 5 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D06-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Người lao động và người sử dụng lao động gặp gỡ, trao đổi mua bán hàng hóa việc làm ở nơi nào dưới đây?", "o": ["Thị trường lao động.", "Thị trường việc làm.", "Thị trường tài chính.", "Thị trường tiêu dùng."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx · Phần I câu 6 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D06-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nhờ có kiến thức về ngành nghề kinh doanh, chủ thể kinh doanh đã tổ chức tốt các hoạt động sản xuất và phân phối, sản phẩm làm ra thỏa mãn nhu cầu thị hiếu của người tiêu dùng là biểu hiện của năng lực nào sau đây của chủ thể kinh doanh?", "o": ["Năng lực chuyên môn, nghiệp vụ.", "Năng lực giải quyết mối quan hệ.", "Năng lực tìm kiếm thị trường.", "Năng lực phân phối sản phẩm."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D06-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Ở nước ta hiện nay, nam nữa đều có quyền bình đẳng trong tham gia quản lý nhà nước và xã hội là thể hiện quyền bình đẳng giới trong lĩnh vực", "o": ["kinh tế.", "chính trị.", "lao động.", "kinh doanh."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D06-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, công dân có quyền tự ứng cử hoặc giới thiệu người khác ứng cử vào các cơ quan nhà nước là đã thực hiện quyền dân chủ nào dưới đây?", "o": ["Quyền ứng cử.", "Quyền bầu cử.", "Quyền khiếu nại.", "Quyền tố cáo."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D06-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi nền kinh tế có sự tăng lên về quy mô sản lượng trong một thời kỳ nhất định, điều đó chứng tỏ nền kinh tế đó đang", "o": ["lạm phát.", "thất nghiệp.", "tăng trưởng.", "suy thoái."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D06-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quá trình liên kết giữa các quốc gia, vùng lãnh thổ với nhau thông qua việc tham gia vào các tổ chức kinh tế toàn cầu là một trong những hình thức hội nhập kinh tế quốc tế ở cấp độ", "o": ["khu vực.", "song phương.", "toàn cầu.", "toàn diện."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D06-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Doanh nghiệp nỗ lực vượt qua khó khăn để hoạt động có hiệu quả, không chỉ đem lại lợi nhuận mà còn góp phần tạo ra nhiều việc làm với mức thu nhập ổn định cho người lao động là đã góp phần thực hiện tốt trách nhiệm xã hội nào dưới đây của doanh nghiệp?", "o": ["Trách nhiệm pháp lý.", "Trách nhiệm kinh tế.", "Trách nhiệm tiêu dùng.", "Trách nhiệm nhân văn."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx · Phần I câu 12 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D06-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, khi tiến hành kinh doanh, mọi doanh nghiệp đều phải thực hiện nghĩa vụ", "o": ["sử dụng nguyên liệu hữu cơ.", "đầu tư kinh phí quảng cáo.", "bảo vệ quyền lợi người tiêu dùng.", "tổ chức hội nghị trực tuyến định kì."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx · Phần I câu 13 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D06-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, khi mục đích của hôn nhân không đạt được, công dân có quyền yêu cầu cơ các cơ quan nhà nước có thẩm quyền", "o": ["đề bạt bổ nhiệm.", "hỗ trợ kinh phí.", "giải quyết việc làm.", "giải quyết ly hôn."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D06-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, đối với những di sản văn hóa được pháp luật công nhận mọi công dân đều được", "o": ["tiếp cận.", "hủy hoại.", "chiếm đoạt.", "mua bán."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D06-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong hoạt động của Tổ chức Thương mại Thế giới, nguyên tắc nào dưới đây gắn liền với chế độ đối xử tối huệ quốc?", "o": ["Cạnh tranh minh bạch.", "Không phân biệt đối xử.", "Tự do hoá thương mại.", "Cạnh tranh công bằng."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D06-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Thấy cửa hàng bán đồ ăn của mình lượng khách lúc nào cũng ít hơn cửa hàng bán đồ ăn góc phố đối diện do anh D làm chủ, bà H đã thuê anh M viết bài đăng lên mạng xã hội vu khống anh D thường xuyên sử dụng chất cấm để chế biến thực phẩm bán cho khách hàng khiến uy tín của anh D bị suy giảm nghiêm trọng, hành vi của bà H là biểu hiện của hành vi", "o": ["tiêu dùng thông minh.", "kinh doanh phi lợi nhuận.", "cạnh tranh lành mạnh.", "cạnh tranh không lành mạnh."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D06-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Do kinh tế thế giới bị suy thoái đã làm cho các doanh nghiệp trong nước, nhất là các doanh nghiệp nhỏ gặp nhiều khó khăn. Nhiều doanh nghiệp phải đóng cửa, tạm ngừng sản xuất dẫn đến người lao động bị mất việc làm, thất nghiệp gia tăng, nội dung này phản ánh loại hình thất nghiệp nào dưới đây?", "o": ["Thất nghiệp tạm thời.", "Thất nghiệp cơ cấu.", "Thất nghiệp chu kỳ.", "Thất nghiệp tự nguyện."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D06-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi đánh người, làm tổn hại cho sức khỏe của người khác là xâm phạm đến quyền tự do cơ bản nào của công dân?", "o": ["Bất khả xâm phạm về thân thể.", "Bảo hộ về danh dự, nhân phẩm.", "Tự do về thân thể của công dân.", "Bảo hộ về tính mạng, sức khỏe."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D06-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bạn H tham gia loại hình Bảo hiểm toàn diện học sinh với công ty Bảo việt, một lần trên đường đi học về, bạn không may va chạm với xe máy đi ngược dẫn đến chấn thương phải nhập viện điều trị. Trong thời gian nằm viện, bạn H được cơ quan bảo hiểm xã hội thanh toán tiền nằm viện theo quy định, công ty Bảo việt đã thanh toán chế độ bảo hiểm theo hợp đồng mà bạn H đã đóng phí. Bạn H đã tham gia những loại hình bảo hiểm nào dưới đây?", "o": ["Bảo hiểm xã hội và y tế.", "Bảo hiểm thất nghiệp và y tế.", "Bảo hiểm thương mại và y tế.", "Bảo hiểm thương mại và xã hội."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx · Phần I câu 20 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D06-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 21, 22\nKhu vực anh D và chị H sinh sống có nhiều nhà máy đi vào hoạt động. Nhận thấy nhu cầu thuê phòng trọ ngày càng tăng của công nhân, anh D và chị H đã quyết định sử dụng toàn bộ tiền tiết kiệm của hai vợ chồng để xây dựng phòng trọ cho thuê giá rẻ. Số tiền có được từ việc kinh doanh phòng trọ anh chị đã dùng một phần vào việc chi tiêu cho gia đình còn lại tái đầu tư tiếp tục mở rộng số lượng các phòng trọ mới nhằm đáp ứng nhu cầu của công nhân quá đó giúp gia đình có thu nhập ổn định.\nNội dung nào trong thông tin trên thể hiện anh D và chị H đã biết phân tích các điều kiện thực hiện kế hoạch kinh doanh?", "o": ["Xây dựng phòng trọ cho thuê.", "Đánh giá về nhu cầu phòng trọ tăng.", "Phân chia thu nhập từ kinh doanh.", "Mở rộng quy mô kinh doanh phòng trọ."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D06-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 21, 22\nKhu vực anh D và chị H sinh sống có nhiều nhà máy đi vào hoạt động. Nhận thấy nhu cầu thuê phòng trọ ngày càng tăng của công nhân, anh D và chị H đã quyết định sử dụng toàn bộ tiền tiết kiệm của hai vợ chồng để xây dựng phòng trọ cho thuê giá rẻ. Số tiền có được từ việc kinh doanh phòng trọ anh chị đã dùng một phần vào việc chi tiêu cho gia đình còn lại tái đầu tư tiếp tục mở rộng số lượng các phòng trọ mới nhằm đáp ứng nhu cầu của công nhân quá đó giúp gia đình có thu nhập ổn định.\nNội dung nào dưới đây là căn cứ để anh D và chị H xây dựng kế hoạch quản lý thu chi trong gia đình một cách phù hợp?", "o": ["Sống trên địa bàn có tiềm năng kinh doanh.", "Nguồn thu nhập từ kinh doanh phòng trọ.", "Ý tưởng kinh doanh phòng trọ cho thuê.", "Thu nhập ổn định từ lương của anh D."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D06-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 23, 24\nBà H là chủ hộ kinh doanh, đăng kí và mở cửa hàng kinh doanh nước giải khát và bia. Khi mở cửa hàng, bà H lại bán thêm rượu và thuốc lá nhưng không đăng kí bổ sung mặt hàng kinh doanh này với cơ quan đăng kí kinh doanh. Khi kê khai thuế, bà H không kê khai rượu và thuốc lá vì cho rằng những hàng hoá này không có trong hồ sơ đăng kí kinh doanh.\nTrong thông tin trên bà H đã vi phạm những nghĩa vụ nào dưới đây khi tiến hành hoạt động kinh doanh?", "o": ["Kinh doanh không đúng ngàng nghề đăng ký và vi phạm quy định về nộp thuế.", "Kinh doanh đồ uống có cồn và nghĩa vụ về nộp thuế khi kinh doanh.", "Kinh doanh không đúng ngành nghề và kinh doanh đồ uống có cồn.", "Không đăng ký kinh doanh và không kê khai thuế với cơ quan chức năng."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D06-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 23, 24\nBà H là chủ hộ kinh doanh, đăng kí và mở cửa hàng kinh doanh nước giải khát và bia. Khi mở cửa hàng, bà H lại bán thêm rượu và thuốc lá nhưng không đăng kí bổ sung mặt hàng kinh doanh này với cơ quan đăng kí kinh doanh. Khi kê khai thuế, bà H không kê khai rượu và thuốc lá vì cho rằng những hàng hoá này không có trong hồ sơ đăng kí kinh doanh.\nViệc làm của bà H trong thông tin trên là vi phạm trách nhiệm nào dưới đây của chủ doanh nghiệp khi kinh doanh?", "o": ["Pháp lý.", "Kinh tế.", "Đạo đức.", "Nhân văn."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D06-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Trong năm 2023, tỉnh M đã giải quyết việc làm mới cho hơn 8.000 lao động, trong 5 năm đã tạo việc làm cho 41.394 lao động, đạt 103% so với kế hoạch. Chương trình mục tiêu giảm nghèo của tỉnh triển khai có hiệu quả các chính sách, chương trình hỗ trợ người nghèo, hộ nghèo, vùng nghèo. Đa số hộ nghèo được nâng cao nhận thức, cố gắng tìm tòi học tập kinh nghiệm trong sản xuất, tự tạo việc làm để vươn lên thoát nghèo, cải thiện điều kiện sống và sinh hoạt. Kết quả giảm nghèo của toàn tỉnh trong 5 năm đã vượt mục tiêu đề ra, giảm từ 38.085 hộ nghèo, chiếm tỉ lệ 28,4% xuống còn 18.048 hộ nghèo. Qua đó đã góp phần giúp cho tốc độ tăng trưởng kinh tế của tỉnh ngày càng vững chắc, đời sống nhân dân được cải thiện.", "o": ["Chính sách an sinh xã hội của tỉnh M tập trung vào vấn đề giải quyết việc làm và bảo hiểm là phù hợp.", "Nhờ sự hỗ trợ của tỉnh mà những hộ nghèo ở tỉnh M đã chủ động tự tạo việc làm là thể hiện trách nhiệm của công dân trong việc thực hiện chính sách an sinh xã hội.", "Người dân tỉnh M không có nghĩa vụ phải thực hiện các chính sách an sinh xã hội của tỉnh triển khai vì họ đã có thể tự tạo được việc làm cho bản thân.", "Giải pháp mà tỉnh M đang thực hiện là phù hợp với những nội dung cơ bản về phát triển bền vững."], "a": [false, true, false, true], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx · Phần II câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D06-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Anh D và chị H đều làm công nhân trong nhà máy X đã thỏa thuận với bà M về việc thuê một phòng trọ để ở. Thời gian đầu do hai vợ chồng đều đi làm nên thu nhập của hai vợ chồng đủ để trang trải cuộc sống. Gần đây do khủng hoảng kinh tế, anh D bị thất nghiệp phải ở nhà khiến chi tiêu sinh hoạt của hai vợ chồng và các con bị ảnh hưởng. Để giúp đỡ vợ, bên cạnh việc may mượn bạn bè được 20 triệu đồng làm vốn, anh D cải tạo lại một phần diện tích phòng trọ làm nơi sửa chữa đồ gia dụng cho công nhân ở khu vực. Công việc bước đầu mang lại thu nhập hỗ trợ gia đình và trả tiền đã vay cho bạn bè. Thấy anh D sử dụng phòng trọ của mình để kinh doanh, bà M đã yêu cầu anh D thanh toán thêm tiền phòng nhưng không được anh chấp nhận, bức xúc b� M đã ngăn cản không cho khách hàng của anh D đến sửa chữa khiến hai người mâu thuẫn.", "o": ["Anh D có quyền cải tạo lại căn phòng để làm nơi kinh doanh vì anh đã hợp đồng thuê căn phòng này với bà M.", "Cả anh D và bà M đều chưa thực hiện đúng nghĩa vụ tôn trọng tài sản của người khác.", "Gia đình anh D và chị H cần điều chỉnh kế hoạch chi tiêu cắt giảm một số khoản chi không cần thiết là phù hợp với tình hình tài chính hiện tại.", "Việc bà M ngăn cản khách hàng của anh D là chưa tôn trọng quyền tự do kinh doanh của người khác và bà M sẽ phải chịu trách nhiệm dân sự."], "a": [false, false, true, true], "e": "Đáp án: a) Sai; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx · Phần II câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D06-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Hiệp định thương mại Việt Nam - Hoa Kỳ chính thức có hiệu lực từ năm 2001. Trong quá trình thực hiện hai nước cũng phát sinh một số tranh chấp thương mại. Năm 2003, Ủy ban Thương mại quốc tế Hoa Kỳ đã ra phán quyết khẳng định các doanh doanh nghiệp chế biến cá tra, basa Việt Nam xuất hàng sang Hoa Kỳ bán phá giá, làm cho ngành công nghiệp cá nheo Hoa Kỳ bị ảnh hưởng nặng nề. Trước phán quyết này, Việt Nam đã kiện lên tổ chức WTO, sau nhiều lần xem xét các bằng chứng Việt Nam đưa ra, WTO đã ra phán quyết khẳng định các doanh nghiệp Việt Nam không bán phá giá và Hoa Kỳ cũng đã từng bước dỡ bỏ các hàng rào thuế quan đối với sản phẩm cá tra của Việt Nam.", "o": ["Hiệp định thương mại Việt Nam – Hoa Kỳ là thể hiện hình thức hợp tác kinh tế quốc tế song phương.", "Chỉ có Việt Nam và Hoa Kỳ là chủ thể của pháp luật quốc tế, còn WTO không có vai trò là chủ thể của pháp luật quốc tế.", "Việt Nam bị Ủy ban Thương mại Hoa Kỳ áp thuế chống bán phá giá chứng tỏ Việt Nam vi phạm nguyên tắc cạnh tranh công bằng trong quan hệ thương mại quốc tế.", "Hoa Kỳ sau khi xem xét các bằng chứng đã nghiêm túc tuân thủ phán quyết của WTO thể hiện nguyên tắc tận tâm, thiện chí trong quan hệ thương mại quốc tế."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx · Phần II câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D06-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Nhận thấy nhu cầu về sử dụng rau rạch của người dân ngày càng tăng, vợ chồng anh A và chị B quyết định nghỉ việc tại công ty để tiến hành hoạt động kinh doanh rau sạch. Từ số tiền tiết kiệm của hai vợ chồng và thế chấp ngôi nhà đang ở, anh chị đã mở một cửa hàng ngay tại thị trấn. Với phương châm đặt chất lượng lên hàng đầu, luôn cam kết với khách hàng về chất lượng sản phẩm vì vậy chỉ sau 2 năm đi vào hoạt động, cửa hàng của anh chị đã có một lượng khách hàng lớn tin tưởng và thường xuyên sử dụng sản phẩm do cửa hàng cung cấp. Lợi nhuận có được từ việc kinh doanh, ngoài việc trang trải chi phí sinh hoạt cho cả gia đình, anh chị còn tích cực tài trợ cho các hoạt động thiện nguyện giúp đỡ các học sinh có hoàn cảnh khó khăn. Để có nguồn nguyên liệu an toàn và ổn định, anh chị đã hướng dẫn cho bà con nông dân quy trình sản xuất rau sạch và cam kết bao tiêu sản phẩm nhờ đó không chỉ mang lại hiệu quả kinh doanh cho cửa hàng mà còn góp phần giải quyết nhiều việc làm cho lao động nông thôn.", "o": ["Phương châm đặt chất lượng sản phẩm lên hàng đầu, luôn cam kết với khách hàng về chất lượng sản phẩm là thể hiện việc phân tích các điều kiện kinh doanh.", "Cửa hàng kinh doanh của anh A và chị B ngày càng hoạt động hiệu quả có nguyên nhân chủ quan là vợ chồng anh chị luôn thực hiện tốt trách nhiệm kinh doanh.", "Việc giúp đỡ các học sinh có hoàn cảnh có khó khăn trong học tập l� phù hợp với trách nhiệm pháp lý của mỗi doanh nghiệp.", "Đánh giá đúng về yếu tố khách hàng và thị trường là yếu tố giúp anh A và chị B kinh doanh thành công. ----------- HẾT ----------."], "a": [false, true, false, true], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - ĐỀ SỐ 01.docx · Phần II câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}]}, {"id": "TN-D07", "loai": "tn", "khoi": 12, "hoc_ki": 2, "so_de": 7, "ten": "Đề luyện thi tốt nghiệp số 7", "pham_vi": "Đề nguồn của giáo viên, giữ NGUYÊN chữ của đề (chỉ bỏ lỗi sao chép) · Đề số 03 · file nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm 4 lựa chọn + 4 câu đúng/sai (mỗi câu 4 ý)", "cham": {"tong": 10, "tn": 0.25, "ds": [0, 0.1, 0.25, 0.5, 1.0]}, "status": "cho_duyet", "khoa": {"đã giải lại, khớp khoá": 28}, "sua": "CẦN CÔ XEM (em chưa chắc, KHÔNG sửa khoá): (1) Câu 16 («phát biểu sai về quyền và nghĩa vụ nộp thuế»): khoá B «được hoàn lại tiền thuế đã nộp nếu có đủ điều kiện» — theo pháp luật thuế vẫn có hoàn thuế nên ý B có vẻ đúng; em chưa chắc, giữ khoá của đề nguồn. (2) Câu 22 (công ty H xả thải, không bồi thường): khoá D «Pháp lý và kinh tế» — em nghĩ «Pháp lý và đạo đức» (B) hợp hơn; chưa chắc, giữ khoá. (3) Câu đúng/sai 2 ý c (hỗ trợ học phí cho hộ nghèo có phải «trợ giúp xã hội» không — khoá Đ; cũng có thể xếp vào «dịch vụ xã hội cơ bản»), câu đúng/sai 3 ý b (FDI diễn ra ở cả ba hình thức hợp tác — khoá S, em thấy ý này có thể đúng), câu đúng/sai 4 ý a (công ty P và B đều vi phạm nguyên tắc tuân thủ hợp đồng — khoá S, em thấy có thể đúng vì B giao hàng không đạt và P đơn phương chấm dứt): em chưa chắc, giữ khoá của đề nguồn.", "cau": [{"id": "TN-D07-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hoạt động nào dưới đây góp phần đưa sản phẩm từ nơi sản xuất đến với người tiêu dùng?", "o": ["Sản xuất.", "Tiêu dùng.", "Trao đổi.", "Thu nhập."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D07-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hoạt động nào dưới đây góp phần tạo ra hàng hóa, dịch vụ và thu được lợi nhuận?", "o": ["Hoạt động trung gian.", "Hoạt động tiêu dùng.", "Sản xuất kinh doanh.", "Giới thiệu việc làm."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx · Phần I câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D07-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Những quy tắc xử sự chung được áp dụng nhiều lần, ở nhiều nơi đối với tất cả mọi người, trong mọi lĩnh vực của đời sống xã hội là thể hiện đặc điểm nào dưới đây của pháp luật?", "o": ["Tính chặt chẽ về hình thức.", "Tính kỉ luật nghiêm minh.", "Tính quy phạm phổ biến.", "Tính quyền lực, bắt buộc chung."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D07-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong hệ thống các văn bản pháp luật Việt Nam, Hiến pháp được coi l�", "o": ["đạo luật cơ bản nhất.", "luật cụ thể nhất.", "luật dễ thay đổi nhất.", "luật thiếu tính ổn định."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx · Phần I câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D07-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi tỷ lệ thất nghiệp có chiều hướng gia tăng, giải pháp nào dưới đây của Nhà nước sẽ góp phần kiểm soát và kiềm chế thất nghiệp?", "o": ["Mở rộng hoạt động sản xuất.", "Tăng thuế với doanh nghiệp.", "Hạn chế xuất khẩu lao động.", "Xóa bỏ trợ cấp thất nghiệp."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx · Phần I câu 5 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D07-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong bối cảnh nền kinh tế nước ta hiện nay, xu hướng tuyển dụng lao động của các doanh nghiệp có nhiều thay đổi, lao động có đặc trưng nào dưới đây chiếm ưu thế trong tuyển dụng?", "o": ["Lao động được đào tạo.", "Lao động không qua đào tạo.", "Lao động giản đơn.", "lao động có trình độ thấp."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx · Phần I câu 6 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D07-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào dưới đây là sai về bình đẳng giới trong lĩnh vực gia đình?", "o": ["Các con cùng được giáo dục và phát triển.", "Con trai, con gái được bình đẳng trong chăm sóc.", "Các con đều có quyền ngang nhau về học tập.", "Con trai con gái được phân biệt khi nhận thừa kế."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D07-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào dưới đây không vi phạm quyền bất khả xâm phạm về chỗ ở của công dân?", "o": ["Khám xét trái pháp luật chỗ ở của người khác.", "Đuổi trái pháp luật người khác ra khỏi chỗ ở của họ.", "Chiếm giữ chỗ ở của người đang quản lý hợp pháp.", "Phá cửa để vào chỗ ở người khác dập vụ hỏa họa."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D07-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quyền tự do báo chí của công dân không bao gồm quyền nào dưới đây?", "o": ["Sáng tạo tác phẩm báo chí.", "Cung cấp thông tin báo chí.", "Xâm phạm thông tin báo chí.", "Phản hồi thông tin báo chí."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D07-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công ty A xây dựng các trang trại bò sữa theo tiêu chuẩn hiện đại nhất và chú trọng đào tạo, phát triển nguồn nhân lực chất lượng cao. Công ty B cũng đã ứng dụng quy trình sản xuất sữa tươi khép kín từ khâu nhập giống, nuôi dưỡng đến phân phối sản phẩm đến người tiêu dùng. Nguyên nhân dẫn tới sự cạnh tranh giữa công ty A và công ty B là do", "o": ["yêu cầu của cơ quan nhà nước.", "sự khác biệt về điều kiện sản xuất.", "sự khác biệt về tổ chức bộ máy.", "trình độ của người đứng đầu."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D07-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một cơ hội kinh doanh tốt là cơ hội đó phải có", "o": ["tính ràng buộc.", "tính ổn định.", "tính nhất thời.", "tính phổ biến."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D07-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Những người không chấp hành đúng quy định của pháp luật về đăng ký nghĩa vụ quân sự, không chấp hành lệnh gọi nhập ngũ mà đã bị xử phạt hành chính nếu còn vi phạm thì có thể bị xử phạt tù từ", "o": ["3 tháng đến 2 năm.", "3 tháng đến 5 năm.", "3 tháng đến 10 năm.", "3 tháng đến 20 năm."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx · Phần I câu 12 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D07-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Yếu tố nào dưới đây là chỉ tiêu của tăng trưởng kinh tế?", "o": ["Sự gia tăng dân số của một quốc gia.", "Mức tăng tổng sản phẩm quốc nội.", "Số lao động tham gia sản xuất.", "Tổng diện tích đất được sử dụng."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx · Phần I câu 13 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D07-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quá trình một quốc gia thực hiện việc gắn kết nền kinh tế của mình với nền kinh các quốc gia khác trong khu vực và trên thế giới dựa trên cơ sở cùng có lợi và tuân thủ quy định chung là nội dung của khái niệm nào dưới đây?", "o": ["Kinh tế đối ngoại.", "Hội nhập kinh tế.", "Phát triển kinh tế.", "Tăng trưởng kinh tế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D07-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những mục đích của việc thực hiện quản lý thu, chi trong gia đình là nhằm", "o": ["kiểm soát các nguồn thu trong gia đình.", "kiểm soát các khoản thu của con.", "kiểm soát các khoản chi của con.", "kiểm soát các khoản chi của người chồng."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D07-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào dưới đây là sai về quyền và nghĩa vụ của công dân về nộp thuế?", "o": ["Kê khai chính xác, trung thực là trách nhiệm của người nộp thuế.", "Nếu có đủ điều kiện công dân sẽ được hoàn lại tiền thuế đã nộp.", "Mọi công dân đều phải nghiêm chỉnh chấp hành việc nộp thuế.", "Khi quyền lợi hợp pháp bị xâm phạm công dân được khiếu nại về thuế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D07-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những nội dung của quyền bình đẳng trong hôn nhân và gia đình là vợ, chồng có quyền và nghĩa vụ ngang nhau trong việc", "o": ["định đoạt tài sản công cộng", "lựa chọn việc làm phù hợp.", "mở rộng quy mô sản xuất.", "đề xuất mức lương khởi điểm."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D07-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tổng hợp những người sinh sống, cư trú trên lãnh thổ của quốc gia, chịu sự quản lý bằng pháp luật của nhà nước ở quốc gia đó được gọi l�", "o": ["dân cư địa phương.", "dân cư quốc gia.", "dân số thổ cư.", "dân số nội địa."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D07-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 19, 20,21\nTrong quá trình phát triển kinh tế - xã hội, Đảng và Nhà nước ta rất chú trọng vào con người, nhất là những người nghèo, được dư luận quốc tế đánh giá là một trong những quốc gia điển hình trong việc thực hiện Mục tiêu Thiên niên kỷ về xóa đói, giảm nghèo. Theo chuẩn quốc gia, tỷ lệ hộ nghèo đã giảm từ 30% năm 1992 xuống còn 5,8% năm 2016; tính theo chuẩn nghèo tiếp cận đa chiều giảm từ 14,2% năm 2010 xuống còn 6,8% năm 2018, riêng các huyện nghèo giảm 4%. Đến nay, hầu hết các đối tượng chính sách xã hội, trẻ em dưới 6 tuổi, người nghèo, đồng bào dân tộc thiểu số ở các vùng khó khăn đã có bảo hiểm y tế; cấp thẻ bảo hiểm y tế cho trên 34,3 triệu người, hỗ trợ mua thẻ bảo hiểm y tế cho trên 15,1 triệu người. Người dân thụ hưởng những thành quả của tăng trưởng kinh tế, từ đó vươn lên thoát nghèo, cải thiện đời sống vật chất và tinh thần.\nTrong thông tin trên, nội dung nào dưới đây thể hiện trách nhiệm của công dân trong việc chính sách an sinh xã hội của nhà nước?", "o": ["Tự hào với thế giới vì đã thoát nghèo.", "Được cấp phát thẻ bảo hiểm miễn phí.", "Được thụ hưởng thành quả tăng trưởng.", "Tích cực chủ động vươn lên thoát nghèo."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D07-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 19, 20,21\nTrong quá trình phát triển kinh tế - xã hội, Đảng và Nhà nước ta rất chú trọng vào con người, nhất là những người nghèo, được dư luận quốc tế đánh giá là một trong những quốc gia điển hình trong việc thực hiện Mục tiêu Thiên niên kỷ về xóa đói, giảm nghèo. Theo chuẩn quốc gia, tỷ lệ hộ nghèo đã giảm từ 30% năm 1992 xuống còn 5,8% năm 2016; tính theo chuẩn nghèo tiếp cận đa chiều giảm từ 14,2% năm 2010 xuống còn 6,8% năm 2018, riêng các huyện nghèo giảm 4%. Đến nay, hầu hết các đối tượng chính sách xã hội, trẻ em dưới 6 tuổi, người nghèo, đồng bào dân tộc thiểu số ở các vùng khó khăn đã có bảo hiểm y tế; cấp thẻ bảo hiểm y tế cho trên 34,3 triệu người, hỗ trợ mua thẻ bảo hiểm y tế cho trên 15,1 triệu người. Người dân thụ hưởng những thành quả của tăng trưởng kinh tế, từ đó vươn lên thoát nghèo, cải thiện đời sống vật chất và tinh thần.\nTừ những số liệu trong thông tin trên, nhận định nào dưới đây không phải là nội dung của phát triển bền vững?", "o": ["Đảng và Nhà nước ta rất chú trọng vào con người, nhất là những người nghèo.", "Tỷ lệ hộ nghèo đa chiều đã giảm từ 30% năm 1992 xuống còn 5,8% năm 2016.", "Các đối tượng chính sách xã hội đã được cấp hoặc hỗ trợ mua bảo hiểm y tế.", "Quốc tế ghi nhận và xếp hạng các quốc gia thực hiện Mục tiêu Thiên niên."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx · Phần I câu 20 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D07-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 19, 20,21\nTrong quá trình phát triển kinh tế - xã hội, Đảng và Nhà nước ta rất chú trọng vào con người, nhất là những người nghèo, được dư luận quốc tế đánh giá là một trong những quốc gia điển hình trong việc thực hiện Mục tiêu Thiên niên kỷ về xóa đói, giảm nghèo. Theo chuẩn quốc gia, tỷ lệ hộ nghèo đã giảm từ 30% năm 1992 xuống còn 5,8% năm 2016; tính theo chuẩn nghèo tiếp cận đa chiều giảm từ 14,2% năm 2010 xuống còn 6,8% năm 2018, riêng các huyện nghèo giảm 4%. Đến nay, hầu hết các đối tượng chính sách xã hội, trẻ em dưới 6 tuổi, người nghèo, đồng bào dân tộc thiểu số ở các vùng khó khăn đã có bảo hiểm y tế; cấp thẻ bảo hiểm y tế cho trên 34,3 triệu người, hỗ trợ mua thẻ bảo hiểm y tế cho trên 15,1 triệu người. Người dân thụ hưởng những thành quả của tăng trưởng kinh tế, từ đó vươn lên thoát nghèo, cải thiện đời sống vật chất và tinh thần.\nTrong thông tin trên, nội dung nào dưới đây thể hiện kết quả của việc thực hiện các chính sách an sinh xã hội của Đảng và Nhà nước?", "o": ["Chú trọng xóa đói giảm nghèo.", "Cấp thẻ bảo hiểm cho trẻ dưới 6 tuổi.", "Tỷ lệ hộ nghèo đa chiều đã giảm.", "Hỗ trợ người dân mua bảo hiểm."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D07-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22,23,24\nCông ty H chuyên về khai thác khoáng sản trên địa bàn huyện V, trong quá trình hoạt động do thường xuyên xả thải chưa qua xử lý ra môi trường, ảnh hướng tới nguồn nước sinh hoạt của bà con vùng phụ cận. Gần đây, anh M thường xuyên bị đau đầu nên đã tới bệnh viện thăm khám và được kết luận l� mắc một khối u nguy hiểm cần phải phẫu thuật điều trị. Cho rằng nguyên nhân bị mắc bệnh là do sử dụng nguồn nước ô nhiễm do công ty H gây nên, anh M đã nhiều lần yêu cầu công ty bồi thường nhưng không chấp nhận. Bức xúc, anh M đã làm đơn tố cáo tới cơ quan chức năng, khiến công ty H bị đình chỉ hoạt động. Cũng trong thời gian đó, anh M được phòng công tác xã hội bệnh viện tỉnh P hỗ trợ 50% kinh phí để điều trị, nên căn bệnh của anh M đã có tiến triển, sức khỏe đã từng bước ổn định.\nThông tin trên cho thấy công ty H chưa thực hiện đúng những trách nhiệm xã hội nào dưới đây?", "o": ["Kinh tế và đạo đức.", "Pháp lý và đạo đức.", "Nhân văn và đạo đức.", "Pháp lý và kinh tế."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D07-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22,23,24\nCông ty H chuyên về khai thác khoáng sản trên địa bàn huyện V, trong quá trình hoạt động do thường xuyên xả thải chưa qua xử lý ra môi trường, ảnh hướng tới nguồn nước sinh hoạt của bà con vùng phụ cận. Gần đây, anh M thường xuyên bị đau đầu nên đã tới bệnh viện thăm khám và được kết luận l� mắc một khối u nguy hiểm cần phải phẫu thuật điều trị. Cho rằng nguyên nhân bị mắc bệnh là do sử dụng nguồn nước ô nhiễm do công ty H gây nên, anh M đã nhiều lần yêu cầu công ty bồi thường nhưng không chấp nhận. Bức xúc, anh M đã làm đơn tố cáo tới cơ quan chức năng, khiến công ty H bị đình chỉ hoạt động. Cũng trong thời gian đó, anh M được phòng công tác xã hội bệnh viện tỉnh P hỗ trợ 50% kinh phí để điều trị, nên căn bệnh của anh M đã có tiến triển, sức khỏe đã từng bước ổn định.\nTrong thông tin trên, việc làm nào dưới đây vừa vi phạm quyền v� nghĩa vụ của công dân trong kinh doanh vừa vi phạm quyền và nghĩa vụ của công dân trong bảo vệ tài nguyên và môi trường?", "o": ["Từ chối bồi thường vì chưa có căn cứ pháp lý.", "Xả chất thải chưa qua xử lý ra môi trường.", "Bị tố cáo về hành vi vi phạm trong kinh doanh.", "Không thực hiện tốt trách nhiệm nhân đạo, từ thiện."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D07-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22,23,24\nCông ty H chuyên về khai thác khoáng sản trên địa bàn huyện V, trong quá trình hoạt động do thường xuyên xả thải chưa qua xử lý ra môi trường, ảnh hướng tới nguồn nước sinh hoạt của bà con vùng phụ cận. Gần đây, anh M thường xuyên bị đau đầu nên đã tới bệnh viện thăm khám và được kết luận l� mắc một khối u nguy hiểm cần phải phẫu thuật điều trị. Cho rằng nguyên nhân bị mắc bệnh là do sử dụng nguồn nước ô nhiễm do công ty H gây nên, anh M đã nhiều lần yêu cầu công ty bồi thường nhưng không chấp nhận. Bức xúc, anh M đã làm đơn tố cáo tới cơ quan chức năng, khiến công ty H bị đình chỉ hoạt động. Cũng trong thời gian đó, anh M được phòng công tác xã hội bệnh viện tỉnh P hỗ trợ 50% kinh phí để điều trị, nên căn bệnh của anh M đã có tiến triển, sức khỏe đã từng bước ổn định.\nViệc anh M được phòng công tác xã hội bệnh viện tỉnh P hỗ trợ 50% kinh phí điều trị bệnh là góp phần đảm bảo công dân được thực hiện quyền", "o": ["đảm bảo an sinh xã hội.", "chăm sóc sức khỏe.", "bảo vệ môi trường sống.", "đóng bảo hiểm y tế."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D07-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Cuối năm là thời điểm công việc bận rộn, nhiều gia đình chú tâm hơn trong việc thờ cúng. Nắm bắt xu thế này, chị H đã mở dịch vụ cung cấp đồ thờ cúng trọn gói ngay tại nhà. Để có nguồn hàng ổn định, chị đã chủ động kết nối với nhiều hộ sản xuất trong vùng để có được những sản phẩm chất lượng. Các dịch vụ giao hành nhanh cũng đã cam kết với chị về việc giao hàng uy tín và kịp thời. Ngoài ra để có nhân lực đóng gói sản phẩm, chị H đã thuê các bạn sinh viên làm việc theo giờ và bán thời gian một cách linh hoạt để vừa có thu nhập vừa giúp chị kịp đơn hàng giao cho khách. Do không phải thuê mặt bằng và đăng ký kinh doanh cũng như thực hiện nghĩa vụ thuế nên lợi nhuận thu được từ hoạt động kinh doanh của chị H khá hiệu quả. Bên cạnh việc giải quyết việc làm cho các đối tượng khác nhau, chị H luôn thanh toán tiền hàng, lương thưởng kịp thời cho người lao động nên họ cũng yên tâm và cam kết gắn bó với chị H.", "o": ["Chị H quyết định kinh doanh đồ thờ cúng vào dịp cuối năm là thể hiện việc xác định ý tưởng kinh doanh.", "Vì kinh doanh tại nhà nên chị H không cần đăng ký kinh doanh cũng như không cần kê khai hồ sơ với cơ quan thuế.", "Vì thuê theo giờ và bán thời gian nên chị H không có nghĩa vụ thực hiện các chế độ về bảo hiểm xã hội, bảo hiểm thất nghiệp và y tế cho người lao động là phù hợp.", "Các hộ gia đình nên cùng chị H liên kết hình thành hợp tác xã vì như vậy sẽ tận dụng được thế mạnh của nhau và mang lại thu nhập ổn định."], "a": [true, false, true, true], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx · Phần II câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D07-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Gia đình anh G thuộc hộ nghèo sinh sống trên địa bàn xã X, đời sống gặp rất nhiều khó khăn do vợ anh bị mắc bệnh hiểm nghèo, hai con còn nhỏ, thu nhập của gia đình hoàn toàn phụ thuộc vào lao động làm thuê của anh G. Nắm bắt được hoàn cảnh đó, chính quyền xã đã tích cực vận động các tổ chức đoàn thể chung tay giúp đỡ. Các con của anh G ngoài việc được miễn toàn bộ tiền học phí theo quy định, hàng tháng còn nhận được một số tiền trợ cấp. Chị M vợ anh được cấp phát thẻ bảo hiểm y tế để khám chữa bệnh. Ngoài ra ngân hàng chính sách xã hội đã tạo điều kiện để anh G vay vốn ưu đãi để phát triển kinh tế gia đình. Với sự giúp đỡ này, bản thân anh G cùng các thành viên trong gia đình đã không ngững cố gắng nỗ lực vượt qua khó khăn nhờ đó cuộc sống của gia đình đã từng bước ổn định.", "o": ["Chính sách miễn học phí cho đối tượng hộ nghèo, cận nghèo là góp phần thực hiện quyền của công dân về học tập.", "Tất cả những người bị mắc bệnh hiểm nghèo đều được cấp thẻ bảo hiểm y tế là thể hiện quyền của công dân về chăm sóc sức khỏe.", "Hỗ trợ học phí và chi phí học tập cho con em các hộ nghèo là nội dung của chính sách trợ giúp xã hội trong hệ thống chính sách an sinh xã hội của nhà nước ta.", "Gia đình anh G thực hiện chưa tốt trách nhiệm của công dân đối với các chính sách an sinh xã hội của nhà nước."], "a": [true, false, true, false], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx · Phần II câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D07-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Hiệp định thương mại tự do Việt Nam – Hàn Quốc (VKFTA) được ký kết ngày 5/5/2015 và chính thức có hiệu lực từ ngày 20/12/2015, hiệp định đã mở ra cơ hội thu hút vốn đầu tư nước ngoài từ các doanh nghiệp Hàn Quốc vào Việt Nam. Tính đến nay tập đoàn S đã đầu tư Việt Nam đạt khoảng trên 17 tỷ USD, hàng năm tạo ra trên 170.000 việc làm với mức thu nhập ổn định. Đến nay, tập đoàn S đã xuất khẩu 54,4 tỷ USD, chiếm 25,4% kim ngạch xuất khẩu của cả nước. Bên cạnh đó tập đoàn S luôn chú trọng đến yếu tố con người, ngoài những quy định liên quan đến vấn đề nghỉ ngơi xen kẽ giờ làm việc cho toàn thể nhân viên, tập đoàn còn đưa ra giải pháp đó là, trong 8 tiếng làm việc chính thức của nhân viên, cứ sau 2 giờ, những nhân viên làm việc trực tiếp tại xưởng sản xuất lại có 10 phút giải lao tại xưởng. Thời gian nghỉ để ăn giữa ca là 60 phút, hàng năm tất cả các nhân viên đều được tham gia chương trình khám sức khỏe tổng quát định kỳ.", "o": ["Hiệp định thương mại tự do Việt Nam – Hàn Quốc là biểu hiện của hình thức hợp tác song phương..", "Đầu tư trực tiếp nước ngoài FDI diễn ra ở cả hình thức hợp tác song phương, khu vực và toàn cầu..", "Coi trọng yếu tố con người trong phát triển là phù hợp với trách nhiệm đạo đức của doanh nghiệp.", "Công ty S đã thực hiện tốt quyền của công dân trong bảo vệ và chăm sóc sức khỏe."], "a": [true, false, true, true], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx · Phần II câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D07-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Năm 2012, Công ty P (Trụ sở thương mại tại Việt Nam) đã kí hợp đồng nhập khẩu giấy phế liệu với Công ty B (Trụ sở thương mại tại Hàn Quốc), số lượng 1.000 tấn, đơn giá 235 USD/tấn, tổng giá trị hợp đồng là 235 000 USD, giá được tính tại cầu cảng của nước nhập khẩu là Hải Phòng, đã bao gồm các chi phí bảo hiểm, vận chuyển tới cảng đích đến. Về phẩm chất hàng hoá, hai bên thoả thuận, giấy phế liệu phải đảm bảo độ ẩm không quá 12% và một số điều kiện khác về hợp chất. Tuy nhiên, do nghi ngờ về độ ẩm của sản phẩm, Công ty P đã đề nghị VinaControl giám định chất lượng của lô hàng. Kết quả là 15/20 container lô hàng thứ nhất không đạt chất lượng về độ ẩm như cam kết trong hợp đồng trước đó, vì vậy công ty P đã đơn phương chấm dứt hợp đồng và không nhận hàng khiến công ty B bị thiệt hại nặng.", "o": ["Công ty P và công ty B đều vi phạm nguyên tắc tuân thủ hợp đồng đã ký kết.", "Công ty P có quyền khởi kiện công ty B và yêu cầu bồi thường thiệt hại theo quy định.", "Việc công ty P đề nghị công ty VinaControl giám định chất lượng của lô hàng đối với công ty B là vi phạm nguyên tắc thiện chí trung thực.", "Công ty B không có quyền kháng cáo kết quả kiểm định của công ty P vì công ty B vi phạm hợp đồng trước. ---------- HẾT ---------."], "a": [false, true, false, false], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Sai.", "nguon": "Đề nguồn: 13_ĐỀ GV (có đáp án) - ĐỀ SỐ 03.docx · Phần II câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}]}, {"id": "TN-D08", "loai": "tn", "khoi": 12, "hoc_ki": 2, "so_de": 8, "ten": "Đề luyện thi tốt nghiệp số 8", "pham_vi": "Đề nguồn của giáo viên, giữ NGUYÊN chữ của đề (chỉ bỏ lỗi sao chép) · Đề số 04 · file nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm 4 lựa chọn + 4 câu đúng/sai (mỗi câu 4 ý)", "cham": {"tong": 10, "tn": 0.25, "ds": [0, 0.1, 0.25, 0.5, 1.0]}, "status": "cho_duyet", "khoa": {"đã giải lại, khớp khoá": 27, "đã tự giải lại": 1}, "sua": "Câu 12 («tự ý bắt người, giam giữ người không theo quy định của pháp luật là xâm phạm quyền nào của công dân»): đề nguồn ghi khoá B «Bất khả xâm phạm về thư tín» (gạch chân và file ĐÁP ÁN cùng ghi B), nhưng bắt, giam giữ người trái pháp luật xâm phạm quyền bất khả xâm phạm về THÂN THỂ (C); em tự giải lại và sửa khoá thành C (tự tin trên 95%, SGK Kết nối tri thức).", "cau": [{"id": "TN-D08-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong nền kinh tế hàng hóa, chủ thể nào dưới đây là các cá nhân, tổ chức đóng vai trò cầu nối giữa người sản xuất với người tiêu dùng?", "o": ["Chủ thể sản xuất.", "Chủ thể nhà nước", "Chủ thể tiêu dùng.", "Chủ thể trung gian."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D08-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mô hình sản xuất kinh doanh nào dưới đây mà các cổ đông tham gia công ty đó chỉ chịu trách nhiệm về các khoản nợ và nghĩa vụ tài sản của doanh nghiệp trong phạm vi số vốn đã góp vào doanh nghiệp?", "o": ["Công ty tư nhân.", "Công ty cổ phần.", "Công ty hợp danh.", "Công ty nhà nước."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx · Phần I câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D08-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Cá nhân, tổ chức không làm những điều mà pháp luật cấm là thực hiện pháp luật theo hình thức", "o": ["áp dụng pháp luật.", "tuân thủ pháp luật.", "sử dụng pháp luật.", "thi hành pháp luật."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D08-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công dân được tham gia bầu cử và ứng cử vào Quốc hội là thực hiện tốt quyền con người trên lĩnh vực nào dưới đây?", "o": ["Chính trị.", "Kinh tế.", "Văn hóa.", "Xã hội."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx · Phần I câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D08-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong bối cảnh khan hiếm nguồn nguyên liệu, giá cả các yếu tố sản xuất tăng cao, một số doanh nghiệp phải tăng chi phí để mua đủ nguyên liệu phục vụ sản xuất, một số doanh nghiệp khác chấp nhận tình trạng sản xuất gián đoạn do không chuẩn bị đủ nguyên liệu đầu vào. Các doanh nghiệp chấp nhận thu hẹp nguồn cung là do sự ảnh hưởng của yếu tố nào dưới đây?", "o": ["Giá cả các yếu tố sản xuất.", "Cầu về nguồn nguyên liệu.", "Thị hiếu người sản xuất.", "Kỳ vọng của doanh nghiệp."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx · Phần I câu 5 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D08-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong bối cảnh cuộc cách mạng công nghiệp 4.0, ngành X đang đổi mới công nghệ sản xuất, ứng dụng tin học trong quản lí, đưa máy móc tự động hoá vào sản xuất, điều này làm cho nhu cầu lao động của ngành X giảm, nhiều lao động trong ngành X phải nghỉ việc, rơi vào tình trạng thất nghiệp. Điều này phản ánh loại hình thất nghiệp", "o": ["tạm thời.", "cơ cấu.", "chu kỳ.", "tự nguyện."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx · Phần I câu 6 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D08-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Các quan hệ thỏa thuận giữa người sử dụng sức lao động và người lao động về tiền lương, điều kiện làm việc trên cơ sở của hợp đồng lao động được diễn ra ở", "o": ["thị trường lao động.", "thị trường tài chính.", "thị trường tiền tệ.", "thị trường công nghệ"], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D08-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tập hợp những điều kiện, hoàn cảnh thuận lợi để thực hiện được mục tiêu kinh doanh sẽ góp phần tạo ra các", "o": ["sản phẩm kinh doanh.", "cơ hội kinh doanh.", "năng lực kinh doanh.", "chủ thể kinh doanh."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D08-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Các dân tộc trên lãnh thổ Việt Nam nếu có đủ điều kiện đều được tham gia vào bộ máy nhà nước là thể hiện quyền bình đẳng giữa các dân tộc trên lĩnh vực", "o": ["lao động.", "kinh tế.", "kinh doanh.", "chính trị."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D08-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo Luật Bình đẳng giới năm 2006, nam, nữ được đối xử bình đẳng trong việc thành lập doanh nghiệp là thuộc quyền bình đẳng giới trong lĩnh vực nào sau đây?", "o": ["Chính trị.", "Kinh tế.", "Lao động.", "Y tế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D08-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, việc Ủy ban nhân dân xã Y tổ chức lấy ý kiến của người dân về kế hoạch lắp đặt hệ thống loa phát thanh ở địa phương là thực hiện nội dung quyền dân chủ nào dưới đây của công dân?", "o": ["Độc lập phán quyết.", "Tham gia quản lí nhà nước và xã hội.", "Tự do ngôn luận.", "Chủ động kiểm toán ngân sách quốc gia."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D08-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi tự ý bắt người, giam giữ người không theo quy định của pháp luật là đã xâm phạm đến quyền nào dưới đây của công dân?", "o": ["Bất khả xâm phạm về chỗ ở.", "Bất khả xâm phạm về thư tín.", "Bất khả xâm phạm về thân thể.", "Bất khả xâm phạm về thông tin."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx · Phần I câu 12 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D08-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào dưới đây là sai về phát triển kinh tế?", "o": ["Phát triển kinh tế là quá trình tăng tiến về mọi mặt của nền kinh tế.", "Muốn phát triển kinh tế cần thúc đẩy tăng trưởng kinh tế với tốc độ cao.", "Mục tiêu cuối cùng của phát triển kinh tế là xây dựng cơ cấu kinh tế hiện đại.", "Phát triển kinh tế góp phần giảm bớt chệnh lệch trình độ các vùng miền."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx · Phần I câu 13 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D08-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào dưới đây là sai về sự cần thiết của hội nhập kinh tế quốc tế?", "o": ["Hội nhập kinh tế quốc tế giúp các quốc gia tận dụng được các nguồn lực bên ngoài để phát triển", "Hội nhập kinh tế quốc tế góp phần mở rộng thị trường để thúc đẩy sản xuất trong nước.", "Hội nhập kinh tế quốc tế giúp nền kinh tế quốc gia phát triển bền vững.", "Hội nhập kinh tế quốc tế làm cho nền kinh tế quốc gia ngày càng phụ thuộc vào bên ngoài."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D08-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Loại hình bảo hiểm do Nhà nước tổ chức nhằm bảo đảm thay thế hoặc bù đắp một phần thu nhập của người lao động khi họ bị giảm hoặc mất thu nhập do ốm, đau, thai sản, tai nạn lao động, bệnh nghề nghiệp, hết tuổi lao động dựa trên cơ sở mức đóng vào quỹ bảo hiểm xã hội của người lao động trước đó là loại hình bảo hiểm nào dưới đây?", "o": ["Bảo hiểm xã hội.", "Bảo hiểm dân sự.", "Bảo hiểm con người.", "Bảo hiểm thương mại."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D08-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không phản ánh sự cần thiết phải quản lí thu, chi trong gia đình?", "o": ["Tăng số tiền mặt cho hoạt động mua sắm hằng ngày.", "Tăng chất lượng cuộc sống của gia đình.", "Kiểm soát được nguồn thu, chi trong gia đình.", "Dự phòng cho các trường hợp khẩn cấp và tương lai."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D08-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quyền bán, trao đổi, tặng cho, cho vay, để thừa kế, từ bỏ quyền sở hữu, tiêu dùng hoặc tiêu huỷ tài sản là quyền nào của chủ sở hữu?", "o": ["Quyền định đoạt.", "Quyền tự quyết định.", "Quyền chiếm hữu.", "Quyền sử dụng."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D08-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Vùng biển nào dưới đây mà các quốc gia ven biển có chủ quyền hoàn toàn, tuyệt đối và đầy đủ giống như trên đất liền?", "o": ["Vùng thềm lục địa.", "Vùng nội thủy.", "Vùng lãnh hải.", "Vùng tiếp lãnh hải."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D08-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 19,20,21\nCông ty A chuyên về sản xuất và kinh doanh các sản phẩm gỗ và nội thất. Trước khi đưa ra thị trường một sản phẩm mới, công ty luôn chủ động khảo sát nhu cầu và thị hiếu người tiêu dùng. Thông qua việc ứng dụng công nghệ thông tin, công ty đã thiết lập được kênh thông tin giữa công ty với người tiêu dùng, chủ động và kịp thời xử lý các vấn đề phát sinh của khách hàng trong quá trình sử dụng sản phẩm. Hàng năm công ty chủ động xây dựng báo cáo đánh giá tác động môi trường gửi đến các cơ quan chức năng phê duyệt, đặc biệt định kỳ hàng tháng công ty đã tổ chức kiểm định chất lượng không khí, nguồn nước thải khu vực dân cư sinh sống cạnh nhà máy để có đánh giá và điều chỉnh kịp thời. Chính những việc làm này đã góp phần nâng cao uy tín và vị thế của công ty, giúp công ty không ngừng lớn mạnh và phát triển.\nTrong thông tin trên, nội dung nào dưới đây thể hiện việc xác định chiến lược kinh doanh của công ty A?", "o": ["Khảo sát thị trường trước khi bán.", "Ứng dụng công nghệ thông tin.", "Luôn duy trì mối quan hệ với khách hàng", "Có báo cáo đánh giá tác động về môi trường."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D08-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 19,20,21\nCông ty A chuyên về sản xuất và kinh doanh các sản phẩm gỗ và nội thất. Trước khi đưa ra thị trường một sản phẩm mới, công ty luôn chủ động khảo sát nhu cầu và thị hiếu người tiêu dùng. Thông qua việc ứng dụng công nghệ thông tin, công ty đã thiết lập được kênh thông tin giữa công ty với người tiêu dùng, chủ động và kịp thời xử lý các vấn đề phát sinh của khách hàng trong quá trình sử dụng sản phẩm. Hàng năm công ty chủ động xây dựng báo cáo đánh giá tác động môi trường gửi đến các cơ quan chức năng phê duyệt, đặc biệt định kỳ hàng tháng công ty đã tổ chức kiểm định chất lượng không khí, nguồn nước thải khu vực dân cư sinh sống cạnh nhà máy để có đánh giá và điều chỉnh kịp thời. Chính những việc làm này đã góp phần nâng cao uy tín và vị thế của công ty, giúp công ty không ngừng lớn mạnh và phát triển.\nCông ty A đã thực hiện tốt nghĩa vụ bảo vệ môi trường ở nội dung nào dưới đây?", "o": ["Tố cáo các hành vi vi phạm về môi trường.", "Đóng góp kinh phí để bảo vệ môi trường.", "Xử lý các hành vi vi phạm về môi trường.", "Chấp hành quy định về bảo vệ môi trường"], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx · Phần I câu 20 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D08-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 19,20,21\nCông ty A chuyên về sản xuất và kinh doanh các sản phẩm gỗ và nội thất. Trước khi đưa ra thị trường một sản phẩm mới, công ty luôn chủ động khảo sát nhu cầu và thị hiếu người tiêu dùng. Thông qua việc ứng dụng công nghệ thông tin, công ty đã thiết lập được kênh thông tin giữa công ty với người tiêu dùng, chủ động và kịp thời xử lý các vấn đề phát sinh của khách hàng trong quá trình sử dụng sản phẩm. Hàng năm công ty chủ động xây dựng báo cáo đánh giá tác động môi trường gửi đến các cơ quan chức năng phê duyệt, đặc biệt định kỳ hàng tháng công ty đã tổ chức kiểm định chất lượng không khí, nguồn nước thải khu vực dân cư sinh sống cạnh nhà máy để có đánh giá và điều chỉnh kịp thời. Chính những việc làm này đã góp phần nâng cao uy tín và vị thế của công ty, giúp công ty không ngừng lớn mạnh và phát triển.\nTrong thông tin trên, công ty A đã thực hiện tốt những trách nhiệm xã hội nào dưới đây?", "o": ["Kinh tế, nhân đạo và đạo đức.", "Kinh tế, pháp lý và nhân văn.", "Đạo đức, kinh tế và pháp lý.", "Pháp lý, nhân văn và đạo đức."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D08-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22,23,24\nNước X và Y kí kết với nhau hiệp định đầu tư, theo đó nhà đầu tư của nước X và nước Y được hưởng những quyền lợi, ưu đãi và thực hiện những nghĩa vụ trên lãnh thổ của nhau như các nhà đầu tư trong nước mình, không có sự phân biệt đối xử nào. Tuy nhiên, nước X sau đó ban hành luật trái với hiệp định đã kí kết, trong đó hạn chế một số ưu đãi của nhà đầu tư nước Y trên lãnh thổ của mình.\nNhà đầu tư của nước X và nước Y được hưởng những quyền lợi, ưu đãi và thực hiện những nghĩa vụ trên lãnh thổ của nhau như các nhà đầu tư trong nước mình, không có sự phân biệt đối xử nào là thể hiện chế độ", "o": ["đối xử tối huệ quốc.", "đối xử đặc biệt.", "đối xử quốc gia.", "đối xử qua lại."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D08-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22,23,24\nNước X và Y kí kết với nhau hiệp định đầu tư, theo đó nhà đầu tư của nước X và nước Y được hưởng những quyền lợi, ưu đãi và thực hiện những nghĩa vụ trên lãnh thổ của nhau như các nhà đầu tư trong nước mình, không có sự phân biệt đối xử nào. Tuy nhiên, nước X sau đó ban hành luật trái với hiệp định đã kí kết, trong đó hạn chế một số ưu đãi của nhà đầu tư nước Y trên lãnh thổ của mình.\nHiệp định đầu tư giữa nước X và nước Y là thể hiện hình thức hội nhập kinh tế quốc tế", "o": ["song phương.", "khu vực.", "toàn cầu.", "toàn diện."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D08-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22,23,24\nNước X và Y kí kết với nhau hiệp định đầu tư, theo đó nhà đầu tư của nước X và nước Y được hưởng những quyền lợi, ưu đãi và thực hiện những nghĩa vụ trên lãnh thổ của nhau như các nhà đầu tư trong nước mình, không có sự phân biệt đối xử nào. Tuy nhiên, nước X sau đó ban hành luật trái với hiệp định đã kí kết, trong đó hạn chế một số ưu đãi của nhà đầu tư nước Y trên lãnh thổ của mình.\nNước X ban hành luật trái với hiệp định đã ký kết là vi phạm nguyên tắc nào dưới đây của pháp luật quốc tế?", "o": ["Nguyên tắc bình đẳng về chủ quyền các nước.", "Nguyên tắc tận tâm, thiện chí thực hiện cam kết.", "Nguyên tắc giải quyết bằng biện pháp hòa bình.", "Nguyên tắc không can thiệp công việc nội bộ"], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D08-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Với dự kiến sẽ mua được nhà và ra ở riêng sau 3 năm kết hôn vì vậy anh D và chị H đã chủ động chi tiêu tiết kiệm cũng như làm thêm để bổ sung vào thu nhập của gia đình. Tuy nhiên, một thời sau đó chị H mang thai v� sinh con nhỏ khiến kế hoạch của anh chị có sự điều chỉnh. Ngoài khoản tiền tiết kiệm để mua nhà, anh chị dành phần lớn các khoản thu nhập để chi tiêu gia đình và con nhỏ. Vốn có hiểu biết về bán hàng qua mạng vì vậy sau khi sinh chị H quyết định nghỉ làm để có thời gian chăm con, kết hợp bán hàng trực tuyến để tăng thu nhập. Dựa vào vốn kiến thức đã học về thảo dược, chị H kinh doanh các loại mỹ phẩm có nguồn gốc từ thiên nhiên và được rất nhiều khách hàng tin tưởng. Lợi nhuận có được từ việc kinh doanh trực tuyến vừa giúp chị bổ sung vào các khoản chi tiêu ngày càng tăng do thêm thành viên mới. Được sự tư vấn của anh D, chị H đã mua một gói bảo hiểm an sinh xã hội trả góp hàng năm để vừa tiết kiệm lâu dài vừa đề phòng lúc con ốm đau phải điều trị.", "o": ["Kế hoạch thu chi của gia đình anh D và chị H bao gồm: Xác định mục tiêu, phân bổ thu nhập và thực hiện kế hoạch.", "Gói bảo hiểm mà chị H mua cho con là loại hình bảo hiểm xã hội do nh� nước là chủ thể tổ chức.", "Chị H phải nghỉ việc để ở nhà chăm con và bán hàng qua mạng là không phù hợp với quyền và nghĩa vụ của công dân trong hôn nhân gia đình, vì anh D không có sự giúp đỡ hỗ trợ cho vợ.", "Chị H có thể bị xử phạt hành chính và bồi thường về mặt dân sự về hành vi kinh doanh không có giấy phép và kinh doanh các ngành nghề có điều kiện."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D08-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Sau 40 năm thực hiện công cuộc Đổi mới, đến nay Việt Nam đã có hơn 930.000 doanh nghiệp đang hoạt động. Năm 2023, các doanh nghiệp đã đóng góp khoảng 60% GDP, tạo ra 30% nguồn thu ngân sách nhà nước, thu hút 85% lực lượng lao động. Bên cạnh vai trò là động lực quan trọng của nền kinh tế đất nước, khu vực doanh nghiệp cũng đóng góp tích cực trong việc thực hiện có hiệu quả đường lối chính sách của Đảng và Nhà nước về an sinh xã hội, giữ gìn bản sắc văn hóa truyền thống, khắc phục hậu quả thiên tai, dịch bệnh, chăm lo đời sống vật chất tinh thần cho nhân dân. Đồng thời góp phần bảo đảm an ninh năng lượng, an ninh lương thực, củng cố an ninh quốc phòng v� giữ vững độc lập, tự chủ của nền kinh tế trong xu thế toàn cầu hóa và hội nhập quốc tế ngày càng sâu rộng.", "o": ["Sự tăng trưởng của các doanh nghiệp là một trong những chỉ tiêu để đánh giá sự tăng trưởng kinh tế của nước ta.", "Việc thực hiện trách nhiệm xã hội của doanh nghiệp là yếu tố quyết định đến việc thực hiện chính sách an sinh xã hội của nhà nước.", "Thực hiện tốt trách nhiệm xã hội của doanh nghiệp là yếu tố cơ bản để tạo nên sự phát triển bền vững của đất nước.", "Ở nước ta mọi doanh nghiệp đều được tự do kinh doanh những ngành nghề mà doanh nghiệp có nhu cầu nhưng phải thực hiện tốt nghĩa vụ nộp thuế."], "a": [false, false, true, false], "e": "Đáp án: a) Sai; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D08-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Sau khi bàn bạc, anh M cùng các thành viên trong gia đình quyết định mở cửa hàng kinh doanh thực phẩm hữu cơ ngay tại nhà. Qua khảo sát thị trường, sản phẩm, khách hàng và các đối thủ cạnh tranh cho thấy: Xu hướng của người tiêu dùng ở khu vực này đang quan tâm đến việc ăn uống lành mạnh và thực phẩm hữu cơ. Thị trường ở đây đã có một vài cửa hàng thực phẩm, nhưng chưa có cửa hàng nào tập trung hoàn toàn vào thực phẩm hữu cơ. Để thực hiện kế hoạch này, anh M sử dụng toàn bộ số tiền tiết kiệm của hai vợ chồng để cải tạo cửa hàng và nhập nguyên vật liệu. Ngoài thời gian đi học, các con của anh M học lớp 8 và lớp 11 cũng tham gia hỗ trợ bố mẹ đóng hàng và giao hàng. Sau một thời gian hoạt động, cửa hàng của anh M bước đầu tạo dựng được uy tín và thương hiệu với khách hàng. Thu nhập có được từ kinh doanh ngoài việc đầu tư trở lại cửa hàng, anh M đã bổ sung vào các khoản chi tiêu của gia đình.", "o": ["Thông tin nói về ý tưởng kinh doanh thực phẩm hữu cơ.", "Kế hoạch kinh doanh của anh M theo tiến trình đó là: Khảo sát thị trường, xây dựng mục tiêu, thực hiện kế hoạch và điều chỉnh quy mô.", "Anh M sử dụng sức lao động của các con chưa thành niên là vi phạm nghĩa vụ của công dân trong kinh doanh và trong hôn nhân gia đình.", "Vì kinh doanh hộ gia đình nên anh M cùng các thành viên không cần phải thực hiện nghĩa vụ kê khai và nộp thuế."], "a": [true, false, false, false], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Sai.", "nguon": "Đề nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D08-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Gia đình bà M kinh doanh dịch vụ nhà trọ cho công nhân trên địa bàn huyện X. Do đầu tư vào kinh doanh trực tuyến bị thất bại, bà M đã bán toàn bộ mảnh đất cùng các giá trị tài sản trên đất cho anh H. Sau khi tiếp nhận lại từ bà M, anh H đã cải tạo lại một phần diện tích khu sinh hoạt chung của các phòng trọ, đồng thời thông báo về việc tăng giá thuê phòng và tiền dịch vụ điện nước khiến nhiều hộ gia đình rất bức xúc và không đồng ý. Nhiều lần liên lạc với bà M không được, chị D một công nhân thuê trọ đã viết bài xuyên tạc bà M và anh H cấu kết để làm ăn phi pháp sau đó đăng lên mạng xã hội khiến uy tín của anh H bị suy giảm. Yêu cầu chị D gỡ bài không được, anh H đã đập phá đồ đạc đồng thời đuổi chị D ra khỏi phòng trọ v� chấm dứt hợp đồng với chị D.", "o": ["Theo quy định của pháp luật, bà M và anh H đồng thời là chủ sở hữu hợp pháp đối với các phòng trọ đang cho thuê.", "Anh H có quyền chiếm hữu, sử dụng và định đoạt đối với tất cả các tài sản mà bà M đã chuyển giao cho mình.", "Các gia đình thuê phòng trọ của anh H cần điều chỉnh lại kế hoạch thu chi trong gia đình theo đó tăng khoản chi tiêu thiết yếu, giảm khoản tiết kiệm để phù hợp với thực tế.", "Anh H đuổi chị D ra khỏi phòng trọ mà chị đã thuê không vi phạm nghĩa vụ tôn trọng tài sản của công dân vì đây là phòng trọ do anh H là chủ sở hữu."], "a": [false, true, true, false], "e": "Đáp án: a) Sai; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 14_ĐỀ GV (có đáp án) - ĐỀ SỐ 04.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}]}, {"id": "TN-D09", "loai": "tn", "khoi": 12, "hoc_ki": 2, "so_de": 9, "ten": "Đề luyện thi tốt nghiệp số 9", "pham_vi": "Đề nguồn của giáo viên, giữ NGUYÊN chữ của đề (chỉ bỏ lỗi sao chép) · ĐS2 KTPL 12 nộp Sở 2026 · file nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm 4 lựa chọn + 4 câu đúng/sai (mỗi câu 4 ý)", "cham": {"tong": 10, "tn": 0.25, "ds": [0, 0.1, 0.25, 0.5, 1.0]}, "status": "cho_duyet", "khoa": {"đã giải lại, khớp khoá": 28}, "sua": "", "cau": [{"id": "TN-D09-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi phân tích yếu tố về khách hàng để lập kế hoạch kinh doanh, các chủ thể không cần quan tâm đến nội dung nào dưới đây?", "o": ["Mong muốn khách hàng.", "Địa điểm làm việc.", "Giới tính khách hàng.", "Thu nhập hàng tháng."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx · Phần I câu 1 · khoá: gạch chân · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D09-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Doanh nghiệp X hoạt động trong lĩnh vực dệt may. Để thúc đẩy sản xuất, công ty đã đầu tư hệ thống máy dệt hiện đại và tuyển chọn đội ngũ lao động lành nghề nhằm tạo ra các sản phẩm có chất lượng cao phục vụ nhu cầu của xã hội. Đây là hoạt động", "o": ["tiêu dùng sản phẩm.", "sản xuất vật chất.", "phân phối thu nhập.", "trao đổi hàng hóa."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx · Phần I câu 2 · khoá: gạch chân · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D09-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi tham gia giao thông, anh K phát hiện một xe tải chở hàng cồng kềnh va chạm gây thương tích nặng cho một người đi đường rồi bỏ chạy. Anh Q đã lập tức báo tin cho cơ quan công an để truy tìm thủ phạm. Anh Q đã thực hiện đúng nghĩa vụ nào sau đây?", "o": ["Tố giác hành vi vi phạm pháp luật.", "Giải quyết các tranh chấp cá nhân.", "Bảo vệ bí mật của người lái xe tải.", "Đình chỉ hoạt động kinh doanh vận tải."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx · Phần I câu 3 · khoá: gạch chân · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D09-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong đợt bầu cử đại biểu Quốc hội, bà H do bận việc nên đã nhờ cháu trai đi bầu cử giúp mình. Trong trường hợp này, bà H đã thực hiện chưa đúng nghĩa vụ nào?", "o": ["Nghĩa vụ bầu cử trực tiếp.", "Nghĩa vụ vận động cử tri.", "Nghĩa vụ giám sát hòm phiếu.", "Nghĩa vụ niêm phong phiếu bầu."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx · Phần I câu 4 · khoá: gạch chân · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D09-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nhà nước ta thực hiện quản lý xã hội, duy trì trật tự và thúc đẩy phát triển kinh tế thông qua hệ thống Hiến pháp và pháp luật do chính các cơ quan Nhà nước ban hành. Tổ chức nào sau đây giữ vai trò đó?", "o": ["Đảng Cộng sản Việt Nam.", "Nhà nước Cộng hòa xã hội chủ nghĩa Việt Nam.", "Mặt trận Tổ quốc Việt Nam.", "Các tổ chức phi chính phủ quốc tế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx · Phần I câu 5 · khoá: gạch chân · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D09-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Gia đình anh X thuộc diện hộ có hoàn cảnh đặc biệt khó khăn tại địa phương. Vừa qua, anh được chính quyền xã hỗ trợ lắp đặt hệ thống nước sạch và cấp thẻ bảo hiểm y tế miễn phí. Đây là biểu hiện của chính sách an sinh xã hội ở nội dung nào?", "o": ["Bảo đảm các dịch vụ y tế bắt buộc.", "Bảo hiểm xã hội bắt buộc.", "Bảo đảm các dịch vụ xã hội cơ bản.", "Chính sách giải quyết việc làm ."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx · Phần I câu 6 · khoá: gạch chân · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D09-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Để đánh giá mức độ tăng trưởng kinh tế của Việt Nam trong năm 2025, các chuyên gia kinh tế đã so sánh tổng giá trị hàng hóa và dịch vụ cuối cùng mà nền kinh tế tạo ra trong năm đó so với năm trước. Chỉ tiêu này là", "o": ["tổng sản phẩm quốc nội (GDP).", "chỉ số phát triển con người (HDI).", "hệ số bất bình đẳng thu nhập (Gini).", "tỷ lệ nghèo đa chiều quốc gia."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx · Phần I câu 7 · khoá: gạch chân · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D09-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định pháp luật, nam và nữ có quyền ngang nhau trong việc lựa chọn ngành nghề, nâng cao trình độ chuyên môn và tham gia các hoạt động nghiên cứu khoa học. Đây là nội dung bình đẳng giới trên lĩnh vực", "o": ["chính trị.", "gia đình.", "kinh tế.", "giáo dục."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx · Phần I câu 8 · khoá: gạch chân · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D09-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trên thị trường lao động, khi một lĩnh vực sản xuất mới ra đời cần rất nhiều kỹ sư công nghệ nhưng số lượng người đáp ứng được chuyên môn lại rất ít. Tình trạng này phản ánh hiện tượng nào?", "o": ["Thất nghiệp cơ cấu tăng cao.", "Thiếu hụt nguồn nhân lực.", "Cung lao động vượt cầu lao động.", "lạm phát chi phí đẩy trong sản xuất."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx · Phần I câu 9 · khoá: gạch chân · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D09-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Anh M làm việc tại một xưởng cơ khí, do yêu cầu ần áp dụng công nghệ hiện đại nên xưởng tạm dừng hoạt động trong một thời gian ngắn, cho lao động đi đào tạo, nâng cao trình độ. Trong ba tháng chờ đợi xưởng vận hành trở lại, anh M thuộc loại hình thất nghiệp nào?", "o": ["Thất nghiệp chu kỳ.", "Thất nghiệp tạm thời.", "Thất nghiệp cơ cấu.", "Thất nghiệp bắt buộc."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx · Phần I câu 10 · khoá: gạch chân · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D09-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Cơ quan công chức nhà nước có thẩm quyền ra quyết định xử lí người vi phạm pháp luật là hình thức", "o": ["áp dụng pháp luật.", "sử dụng pháp luật.", "tuân thủ pháp luật.", "thi hành pháp luật."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx · Phần I câu 11 · khoá: gạch chân · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D09-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những nguyên nhân khách quan dẫn đến hiện tượng lạm phát khi giá cả hầu hết các loại hàng hóa trên thị trường tăng liên tục là do", "o": ["Nhà nước tăng thuế thu nhập cá nhân.", "Giá các yếu tố đầu vào sản xuất tăng.", "Lượng cung tiền trong lưu thông giảm.", "Người dân tăng cường gửi tiền tiết kiệm."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx · Phần I câu 12 · khoá: gạch chân · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D09-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mọi hành vi xâm phạm đến tính mạng, sức khỏe của người khác nếu đủ yếu tố cấu thành tội phạm sẽ bị cơ quan Nhà nước áp dụng các hình phạt nghiêm khắc theo Bộ luật Hình sự. Điều này thể hiện đặc điểm nào của pháp luật?", "o": ["Tính quy phạm phổ biến.", "Tính xác định chặt chẽ về hình thức.", "Tính quyền lực, bắt buộc chung.", "Tính tự giác thực hiện của công dân."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx · Phần I câu 13 · khoá: gạch chân · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D09-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Cơ chế vận hành của hệ thống chính trị Việt Nam hiện nay được xác định theo phương thức", "o": ["Đảng lãnh đạo, Nhà nước quản lý, Nhân dân làm chủ.", "Nhà nước làm chủ, Đảng giám sát, Dân thực hiện.", "Đảng quản lý, Nhà nước lãnh đạo, Dân thi hành.", "Dân quyết định, Đảng thi hành, Nhà nước kiểm tra."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx · Phần I câu 14 · khoá: gạch chân · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D09-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Để đáp ứng các yêu cầu khắt khe từ thị trường Châu Âu (EU) khi Việt Nam thực hiện hiệp định EVFTA, các doanh nghiệp thủy sản trong nước cần ưu tiên giải pháp nào?", "o": ["Tăng cường sử dụng các loại thuốc tăng trưởng.", "Hạ thấp tiêu chuẩn vệ sinh để giảm giá bán.", "Đổi mới công nghệ và đảm bảo truy xuất nguồn gốc.", "Chỉ tập trung khai thác tự nhiên, hạn chế nuôi trồng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx · Phần I câu 15 · khoá: gạch chân · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D09-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc Việt Nam gia nhập Hiệp hội các quốc gia Đông Nam Á (ASEAN) là biểu hiện của hình thức hội nhập kinh tế quốc tế ở cấp độ nào?", "o": ["Hội nhập song phương.", "Hội nhập khu vực.", "Hội nhập toàn cầu.", "Hội nhập nội lục địa."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx · Phần I câu 16 · khoá: gạch chân · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D09-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hoạt động nào sau đây của Nhà nước Việt Nam không phản ánh trực tiếp quá trình hội nhập kinh tế quốc tế?", "o": ["Ký kết hiệp định bảo hộ đầu tư với Hoa Kỳ.", "Tham gia Diễn đàn hợp tác Á - Âu (ASEM).", "Tổ chức giải chạy Marathon quốc tế tại Đà Nẵng.", "Đàm phán giảm thuế quan với khối kinh tế CPTPP."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx · Phần I câu 17 · khoá: gạch chân · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D09-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc thực hiện lộ trình cắt giảm thuế nhập khẩu hàng hóa giữa Việt Nam và các quốc gia thành viên cùng ký kết Hiệp định thương mại tự do sẽ đem lại kết quả trực tiếp nào?", "o": ["Thiết lập rào cản thuế quan cao với mọi quốc gia.", "Xóa bỏ hàng rào thuế quan đối với các nước thành viên.", "Hạn chế hoàn toàn sự di chuyển vốn đầu tư quốc tế.", "Tăng doanh thu từ thuế xuất nhập khẩu lên mức cao nhất."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx · Phần I câu 18 · khoá: gạch chân · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D09-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi doanh nghiệp chủ động đầu tư hệ thống tái chế chất thải để giảm thiểu ô nhiễm môi trường cho cộng đồng xung quanh, doanh nghiệp đó đang thực hiện tốt", "o": ["trách nhiệm xã hội của doanh nghiệp.", "mục tiêu tối đa hóa lợi nhuận tài chính.", "quyền tự do định đoạt trong kinh doanh.", "nghĩa vụ nộp thuế thu nhập doanh nghiệp."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx · Phần I câu 19 · khoá: gạch chân · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D09-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin sau\nvà trả lời các câu hỏi từ 20, 21:\nCông ty công nghệ X có trụ sở tại Việt Nam thực hiện ký kết hợp đồng cung cấp linh kiện điện tử cho Tập đoàn điện máy Y tại Nhật Bản. Hợp đồng quy định rõ về chất lượng, hình thức giao hàng qua đường biển và phương thức thanh toán quốc tế. Trong quá trình thực hiện, do phía Việt Nam vi phạm thời hạn giao hàng, Tập đoàn Y đã căn cứ vào các điều khoản thỏa thuận để yêu cầu bồi thường thiệt hại. Đồng thời, hai bên cũng tuân thủ nghiêm túc các nguyên tắc về tự nguyện, bình đẳng và thượng tôn pháp luật quốc tế để giải quyết mâu thuẫn nảy sinh, nhằm duy trì uy tín và mối quan hệ hợp tác lâu dài giữa hai quốc gia thành viên của nhiều tổ chức thương mại đa phương.\nHợp đồng mua bán giữa Công ty X và Tập đoàn Y là biểu hiện của hình thức pháp lý nào trong hội nhập?", "o": ["Hợp đồng lao động quốc tế.", "Hợp đồng thương mại quốc tế.", "Hợp đồng ủy thác chính trị quốc gia.", "Hợp đồng viện trợ nhân đạo đa quốc gia."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx · Phần I câu 20 · khoá: gạch chân · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D09-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc hai công ty căn cứ vào thỏa thuận ban đầu để xử lý vi phạm giao hàng chậm thể hiện nguyên tắc nào của pháp luật quốc tế?", "o": ["Tự ý thay đổi nội dung cam kết.", "Thiện chí thực hiện cam kết.", "Phụ thuộc hoàn toàn vào luật pháp Nước Nhật.", "Xóa bỏ hoàn toàn trách nhiệm của bên bán."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx · Phần I câu 21 · khoá: gạch chân · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D09-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong vùng đặc quyền kinh tế của quốc gia ven biển, tất cả các quốc gia khác được hưởng quyền nào dưới đây?", "o": ["Tự do đặt dây cáp ngầm.", "Tự do cải tạo các đảo.", "Tự do sản xuất năng lượng.", "Tự chủ việc thu phí đi lại."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx · Phần I câu 22 · khoá: gạch chân · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D09-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin sau và trả lời các câu hỏi 23, 24\nGia đình anh Hải có thu nhập hằng tháng 30 triệu đồng. Để thực hiện kế hoạch mua nhà chung cư trong tương lai, anh Hải thiết lập kế hoạch chi tiêu: dành 50% cho sinh hoạt thiết yếu (ăn uống, học hành), 20% cho học tập của bản thân và 30% để tiết kiệm. Tuy nhiên tháng trước, thu nhập gia đình bị giảm xuống còn 20 triệu đồng. Để duy trì khoản tiết kiệm mục tiêu, anh Hải đã quyết định cắt giảm toàn bộ chi phí du lịch, chuyển từ ăn ngoài hàng sang tự nấu ăn tại nhà và nhận thêm việc thiết kế đồ họa vào buổi tối để kiếm thêm thu nhập 5 triệu đồng/tháng. Nhờ sự linh hoạt này, tình hình tài chính gia đình vẫn được đảm bảo ổn định.\nViệc anh Hải nhận thêm công việc thiết kế đồ họa ngoài giờ vào buổi tối để tăng thu nhập được gọi là nguồn thu nhập", "o": ["thụ động.", "chủ động.", "thừa kế.", "ổn định."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx · Phần I câu 23 · khoá: gạch chân · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D09-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin sau và trả lời các câu hỏi 23, 24\nGia đình anh Hải có thu nhập hằng tháng 30 triệu đồng. Để thực hiện kế hoạch mua nhà chung cư trong tương lai, anh Hải thiết lập kế hoạch chi tiêu: dành 50% cho sinh hoạt thiết yếu (ăn uống, học hành), 20% cho học tập của bản thân và 30% để tiết kiệm. Tuy nhiên tháng trước, thu nhập gia đình bị giảm xuống còn 20 triệu đồng. Để duy trì khoản tiết kiệm mục tiêu, anh Hải đã quyết định cắt giảm toàn bộ chi phí du lịch, chuyển từ ăn ngoài hàng sang tự nấu ăn tại nhà và nhận thêm việc thiết kế đồ họa vào buổi tối để kiếm thêm thu nhập 5 triệu đồng/tháng. Nhờ sự linh hoạt này, tình hình tài chính gia đình vẫn được đảm bảo ổn định.\nHành động anh Hải chuyển từ ăn ngoài sang tự nấu ăn tại nhà khi thu nhập giảm sút thể hiện bước nào trong quản lý thu chi?", "o": ["Thay đổi mục tiêu tài chính dài hạn.", "Điều chỉnh kế hoạch chi tiêu cho phù hợp.", "Tăng cường vay mượn từ người thân.", "Bỏ qua các nhu cầu thiết yếu của gia đình."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx · Phần I câu 24 · khoá: gạch chân · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D09-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Gia đình chị Lan có tổng thu nhập hằng tháng từ lương và kinh doanh nhỏ khoảng 45 triệu đồng. Sau khi tham khảo các mô hình quản lý tài chính bền vững, vợ chồng chị thống nhất chia thu nhập thành các phần: dành 55% cho tiêu dùng thiết yếu (ăn uống, điện nước, xăng xe), trích 10% tiết kiệm dài hạn cho mục tiêu mua xe ô tô, dành 15% đầu tư nâng cao trình độ ngoại ngữ cho các con, chuẩn bị 10% dự phòng rủi ro y tế và 10% còn lại dành cho giải trí. Chị Lan cài đặt ứng dụng ghi chép thu chi hằng ngày để theo dõi và chủ động cắt giảm các khoản mua sắm quần áo không nằm trong kế hoạch ban đầu. Chị tin rằng việc kiểm soát dòng tiền tốt sẽ giúp gia đình không rơi vào cảnh nợ nần và luôn sẵn sàng cho các kế hoạch tương lai.", "o": ["Việc chị Lan phân bổ thu nhập vào nhiều mục tiêu khác nhau là hình thức quản lý tài chính nhằm tối ưu hóa nguồn lực và đảm bảo an toàn tài chính.", "Hành động ghi chép thu chi hằng ngày trên ứng dụng giúp gia đình chị Lan điều chỉnh thói quen chi tiêu chưa hợp lý để thực hiện mục tiêu tiết kiệm.", "Quản lý tài chính gia đình hiệu quả theo mô hình của chị Lan yêu cầu các thành viên phải cắt giảm tuyệt đối mọi nhu cầu về giải trí và hưởng thụ.", "Tiết kiệm dài hạn và dự phòng rủi ro y tế là những bước đi quan trọng giúp gia đình chị Lan chủ động ứng phó với các tình huống biến động bất ngờ."], "a": [true, true, false, true], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx · Phần II câu 1 · khoá: gạch chân · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D09-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Doanh nghiệp sản xuất bao bì nhựa Thành Công thực hiện đóng bảo hiểm xã hội (BHXH), bảo hiểm y tế (BHYT) đầy đủ cho 300 lao động theo đúng mức lương cam kết. Nhận thấy xưởng sản xuất chứa nhiều nguyên liệu dễ bắt lửa, doanh nghiệp đã chủ động tham gia bảo hiểm cháy nổ bắt buộc cho toàn bộ nhà kho và máy móc. Tháng 11 vừa qua, một vụ hỏa hoạn do sự cố trạm biến áp đã thiêu rụi kho hàng trị giá 800 triệu đồng. Nhờ tham gia bảo hiểm đầy đủ, Thành Công đã được công ty bảo hiểm chi trả bồi thường thiệt hại và những công nhân trực tiếp tham gia chữa cháy bị thương cũng được quỹ bảo hiểm xã hội chi trả chế độ tai nạn lao động kịp thời để ổn định cuộc sống và sớm quay lại sản xuất.", "o": ["Việc doanh nghiệp Thành Công tham gia bảo hiểm xã hội và bảo hiểm cháy nổ bắt buộc là thực hiện đúng trách nhiệm pháp lý theo quy định của Nhà nước.", "Bảo hiểm cháy nổ cho kho hàng là loại hình bảo hiểm thương mại mang tính tự nguyện cao, doanh nghiệp có quyền không tham gia nếu tài chính eo hẹp.", "Việc công ty bảo hiểm bồi thường thiệt hại 800 triệu đồng thể hiện vai trò của bảo hiểm trong việc chia sẻ rủi ro tài chính và khắc phục tổn thất cho chủ thể.", "Chế độ tai nạn lao động cho công nhân trong vụ cháy trên là quyền lợi trực tiếp từ việc tham gia bảo hiểm xã hội bắt buộc mà doanh nghiệp đã thực hiện."], "a": [true, false, true, true], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx · Phần II câu 2 · khoá: gạch chân · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D09-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Trong giai đoạn 2015 - 2025, báo cáo phát triển kinh tế của quốc gia X ghi nhận những bước chuyển mình ấn tượng. Thu nhập bình quân tại khu vực thành thị tăng trưởng mạnh từ mức 300 USD lên 600 USD/người/tháng, trong khi khu vực nông thôn cũng tăng từ 150 USD lên 400 USD. Đặc biệt, hệ số chênh lệch thu nhập giữa hai khu vực này đã thu hẹp đáng kể, đồng thời chỉ số phát triển con người (HDI) của quốc gia này cũng tăng lên nhờ các chính sách phổ cập y tế và giáo dục. Tuy nhiên, tình trạng ô nhiễm không khí tại các khu công nghiệp tập trung vẫn đang là thách thức lớn. Các chuyên gia nhận định, quốc gia X đang trên đà phát triển nhưng cần chú trọng hơn nữa đến vấn đề bảo vệ tài nguyên môi trường để đảm bảo tính bền vững.", "o": ["Tăng thu nhập bình quân ở cả khu vực thành thị và nông thôn là minh chứng tiêu biểu cho tốc độ tăng trưởng kinh tế nhanh chóng của quốc gia X.", "Chỉ số HDI tăng lên nhờ y tế và giáo dục là chỉ tiêu duy nhất và đầy đủ nhất để kết luận quốc gia X đã đạt đến trình độ phát triển kinh tế bền vững.", "Sự thu hẹp khoảng cách thu nhập giữa thành thị và nông thôn cho thấy quốc gia X đang hướng tới mục tiêu gắn tăng trưởng với tiến bộ và công bằng xã hội.", "Tình trạng ô nhiễm tại các khu công nghiệp phản ánh quốc gia X mới chỉ chú trọng phát triển chiều rộng (số lượng) mà chưa quan tâm đúng mức tới chất lượng."], "a": [true, false, true, true], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx · Phần II câu 3 · khoá: gạch chân · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D09-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Tập đoàn thực phẩm hữu cơ S luôn đề cao uy tín thương hiệu thông qua các cam kết chặt chẽ về trách nhiệm xã hội (CSR). Tập đoàn không chỉ đảm bảo mức lương cao và môi trường làm việc an toàn cho nhân viên mà còn đầu tư hệ thống xử lý nước thải đạt chuẩn Châu Âu trước khi xả ra môi trường. Hằng năm, doanh nghiệp trích 2% lợi nhuận để hỗ trợ các hộ nông dân nghèo trong chuỗi liên kết sản xuất áp dụng công nghệ sạch. Các sản phẩm của tập đoàn luôn có mã QR minh bạch về nguồn gốc xuất xứ và quy trình chế biến. Nhờ đó, dù có mức giá cao hơn đối thủ, sản phẩm của tập đoàn S vẫn chiếm lĩnh được niềm tin của người tiêu dùng và được vinh danh là doanh nghiệp tiêu biểu vì sự phát triển bền vững của cộng đồng.", "o": ["Trách nhiệm xã hội của tập đoàn S được thực hiện một cách đồng bộ, bao gồm trách nhiệm kinh tế, trách nhiệm pháp lý và trách nhiệm đạo đức.", "Việc đầu tư hệ thống xử lý nước thải chuẩn Châu Âu cho thấy doanh nghiệp đang cố tình gia tăng chi phí sản xuất để trốn tránh nghĩa vụ nộp thuế Nhà nước.", "Thực hiện tốt trách nhiệm xã hội giúp tập đoàn S xây dựng hình ảnh thương hiệu uy tín, từ đó tạo ra lợi thế cạnh tranh khác biệt trên thị trường thực phẩm.", "Doanh nghiệp chỉ cần chú trọng thực hiện các hoạt động từ thiện bên ngoài (thiện nguyện) là đủ để được coi là đã hoàn thành xuất sắc trách nhiệm xã hội."], "a": [true, false, true, false], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 19_ĐỀ GV (có đáp án) - ĐS2 - KTPL 12 NỘP SỞ 2026.docx · Phần II câu 4 · khoá: gạch chân · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}]}, {"id": "TN-D10", "loai": "tn", "khoi": 12, "hoc_ki": 2, "so_de": 10, "ten": "Đề luyện thi tốt nghiệp số 10", "pham_vi": "Đề nguồn của giáo viên, giữ NGUYÊN chữ của đề (chỉ bỏ lỗi sao chép) · mã 1206 · file nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm 4 lựa chọn + 4 câu đúng/sai (mỗi câu 4 ý)", "cham": {"tong": 10, "tn": 0.25, "ds": [0, 0.1, 0.25, 0.5, 1.0]}, "status": "cho_duyet", "khoa": {"đã giải lại, khớp khoá": 28}, "sua": "CẦN CÔ XEM (em chưa chắc, KHÔNG sửa khoá): (1) Câu 6 và câu 23 của đề này là CÙNG MỘT câu hỏi (xử phạt doanh nghiệp buôn bán hàng giả thể hiện «tính quyền lực, bắt buộc chung»), chỉ xáo thứ tự phương án — lỗi lặp của đề nguồn; hai khoá nhất quán (C và D cùng là «tính quyền lực, bắt buộc chung»), em giữ nguyên.", "cau": [{"id": "TN-D10-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Loại hình bảo hiểm trong đó người lao động tham gia được hỗ trợ học nghề, được bù đắp một phần thu nhập khi bị mất việc là", "o": ["bảo hiểm y tế.", "bảo hiểm tài sản.", "bảo hiểm thất nghiệp.", "bảo hiểm con người."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D10-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công ty X kinh doanh thuốc bảo vệ thực vật. Để tiết kiệm chi phí, công ty X không xử lí nước thải theo quy trình mà bí mật xả trực tiếp một lượng lớn nước thải ra sông khiến cá chết hàng loạt và ảnh hưởng đến sức khỏe của người dân sống gần khu vực đó. Công ty X đã vi phạm quyền và nghĩa vụ bảo vệ môi trường ở nội dung nào sau đây?", "o": ["Kinh doanh ngành nghề mà pháp luật không cấm.", "Xả nước thải được xử lý đạt quy chuẩn kỹ thuật môi trường.", "Lựa chọn địa điểm kinh doanh phù hợp.", "Chôn lấp chất thải nguy hại đúng quy trình kỹ thuật."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx · Phần I câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D10-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Các suy nghĩ có tính sáng tạo, khả thi về cách tạo ra một sản phẩm hoặc dịch vụ nhằm thu được lợi nhuận trong quá trình kinh doanh là", "o": ["ý tưởng kinh doanh.", "chỉ tiêu kinh doanh.", "môi trường kinh doanh.", "cơ chế kinh doanh."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D10-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hiến pháp năm 2013 quy định, Nhà nước được tổ chức và hoạt động theo Hiến pháp và pháp luật phản ánh trực tiếp nguyên tắc hoạt động nào sau đây của hệ thống chính trị nước Cộng hòa xã hội chủ nghĩa Việt Nam?", "o": ["Tập trung dân chủ.", "Phân cấp, phân quyền.", "Tam quyền phân lập.", "Pháp chế xã hội chủ nghĩa."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx · Phần I câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D10-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Gia đình bạn H có tổng thu nhập ổn định mỗi tháng là 60 triệu đồng từ tiền lương và hoạt động kinh doanh. Gia đình bạn H đã bàn bạc và quyết định phân chia tổng thu nhập thành các khoản chi mỗi tháng bao gồm: 30 triệu đồng chi thiết yếu, 18 triệu đồng chi không thiết yếu và 12 triệu đồng để tiết kiệm. Gia đình bạn H đã thực hiện những bước nào sau đây trong việc lập kế hoạch quản lí thu, chi?", "o": ["Xác định tổng thu nhập và thống nhất các khoản chi thiết yếu, không thiết yếu.", "Xác định tổng thu nhập và điều chỉnh kế hoạch thu, chi.", "Thống nhất các khoản chi thiết yếu và điều chỉnh kế hoạch thu, chi.", "Thống nhất các khoản chi không thiết yếu và thực hiện thu, chi theo kế hoạch."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx · Phần I câu 5 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D10-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, việc cơ quan có thẩm quyền xử phạt các doanh nghiệp có hành vi buôn bán hàng giả là thể hiện đặc điểm nào sau đây của pháp luật?", "o": ["Tính tự giác, tự nguyện.", "Tính chặt chẽ về hình thức.", "Tính quyền lực, bắt buộc chung.", "Tính phù hợp về nội dung."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx · Phần I câu 6 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D10-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nhà nước ban hành văn bản quy phạm pháp luật để bảo đảm hoạt động sản xuất kinh doanh theo đúng quy định là thể hiện vai trò nào sau đây của pháp luật?", "o": ["Cơ sở để kiểm soát việc chi tiêu của công dân.", "Phương tiện để Nhà nước quản lí xã hội.", "Khẳng định quyền lực của tầng lớp lãnh đạo.", "Công cụ để bảo đảm mọi nhu cầu của công dân."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D10-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 8, 9, 10\nTheo Báo cáo của Tổng cục thống kê, giai đoạn 2016 – 2020, Việt Nam có tốc độ tăng GDP bình quân đạt 5,99%/năm. Chỉ số giá tiêu dùng (CPI) bình quân giai đoạn này tăng 3,15%, thấp hơn mức tăng 7,65%/năm của giai đoạn 2011 – 2015. Tỉ lệ hộ nghèo giảm từ 9,2% năm 2016 xuống còn 4,8% năm 2020. Chỉ số phát triển con người (HDI) năm 2020 là 0,702 trong khi đó năm 2016 là 0,695. Trong năm 2016, Luật Bảo hiểm xã hội có hiệu lực thi hành cùng với các chính sách về tài chính cho y tế đã đảm bảo cơ hội tiếp cận dịch vụ y tế của người dân.\nTheo thông tin trên, tác động tích cực của tăng trưởng kinh tế đối với phát triển bền vững được thể hiện ở nhận định nào sau đây?", "o": ["Tăng trưởng kinh tế góp phần nâng cao chất lượng cuộc sống của người dân.", "Tăng trưởng kinh tế thúc đẩy chuyển dịch cơ cấu kinh tế theo hướng hợp lí.", "Tăng trưởng kinh tế làm tăng năng suất lao động bình quân.", "Tăng trưởng kinh tế đã giải quyết triệt để vấn đề thất nghiệp."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D10-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 8, 9, 10\nTheo Báo cáo của Tổng cục thống kê, giai đoạn 2016 – 2020, Việt Nam có tốc độ tăng GDP bình quân đạt 5,99%/năm. Chỉ số giá tiêu dùng (CPI) bình quân giai đoạn này tăng 3,15%, thấp hơn mức tăng 7,65%/năm của giai đoạn 2011 – 2015. Tỉ lệ hộ nghèo giảm từ 9,2% năm 2016 xuống còn 4,8% năm 2020. Chỉ số phát triển con người (HDI) năm 2020 là 0,702 trong khi đó năm 2016 là 0,695. Trong năm 2016, Luật Bảo hiểm xã hội có hiệu lực thi hành cùng với các chính sách về tài chính cho y tế đã đảm bảo cơ hội tiếp cận dịch vụ y tế của người dân.\nChỉ số giá tiêu dùng bình quân trong giai đoạn 2016 – 2020 phản ánh tình hình kinh tế Việt Nam ở mức lạm phát nào sau đây?", "o": ["Siêu lạm phát.", "Lạm phát phi mã.", "Giảm phát.", "Lạm phát vừa phải."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D10-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 8, 9, 10\nTheo Báo cáo của Tổng cục thống kê, giai đoạn 2016 – 2020, Việt Nam có tốc độ tăng GDP bình quân đạt 5,99%/năm. Chỉ số giá tiêu dùng (CPI) bình quân giai đoạn này tăng 3,15%, thấp hơn mức tăng 7,65%/năm của giai đoạn 2011 – 2015. Tỉ lệ hộ nghèo giảm từ 9,2% năm 2016 xuống còn 4,8% năm 2020. Chỉ số phát triển con người (HDI) năm 2020 là 0,702 trong khi đó năm 2016 là 0,695. Trong năm 2016, Luật Bảo hiểm xã hội có hiệu lực thi hành cùng với các chính sách về tài chính cho y tế đã đảm bảo cơ hội tiếp cận dịch vụ y tế của người dân.\nThông tin trên đề cập đến chỉ tiêu nào sau đây của tăng trưởng kinh tế?", "o": ["Chỉ số giá tiêu dùng.", "Tỉ lệ hộ nghèo đa chiều.", "Tổng sản phẩm quốc nội.", "Chỉ số phát triển con người."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D10-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, việc người dân phát biểu ý kiến, bày tỏ quan điểm của mình về các vấn đề trong xã hội là thể hiện quyền nào sau đây của công dân?", "o": ["Quyền tự do ngôn luận.", "Quyền được pháp luật bảo hộ về sức khỏe.", "Quyền bảo mật thông tin.", "Quyền được pháp luật bảo hộ về danh dự."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D10-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hệ thống chính trị nước Cộng hòa xã hội chủ nghĩa Việt Nam không bao gồm cơ quan, tổ chức nào sau đây?", "o": ["Nhà nước Cộng hòa xã hội chủ nghĩa Việt Nam.", "Đảng Cộng sản Việt Nam.", "Đại sứ quán của các quốc gia khác tại Việt Nam.", "Mặt trận Tổ quốc Việt Nam."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx · Phần I câu 12 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D10-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nơi diễn ra sự thỏa thuận, xác lập quan hệ giữa người sử dụng lao động và người lao động là thị trường", "o": ["tiền tệ.", "lao động.", "chứng khoán.", "tài chính."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx · Phần I câu 13 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D10-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào sau đây không phải là tác động tiêu cực của lạm phát đối với doanh nghiệp?", "o": ["Quy mô sản xuất của một số doanh nghiệp bị thu hẹp.", "Kích thích sản xuất và kinh doanh phát triển.", "Lợi nhuận của doanh nghiệp bị giảm sút.", "Giá cả các yếu tố đầu vào của sản xuất tăng cao."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D10-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc doanh nghiệp thuê người nổi tiếng có sức ảnh hưởng lớn đến cộng đồng để quảng cáo có nội dung sai sự thật, gây hiểu lầm về hàng hóa, dịch vụ là vi phạm quyền và nghĩa vụ trong kinh doanh ở nội dung nào sau đây?", "o": ["Lựa chọn hình thức tổ chức kinh doanh.", "Công khai thông tin về thành lập doanh nghiệp.", "Bảo vệ lợi ích hợp pháp của người tiêu dùng.", "Mở rộng quy mô sản xuất kinh doanh."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D10-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 16, 17\nViệt Nam đã xây dựng các quy định pháp luật về sở hữu tài sản trí tuệ hài hòa với những hiệp định quốc tế lớn và điều chỉnh các quy định này cho phù hợp với Hiệp định Đối tác Toàn diện và Tiến bộ Xuyên Thái Bình Dương (CPTPP). Điều này tạo hành lang pháp lí cho các doanh nghiệp Việt Nam thích ứng với các yêu cầu của quá trình hội nhập kinh tế quốc tế.\nThông tin trên thể hiện mối quan hệ giữa pháp luật quốc tế và luật quốc gia ở nội dung nào sau đây?", "o": ["Pháp luật quốc tế có nguồn gốc từ luật quốc gia.", "Pháp luật quốc tế chịu sự quyết định của luật quốc gia.", "Pháp luật quốc tế áp đặt quan điểm lên luật quốc gia.", "Pháp luật quốc tế là cơ sở để hoàn thiện luật quốc gia."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D10-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 16, 17\nViệt Nam đã xây dựng các quy định pháp luật về sở hữu tài sản trí tuệ hài hòa với những hiệp định quốc tế lớn và điều chỉnh các quy định này cho phù hợp với Hiệp định Đối tác Toàn diện và Tiến bộ Xuyên Thái Bình Dương (CPTPP). Điều này tạo hành lang pháp lí cho các doanh nghiệp Việt Nam thích ứng với các yêu cầu của quá trình hội nhập kinh tế quốc tế.\nĐể nâng cao hiệu quả hoạt động thương mại quốc tế, các doanh nghiệp Việt Nam không được thực hiện việc làm nào sau đây?", "o": ["Tìm hiểu quy định của pháp luật về hợp đồng thương mại quốc tế.", "Mô phỏng, sao chép kiểu dáng công nghiệp trái phép.", "Nâng cao năng lực ứng dụng công nghệ và chuyển đổi số trong kinh doanh.", "Xây dựng chiến lược thu hút nguồn nhân lực chất lượng cao."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D10-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối tượng K đã xâm nhập vào một khu di tích lịch sử cấp quốc gia, cố ý làm hỏng bảo vật được trưng bày ở đây. Sau đó, đối tượng này đã bị công an tạm giam 03 tháng để điều tra. Hành vi của đối tượng K vi phạm quyền và nghĩa vụ của công dân về bảo vệ di sản văn hóa ở nội dung nào sau đây?", "o": ["Tôn trọng, bảo vệ di sản văn hóa.", "Khai thác hợp pháp di sản văn hóa.", "Sở hữu hợp pháp di sản văn hóa.", "Nghiên cứu, tham quan di sản văn hóa."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D10-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc thực hiện trách nhiệm xã hội của doanh nghiệp mang lại ý nghĩa nào sau đây?", "o": ["Góp phần bảo vệ môi trường.", "Giải quyết triệt để vấn đề thất nghiệp.", "Giảm lợi thế cạnh tranh của doanh nghiệp.", "Thu hẹp thị trường lao động."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D10-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào sau đây không thể hiện sự cần thiết của hội nhập kinh tế quốc tế đối với các quốc gia?", "o": ["Giúp chuyển dịch cơ cấu kinh tế theo hướng hiện đại.", "Giúp các nước giảm áp lực gia tăng dân số tự nhiên.", "Tạo nhiều việc làm, nâng cao thu nhập cho người dân.", "Tạo cơ hội để mở rộng thị trường, thu hút vốn đầu tư."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx · Phần I câu 20 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D10-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Pháp luật quy định người dân tộc thiểu số được giới thiệu ứng cử đại biểu Quốc hội là thể hiện quyền bình đẳng giữa các dân tộc trên lĩnh vực nào sau đây?", "o": ["Giáo dục.", "Văn hóa.", "Kinh tế.", "Chính trị."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D10-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nguyên tắc nào sau đây của Tổ chức Thương mại thế giới (WTO) yêu cầu các nước thành viên phải từng bước mở cửa thị trường, xóa bỏ các rào cản trong thương mại quốc tế?", "o": ["Thiện chí, trung thực.", "Tuân thủ cam kết.", "Tự do hoá thương mại.", "Cạnh tranh minh bạch."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D10-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, việc cơ quan có thẩm quyền xử phạt các doanh nghiệp có hành vi buôn bán hàng giả là thể hiện đặc điểm nào sau đây của pháp luật?", "o": ["Tính phù hợp về nội dung.", "Tính chặt chẽ về hình thức.", "Tính tự giác, tự nguyện.", "Tính quyền lực, bắt buộc chung."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D10-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hiến pháp năm 2013 quy định, mọi người có quyền bất khả xâm phạm về đời sống riêng tư; có quyền bảo vệ danh dự, uy tín của mình là thể hiện quyền nào sau đây của công dân?", "o": ["Quyền được pháp luật bảo hộ về danh dự, nhân phẩm.", "Quyền sở hữu tài sản hợp pháp.", "Quyền được pháp luật bảo hộ về tính mạng, sức khỏe.", "Quyền bất khả xâm phạm về thân thể."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D10-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc thông tin sau: Công ty P của nước G (bên bán) và công ty T của nước Q (bên mua) có trụ sở tại Việt Nam kí hợp đồng xuất khẩu 100 tấn cà phê với giá 4000 USD/tấn, thời gian giao hàng 45 ngày kể từ ngày kí hợp đồng, giao tại cảng H. Sau khi công ty P gửi hợp đồng đã kí, công ty T đã đơn phương thay đổi một số điều khoản quan trọng về điều kiện vận chuyển và để cho công ty khác thực hiện thay hợp đồng ban đầu. Công ty P sau đó tuyên bố hợp đồng vô hiệu vì bị thay đổi và từ chối thực hiện các nghĩa vụ theo thỏa thuận dự kiến ban đầu. Công ty T phải mua hàng từ một công ty khác với giá cao hơn nên đã yêu cầu công ty P bồi thường phần chênh lệch.", "o": ["Công dân nước Q cư trú và làm việc ổn định tại trụ sở của công ty T ở Việt Nam được hưởng chế độ đối xử quốc gia.", "Hợp đồng thương mại giữa công ty T và công ty P được xác lập theo nguyên tắc tự do giao kết hợp đồng.", "Khi xảy ra tranh chấp, công ty P có thể căn cứ vào quy định của pháp luật quốc tế để bảo vệ quyền và lợi ích hợp pháp của mình.", "Công ty P phải bồi thường phần thiệt hại cho công ty T."], "a": [true, true, true, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx · Phần II câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D10-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc thông tin sau: Ông N thành lập công ty X để kinh doanh vật tư nông nghiệp. Trong quá trình hoạt động, công ty X đã bán sản phẩm cho nhiều hộ kinh doanh mà không xuất hóa đơn bán hàng. Anh M sử dụng sản phẩm phân bón của công ty X cho vườn sầu riêng, sau một thời gian có nhiều cây sầu riêng xảy ra hiện tượng héo lá và chết. Anh M liên hệ chuyên gia đến thẩm định, kết quả thẩm định cho thấy cây chết do một số chất có trong phân bón của công ty X cung cấp gây ra. Qua tìm hiểu, anh M có chứng cứ về sản phẩm phân bón của công ty X có hàm lượng không đúng như thông tin được in trên bao bì sản phẩm. Anh M đã đăng thông tin kết quả thẩm định lên trang cá nhân để cảnh báo người tiêu dùng về sản phẩm phân bón của công ty X và trình báo cho cơ quan chức năng để giải quyết.", "o": ["Công ty X không có nghĩa vụ phải bồi thường thiệt hại cho anh M.", "Ông N lựa chọn kinh doanh vật tư nông nghiệp là thực hiện quyền của công dân trong kinh doanh.", "Anh M đã vi phạm quyền tự do ngôn luận của công dân.", "Vì không xuất hóa đơn bán hàng, công ty X không phải chịu trách nhiệm pháp lí về các sản phẩm đã bán cho anh M."], "a": [false, true, false, false], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Sai.", "nguon": "Đề nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx · Phần II câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D10-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc thông tin sau: Năm 2024, các chính sách an sinh xã hội của Việt Nam được thực hiện đầy đủ, kịp thời, đem lại hiệu quả lớn. Tính đến hết tháng 12/2024, đối tượng tham gia bảo hiểm xã hội (BHXH) chiếm 42,7% lực lượng lao động trong độ tuổi (trong đó: BHXH bắt buộc đạt khoảng 17,8 triệu người, BHXH tự nguyện đạt hơn 2,3 triệu người). Số người tham gia bảo hiểm thất nghiệp ước đạt 15,8 triệu, chiếm khoảng 33% lực lượng lao động trong độ tuổi, tăng thêm 2,5 triệu người so với năm 2020. Tính đến tháng 01/2025, thực hiện chính sách về nhà ở, Chương trình phát động xóa nhà tạm, nhà dột nát của Chính phủ đã hỗ trợ được 35 466 căn nhà cho những người có hoàn cảnh khó khăn. Chương trình này đã góp phần vào việc giảm tỉ lệ hộ nghèo đa chiều và nâng cao mức sống cho người dân.", "o": ["Thông tin trên cho thấy hơn 2,3 triệu người trong độ tuổi lao động đã chủ động lựa chọn loại hình bảo hiểm phù hợp với mình.", "Chương trình phát động xóa nhà tạm, nhà dột nát của Chính phủ đã góp phần nâng cao mức sống cho người dân.", "Chủ doanh nghiệp phải có nghĩa vụ tham gia bảo hiểm xã hội tự nguyện cho người lao động.", "Năm 2024, bảo hiểm thất nghiệp đã bù đắp một phần thu nhập cho khoảng 33% lực lượng lao động trong độ tuổi bị mất việc làm."], "a": [true, true, false, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Sai.", "nguon": "Đề nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx · Phần II câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D10-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc thông tin sau: Công ty M kinh doanh trong lĩnh vực may mặc với diện tích hơn 1000m2. Công ty M tham gia bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp đầy đủ cho người lao động. Công ty M đã kí hợp đồng cung cấp lô hàng trị giá gần 2 tỉ đồng với công ty N, trong đó có điều khoản giao hàng đúng hạn. Tuy nhiên gần đến thời gian giao hàng, công ty M đã xảy ra sự cố chập điện, khiến số hàng hóa cho đơn hàng trên bị thiêu rụi gần như hoàn toàn, một số công nhân bị tai nạn đã được đưa vào bệnh viện điều trị. Vì sự cố trên, công ty M không giao hàng đúng hạn nên đã bị công ty N yêu cầu phải bồi thường hợp đồng. Đồng thời, do chủ quan, công ty M không nộp phí bảo hiểm cháy, nổ mặc dù quá hạn nộp phí rất lâu nên công ty M không được tổ chức bảo hiểm chi trả phần thiệt hại do sự cố trên gây ra.", "o": ["Công ty M không bắt buộc phải mua bảo hiểm cháy, nổ theo quy định.", "Trong trường hợp trên, công nhân bị tai nạn sẽ được hỗ trợ thanh toán chi phí điều trị.", "Công ty M tham gia bảo hiểm cho người lao động là góp phần giảm gánh nặng hỗ trợ cho ngân sách nhà nước.", "Công ty M đã thực hiện trách nhiệm của người sử dụng lao động đối với người lao động về bảo hiểm."], "a": [false, true, true, true], "e": "Đáp án: a) Sai; b) Đúng; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: 20_ĐỀ GV (có đáp án) - MÃ 1206 - KTPL 12.docx · Phần II câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}]}, {"id": "TN-D11", "loai": "tn", "khoi": 12, "hoc_ki": 2, "so_de": 11, "ten": "Đề luyện thi tốt nghiệp số 11", "pham_vi": "Đề nguồn của giáo viên, giữ NGUYÊN chữ của đề (chỉ bỏ lỗi sao chép) · «10 ĐỀ» Đề 1 · file nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm 4 lựa chọn + 4 câu đúng/sai (mỗi câu 4 ý)", "cham": {"tong": 10, "tn": 0.25, "ds": [0, 0.1, 0.25, 0.5, 1.0]}, "status": "cho_duyet", "khoa": {"đã giải lại, khớp khoá": 24, "đã tự giải lại": 4}, "sua": "Khoá đã rà 16/11/2026 cùng đề «học kì II» lớp 12: Rà đáp án (đề nguồn ghi khác): câu 4 — tạo sản phẩm mới, tối ưu sản xuất, cải tiến quản lý → năng lực tổ chức, lãnh đạo (A); câu 6 — «quyết định hình thức quản lý nhà nước ở cơ sở» không thuộc quyền đóng góp ý kiến (C); câu 20 — bệnh nhân được biết thông tin về phương pháp điều trị, giá dịch vụ → quyền được thông tin và giải thích (A); câu đúng/sai 4 ý b — không có «Tòa án kinh tế quốc tế» để nước B khởi kiện, tranh chấp thương mại giải quyết qua cơ chế của WTO → Sai.", "cau": [{"id": "TN-D11-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Những người sản xuất, cung cấp hàng hóa, dịch vụ ra thị trường, đáp ứng nhu cầu tiêu dùng của xã hội là", "o": ["Chủ thể nhà nước.", "Chủ thể tiêu dùng.", "Chủ thể sản xuất.", "Chủ thể trung gian."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D11-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc tổ chức, cá nhân vận dụng pháp luật, tiến hành những hoạt động mà pháp luật cho phép được gọi là hình thức thực hiện pháp luật nào?", "o": ["Tuân thủ pháp luật.", "Thi hành pháp luật.", "Sử dụng pháp luật.", "Áp dụng pháp luật."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D11-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Loại hình thất nghiệp nào dưới đây xảy ra do sự thay đổi trong cơ cấu ngành nghề của nền kinh tế?", "o": ["Thất nghiệp cơ cấu.", "Thất nghiệp tạm thời.", "Thất nghiệp chu kỳ.", "Thất nghiệp thời vụ."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D11-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc tạo ra sản phẩm mới, tối ưu hóa quá trình sản xuất và không ngừng cải tiến trong quản lý là biểu hiện của năng lực nào sau đây của người kinh doanh?", "o": ["Năng lực tổ chức, lãnh đạo.", "Năng lực giải quyết mối quan hệ.", "Năng lực tìm kiếm thị trường.", "Năng lực phân phối sản phẩm."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 4 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D11-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo Luật Bình đẳng giới năm 2006, nam và nữ được đối xử bình đẳng về quyền gì trong lĩnh vực lao động?", "o": ["Chính trị.", "Kinh tế.", "Lao động.", "Y tế."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 5 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D11-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quyền tham gia đóng góp ý kiến vào các quyết định của nhà nước và xã hội không bao gồm việc nào dưới đây?", "o": ["Góp ý xây dựng các văn bản quy phạm pháp luật.", "Tham gia thảo luận về các vấn đề quan trọng của đất nước.", "Quyết định hình thức quản lý nhà nước ở cơ sở.", "Vận động mọi người góp ý kiến về các vấn đề của địa phương."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 6 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D11-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những yếu tố quan trọng nhất trong sự phát triển kinh tế là", "o": ["Tổng sản phẩm quốc nội bình quân đầu người.", "Chỉ số phát triển con người.", "Thu nhập quốc dân bình quân đầu người.", "Tổng sản phẩm quốc nội."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D11-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Người lao động bị mất việc làm có thể tham gia bảo hiểm nào dưới đây để nhận hỗ trợ về thu nhập và tìm kiếm công việc mới?", "o": ["Bảo hiểm thất nghiệp.", "Bảo hiểm y tế.", "Bảo hiểm xã hội.", "Bảo hiểm thân thể."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D11-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chủ sở hữu có quyền sử dụng tài sản theo các hình thức hợp pháp, bao gồm cho vay, bán, hoặc cho mượn tài sản. Đây là quyền gì của chủ sở hữu?", "o": ["Chiếm hữu tài sản.", "Định đoạt tài sản.", "Sử dụng tài sản.", "Ủy quyền tài sản."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D11-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mô hình kinh tế nào sau đây có đặc điểm là các thành viên hợp tác trong sản xuất, kinh doanh nhằm mục đích chung và cùng nhau chia sẻ lợi ích?", "o": ["Mô hình kinh tế hợp tác xã.", "Mô hình kinh tế hộ gia đình.", "Mô hình công ty cổ phần.", "Mô hình doanh nghiệp tư nhân."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D11-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hiến pháp năm 2013 quy định về quyền và nghĩa vụ cơ bản của công dân là", "o": ["Quyền tự do cá nhân và nghĩa vụ bảo vệ tổ quốc.", "Quyền và nghĩa vụ bình đẳng trước pháp luật.", "Quyền tự do ngôn luận và nghĩa vụ tham gia lao động.", "Quyền và nghĩa vụ cơ bản của công dân được ghi nhận trong các điều kiện sống."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D11-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật hiện hành, người có hành vi xâm phạm tài sản của người khác sẽ chịu trách nhiệm pháp lý nào?", "o": ["Phạt tiền từ 1.000.000₫ đến 3.000.000₫.", "Phạt tù từ 06 tháng đến 03 năm.", "Cải tạo không giam giữ từ 12 tháng đến 18 tháng.", "Phạt tù từ 03 năm đến 07 năm."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 12 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D11-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật hiện hành, hành vi đưa thông tin sai sự thật ảnh hưởng đến danh dự, uy tín của người khác là vi phạm quyền nào?", "o": ["Quyền được bảo vệ sức khỏe.", "Quyền được bảo vệ danh dự, nhân phẩm.", "Quyền sở hữu tài sản.", "Quyền tự do ngôn luận."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 13 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D11-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Các quan hệ thỏa thuận về tiền lương và điều kiện làm việc của người lao động thuộc loại quan hệ nào?", "o": ["Thị trường lao động.", "Thị trường hàng hóa.", "Quan hệ lao động.", "Thị trường tiêu dùng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D11-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong bối cảnh nhiều công ty cùng sản xuất một loại sản phẩm, công ty Y đã áp dụng chiến lược tặng quà kèm theo sản phẩm để thu hút khách hàng, trong khi không điều chỉnh giá bán. Việc làm của công ty Y thể hiện hành vi", "o": ["phù hợp với tập quán thương mại.", "cạnh tranh không lành mạnh.", "vì lợi ích của người tiêu dùng.", "vì lợi ích lâu dài của xã hội."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D11-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 16, 17\nTheo báo cáo của ngành Giáo dục, tính đến hết năm 2023, cả nước có hơn 22 triệu học sinh, sinh viên tham gia học tập tại các cơ sở giáo dục phổ thông và đại học, trong đó gần 95% học sinh cấp tiểu học và trung học cơ sở đạt chuẩn phổ cập giáo dục. Ngoài ra, đã có hơn 3 triệu học sinh, sinh viên nhận được học bổng hoặc các hỗ trợ tài chính khác để đảm bảo điều kiện học tập. Ngành Giáo dục cũng đã tổ chức các chương trình ngoại khóa, phát triển kỹ năng sống cho trên 15 triệu lượt học sinh trong năm qua.\nTừ những số liệu trong thông tin trên, nhận định nào sau đây phù hợp với vai trò của giáo dục?", "o": ["Gần 95% học sinh cấp tiểu học và trung học cơ sở đạt chuẩn phổ cập giáo dục, cho thấy vẫn còn một số ít học sinh chưa được tiếp cận giáo dục.", "Hơn 3 triệu học sinh, sinh viên được nhận học bổng hoặc hỗ trợ tài chính đã tạo điều kiện tốt hơn để tiếp cận giáo dục.", "Hơn 15 triệu lượt học sinh tham gia chương trình ngoại khóa tạo áp lực cho ngân sách nhà nước.", "Chỉ có 95% học sinh tiểu học và trung học cơ sở đạt chuẩn phổ cập, cho thấy hệ thống giáo dục chưa đạt được hiệu quả như mong muốn."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D11-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 16, 17\nTheo báo cáo của ngành Giáo dục, tính đến hết năm 2023, cả nước có hơn 22 triệu học sinh, sinh viên tham gia học tập tại các cơ sở giáo dục phổ thông và đại học, trong đó gần 95% học sinh cấp tiểu học và trung học cơ sở đạt chuẩn phổ cập giáo dục. Ngoài ra, đã có hơn 3 triệu học sinh, sinh viên nhận được học bổng hoặc các hỗ trợ tài chính khác để đảm bảo điều kiện học tập. Ngành Giáo dục cũng đã tổ chức các chương trình ngoại khóa, phát triển kỹ năng sống cho trên 15 triệu lượt học sinh trong năm qua.\nTrong thông tin trên, nội dung nào sau đây thể hiện trách nhiệm công dân về giáo dục?", "o": ["Gần 95% học sinh cấp tiểu học và trung học cơ sở đạt chuẩn phổ cập giáo dục.", "Hơn 22 triệu học sinh, sinh viên tham gia học tập.", "Hơn 3 triệu học sinh, sinh viên nhận được hỗ trợ tài chính.", "Trên 15 triệu lượt học sinh tham gia chương trình ngoại khóa."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D11-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quản lý chi tiêu trong gia đình là việc sử dụng các khoản thu và chi để đảm bảo nhu cầu của các thành viên sao cho phù hợp với", "o": ["Kế hoạch chi tiêu.", "Nguồn thu nhập.", "Phong cách sống của gia đình.", "Mức sống của xã hội."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D11-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào sau đây không đúng khi nói về tầm quan trọng của quản lý chi tiêu gia đình?", "o": ["Kiểm soát được việc tiêu dùng không hợp lý trong gia đình.", "Nâng cao đời sống tinh thần và vật chất của gia đình.", "Đảm bảo mọi thành viên chỉ chi tiêu theo ý kiến của người đứng đầu gia đình.", "Giúp phân bổ ngân sách hợp lý giữa các nhu cầu."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D11-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo Luật Khám bệnh, chữa bệnh năm 2023, bệnh nhân được biết các thông tin về phương pháp điều trị, giá dịch vụ và được hướng dẫn tự chăm sóc sức khỏe là nội dung thuộc quyền nào?", "o": ["Quyền được thông tin và giải thích về tình trạng sức khỏe.", "Quyền được khám bệnh, chữa bệnh.", "Quyền được lựa chọn bác sĩ điều trị.", "Quyền được bảo vệ thông tin cá nhân."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 20 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D11-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Cơ quan chức năng phát hiện nhà thuốc M kinh doanh thuốc giả với tổng giá trị 50 triệu đồng. Theo quy định pháp luật, hành vi này phải chịu trách nhiệm pháp lý nào sau đây?", "o": ["Phạt tiền, buộc tiêu hủy toàn bộ số thuốc giả.", "Phạt tiền, thu hồi giấy phép kinh doanh của nhà thuốc M.", "Thu hồi chứng chỉ hành nghề của chủ nhà thuốc M vĩnh viễn.", "Cảnh cáo và yêu cầu đình chỉ hoạt động trong 6 tháng."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D11-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22, 23, 24\nHội nhập kinh tế quốc tế đã tạo điều kiện cho Việt Nam đa dạng hóa các mặt hàng xuất khẩu. Trong đó, cà phê là một trong những sản phẩm thế mạnh của Việt Nam. Chỉ tính riêng trong nửa đầu năm 2024, Việt Nam đã xuất khẩu ước tính 1,1 triệu tấn cà phê với giá trị đạt 2,5 tỷ đô la Mỹ, tăng 35% về lượng và 45% về giá trị so với cùng kỳ năm trước. Tuy nhiên, một lô hàng của công ty cổ phần X bị phát hiện chứa chất bảo quản vượt mức cho phép. Phía đối tác yêu cầu công ty X bồi thường toàn bộ giá trị lô hàng nhưng công ty này không chấp nhận vì trong hợp đồng không quy định điều khoản này.\nTrong thông tin trên, hội nhập kinh tế quốc tế đem lại lợi ích nào sau đây cho các doanh nghiệp trong hoạt động xuất khẩu cà phê tại Việt Nam?", "o": ["Tăng giá trị xuất khẩu và nâng cao thương hiệu quốc gia.", "Đạt giá trị xuất khẩu 2,5 tỷ đô la Mỹ trong năm 2024.", "Tiếp cận thị trường và tăng giá trị xuất khẩu là 35%.", "Tạo cơ hội để các doanh nghiệp Việt Nam tham gia vào chuỗi cung ứng toàn cầu."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D11-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22, 23, 24\nHội nhập kinh tế quốc tế đã tạo điều kiện cho Việt Nam đa dạng hóa các mặt hàng xuất khẩu. Trong đó, cà phê là một trong những sản phẩm thế mạnh của Việt Nam. Chỉ tính riêng trong nửa đầu năm 2024, Việt Nam đã xuất khẩu ước tính 1,1 triệu tấn cà phê với giá trị đạt 2,5 tỷ đô la Mỹ, tăng 35% về lượng và 45% về giá trị so với cùng kỳ năm trước. Tuy nhiên, một lô hàng của công ty cổ phần X bị phát hiện chứa chất bảo quản vượt mức cho phép. Phía đối tác yêu cầu công ty X bồi thường toàn bộ giá trị lô hàng nhưng công ty này không chấp nhận vì trong hợp đồng không quy định điều khoản này.\nTheo quy định của pháp luật Việt Nam, hành vi vi phạm của công ty cổ phần X phải chịu trách nhiệm pháp lý nào sau đây?", "o": ["Buộc thu hồi sản phẩm và thay đổi quy trình sản xuất.", "Đền bù cho đối tác toàn bộ giá trị của lô hàng bị trả lại.", "Xử phạt hành chính và áp dụng hình phạt bổ sung theo quy định.", "Tước quyền xuất khẩu mặt hàng cà phê trong thời gian quy định."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D11-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22, 23, 24\nHội nhập kinh tế quốc tế đã tạo điều kiện cho Việt Nam đa dạng hóa các mặt hàng xuất khẩu. Trong đó, cà phê là một trong những sản phẩm thế mạnh của Việt Nam. Chỉ tính riêng trong nửa đầu năm 2024, Việt Nam đã xuất khẩu ước tính 1,1 triệu tấn cà phê với giá trị đạt 2,5 tỷ đô la Mỹ, tăng 35% về lượng và 45% về giá trị so với cùng kỳ năm trước. Tuy nhiên, một lô hàng của công ty cổ phần X bị phát hiện chứa chất bảo quản vượt mức cho phép. Phía đối tác yêu cầu công ty X bồi thường toàn bộ giá trị lô hàng nhưng công ty này không chấp nhận vì trong hợp đồng không quy định điều khoản này.\nTrong trường hợp trên, công ty cổ phần X nên lựa chọn phương thức giải quyết đầu tiên nào sau đây phù hợp với nguyên tắc hợp tác quốc tế với phía đối tác?", "o": ["Thương lượng với các bên liên quan để đạt thỏa thuận.", "Đàm phán trực tiếp với đại diện của tổ chức quốc tế.", "Đưa tranh chấp ra Tòa án quốc tế để giải quyết.", "Đơn phương đình chỉ hợp đồng thương mại để giảm thiệt hại."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D11-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Vị thế của Việt Nam trên thế giới đã được củng cố toàn diện trong giai đoạn 2011 - 2022. Cùng với quá trình hội nhập kinh tế quốc tế mạnh mẽ, đến năm 2020, Việt Nam có 30 đối tác chiến lược và đối tác chiến lược toàn diện; có quan hệ ngoại giao với 189/193 nước, có quan hệ kinh tế với 160 nước và 70 vùng lãnh thổ. Đến năm 2022, tổng số quan hệ kinh tế - thương mại của Việt Nam đã nâng lên thành 230 nước và vùng lãnh thổ. Với việc thực hiện chủ trương hội nhập quốc tế toàn diện với trọng tâm là hội nhập kinh tế quốc tế, vị thế của đất nước tiếp tục được cải thiện đáng kể. Có thể khẳng định, hội nhập kinh tế quốc tế đóng góp quan trọng vào việc mở rộng và đưa quan hệ của nước ta với các đối tác đi vào chiều sâu, tạo thế đan xen lợi ích, góp phần gìn giữ môi trường hòa bình, ổn định để phát triển đất nước; nâng cao uy tín và vị thế của Việt Nam trên trường quốc tế.", "o": ["Việc thiết lập quan hệ đối tác chiến lược và chiến lực toàn diện là thể hiện hình thức hội nhập kinh tế quốc tế ở cấp độ khu vực.", "Hội nhập kinh tế quốc tế không góp phần thúc đẩy sự tăng trưởng GDP hàng năm ở Việt Nam.", "Nước ta đang phát triển vì vậy khi hội nhập kinh tế quốc tế, Việt Nam phải chấp nhận từ bỏ lợi ích của mình để hội nhập.", "Hội nhập kinh tế quốc tế góp phần đưa hàng hóa của Việt Nam đến với các thị trường trên thế giới."], "a": [false, false, false, true], "e": "Đáp án: a) Sai; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần II câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D11-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Từ năm 2018, ông M thành lập Công ty Trách nhiệm hữu hạn Thương mại và Sản xuất G với ngành nghề kinh doanh dầu nhớt, phụ tùng xe gắn máy. Trong thời gian kinh doanh, ông M nhận thấy khách hàng ưa chuộng các phụ tùng xe gắn máy hiệu H và dầu nhớt hiệu K nên nảy sinh ý định làm giả sản phẩm của các thương hiệu này bán cho khách hàng để thu lợi. Ông M chỉ đạo nhân viên thiết kế các mẫu tem xác nhận hàng chính hãng và thuê người in nhiều mẫu tem để sử dụng, sau đó ông cùng vợ đến một số chợ trong khu vực tìm mua các phụ tùng xe gắn máy, dầu nhớt chất lượng kém đem về đóng gói, dán tem làm giả sản phẩm của các thương hiệu nổi tiếng, bán ra thị trường cho khách với giá thấp hơn hàng chính hãng từ 10% – 15%. Bằng thủ đoạn đó, trong thời gian gần 2 năm, vợ chồng ông M đã sản xuất số lượng hàng giả có giá trị tương đương hàng thật hơn 750 triệu đồng, thu lợi khoảng 300 triệu đồng.", "o": ["Hành vi làm giả hàng hóa các thương hiệu nổi tiếng để thu lợi nhuận là vi phạm quyền mở rộng kinh doanh của công dân.", "Ông M cùng vợ phải chịu trách nhiệm hình sự về hành vi vi phạm pháp luật của mình.", "Ông M vừa vi phạm nghĩa vụ kinh doanh vừa vi phạm nghĩa vụ nộp thuế cho nhà nước.", "Việc thành lập doanh nghiệp của ông M thể hiện quyền của công dân về kinh doanh."], "a": [false, true, true, true], "e": "Đáp án: a) Sai; b) Đúng; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần II câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D11-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Công ty cổ phần B chuyên sản xuất mặt hàng đồ chơi trẻ em. Từ nhiều năm nay, công ty đã thực hiện đầy đủ quy định pháp luật về bảo vệ môi trường trong sản xuất, kinh doanh, hàng năm công ty đầu tư hàng tỉ đồng để xây dựng hệ thống xử lí nước thải bảo vệ môi trường, sản xuất đồ chơi không ảnh hưởng đến sức khoẻ của trẻ em. Đồng thời, công ty còn thực hiện đúng nghĩa vụ kê khai và nộp thuế cho Nhà nước theo quy định.", "o": ["Thực hiện quy định của pháp luật về bảo vệ môi trường là công ty đã thực hiện tốt trách nhiệm xã hội ở hình thức pháp lý và kinh tế.", "Việc sản xuất các đồ chơi không ảnh hưởng đến sức khỏe của trẻ em là phù hợp với trách nhiệm xã hội của doanh nghiệp ở hình thức đạo đức và kinh tế.", "Thực hiện tốt nghĩa vụ nộp thuế cho nhà nước gắn liền với trách nhiệm nhân văn của doanh nghiệp.", "Thông qua việc tạo ra những sản phẩm không ảnh hưởng đến sức khỏe của trẻ em, công ty B đã thể hiện trách nhiệm của mình trong việc thúc đẩy phát triển bền vững."], "a": [false, true, false, true], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần II câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D11-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Sau khi phát hiện mặt hàng thép nhập khẩu từ nước B có dấu hiệu phá giá, ngành thép nước C đã yêu cầu Bộ Thương mại nước C mở cuộc điều tra. Kết quả cho thấy mặt hàng này được trợ giá bởi chính phủ nước B, gây ảnh hưởng lớn đến ngành thép nội địa nước C. Bộ Thương mại nước C quyết định áp thuế chống bán phá giá đối với mặt hàng thép nhập khẩu từ nước B với mức thuế 15%.", "o": ["Việc áp thuế chống bán phá giá đối với mặt hàng thép nhập khẩu từ nước B là biện pháp nhằm bảo vệ ngành sản xuất nội địa.", "Nước B có thể khởi kiện việc áp thuế chống bán phá giá lên Tòa án kinh tế quốc tế.", "Trong trường hợp nước C muốn điều chỉnh mức thuế áp dụng, nước C cần thông báo trước cho nước B.", "Việc áp thuế chống bán phá giá sẽ do Bộ Công thương nước C trực tiếp thực hiện mà không cần thông qua kết luận điều tra."], "a": [true, false, true, false], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần II câu 4 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}]}, {"id": "TN-D12", "loai": "tn", "khoi": 12, "hoc_ki": 2, "so_de": 12, "ten": "Đề luyện thi tốt nghiệp số 12", "pham_vi": "Đề nguồn của giáo viên, giữ NGUYÊN chữ của đề (chỉ bỏ lỗi sao chép) · «10 ĐỀ» Đề 2 · file nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm 4 lựa chọn + 4 câu đúng/sai (mỗi câu 4 ý)", "cham": {"tong": 10, "tn": 0.25, "ds": [0, 0.1, 0.25, 0.5, 1.0]}, "status": "cho_duyet", "khoa": {"đã giải lại, khớp khoá": 27, "đã tự giải lại": 1}, "sua": "Khoá đã rà 16/11/2026 cùng đề «học kì II» lớp 12: Rà đáp án (đề nguồn ghi khác): câu đúng/sai 4 — Công ước Luật Biển 1982 là cơ sở pháp lí quan trọng bảo vệ quyền và lợi ích của Việt Nam trên biển (ý c Đúng); các hiệp định phân định biển nhằm xác định ranh giới, không phải «chia đều lợi ích» (ý d Sai).", "cau": [{"id": "TN-D12-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong nền kinh tế xã hội, hoạt động đóng vai trò cơ bản nhất, quyết định các hoạt động khác của đời sống xã hội là hoạt động", "o": ["sản xuất", "phân phối.", "tiêu dùng", "trao đổi."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D12-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khởi tố bị can là hoạt động tư pháp của cơ quan nào dưới đây?", "o": ["Viện kiểm sát nhân dân.", "Tòa án nhân dân.", "Ủy ban nhân dân.", "Hội đồng nhân dân."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D12-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Số lượng hàng hóa, dịch vụ mà nhà cung cấp sẵn sàng đáp ứng cho nhu cầu của thị trường tương ứng với mức giá cả được xác định trong một khoảng thời gian nhất định được gọi là", "o": ["cung.", "cầu.", "lạm phát.", "thất nghiệp."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D12-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong mối quan hệ giữa thị trường việc làm và thị trường lao động, khi khả năng cung ứng lao động lớn hơn khả năng tạo việc làm sẽ dẫn đến hiện tượng nào trong xã hội gia tăng?", "o": ["Lạm phát.", "Thất nghiệp.", "Cạnh tranh.", "Khủng hoảng."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D12-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công dân dù ở cương vị nào, khi vi phạm pháp luật đều bị xử lí theo quy định là", "o": ["công dân bình đẳng về kinh tế.", "công dân bình đẳng về quyền và nghĩa vụ.", "công dân bình đẳng về trách nhiệm pháp lí.", "công dân bình đẳng về chính trị."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 5 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D12-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc làm nào dưới đây thể hiện quyền bình đẳng giới trên lĩnh vực chính trị?", "o": ["Đăng ký học nâng cao trình độ.", "Góp ý dự thảo Luật đất đai sửa đổi.", "Hưởng trợ cấp tai nạn lao động.", "Đăng ký thành lập doanh nghiệp."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 6 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D12-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Giá trị bằng tiền của tất cả các hàng hóa và dịch vụ cuối cùng được sản xuất ra trên lãnh thổ một nước trong thời gian nhất định được gọi là", "o": ["tổng thu nhập quốc dân ( GNI).", "tổng thu nhập quốc nội (GDP).", "tổng thu nhập quốc nội trên đầu người.", "tổng thu nhập quốc dân trên đầu người."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D12-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chủ thể của loại hình bảo hiểm xã hội là do", "o": ["các doanh nghiệp tư nhân.", "tổ chức thương mại.", "nhà đầu tư nước ngoài.", "Nhà nước tổ chức."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D12-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc chủ thể nắm giữ, chi phối tài sản một cách trực tiếp hoặc gián tiếp như chủ thể có quyền đối với tài sản được gọi là quyền", "o": ["chiếm hữu.", "sở hữu.", "sử dụng.", "định đoạt."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D12-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, khi thực hiện quyền của mình về bảo vệ Tổ quốc, mọi công dân nếu đủ điều kiện đều được", "o": ["kinh doanh mặt hàng quân sự.", "hợp lý hóa mô hình kinh doanh.", "mở rộng quy mô sản xuất.", "phục vụ trong quân đội."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D12-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những cơ chế kinh tế được các quốc gia vận dụng để điều hành nền kinh tế đó là", "o": ["cơ chế tự cung tự cấp.", "cơ chế kế hoạch hoá tập trung.", "Cơ chế chỉ huy của Chính phủ.", "Cơ chế thị trường."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D12-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào sau đây thể hiện thói quen chi tiêu không hợp lí?", "o": ["Chi tiêu theo cảm xúc cá nhân.", "Không bỏ qua chi phí phát sinh.", "Sử dụng công cụ hỗ trợ quản lí tài chính.", "Điều chỉnh hoạt động chi tiêu"], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 12 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D12-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Ở nước ta hiện nay, nam nữ bình đẳng trong về tiêu chuẩn, độ tuổi khi được đề bạt, bổ nhiệm vào cùng vị trí quản lý, lãnh đạo của cơ quan tổ chức là thể hiện bình đẳng giới trong lĩnh vực", "o": ["chính trị.", "văn hóa.", "kinh tế.", "gia đình."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 13 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D12-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Căn cứ vào tiêu chí/ đặc điểm nào để phân chia các loại thị trường như thị trường vàng, thị trường bảo hiểm, thị trường bất động sản?", "o": ["Phạm vi hoạt động", "Đối tượng hàng hoá", "Tính chất và cơ chế vận hành", "Vai trò của các đối tượng mua bán"], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D12-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào sau đây thể hiện việc không tôn trọng quyền sở hữu tài sản của công dân?", "o": ["Trao đổi tài sản với bạn bè.", "Thừa kế tài sản của người thân.", "Kí kết hợp đồng mua bán tài sản.", "Làm hỏng tài sản của đồng nghiệp."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D12-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo Luật Di sản văn hoá năm 2013, tổ chức, cá nhân có nghĩa vụ giao nộp di vật, cổ vật, bảo vật quốc gia do mình tìm được cho ai?", "o": ["Bất kì ai mà tổ chức, cá nhân tin tưởng.", "Đại diện tổ chức xã hội nơi cư trú.", "Cơ quan nhà nước có thẩm quyền nơi gần nhất.", "Bất kì cơ quan nhà nước nào."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D12-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trường hợp nào sau đây vi phạm pháp luật về quyền, nghĩa vụ của công dân trong học tập?", "o": ["Học sinh K tự ý tắt điện phòng học bên cạnh khi thấy các bạn lớp đó quên tắt.", "Ông B yêu cầu hội đồng tuyển sinh đại học Trường Đại học X phải cộng điểm ưu tiên cho con mình vì gia đình ông thuộc đồng bào dân tộc thiểu số.", "Với lí do để nâng cao kết quả học tập của học sinh, cô giáo S đã yêu cầu học sinh lớp mình chủ nhiệm học thêm lớp học miễn phí do cô dạy.", "Cho rằng con gái thì không cần học cao nên sau khi T học hết trung học cơ sở, gia đình bà M đã không cho T tiếp tục học lên cấp THPT."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D12-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 18, 19, 20\nGia đình anh T có thu nhập trung bình và đang có kế hoạch sau 8 năm nữa sẽ mua một căn hộ trên phố. Để thực hiện được kế hoạch này, vợ anh là chị H thường xuyên theo dõi, lập kế hoạch thu, chi trong gia đình và điều chỉnh việc sử dụng tài chính để đảm bảo các nhu cầu cơ bản được đáp ứng, tài chính gia đình được duy trì ổn định. Chị cũng thường xuyên theo dõi chi tiêu, ghi chép đánh giá để điều chỉnh kế hoạch khi cần.\nViệc chi tiêu có kế hoạch sẽ giúp gia đình anh T chủ động thực hiện", "o": ["tiêu dùng không giới hạn.", "chi tiêu không tiết kiệm.", "kế hoạch tài chính gia đình.", "cắt bỏ chi tiêu thiết yếu."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D12-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 18, 19, 20\nGia đình anh T có thu nhập trung bình và đang có kế hoạch sau 8 năm nữa sẽ mua một căn hộ trên phố. Để thực hiện được kế hoạch này, vợ anh là chị H thường xuyên theo dõi, lập kế hoạch thu, chi trong gia đình và điều chỉnh việc sử dụng tài chính để đảm bảo các nhu cầu cơ bản được đáp ứng, tài chính gia đình được duy trì ổn định. Chị cũng thường xuyên theo dõi chi tiêu, ghi chép đánh giá để điều chỉnh kế hoạch khi cần.\nThói quen chi tiêu của gia đình anh T là", "o": ["Chi tiêu cảm hứng, không có kế hoạch.", "Lãng phí tiền bạc cho những khoản chi không cần thiết.", "Chi tiêu quá mức so với khả năng tài chính.", "Thường xuyên theo dõi, điều chỉnh cách chi tiêu."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D12-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 18, 19, 20\nGia đình anh T có thu nhập trung bình và đang có kế hoạch sau 8 năm nữa sẽ mua một căn hộ trên phố. Để thực hiện được kế hoạch này, vợ anh là chị H thường xuyên theo dõi, lập kế hoạch thu, chi trong gia đình và điều chỉnh việc sử dụng tài chính để đảm bảo các nhu cầu cơ bản được đáp ứng, tài chính gia đình được duy trì ổn định. Chị cũng thường xuyên theo dõi chi tiêu, ghi chép đánh giá để điều chỉnh kế hoạch khi cần.\nĐể thực hiện tốt kế hoạch thu, chi trong gia đình, trong thời gian tới chị H không nên", "o": ["điều chỉnh tỉ lệ phân chia các khoản chi.", "thực hiện các khoản chi theo kế hoạch.", "cắt giảm các khoản chi thiết yếu.", "kiểm soát các nguồn thu trong gia đình."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 20 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D12-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 21, 22, 23, 24\nSau khi học hết lớp 9, T muốn tiếp tục đi học tiếp nhưng bố mẹ T không đồng ý vì cho rằng là con gái thì không cần học nhiều và yêu cầu T vào làm ở nhà máy X gần nhà dù gia đình vẫn có đủ điều kiện cho T theo học. Trong quá trình làm việc ở nhà máy X, T làm ở bộ phận thường xuyên tiếp xúc với các chất độc hại thông qua công việc hằng ngày là xả nước thải ra môi trường.\nTheo Luật Hôn nhân và gia đình hiện hành, bố mẹ của T đã phân biệt đối xử với các con trên cơ sở nào?", "o": ["Điều kiện kinh tế gia đình.", "Giới tính.", "Lực học của các con.", "Điều kiện việc làm ở địa phương."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D12-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 21, 22, 23, 24\nSau khi học hết lớp 9, T muốn tiếp tục đi học tiếp nhưng bố mẹ T không đồng ý vì cho rằng là con gái thì không cần học nhiều và yêu cầu T vào làm ở nhà máy X gần nhà dù gia đình vẫn có đủ điều kiện cho T theo học. Trong quá trình làm việc ở nhà máy X, T làm ở bộ phận thường xuyên tiếp xúc với các chất độc hại thông qua công việc hằng ngày là xả nước thải ra môi trường.\nTheo Luật Giáo dục hiện hành, việc T học hết lớp 9 thể hiện T đã hoàn thành", "o": ["giáo dục phổ thông.", "giáo dục nghề nghiệp.", "bồi dưỡng giáo dục.", "phổ cập giáo dục."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D12-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 21, 22, 23, 24\nSau khi học hết lớp 9, T muốn tiếp tục đi học tiếp nhưng bố mẹ T không đồng ý vì cho rằng là con gái thì không cần học nhiều và yêu cầu T vào làm ở nhà máy X gần nhà dù gia đình vẫn có đủ điều kiện cho T theo học. Trong quá trình làm việc ở nhà máy X, T làm ở bộ phận thường xuyên tiếp xúc với các chất độc hại thông qua công việc hằng ngày là xả nước thải ra môi trường.\nVới tính chất công việc của mình, T có quyền yêu cầu Công ty X tổ chức cho mình khám sức khoẻ định kì theo quy định hiện hành của pháp luật là", "o": ["ít nhất 01 tháng một lần.", "ít nhất 03 tháng một lần.", "ít nhất 06 tháng một lần.", "ít nhất 09 tháng một lần."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D12-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 21, 22, 23, 24\nSau khi học hết lớp 9, T muốn tiếp tục đi học tiếp nhưng bố mẹ T không đồng ý vì cho rằng là con gái thì không cần học nhiều và yêu cầu T vào làm ở nhà máy X gần nhà dù gia đình vẫn có đủ điều kiện cho T theo học. Trong quá trình làm việc ở nhà máy X, T làm ở bộ phận thường xuyên tiếp xúc với các chất độc hại thông qua công việc hằng ngày là xả nước thải ra môi trường.\nViệc nhà máy X xả thải ra môi trường là vi phạm", "o": ["nghĩa vụ trong bảo vệ môi trường,", "quyền về bảo vệ môi trường.", "nghĩa vụ trong nộp thuế.", "quyền tuyển dụng lao động."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D12-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Theo số liệu từ Cục Đầu tư nước ngoài, Bộ Kế hoạch và Đầu tư, tính đến ngày 20/12/2023, tổng vốn đầu tư nước ngoài đăng kí vào Việt Nam (FDI) đạt gần 36,61 tỉ USD, tăng 32,1 % so với cùng kì; vốn thực hiện của dự án đầu tư nước ngoài ước đạt khoảng 23,18 tỉ USD, tăng 3,5 % so với năm 2022. Trong những năm qua, vốn vay ưu đãi và vốn viện trợ không hoàn lại (ODA) có tác động trực tiếp và gián tiếp đến tăng trưởng kinh tế ở Việt Nam. Vốn ODA góp phần gia tăng tổng đầu tư xã hội, tạo động lực thu hút đầu tư tư nhân và vốn FDI, từ đó thúc đẩy tăng trưởng kinh tế, hỗ trợ Việt Nam đạt được nhiều kết quả trong công cuộc xoá đói giảm nghèo. (Theo: Trang thông tin điện tử Đầu tư nước ngoài – Bộ Kế hoạch và Đầu tư, “Tình hình thu hút đầu tư nước ngoài tại Việt Nam năm 2023”, ngày 16/01/2024)", "o": ["Vốn đầu tư trực tiếp nước ngoài (FDI) còn có tên gọi khác là vốn ODA.", "Mặc dù vốn đầu tư nước ngoài đăng kí vào Việt Nam tăng nhưng tác động của nó đến tăng trưởng kinh tế vẫn còn nhiều tranh cãi.", "Cùng với hoạt động thương mại quốc tế và các dịch vụ thu ngoại tệ, đầu tư quốc tế là một trong các hoạt động kinh tế đối ngoại cơ bản, có ý nghĩa to lớn đối với sự tăng trưởng kinh tế của Việt Nam.", "Việt Nam tiếp nhận vốn vay ưu đãi và vốn viện trợ không hoàn lại góp phần xoá đói giảm nghèo, nâng cao đời sống của các tầng lớp dân cư, thúc đẩy phát triển kinh tế – xã hội."], "a": [false, false, true, true], "e": "Đáp án: a) Sai; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần II câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D12-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Vốn được đào tạo bài bản về công nghệ thông tin và có niềm đam mê đặc biệt với lĩnh vực giáo dục, anh S – Giám đốc điều hành của Công ty Cổ phần phát triển công nghệ giáo dục ABC bắt đầu khởi nghiệp từ năm 2019 (khi còn là sinh viên). Anh cho biết, bản thân nhận thức được rất rõ những giá trị mà khởi nghiệp sớm mang lại, cũng như những khó khăn, thách thức đi kèm. Anh cho rằng để tránh thất bại, các bạn trẻ cần hiểu bản chất của kinh doanh, phân tích thật kĩ về lợi thế cạnh tranh, sự khác biệt, tìm hiểu thị trường và lập kế hoạch kinh doanh thật chi tiết. Tiếp theo là khâu tìm kiếm đội ngũ nhân sự chất lượng để thực hiện dự án. Yếu tố cuối cùng không thể thiếu được đó là dự phòng rủi ro.", "o": ["Ý tưởng kinh doanh của anh S được xác định dựa trên lợi thế nội tại về sự đam mê và hiểu biết.", "Lập kế hoạch kinh doanh một cách chi tiết là việc cần làm đối với người khởi sự kinh doanh.", "Khi đưa ra lời khuyên về khởi nghiệp, anh S nhấn mạnh bước xác định mục tiêu trong quy trình lập kế hoạch kinh doanh.", "Chỉ nên phân tích rủi ro và biện pháp xử lí khi kế hoạch kinh doanh được triển khai trong thực tiễn."], "a": [true, true, false, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Sai.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần II câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D12-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Vợ chồng ông K cùng con là anh T đang sinh sống trên mảnh đất được cấp quyền sử dụng đất mang tên ông K. Năm 2006, vì làm ăn không thuận lợi, ông K có thương lượng và nhượng lại mảnh đất gia đình đang ở cho em gái ruột của ông là cô P với giá 50 triệu đồng. Vì là anh em ruột, ông K và cô P chỉ làm giấy tờ kí tay về thoả thuận trên và ông K giao giấy chứng nhận quyền sử dụng đất cho cô P giữ. Cô P có hứa với gia đình ông K sau này nếu làm ăn được muốn lấy lại đất thì cô sẽ bán lại mảnh đất trên để sinh sống. Năm 2011, con ông K là anh T có đến xin chuộc lại mảnh đất trên thì được cô P đồng ý với giá 130 triệu đồng. Hai tháng sau, tình hình bất động sản nơi này giao dịch trở nên “sôi động”, anh T mang tiền đến mua lại đất thì được biết cô P đã nhượng lại cho cô Ch với giá 500 triệu đồng.", "o": ["Mảnh đất của gia đình ông K trước khi giao cho cô P thuộc sở hữu toàn dân mà Nhà nước là đại diện chủ sở hữu.", "Sau khi nhận giấy chứng nhận quyền sử dụng đất từ ông K và kí giấy thoả thuận tay với ông, quyền sử dụng đất đã được xác lập cho cô P.", "Thoả thuận nhượng đất giữa cô P và cô Ch là phù hợp với quy định của pháp luật.", "Gia đình anh T có quyền yêu cầu cô P huỷ bỏ thoả thuận nhượng đất với cô Ch."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần II câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D12-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Với chủ trương nhất quán thông qua các biện pháp hoà bình giải quyết tranh chấp, bất đồng trên biển, Việt Nam đã có nhiều nỗ lực trong việc áp dụng có hiệu quả Công ước Liên hợp quốc về Luật Biển 1982 để phân định biển với các nước láng giềng, trong đó luôn đề cao nguyên tắc công bằng để tìm ra giải pháp hợp lí, cụ thể là: Việt Nam đã kí với Thái Lan Hiệp định về phân định biển ngày 09/8/1997; kí với Trung Quốc Hiệp định về phân định vịnh Bắc Bộ và Hiệp định hợp tác nghề cá trong vịnh Bắc Bộ ngày 25/12/2000; kí với Indonesia Hiệp định về phân định thềm lục địa ngày 26/6/2003.", "o": ["Các quốc gia cần đàm phán với nhau để giải quyết những tranh chấp, bất đồng trên biển.", "Trong bất kì trường hợp nào, các quốc gia cũng không được giải quyết tranh chấp, bất đồng trên biển bằng vũ lực.", "Công ước Liên hợp quốc về Luật Biển năm 1982 là cơ sở pháp lí quan trọng để bảo vệ quyền và lợi ích của Việt Nam trên biển.", "Việt Nam kí các Hiệp định với Thái Lan, Trung Quốc, Indonesia nhằm chia đều lợi ích giữa các quốc gia."], "a": [true, true, true, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần II câu 4 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}]}, {"id": "TN-D13", "loai": "tn", "khoi": 12, "hoc_ki": 2, "so_de": 13, "ten": "Đề luyện thi tốt nghiệp số 13", "pham_vi": "Đề nguồn của giáo viên, giữ NGUYÊN chữ của đề (chỉ bỏ lỗi sao chép) · «10 ĐỀ» Đề 3 · file nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm 4 lựa chọn + 4 câu đúng/sai (mỗi câu 4 ý)", "cham": {"tong": 10, "tn": 0.25, "ds": [0, 0.1, 0.25, 0.5, 1.0]}, "status": "cho_duyet", "khoa": {"đã giải lại, khớp khoá": 26, "đã tự giải lại": 2}, "sua": "Khoá đã rà 16/11/2026 cùng đề «học kì II» lớp 12: Câu đúng/sai 3 (anh Tuấn thành lập công ty): đề ghi Đ/S ngay trong từng ý (Đ, S, S, Đ); ý c «không có báo cáo tài chính» sai vì đoạn thông tin nói báo cáo tài chính được ghi chép đầy đủ. Gạch chân và file ĐÁP ÁN ghi nhầm ý c là Đúng. Câu đúng/sai 2 (chị T du học cho con): chữ Đúng/Sai đề viết cuối từng ý là S, Đ, S, Đ — gạch chân và file ĐÁP ÁN ghi ngược (Đ, S, Đ, S); ý c «chỉ khi chi tiêu theo sở thích… mới đạt tự do tài chính» rõ ràng sai.", "cau": [{"id": "TN-D13-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong nền kinh tế, chủ thể nào đóng vai trò quan trọng trong việc tạo ra hàng hoá cho xã hội, phục vụ nhu cầu tiêu dùng?", "o": ["Chủ thể trung gian", "Doanh nghiệp Nhà nước", "Các điểm bán hàng", "Chủ thể sản xuất"], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D13-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong nền kinh tế, chủ thể nào đóng vai trò là cầu nối giữa chủ thể sản xuất và chủ thể tiêu dùng?", "o": ["Chủ thể trung gian.", "Nhà đầu tư chứng khoán.", "Chủ thể doang nghiệp.", "Chủ thể nhà nước."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D13-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Loại thuế được cộng vào giá bán hàng hóa, dịch vụ và do người tiêu dùng trả khi sử dụng sản phẩm đó được gọi là gì?", "o": ["Thuế giá trị gia tăng.", "Thuế thu nhập doanh nghiệp.", "Thuế thu nhập cá nhân .", "Thuế bảo vệ môi trường."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D13-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Vai trò nào sau đây không phải của thuế?", "o": ["Thuế là nguồn thu quan trọng nhất cho ngân sách nhà nước.", "Thuế là công cụ kích thích đầu tư nhằm thúc đẩy tăng trưởng kinh tế.", "Thuế thực hiện công bằng an sinh xã hội.", "Thuế là công cụ hiệu quả nhất để điều tiết thu nhập"], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D13-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Lượng hàng hóa, dịch vụ mà người tiêu dùng sẵn sàng mua với một mức giá nhất định trong khoảng thời gian xác định được gọi là", "o": ["cung.", "cầu.", "giá trị.", "giá cả."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 5 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D13-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong sản xuất và lưu thông hàng hóa, khi giá cả thị trường giảm xuống thì các doanh nghiệp thường có xu hướng", "o": ["tăng giá trị cá biệt của hàng hóa", "mở rộng quy mô sản xuất.", "tăng khối lượng cung hàng hóa.", "thu hẹp quy mô sản xuất."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 6 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D13-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tình trạng mức giá chung của nền kinh tế tăng lên trong một khoảng thời gian nhất định được gọi là", "o": ["Tăng trưởng.", "Lạm phát.", "Khủng hoảng.", "Suy thoái."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D13-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Xác định nguyên nhân dẫn đến lạm phát trong thông tin sau: Thông tin.Khi mất cân đối giữa tốc độ tăng cung tiền và tốc độ tăng trưởng GDP lớn thì sức ép lạm phát bắt đầu xuất hiện. Ví dụ, trong hai năm 2005 và 2006, GDP của Việt Nam tăng trưởng 17%, trong khi đó, tiền mặt trong lưu thông và tiền gửi trong ngân hàng tăng tới 73%.", "o": ["Chi phí sản xuất tăng cao.", "Tổng cầu của nền kinh tế tăng.", "Giá cả nguyên liệu, nhân công, thuế,… giảm.", "Lượng tiền trong lưu thông vượt quá mức cần thiết."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D13-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Để khắc phục tình trạng lạm phát do lượng tiền mặt trong lưu thông vượt quá mức cần thiết, nhà nước cần", "o": ["giảm thuế.", "giảm mức cung tiền.", "giảm lãi suất tiền gửi.", "tăng chi tiêu ngân sách."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D13-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tình trạng thất nghiệp để lại hậu quả như thế nào đối với xã hội?", "o": ["Thu nhập giảm hoặc không có, đời sống gặp nhiều khó khăn.", "Lợi nhuận giảm hoặc thua lỗ, buộc phải thu hẹp quy mô sản xuất.", "Lãng phí nguồn lực, làm cho nền kinh tế rơi vào tình trạng suy thoái.", "Phát sinh nhiều tệ nạn xã hội; trật tự, an ninh xã hội không ổn định."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D13-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nơi diễn ra các quan hệ thoả thuận giữa người sử dụng lao động và người lao động về tiền lương, điều kiện làm việc trên cơ sở hợp đồng lao động được gọi là", "o": ["thị trường việc làm.", "thị trường lao động.", "trung tâm giới thiệu việc làm.", "trung tâm môi giới việc làm."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D13-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phiên giao dịch việc làm đã giúp cho các cơ sở sản xuất, kinh doanh tuyển dụng được lao động và những người lao động đã tìm được việc làm phù hợp là biểu hiện nội dung nào sau đây?", "o": ["Mối quan hệ giữa thị trường lao động và thị trường việc làm.", "Mối quan hệ giữa những người sử dụng lao động với nhau.", "Mối quan hệ giữa lao động và thị trường lao động.", "Mối quan hệ giữa việc làm và thị trường việc làm."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 12 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D13-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào sau đây là sai về sự cần thiết của hội nhập kinh tế quốc tế?", "o": ["Tạo cơ hội tiếp cận và sử dụng nguồn lực tài chính bên ngoài.", "Tạo cơ hội tiếp cận và sử dụng kinh nghiệm quản lí bên ngoài.", "Giúp mỗi quốc gia mở rộng thị trường, thu hút nguồn vốn đầu tư.", "Giúp nước này có thể chi phối nước khác về lĩnh vực kinh tế."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 13 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D13-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tổ chức lương thực và Nông nghiệp Liên Hợp Quốc là tổ chức quốc tế thuộc cấp độ hội nhập nào dưới đây ?", "o": ["Hội nhập toàn cầu", "Hội nhập khu vực", "Hội nhập song phương", "Hội nhập đa phương"], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D13-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hệ thống các chính sách do Nhà nước và các lực lượng xã hội thực hiện giải quyết các vấn đề xã hội nhằm nâng cao năng lực tự bảo vệ của người dân và xã hội trước những rủi ro hay nguy cơ giảm hoặc mất thu nhập góp phần cải thiện chất lượng cuộc sống, phát triển và công bằng xã hội là nội dung của khái niệm nào sau đây?", "o": ["Trợ giúp xã hội.", "Chính sách xã hội.", "An sinh xã hội.", "Bảo hiểm xã hội."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D13-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với một doanh nghiệp bước khởi đầu trong quá trình lập kế hoạch kinh doanh là", "o": ["xác định mục tiêu và chiến lược kinh doanh.", "xác định định hướng, ý tưởng kinh doanh.", "xây dựng kế hoạch hoạt động kinh doanh.", "phân tích các điều kiện thực hiện ý tưởng kinh doanh"], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D13-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc trường hợp sau và trả lời các câu hỏi 17, 18\nAnh B thành lập doanh nghiệp tư nhân chuyên bán hàng và cung cấp dịch vụ công nghệ thông tin, được cơ quan nhà nước có thẩm quyền cấp Giấy chứng nhận đăng kí doanh nghiệp. Trước kì nộp thuế, anh B đến cơ quan thuế và được cung cấp đầy đủ thông tin tài liệu liên quan đến quyền và nghĩa vụ nộp thuế. Hiểu được quyền và nghĩa vụ của mình, anh B nghiêm chỉnh chấp hành chế độ kế toán thống kê, ghi chép đầy đủ doanh số bán hàng, kê khai đầy đủ, kịp thời, chính xác số tiền thuế phải nộp, đóng thuế đầy đủ và đúng hạn.\nDoanh nghiệp anh B thực hiện hình thức tổ chức kinh doanh nào?", "o": ["Công ty cổ phần.", "Doanh nghiệp tư nhân.", "Kinh tế tập thể.", "Doanh nghiệp tư bản tư nhân."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D13-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc trường hợp sau và trả lời các câu hỏi 17, 18\nAnh B thành lập doanh nghiệp tư nhân chuyên bán hàng và cung cấp dịch vụ công nghệ thông tin, được cơ quan nhà nước có thẩm quyền cấp Giấy chứng nhận đăng kí doanh nghiệp. Trước kì nộp thuế, anh B đến cơ quan thuế và được cung cấp đầy đủ thông tin tài liệu liên quan đến quyền và nghĩa vụ nộp thuế. Hiểu được quyền và nghĩa vụ của mình, anh B nghiêm chỉnh chấp hành chế độ kế toán thống kê, ghi chép đầy đủ doanh số bán hàng, kê khai đầy đủ, kịp thời, chính xác số tiền thuế phải nộp, đóng thuế đầy đủ và đúng hạn.\nAnh B đã thực hiện nghĩa vụ của một doanh nghiệp như thế nào khi thực hiện hoạt động kinh doanh của mình?", "o": ["Đóng thuế đầy đủ và đúng hạn.", "Kê khai sai lệch về doanh thu của doanh nghiệp.", "Tự do lựa chọn hình thức tổ chức kinh doanh.", "Được cơ quan thuế hướng dẫn đầy đủ thủ tục."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D13-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 19,20\nHằng năm, trường trung học phổ thông Y thường tổ chức cho học sinh đi tham quan các di tích lịch sử - văn hoá của tỉnh. Qua hoạt động tham quan này, học sinh của trường THPT Y được thực hiện quyền của công dân về bảo vệ di sản văn hoá, được giáo dục truyền thống văn hoá của tỉnh qua các thời kì lịch sử. Khi đi tham quan, học sinh tìm hiểu ý nghĩa, lịch sử của các di sản văn hoá của tỉnh. Một số bạn còn ghi chép lại các sự kiện, tìm hiểu thêm các tư liệu liên quan đến di tích.\nHoạt động tổ chức cho học sinh tham quan các di tích lịch sử văn hóa tỉnh của của trường THPT Y là góp phần thực hiện quyền của công dân trong bảo vệ di sản văn hóa ở nội dung nào dưới đây?", "o": ["Tiếp cận và hưởng thụ giá trị di sản.", "Khai thác nguồn lợi kinh tế của di sản.", "Tôn tạo và bổ sung các di sản mới.", "Tham gia phục dựng giá trị di sản."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D13-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 19,20\nHằng năm, trường trung học phổ thông Y thường tổ chức cho học sinh đi tham quan các di tích lịch sử - văn hoá của tỉnh. Qua hoạt động tham quan này, học sinh của trường THPT Y được thực hiện quyền của công dân về bảo vệ di sản văn hoá, được giáo dục truyền thống văn hoá của tỉnh qua các thời kì lịch sử. Khi đi tham quan, học sinh tìm hiểu ý nghĩa, lịch sử của các di sản văn hoá của tỉnh. Một số bạn còn ghi chép lại các sự kiện, tìm hiểu thêm các tư liệu liên quan đến di tích.\nViệc làm nào sau đây của các bạn học sinh trường THPT Y thể hiện nghĩa vụ của công dân trong bảo vệ di sản văn hóa?", "o": ["Tìm hiểu giá trị các di tích.", "Tôn trọng giá trị vốn có của di sản.", "Ghi chép lại đặc điểm di sản.", "Thay đổi giá trị vốn có của di sản."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 20 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D13-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 21,22\nPhát hiện chồng mình là anh D thường qua lại với chị H là người yêu cũ dù chị đã có chồng con, chị M bế con bỏ nhà đi biệt tích. Nắm được sự việc, bà V mẹ chị M, tới nhà bà K nói chuyện, do thiếu kiềm chế, bà V đã có lời lẽ xúc phạm bà K và anh D nên bị con gái bà K mời ra khỏi nhà. Trong thời gian đó, do thường xuyên không được trang bị bảo hộ đạt chuẩn, anh D bị tai nạn phải nằm viện điều trị một tháng. Vì ông T giám đốc công ty nơi anh D làm việc không đồng ý bồi thường số tiền mà anh D yêu cầu nên bà K đã thuê phóng viên viết bài công khai việc ông T có con ngoài ra thú rồi chia sẻ lên mạng khiến uy tín của ông bị ảnh hưởng nghiêm trọng và vợ ông đòi ly hôn.\nTrong thông tin trên những ai dưới đây đã vi phạm quyền và nghĩa vụ giữa vợ và chồng trong quan hệ hôn nhân và gia đình?", "o": ["Chị H, ông T và bà K.", "Ông T, anh D và bà V.", "Anh D, chị H và ông T.", "Anh D, chị H và chị M."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D13-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 21,22\nPhát hiện chồng mình là anh D thường qua lại với chị H là người yêu cũ dù chị đã có chồng con, chị M bế con bỏ nhà đi biệt tích. Nắm được sự việc, bà V mẹ chị M, tới nhà bà K nói chuyện, do thiếu kiềm chế, bà V đã có lời lẽ xúc phạm bà K và anh D nên bị con gái bà K mời ra khỏi nhà. Trong thời gian đó, do thường xuyên không được trang bị bảo hộ đạt chuẩn, anh D bị tai nạn phải nằm viện điều trị một tháng. Vì ông T giám đốc công ty nơi anh D làm việc không đồng ý bồi thường số tiền mà anh D yêu cầu nên bà K đã thuê phóng viên viết bài công khai việc ông T có con ngoài ra thú rồi chia sẻ lên mạng khiến uy tín của ông bị ảnh hưởng nghiêm trọng và vợ ông đòi ly hôn.\nAnh D và chị H đã vi phạm nội dung nào dưới đây của quyền và nghĩa vụ giữa vợ và chồng trong gia đình?", "o": ["Quyền kết hôn.", "Quyền ly hôn.", "Quyền tài sản.", "Quyền nhân thân."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D13-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 23,24\nHundu và Renda đều là hai quốc gia thành viên của Công ước về chống khủng bố quốc tế. Tháng 4/ 2011, Chính phủ Hundu nhận được báo cáo của Cục tình báo quốc gia về việc phát hiện ra nơi ẩn náu trên lãnh thổ Renda của tên trùm khủng bố ( bị truy nã toàn cầu) mà quốc gia này đang tìm kiếm. Chính phủ Hundu ngay lập tức bí mật điều động máy bay quân sự với tần số siêu âm, thoát khỏi sự kiểm soát của rada trinh thám Renda, vượt biên giới, tiến vào lãnh thổ nước này và tấn công nơi ở của tên trùm khủng bố, đồng thời tiêu diệt tên này.\nPhát hiện ra hành vi của Hundu, Renda đã lên tiếng phản đối mạnh mẽ. phía Renda cho rằng hành vi này đã vi phạm nghiêm trọng chủ quyền quốc gia. Tuy nhiên, Hundu cho rằng hành vi của quốc gia này là nhằm thưc hiện nghĩa vụ thành viên của Công ước về chống khủng bố. Hơn nữa, Tổng thống Hundu đã thực hiện cuộc điện đàm chính thức với Tổng thống Renda và ông này hứa sẽ tạo mọi điều kiện thuận lợi cho hoạt động chống khủng bố được thực hiện bởi Hundu.\nHành vi Hundu bí mật điều động máy bay quân sự với tần số siêu âm, thoát khỏi sự kiểm soát của rada trinh thám Renda, vượt biên giới, tiến vào lãnh thổ Renda là", "o": ["vi phạm pháp luật của Randa.", "vi phạm nguyên tắc bình đẳng về chủ quyền giữa các quốc gia của pháp luật quốc tế.", "hành động cần thiết khi bắt khủng bố.", "vi phạm pháp luật quốc tế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D13-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 23,24\nHundu và Renda đều là hai quốc gia thành viên của Công ước về chống khủng bố quốc tế. Tháng 4/ 2011, Chính phủ Hundu nhận được báo cáo của Cục tình báo quốc gia về việc phát hiện ra nơi ẩn náu trên lãnh thổ Renda của tên trùm khủng bố ( bị truy nã toàn cầu) mà quốc gia này đang tìm kiếm. Chính phủ Hundu ngay lập tức bí mật điều động máy bay quân sự với tần số siêu âm, thoát khỏi sự kiểm soát của rada trinh thám Renda, vượt biên giới, tiến vào lãnh thổ nước này và tấn công nơi ở của tên trùm khủng bố, đồng thời tiêu diệt tên này.\nPhát hiện ra hành vi của Hundu, Renda đã lên tiếng phản đối mạnh mẽ. phía Renda cho rằng hành vi này đã vi phạm nghiêm trọng chủ quyền quốc gia. Tuy nhiên, Hundu cho rằng hành vi của quốc gia này là nhằm thưc hiện nghĩa vụ thành viên của Công ước về chống khủng bố. Hơn nữa, Tổng thống Hundu đã thực hiện cuộc điện đàm chính thức với Tổng thống Renda và ông này hứa sẽ tạo mọi điều kiện thuận lợi cho hoạt động chống khủng bố được thực hiện bởi Hundu.\nHành vi của Hundu có hợp pháp không? Vì sao?", "o": ["Có, vì Hundu thực hiện nghĩa vụ thành viên của Công ước về chống khủng bố.", "Không, vì Hundu bí mật điều động máy bay quân sự tiến vào lãnh thổ Renda.", "Không, vì Hundu vi phạm các nguyên tắc cơ bản của pháp luật quốc tế.", "Có, vì tiêu diệt khủng bố là nghĩa vụ của tất cả các nước trên thế giới. II/ CÂU HỎI TRẮC NGHIỆM ĐÚNG/SAI"], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D13-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc thông tin sau Chị E giao kết hợp đồng lao động không xác định thời hạn với công ty A. Hàng tháng, chị E đóng đầy đủ các loại BHXH. Đến 01/6/2020, chị E nghỉ thai sản (nghỉ đến hết 31/12/2020). Vì lý do gia đình, 01/1/2021 chị E nộp đơn xin nghỉ việc. Trước khi chấm dứt HĐLĐ, tổng thời gian đóng bảo hiểm thất nghiệp là 15 tháng. Căn cứ vào quy định của pháp luật lao động chị đã làm hồ sơ gửi cơ quan chức năng để nhận hỗ trợ theo quy định. Sau đó được sự tư vấn của bạn bè, chị E tham gia gói bảo hiểm nhân thọ cho cả mẹ và con chị.", "o": ["Loại hình bảo hiểm xã hội mà chị E tham gia trước khi nghỉ việc là bảo hiểm xã hội tự nguyện.", "Chị E đã tham gia loại hình bảo hiểm thất nghiệp tự nguyện nên chị được hưởng trợ cấp thất nghiệp.", "Trước khi nghỉ việc chị E không tham gia bảo hiểm y tế.", "Bảo hiểm nhân thọ mà chị E tham gia là loại hình bảo hiểm thương mai."], "a": [false, false, false, true], "e": "Đáp án: a) Sai; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D13-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Chị T ấp ủ dự định cho con trai (hiện đang học lớp 10) đi du học. Chị ước tính số tiền cần để trả tiền chi phí cho con 4 năm đại học là 300 triệu đồng. Với số tiền lớn này, Chị T xác định mốc thời gian tiết kiệm tiền phải trên 2 năm, mục tiêu trước mắt là khoản chi phí cho con học trung tâm để lấy chứng chỉ ngoại ngữ trong năm học lớp 10 này. Chị T lập một kế hoạch tài chính để đạt được mục tiêu tài chính trên. Theo dự kiến, mỗi tháng nhà chị T sẽ phải tiết kiệm tối thiểu 8 triệu đồng và duy trì mức tiết kiệm này là 3 năm. Để dự phòng chi phí phát sinh và đáp ứng các nhu cầu cấp thiết khác như: quỹ học tập, quỹ dự phòng, quỹ mừng sinh nhật bạn bè, người thân, ... mỗi tháng chị T tiết kiệm thêm 1 triệu đồng bỏ ở một ống tiết kiệm riêng dùng trong trường hợp khẩn cấp. Ngoài ra, chị T dự tính, sẽ làm thêm công việc báo cáo thuế tháng cho 2 công ty và chị T dùng số tiền này bổ sung vào quỹ tiết kiệm của mình. Trong 20 tháng đầu tiên, gia đình chị T cố gắng đạt được mục tiêu tiết kiệm 200 triệu đồng. Từ số tiền này, T sẽ mở tài khoản tiết kiệm ở ngân hàng để đầu tư sinh lời mỗi năm. Số tiền sinh lời này, T dùng bổ sung vào quỹ tiết kiệm của mình để sớm đạt được mục tiêu tài chính đã đặt.", "o": ["Quản lí thu, chi là việc quản lí các nguồn thu nhập và các khoản chi tiêu của tất cả các thành viên trong gia đình.", "Mục tiêu tài chính của gia đình chị T là mục tiêu tài chính trung hạn.", "Chỉ khi nào được chi tiêu theo sở thích, thỏa mãn mọi nhu cầu của các thành viên trong gia đình thì mới đạt được mục tiêu tự do tài chính.", "Mục tiêu tài chính cho con trai học lấy chứng chỉ ngoại ngữ là mục tiêu tài chính ngắn hạn."], "a": [false, true, false, true], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần II câu 2 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D13-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Anh Tuấn đăng ký thành lập công ty tư nhân chuyên sản xuất hàng may mặc. Khi đăng ký thành lập công ty, anh kê khai đầy đủ nội dung hồ sơ đăng ký doanh nghiệp. Sau 5 năm hoạt động, công ty sản xuất kinh doanh hiệu quả, mang lại lợi nhuận, nộp thuế đóng góp vào ngân sách nhà nước, giải quyết việc làm cho người lao động ở địa phương. Trong suốt 5 năm qua, vốn và tài sản của công ty được sử dụng vào hoạt động kinh doanh luôn được ghi chép đầy đủ vào sổ kế toán và báo cáo tài chính của công ty.", "o": ["Công ty anh Tuấn thành lập thực hiện quyền tuyển dụng, thuê và sử dụng lao động khi tiến hành kinh doanh.", "Anh Tuấn đã thực hiện nghĩa vụ bảo vệ môi trường và tài nguyên thiên nhiên.", "Doanh nghiệp của anh Tuấn không có báo cáo tài chính, vi phạm pháp luật về kinh doanh.", "Khi tiến hành hoạt động kinh doanh, anh Tuấn đã đóng góp vào ngân sách nhà nước."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần II câu 3 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D13-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Anh D hoạt động trong lĩnh vực xuất bản phần mềm cho máy tính. Ngay khi nhận được khoản thu nhập đầu tiên từ công việc, anh D đã chủ động tìm hiểu thông tin về việc nộp thuế để thực hiện nghĩa vụ của mình. Anh D trực tiếp đến cơ quan thuế đề nghị hỗ trợ và được cán bộ cơ quan thuế cung cấp đầy đủ các thông tin liên quan đến quyền và nghĩa vụ nộp thuế. Sau khi nắm được thông tin, anh D đăng kí mã số thuế cá nhân, kê khai đầy đủ thông tin về thu nhập của bản thân và nộp đủ số tiền thuế theo quy định của pháp luật. Thời gian sau đó, mỗi khi đến kì nộp thuế, anh D luôn chủ động khai thuế và nộp thuế đầy đủ, đúng hạn.", "o": ["Anh D vừa thực hiện tốt nghĩa vụ kinh doanh vừa thực hiện tốt nghĩa vụ nộp thuế.", "Việc anh D được cung cấp đầy đủ các thông tin liên quan đến việc nộp thuế của bản thân thể hiện cơ quan thuế đã thực hiện tốt nghĩa vụ của mình.", "Anh D đã thực hiện tốt trách nhiệm kinh tế của doanh nghiệp khi tiến hành kinh doanh.", "Việc đăng ký mã số thuế cá nhân của anh D là thực hiện quyền của công dân về nộp thuế."], "a": [true, true, false, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Sai.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}]}, {"id": "TN-D14", "loai": "tn", "khoi": 12, "hoc_ki": 2, "so_de": 14, "ten": "Đề luyện thi tốt nghiệp số 14", "pham_vi": "Đề nguồn của giáo viên, giữ NGUYÊN chữ của đề (chỉ bỏ lỗi sao chép) · «10 ĐỀ» Đề 4 · file nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm 4 lựa chọn + 4 câu đúng/sai (mỗi câu 4 ý)", "cham": {"tong": 10, "tn": 0.25, "ds": [0, 0.1, 0.25, 0.5, 1.0]}, "status": "cho_duyet", "khoa": {"đã giải lại, khớp khoá": 26, "đã tự giải lại": 2}, "sua": "Khoá đã rà 16/11/2026 cùng đề «học kì II» lớp 12: Câu 13 (chủ doanh nghiệp luôn suy nghĩ để vạch ra chiến lược kinh doanh): năng lực lãnh đạo (C). Ngân hàng bài lớp 11 (Bài 6, đề nguồn) cùng khoá «năng lực lãnh đạo»; khoá A («năng lực quốc tế») trong đề này lệch. Câu đúng/sai 2 (Nicaragua) ý c: «vi phạm nghĩa vụ hợp tác» — hành vi tài trợ, huấn luyện lật đổ chính phủ vi phạm nguyên tắc không can thiệp/không dùng vũ lực, không phải nghĩa vụ hợp tác → Sai (đề HK2-05 có cùng câu và khoá Sai).", "cau": [{"id": "TN-D14-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào dưới đây kìm hãm sự tăng trưởng, phát triển kinh tế đất nước?", "o": ["Sản xuất hàng giả, hàng nhái.", "Tạo việc làm cho người lao động.", "Tìm kiếm thị trường tiêu thụ.", "Đóng thuế theo quy định."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D14-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, khi thực hiện quyền tự do ngôn luận công dân có nghĩa vụ", "o": ["trình bày mọi quan điểm.", "xuyên tạc về mặt nội dung.", "tuân thủ quy định pháp luật.", "ủng hộ mọi quan điểm đưa ra."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D14-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chính sách hỗ trợ người dân phòng ngừa, giảm thiểu rủi ro khi bị giảm hoặc mất thu nhập là nội dung của chính sách an sinh xã hội nào sau đây?", "o": ["Chính sách dịch vụ xã hội cơ bản.", "Chính sách việc làm, thu nhập và giảm nghèo.", "Chính sách bảo hiểm xã hội.", "Chính sách trợ giúp xã hội."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D14-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tổ chức kinh tế có tên riêng, có tài sản, trụ sở giao dịch ổn định, được đăng kí kinh doanh theo quy định của pháp luật nhằm mục đích thực hiện các hoạt động kinh doanh được gọi là", "o": ["doanh nghiệp.", "xưởng sản xuất.", "khu công nghiệp.", "đại lí phân phối."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D14-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mọi công dân đều bình đẳng về nghĩa vụ trước pháp luật khi thực hiện hành vi nào sau đây?", "o": ["Đăng kí hồ sơ đấu thầu.", "Xây dựng nguồn quỹ xã hội.", "Bảo vệ an ninh quốc gia.", "Thay đổi địa bàn cư trú."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 5 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D14-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tự tiện bóc mở, thu giữ, tiêu hủy thư tín của người khác là xâm phạm quyền nào dưới đây của công dân?", "o": ["Quyền bất khả xâm phạm về chỗ ở.", "Quyền được đảm bảo an toàn nơi cư trú.", "Đảm bảo an toàn thư tín, điện thoại, điện tín.", "Quyền bất khả xâm phạm về thân thể."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 6 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D14-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong nền kinh tế thị trường người mua hàng hóa, dịch vụ để thỏa mãn nhu cầu tiêu dùng cho sinh hoạt, sản xuất là", "o": ["chủ thể sản xuất.", "chủ thể tiêu dùng.", "chủ thể trung gian.", "chủ thể nhà nước.."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D14-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Sự tranh đua giữa các chủ thể kinh tế nhằm có được những ưu thế trong sản xuất, tiêu thụ hàng hóa, qua đó thu được lợi ích tối đa là nội dung của khái niệm nào dưới đây?", "o": ["Lợi tức.", "Tranh giành.", "Cạnh tranh.", "Đấu tranh."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D14-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, nếu lần đầu tiến hành khiếu nại, người khiếu nại nếu không đồng ý với quyết định giải quyết khiếu nại của cơ quan có thẩm quyền thì có quyền", "o": ["tố cáo cơ quan chức năng.", "sử dụng các biện pháp bạo lực.", "khiếu nại tiếp lần thứ hai.", "từ chối không thực hiện."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D14-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc Việt Nam gia nhập Tổ chức Thương mại Thế giới thể hiện tham gia cấp độ hội nhập nào dưới đây?", "o": ["Hội nhập toàn cầu.", "Hội nhập khu vực.", "Hội nhập song phương.", "Hội nhập đa phương."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D14-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong quá trình lập kế hoạch kinh doanh, việc nào sau đây là quan trọng để đảm bảo tính khả thi của kế hoạch?", "o": ["Phân tích điểm mạnh, điểm yếu, cơ hội, rủi ro.", "Chuẩn bị một kế hoạch marketing chi tiết.", "Xác định mục tiêu và chiến lược kinh doanh phù hợp.", "Quyết định mức giá bán sản phẩm, dịch vụ."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D14-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây thể hiện ý nghĩa của việc thực hiện trách nhiệm xã hội của doanh nghiệp đối với doanh nghiệp?", "o": ["Giúp ổn định cuộc sống cộng đồng.", "Góp phần bảo vệ môi trường sống.", "Nâng cao thương hiệu và uy tín doanh nghiệp.", "Hỗ trợ giải quyết những khó khăn của cộng đồng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 12 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D14-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi tiến hành hoạt động kinh doanh, chủ doanh nghiệp luôn suy nghĩ để vạch ra chiến lược kinh doanh cho công ty của mình, điều này phản ánh năng lực nào dưới đây của chủ thể kinh doanh?", "o": ["Năng lực quốc tế.", "Năng lực giao tiếp.", "Năng lực lãnh đạo.", "Năng lực làm việc nhóm."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 13 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D14-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Căn cứ vào mức độ lạm phát, có những loại lạm phát nào?", "o": ["Có 2 loại lạm phát: lạm phát vừa phải, siêu lạm phát.", "Có 3 loại lạm phát: lạm phát vừa phải, lạm phát phi mã, siêu lạm phát.", "Có 3 loại lạm phát: lạm phát nhẹ, lạm phát vừa, siêu lạm phát.", "Có 2 loại lạm phát: lạm phát nhẹ và siêu lạm phát."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D14-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nguyên nhân nào dưới đây là nguyên nhân chủ quan dẫn đến người lao động có nguy cơ lâm vào tình trạng thất nghiệp?", "o": ["Do cơ sở kinh doanh đóng cửa.", "Mất cân đối cung cầu lao động.", "Bị kỷ luật do vi phạm hợp đồng.", "Nền kinh tế rơi vào khủng hoảng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D14-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tổng thể các quy phạm pháp luật, các nguyên tắc, định hướng pháp luật có mối liên hệ mật thiết và thống nhất với nhau, được sắp xếp thành các ngành luật, các chế định pháp luật và được thể hiện trong các văn bản do cơ quan nhà nước có thẩm quyền ban hành theo những hình thức, thủ tục nhất định để điều chỉnh các quan hệ xã hội phát sinh trên lãnh thổ Việt Nam là đề cập đến khái niệm nào sau đây?", "o": ["Quy phạm pháp luật Việt Nam.", "Hệ thống pháp luật Việt Nam.", "Hệ thống chính trị Việt Nam.", "Thực hiện pháp luật Việt Nam."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D14-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những căn cứ quan trọng để thực hiện hình thức tín dụng cho vay thế chấp được thực hiện là người vay phải có", "o": ["đầy đủ quan hệ nhân thân.", "tài sản đảm bảo.", "địa vị chính trị.", "tư cách pháp nhân."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D14-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và trả lời câu hỏi 18,19\nCông ty V chuyên sản xuất kinh doanh các sản phẩm sữa, thường xuyên cải tiến mẫu mã, đảm bảo chất lượng sản phẩm cung cấp ra thị trường, kê khai và nộp thuế đầy đủ. Doanh nghiệp đã tham gia chương trình sữa học đường, mang sữa đến các trường mầm non, tiểu học tại nhiều địa phương, phát động cán bộ nhân viên quyên góp, giúp đỡ người dân vùng bị thiên tai vượt qua khó khăn và khắc phục hậu quả sau bão lũ,...\nNội dung nào dưới đây phản ánh việc thực hiện trách nhiệm pháp lý của công ty V?", "o": ["Đảm bảo chất lượng sản phẩm.", "Kê khai và nộp thuế đầy đủ.", "Cải tiễn mẫu mã sản phẩm.", "Tham gia dự án sữa miễn phí."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D14-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và trả lời câu hỏi 18,19\nCông ty V chuyên sản xuất kinh doanh các sản phẩm sữa, thường xuyên cải tiến mẫu mã, đảm bảo chất lượng sản phẩm cung cấp ra thị trường, kê khai và nộp thuế đầy đủ. Doanh nghiệp đã tham gia chương trình sữa học đường, mang sữa đến các trường mầm non, tiểu học tại nhiều địa phương, phát động cán bộ nhân viên quyên góp, giúp đỡ người dân vùng bị thiên tai vượt qua khó khăn và khắc phục hậu quả sau bão lũ,...\nHoạt động tham gia chương trình sữa học đường, mang sữa đến các trường mầm non, tiểu học tại nhiều địa phương là thể hiện trách nhiệm nào dưới đây của công ty?", "o": ["Trách nhiệm kinh tế.", "Trách nhiệm đạo đức.", "Trách nhiệm pháp lý.", "Trách nhiệm nhân văn."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D14-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 20,21,22\nSau khi tốt nghiệp đại học ngành công nghệ sinh học, với lợi thế là nhà gần các trường đại học, lại có diện tích đất lớn, chị D quyết định lập nghiệp bằng con đường kinh doanh sản phẩm cây cảnh mi ni với mong muốn sau hai năm sẽ thành lập một doanh nghiệp phân phối các sản phẩm này. Xác định, đây là lĩnh vực kinh doanh không đòi hỏi vốn lớn, trong khi thị trường là các bạn sinh viên có nhu cầu khá cao về loại sản phẩm này, lại không đòi hỏi phải thuê nhiều lao động. Khi bắt tay vào thực hiện công việc kinh doanh, chị đã tìm các nguồn hàng ở nhiều nơi có truyền thống kinh doanh cây cảnh để nhập về khá, ngoài việc thuê một cửa hàng gần trường đại học để bán và giới thiệu sản phẩm, chị D còn ứng dụng các nền tảng mạng xã hội để đăng và quảng bá sản phẩm. Do thời gian đầu chưa có nhiều kinh nghiệm, nên sản phẩm chị cung cấp nhiều cây gặp sâu bệnh chết, đối tượng khách hàng chưa thực sự nhiều, vốn bỏ ra tuy được bảo toàn nhưng lợi nhuận không cao.  Từ thực tế kinh doanh, chị quyết định mở rộng sản xuất và lên kế hoạch đầu tư thêm nhiều cửa hàng mới cũng như phát triển kênh truyền thống nhằm mở rộng thị trường.\nNội dung nào dưới đây thể hiện chị D đã biết xác định ý tưởng khi lập kế hoạch kinh doanh?", "o": ["Mở cửa hàng để bán.", "Thuê lao động bán hàng.", "Sử dụng mạng xã hội.", "Kinh doanh cây cảnh."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 20 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D14-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 20,21,22\nSau khi tốt nghiệp đại học ngành công nghệ sinh học, với lợi thế là nhà gần các trường đại học, lại có diện tích đất lớn, chị D quyết định lập nghiệp bằng con đường kinh doanh sản phẩm cây cảnh mi ni với mong muốn sau hai năm sẽ thành lập một doanh nghiệp phân phối các sản phẩm này. Xác định, đây là lĩnh vực kinh doanh không đòi hỏi vốn lớn, trong khi thị trường là các bạn sinh viên có nhu cầu khá cao về loại sản phẩm này, lại không đòi hỏi phải thuê nhiều lao động. Khi bắt tay vào thực hiện công việc kinh doanh, chị đã tìm các nguồn hàng ở nhiều nơi có truyền thống kinh doanh cây cảnh để nhập về khá, ngoài việc thuê một cửa hàng gần trường đại học để bán và giới thiệu sản phẩm, chị D còn ứng dụng các nền tảng mạng xã hội để đăng và quảng bá sản phẩm. Do thời gian đầu chưa có nhiều kinh nghiệm, nên sản phẩm chị cung cấp nhiều cây gặp sâu bệnh chết, đối tượng khách hàng chưa thực sự nhiều, vốn bỏ ra tuy được bảo toàn nhưng lợi nhuận không cao.  Từ thực tế kinh doanh, chị quyết định mở rộng sản xuất và lên kế hoạch đầu tư thêm nhiều cửa hàng mới cũng như phát triển kênh truyền thống nhằm mở rộng thị trường.\nViệc làm nào dưới đây thể hiện khả năng phân tích các điều kiện thực hiện ý tưởng kinh doanh của chị D?", "o": ["Thành lập doanh nghiệp sau hai năm.", "Thiếu kinh nghiệm nên chưa thành công.", "Lựa chọn kinh doanh cây cảnh.", "Nhu cầu về mặt hàng cây cảnh lớn."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D14-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 20,21,22\nSau khi tốt nghiệp đại học ngành công nghệ sinh học, với lợi thế là nhà gần các trường đại học, lại có diện tích đất lớn, chị D quyết định lập nghiệp bằng con đường kinh doanh sản phẩm cây cảnh mi ni với mong muốn sau hai năm sẽ thành lập một doanh nghiệp phân phối các sản phẩm này. Xác định, đây là lĩnh vực kinh doanh không đòi hỏi vốn lớn, trong khi thị trường là các bạn sinh viên có nhu cầu khá cao về loại sản phẩm này, lại không đòi hỏi phải thuê nhiều lao động. Khi bắt tay vào thực hiện công việc kinh doanh, chị đã tìm các nguồn hàng ở nhiều nơi có truyền thống kinh doanh cây cảnh để nhập về khá, ngoài việc thuê một cửa hàng gần trường đại học để bán và giới thiệu sản phẩm, chị D còn ứng dụng các nền tảng mạng xã hội để đăng và quảng bá sản phẩm. Do thời gian đầu chưa có nhiều kinh nghiệm, nên sản phẩm chị cung cấp nhiều cây gặp sâu bệnh chết, đối tượng khách hàng chưa thực sự nhiều, vốn bỏ ra tuy được bảo toàn nhưng lợi nhuận không cao.  Từ thực tế kinh doanh, chị quyết định mở rộng sản xuất và lên kế hoạch đầu tư thêm nhiều cửa hàng mới cũng như phát triển kênh truyền thống nhằm mở rộng thị trường.\nChị D đã xác định cho mình mục tiêu kinh doanh là", "o": ["mở rộng sản xuất.", "thành lập doanh nghiệp.", "lập thân, lập nghiệp.", "đẩy mạnh truyền thông."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D14-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và trả lời câu hỏi 23,24\nKhi biết có một căn nhà cũ bán với giá rẻ, anh T liền lên kế hoạch dự trù tài chính, mua lại căn nhà đó để sửa chữa và cho thuê với giá hợp lí. Cách thức này vừa giúp gia đình anh có thêm nguồn thu nhập vừa giữ được tài sản hiện có của anh. Bên cạnh đó, anh T dành một khoản lớn thu nhập cho mục tiêu tiết kiệm. Anh chi tiêu ở mức tối thiểu cho sinh hoạt hằng ngày với các nhu cầu thiết yếu. Anh quan niệm rằng chỉ có tiết kiệm mới có thể thực hiện được mục tiêu mua nhà, mua xe,... Vì vậy, anh hạn chế giao tiếp, không mở rộng quan hệ xã hội để tránh các khoản chi không cần thiết, không mang lại cho anh lợi ích gì.\nNội dung nào dưới đây thể hiện anh T chưa biết phân chia một cách phù hợp giữa các khoản chi tiêu thiết yếu và không thiết yếu?", "o": ["Mua nhà và sửa lại cho thuê.", "Tiết kiệm dùng để mua nhà.", "Bảo toàn tài sản hiện có.", "Dành khoản lớn để tiết kiệm."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D14-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và trả lời câu hỏi 23,24\nKhi biết có một căn nhà cũ bán với giá rẻ, anh T liền lên kế hoạch dự trù tài chính, mua lại căn nhà đó để sửa chữa và cho thuê với giá hợp lí. Cách thức này vừa giúp gia đình anh có thêm nguồn thu nhập vừa giữ được tài sản hiện có của anh. Bên cạnh đó, anh T dành một khoản lớn thu nhập cho mục tiêu tiết kiệm. Anh chi tiêu ở mức tối thiểu cho sinh hoạt hằng ngày với các nhu cầu thiết yếu. Anh quan niệm rằng chỉ có tiết kiệm mới có thể thực hiện được mục tiêu mua nhà, mua xe,... Vì vậy, anh hạn chế giao tiếp, không mở rộng quan hệ xã hội để tránh các khoản chi không cần thiết, không mang lại cho anh lợi ích gì.\nViệc làm nào dưới đây thể hiện anh T đã biết bổ thu nguồn thu nhập cho gia đình?", "o": ["Tập trung vào tiền tiết kiệm.", "Giảm chi tiêu thiết yếu.", "Hạn chế giao tiếp bạn bè.", "Mua nhà rồi cho thuê lại."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D14-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Từ ngày 13 - 17/6/2022, tại Thủ đô Phnom Penh, Campuchia đã diễn ra Cuộc họp hai Chủ tịch Ủy ban liên hợp biên giới Việt Nam - Campuchia, Campuchia - Việt Nam. Tại Cuộc họp, hai bên đã trao đổi một số nội dung liên quan đến việc bảo đảm sự ổn định của đường biên, mốc giới nhằm góp phần củng cố và xây dựng đường biên giới hòa bình, ổn định, hữu nghị và hợp tác cùng phát triển giữa hai nước như: kế hoạch xử lý các cột mốc cũ còn tồn tại trên thực địa tại các khu vực đã hoàn thành phân giới cắm mốc (bao gồm việc dỡ bỏ và giữ lại một số cột mốc để làm chứng tích lịch sử và tạo thuận lợi cho công tác quản lý biên giới); xử lý, khắc phục một số mốc biên giới bị hư hỏng, sạt lở hoặc có nguy cơ sạt lở; khảo sát thực địa, cắm thêm một số cọc đánh dấu điểm đặc trưng làm rõ hướng đi của đường biên giới trên thực địa tại một số khu vực đã hoàn thành phân giới cắm mốc nhưng vẫn có khó khăn trong việc nhận biết. Hai bên khẳng định quyết tâm và nỗ lực tìm giải pháp công bằng, hợp lý mà hai bên cùng chấp nhận được để phân giới cắm mốc đối với 16% đường biên giới còn lại; đồng thời, nhất trí về sự cần thiết xây dựng Hiệp định về quy chế biên giới mới để thay thế cho Hiệp định về quy chế biên giới ký năm 1983 nhằm tạo thuận lợi cho công tác phối hợp quản lý biên giới chung.", "o": ["Xây dựng đường biên giới hòa bình, ổn định, hữu nghị và hợp tác cùng phát triển giữa hai nước Việt Nam – Campuchia là trách nhiệm của Nhà nước và nhân dân cả hai nước.", "Hai nước Việt Nam – Campuchia phối hợp với nhau trong công tác quản lý biên giới chung là thực hiện đúng quy định của pháp luật quốc tế.", "Khảo sát thực địa, cắm thêm một số cọc đánh dấu điểm đặc trưng làm rõ hướng đi của đường biên giới trên thực địa là việc làm cần thiết.", "Đường biên giới trên đất liền giữa hai nước không cần thể hiện trên bản đồ."], "a": [true, true, true, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần II câu 1 · khoá: file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D14-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Năm 1979, một cuộc cách mạng nổi dậy ở Nicaragua thành công đưa Phong trào Sadino lên nắm quyền. Hoa Kỳ từ lâu đã chống đối Sadino, nên sau khi lực lượng Sadino lên nắm quyền, chính quyền Tổng thống Carter nhanh chóng hành động, ủng hộ tài chính cho phe đối lập để chống đối chính phủ của Phong trào Sadino ở Nicaragua. Khi ông Ronald Reagan làm Tổng thống, ông gia tăng hỗ trợ cho các nhóm Contras chống Sandino, thông qua ủng hộ tài chính, huấn luyện quân sự với âm mưu bạo động lật đổ chính phủ Sandino ở Nicaragua. Nicagua kiện Hoa Kỳ lên Toà án Công lí quốc tế. Năm 1986, Toà án Công lí quốc tế ra phán quyết, rằng Hoa Kỳ đã không tuân thủ trách nhiệm đối với pháp luật quốc tế.", "o": ["Tòa án công lý quốc tế là cơ quan tư pháp trong hệ thống pháp luật quốc tế.", "Việc Hoa Kỳ can thiệp ủng hộ tài chính cho phe đối lập để chống đối chính phủ của Phong trào Sadino ở Nicaragua la vi phạm nguyên tắc sử dụng vũ lực trong quan hệ quốc tế.", "Hoạt động ủnh hộ tài chính, huấn luyện quan sự với âm mưu bạo động lật đổ chính phủ Sandino ở Nicaragua của Hoa Kỳ là vi phạm nghĩa vụ hợp tác với các quốc gia khác.", "Việc Toà án Công lí quốc tế ra phán quyết khẳng định Hoa Kỳ đã vi phạm luật pháp quốc tế là thể hiện vai trò của pháp luật quốc tế đối với các quốc gia."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần II câu 2 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D14-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Ông S là giám đốc công ty cổ phần sản xuất hàng công nghiệp. Trong quá trình sản xuất, ông đã chỉ đạo công ty làm mọi cách để giảm chi phí sản xuất nhằm tăng lợi nhuận cho công ty, kể cả việc bỏ qua trách nhiệm của công ty về bảo vệ môi trường như thải khí thải vượt quá mức quy định và xả nước thải chưa qua xử lí vào nguồn nước, gây ảnh hưởng nghiêm trọng đến sức khoẻ và đời sống của người dân khu vực xung quanh. Đối với sản phẩm của công ty, khi sản phẩm có chỗ đứng trong thị trường, ông S chỉ đạo công ty thay đổi một số lính kiện có giá rẻ hơn để lấp ráp vào sản phẩm, làm giảm chi phí sản xuất, tăng lợi nhuận cho công ty. Đối với người lao động, công ty đã ký hợp đồng thời vụ với một số lao động phổ thông để không phải đóng bảo hiểm xã hội cho họ đồng thời tạo điều kiện để họ được tự do di chuyển sang công ty khác nếu cần.", "o": ["Giám đốc S chưa thực hiện tốt trách nhiệm pháp lý và trách nhiệm đạo đức trong quá trình hoạt động sản xuất kinh doanh.", "Việc bỏ qua yếu tố về môi trường cũng như lắp ráp sản phẩm có giá rẻ hơn để tối ưu hóa lợi nhuận là phù hợp với trách nhiệm kinh tế của doanh nghiệp.", "Việc tạo điều để người lao động ký hợp đồng thời vụ và không phải đóng bảo hiểm xã hội là thể hiện trách nhiệm đạo đức của doanh nghiệp.", "Để xây dựng uy tín và thương hiệu cho công ty, ông S nên trích lợi nhuận để tham gia các hoạt động từ thiện nhân đạo."], "a": [true, false, false, false], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Sai.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần II câu 3 · khoá: file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D14-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Trên cùng địa bàn một huyện có anh D là chủ hai doanh nghiệp kinh doanh thức ăn chăn nuôi; anh K là giám đốc một công ty tư nhân có chị P là kế toán, còn anh V là nhân viên của anh K. Để tăng vốn kinh doanh, anh K chỉ đạo chị P là kế toán kê khai không đầy đủ số tiền thuế phải nộp của công ty nên anh K đã bị cơ quan chức năng xử phạt. Nghi ngờ anh V là tố cáo hành vi của mình, anh K cố tình trì hoãn đóng bảo hiểm xã hội cho anh V như đã cam kết. Bức xúc, anh V tự ý nghỉ việc ở công ty của anh K và sang làm việc cho anh D. Một lần chứng kiến anh D bị cơ quan chức năng xử phạt về hành vi cung cấp sản phẩm không đảm bảo đúng tiêu chuẩn đã công bố, anh V đã kể lại sự việc cho vợ mình là chị T. Vô tình phát hiện việc anh D bị xử phạt, chị P đã viết và đăng bài xuyên tạc về doanh nghiệp của anh D lên mạng xã hội khiến lượng khách hàng của anh D giảm sút", "o": ["Anh D và anh K đều được thực hiện quyền của công dân về kinh doanh.", "Anh K thực hiện tốt nghĩa vụ kinh doanh nhưng vi phạm nghĩa vụ nộp thuế đối.", "Anh K vừa vi phạm trách nhiệm kinh tế vừa vi phạm trách nhiệm pháp lý của doanh nghiệp khi tiến hành kinh doanh.", "Anh K và anh D đều chưa thực hiện tốt nghĩa vụ kinh doanh."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần II câu 4 · khoá: file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}]}, {"id": "TN-D15", "loai": "tn", "khoi": 12, "hoc_ki": 2, "so_de": 15, "ten": "Đề luyện thi tốt nghiệp số 15", "pham_vi": "Đề nguồn của giáo viên, giữ NGUYÊN chữ của đề (chỉ bỏ lỗi sao chép) · «10 ĐỀ» Đề 5 · file nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm 4 lựa chọn + 4 câu đúng/sai (mỗi câu 4 ý)", "cham": {"tong": 10, "tn": 0.25, "ds": [0, 0.1, 0.25, 0.5, 1.0]}, "status": "cho_duyet", "khoa": {"đã giải lại, khớp khoá": 28}, "sua": "", "cau": [{"id": "TN-D15-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Yếu tố nào sau đây là chỉ tiêu của tăng trưởng kinh tế?", "o": ["Số lao động tham gia sản xuất.", "Sự gia tăng dân số của một quốc gia.", "Mức tăng tổng sản phẩm quốc nội.", "Tổng diện tích đất được sử dụng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D15-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, khi thực hiện quyền tự do ngôn luận công dân có nghĩa vụ", "o": ["trình bày mọi quan điểm.", "xuyên tạc về mặt nội dung.", "tuân thủ quy định pháp luật.", "ủng hộ mọi quan điểm đưa ra."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D15-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Sự bảo đảm thay thế hoặc bù đắp một phần thu nhập của người lao động khi họ bị giảm hoặc mất thu nhập do ốm đau, tai nạn lao động, hết tuổi lao động,... trên cơ sở đóng vào quỹ bảo hiểm xã hội được gọi là", "o": ["bảo hiểm nhân thọ.", "bảo hiểm thất nghiệp.", "bảo hiểm xã hội.", "bảo hiểm y tế."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D15-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mô hình sản xuất kinh doanh do cá nhân hoặc một nhóm người là công dân Việt Nam đủ 18 tuổi, có năng lực hành vi dân sự đầy đủ, hoặc một hộ gia đình làm chủ, tự tổ chức sản xuất kinh doanh theo định hướng phát triển kinh tế của nhà nước, địa phương và quy định của pháp luật, tự chủ trong quản lí và tiêu thụ sản phẩm được gọi là", "o": ["công ty hợp danh.", "liên hiệp hợp tác xã.", "hộ sản xuất kinh doanh.", "doanh nghiệp tư nhân."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D15-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mọi công dân đều bình đẳng về nghĩa vụ trước pháp luật khi thực hiện hành vi nào sau đây?", "o": ["Đăng kí hồ sơ đấu thầu.", "Xây dựng nguồn quỹ xã hội.", "Bảo vệ an ninh quốc gia.", "Thay đổi địa bàn cư trú."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 5 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D15-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tự tiện bóc mở, thu giữ, tiêu hủy thư tín của người khác là xâm phạm quyền nào dưới đây của công dân?", "o": ["Quyền bất khả xâm phạm về chỗ ở.", "Quyền được đảm bảo an toàn nơi cư trú.", "Đảm bảo an toàn thư tín, điện thoại, điện tín.", "Quyền bất khả xâm phạm về thân thể."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 6 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D15-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong các hoạt động dưới đây, hoạt động nào mà con người sử dụng các yếu tố sản xuất để tạo ra các sản phẩm đáp ứng nhu cầu của đời sống xã hội?", "o": ["Hoạt động sản xuất.", "Hoạt động trao đổi.", "Hoạt động tiêu dùng.", "Hoạt động phân phối."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D15-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Các hãng xe đua nhau tung ra các mẫu xe máy điện mới, với thiết kế đa dạng và tính năng hiện đại để thu được nhiều lợi nhuận là thể hiện sự", "o": ["tranh giành.", "phát triển.", "đấu tranh.", "cạnh tranh."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D15-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, nếu lần đầu tiến hành khiếu nại, người khiếu nại nếu không đồng ý với quyết định giải quyết khiếu nại của cơ quan có thẩm quyền thì có quyền", "o": ["tố cáo cơ quan chức năng.", "sử dụng các biện pháp bạo lực.", "khiếu nại tiếp lần thứ hai.", "từ chối không thực hiện."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D15-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc Việt Nam gia nhập Tổ chức Thương mại Thế giới thể hiện tham gia cấp độ hội nhập nào dưới đây?", "o": ["Hội nhập toàn cầu.", "Hội nhập khu vực.", "Hội nhập song phương.", "Hội nhập đa phương."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D15-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Kế hoạch kinh doanh xác định rõ sứ mệnh, tầm nhìn, chiến lược, công việc dự định thực hiện và cách đạt được", "o": ["mục tiêu kinh doanh.", "trách nhiệm kinh tế.", "trách nhiệm xã hội.", "mục tiêu xã hội."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D15-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Cam kết của doanh nghiệp đóng góp cho việc phát triển kinh tế bền vững thông qua những việc làm nâng cao chất lượng đời sống của người lao động, thân nhân người lao động, cộng đông, cho toàn xã hội theo cách có lợi cho cả doanh nghiệp cũng như phát triển chung cho cả xã hội được gọi là", "o": ["trách nhiệm xã hội của doanh nghiệp", "trách nhiệm kinh doanh của doanh nghiệp.", "nghĩa vụ xã hội của doanh nghiệp.", "nghĩa vụ kinh doanh của doanh nghiệp."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 12 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D15-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Các nguồn giúp tạo ý tưởng kinh doanh của chủ thể sản xuất kinh doanh xuất phát từ yếu tố nào dưới đây?", "o": ["Lợi thế nội tại và cơ hội bên ngoài.", "Điểm yếu nội tại và khó khăn bên ngoài.", "Mâu thuẫn của chủ thể sản xuất.", "Khó khăn của chủ thể sản xuất."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 13 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D15-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong nền kinh tế thị trường khi xuất hiện tình trạng lạm phát phi mã sẽ gây ra hiện tượng như thế nào đối với nền kinh tế đó?", "o": ["bất ổn nghiêm trọng.", "hiệu ứng tích cực.", "sụp đổ hoàn toàn.", "cung tăng liên tục."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D15-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi tham gia vào thị trường lao động, việc ký kết hợp đồng mua bán sức lao động giữa người bán sức lao động và người mua sức lao động được thực hiện theo nguyên tắc nào dưới đây?", "o": ["Tự nguyện.", "Cưỡng chế.", "Cưỡng bức.", "Tự giác."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D15-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tổng thể các quy phạm pháp luật, các nguyên tắc, định hướng pháp luật có mối liên hệ mật thiết và thống nhất với nhau, được sắp xếp thành các ngành luật, các chế định pháp luật và được thể hiện trong các văn bản do cơ quan nhà nước có thẩm quyền ban hành theo những hình thức, thủ tục nhất định để điều chỉnh các quan hệ xã hội phát sinh trên lãnh thổ Việt Nam là đề cập đến khái niệm nào sau đây?", "o": ["Quy phạm pháp luật Việt Nam.", "Hệ thống pháp luật Việt Nam.", "Hệ thống chính trị Việt Nam.", "Thực hiện pháp luật Việt Nam."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D15-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hình thức vay tín dụng ngân hàng nào sau đây người vay phải trả lãi hàng tháng và một phần nợ gốc?", "o": ["Vay trả góp.", "Vay tín chấp.", "Vay thấu chi.", "Vay thế chấp."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D15-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và trả lời câu hỏi 18,19\nTính chung thời kì thực hiện Chiến lược phát triển kinh tế xã hội 10 năm (2011 - 2020), tăng trưởng GDP của Việt Nam đạt khoảng 5,9%/năm, thuộc nhóm các nước tăng trưởng cao trong khu vực. Quy mô GDP tăng gấp 2,4 lần, từ 116 tỉ USD năm 2010 lên 268,4 tỉ USD vào năm 2020. GDP bình quân đầu người tăng từ 1.331 USD năm 2010 lên khoảng 2.750 USD năm 2020. Tỉ lệ hộ nghèo cả nước giảm nhanh, từ 14,2% năm 2010 xuống còn 7% năm 2015 (theo chuẩn nghèo giai đoạn 2011 - 2015) và giảm từ 9,2% năm 2016 xuống dưới 3% vào năm 2020 (theo chuẩn nghèo đa chiều). Cơ sở hạ tầng thiết yếu ở các huyện nghèo, xã nghèo, vùng đồng bào dân tộc thiểu số được tăng cường. Thực hiện nhiều giải pháp tạo việc làm, nâng cao thu nhập cho người lao động\nNội dung nào dưới đây thể hiện tăng trưởng kinh tế là điều kiện vật chất để thực hiện phát triển bền vững được đề cập trong thông tin trên?", "o": ["Thuộc nhóm các nước tăng trưởng cao.", "Tốc độ tăng dân số phù hợp với.", "Tạo việc làm và nâng cao thu nhập.", "Giảm tỷ lệ lạm phát, giá cả được kiểm soát."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D15-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và trả lời câu hỏi 18,19\nTính chung thời kì thực hiện Chiến lược phát triển kinh tế xã hội 10 năm (2011 - 2020), tăng trưởng GDP của Việt Nam đạt khoảng 5,9%/năm, thuộc nhóm các nước tăng trưởng cao trong khu vực. Quy mô GDP tăng gấp 2,4 lần, từ 116 tỉ USD năm 2010 lên 268,4 tỉ USD vào năm 2020. GDP bình quân đầu người tăng từ 1.331 USD năm 2010 lên khoảng 2.750 USD năm 2020. Tỉ lệ hộ nghèo cả nước giảm nhanh, từ 14,2% năm 2010 xuống còn 7% năm 2015 (theo chuẩn nghèo giai đoạn 2011 - 2015) và giảm từ 9,2% năm 2016 xuống dưới 3% vào năm 2020 (theo chuẩn nghèo đa chiều). Cơ sở hạ tầng thiết yếu ở các huyện nghèo, xã nghèo, vùng đồng bào dân tộc thiểu số được tăng cường. Thực hiện nhiều giải pháp tạo việc làm, nâng cao thu nhập cho người lao động\nYếu tố nào được đề cập trong thông tin trên là nhân tố quyết định việc thực hiện các chỉ tiêu phát triển kinh tế về mặt xã hội?", "o": ["Tăng trưởng dân số.", "Tốc độ tăng lạm phát.", "Tăng trưởng việc làm.", "Tăng trưởng kinh tế."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D15-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 20,21,22\nSau khi tốt nghiệp đại học ngành công nghệ sinh học, với lợi thế là nhà gần các trường đại học, lại có diện tích đất lớn, chị D quyết định lập nghiệp bằng con đường kinh doanh sản phẩm cây cảnh mi ni với mong muốn sau hai năm sẽ thành lập một doanh nghiệp phân phối các sản phẩm này. Xác định, đây là lĩnh vực kinh doanh không đòi hỏi vốn lớn, trong khi thị trường là các bạn sinh viên có nhu cầu khá cao về loại sản phẩm này, lại không đòi hỏi phải thuê nhiều lao động. Khi bắt tay vào thực hiện công việc kinh doanh, chị đã tìm các nguồn hàng ở nhiều nơi có truyền thống kinh doanh cây cảnh để nhập về khá, ngoài việc thuê một cửa hàng gần trường đại học để bán và giới thiệu sản phẩm, chị D còn ứng dụng các nền tảng mạng xã hội để đăng và quảng bá sản phẩm. Do thời gian đầu chưa có nhiều kinh nghiệm, nên sản phẩm chị cung cấp nhiều cây gặp sâu bệnh chết, đối tượng khách hàng chưa thực sự nhiều, vốn bỏ ra tuy được bảo toàn nhưng lợi nhuận không cao.  Từ thực tế kinh doanh, chị quyết định mở rộng sản xuất và lên kế hoạch đầu tư thêm nhiều cửa hàng mới cũng như phát triển kênh truyền thống nhằm mở rộng thị trường.\nNội dung nào dưới đây thể hiện chị D đã biết xác định ý tưởng khi lập kế hoạch kinh doanh?", "o": ["Mở cửa hàng để bán.", "Thuê lao động bán hàng.", "Sử dụng mạng xã hội.", "Kinh doanh cây cảnh."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 20 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D15-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 20,21,22\nSau khi tốt nghiệp đại học ngành công nghệ sinh học, với lợi thế là nhà gần các trường đại học, lại có diện tích đất lớn, chị D quyết định lập nghiệp bằng con đường kinh doanh sản phẩm cây cảnh mi ni với mong muốn sau hai năm sẽ thành lập một doanh nghiệp phân phối các sản phẩm này. Xác định, đây là lĩnh vực kinh doanh không đòi hỏi vốn lớn, trong khi thị trường là các bạn sinh viên có nhu cầu khá cao về loại sản phẩm này, lại không đòi hỏi phải thuê nhiều lao động. Khi bắt tay vào thực hiện công việc kinh doanh, chị đã tìm các nguồn hàng ở nhiều nơi có truyền thống kinh doanh cây cảnh để nhập về khá, ngoài việc thuê một cửa hàng gần trường đại học để bán và giới thiệu sản phẩm, chị D còn ứng dụng các nền tảng mạng xã hội để đăng và quảng bá sản phẩm. Do thời gian đầu chưa có nhiều kinh nghiệm, nên sản phẩm chị cung cấp nhiều cây gặp sâu bệnh chết, đối tượng khách hàng chưa thực sự nhiều, vốn bỏ ra tuy được bảo toàn nhưng lợi nhuận không cao.  Từ thực tế kinh doanh, chị quyết định mở rộng sản xuất và lên kế hoạch đầu tư thêm nhiều cửa hàng mới cũng như phát triển kênh truyền thống nhằm mở rộng thị trường.\nViệc làm nào dưới đây thể hiện khả năng phân tích các điều kiện thực hiện ý tưởng kinh doanh của chị D?", "o": ["Thành lập doanh nghiệp sau hai năm.", "Thiếu kinh nghiệm nên chưa thành công.", "Lựa chọn kinh doanh cây cảnh.", "Nhu cầu về mặt hàng cây cảnh lớn."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D15-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 20,21,22\nSau khi tốt nghiệp đại học ngành công nghệ sinh học, với lợi thế là nhà gần các trường đại học, lại có diện tích đất lớn, chị D quyết định lập nghiệp bằng con đường kinh doanh sản phẩm cây cảnh mi ni với mong muốn sau hai năm sẽ thành lập một doanh nghiệp phân phối các sản phẩm này. Xác định, đây là lĩnh vực kinh doanh không đòi hỏi vốn lớn, trong khi thị trường là các bạn sinh viên có nhu cầu khá cao về loại sản phẩm này, lại không đòi hỏi phải thuê nhiều lao động. Khi bắt tay vào thực hiện công việc kinh doanh, chị đã tìm các nguồn hàng ở nhiều nơi có truyền thống kinh doanh cây cảnh để nhập về khá, ngoài việc thuê một cửa hàng gần trường đại học để bán và giới thiệu sản phẩm, chị D còn ứng dụng các nền tảng mạng xã hội để đăng và quảng bá sản phẩm. Do thời gian đầu chưa có nhiều kinh nghiệm, nên sản phẩm chị cung cấp nhiều cây gặp sâu bệnh chết, đối tượng khách hàng chưa thực sự nhiều, vốn bỏ ra tuy được bảo toàn nhưng lợi nhuận không cao.  Từ thực tế kinh doanh, chị quyết định mở rộng sản xuất và lên kế hoạch đầu tư thêm nhiều cửa hàng mới cũng như phát triển kênh truyền thống nhằm mở rộng thị trường.\nChị D đã xác định cho mình mục tiêu kinh doanh là", "o": ["mở rộng sản xuất.", "thành lập doanh nghiệp.", "lập thân, lập nghiệp.", "đẩy mạnh truyền thông."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D15-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và trả lời câu hỏi 23,24\nKhi biết có một căn nhà cũ bán với giá rẻ, anh T liền lên kế hoạch dự trù tài chính, mua lại căn nhà đó để sửa chữa và cho thuê với giá hợp lí. Cách thức này vừa giúp gia đình anh có thêm nguồn thu nhập vừa giữ được tài sản hiện có của anh. Bên cạnh đó, anh T dành một khoản lớn thu nhập cho mục tiêu tiết kiệm. Anh chi tiêu ở mức tối thiểu cho sinh hoạt hằng ngày với các nhu cầu thiết yếu. Anh quan niệm rằng chỉ có tiết kiệm mới có thể thực hiện được mục tiêu mua nhà, mua xe,... Vì vậy, anh hạn chế giao tiếp, không mở rộng quan hệ xã hội để tránh các khoản chi không cần thiết, không mang lại cho anh lợi ích gì.\nNội dung nào dưới đây thể hiện anh T chưa biết phân chia một cách phù hợp giữa các khoản chi tiêu thiết yếu và không thiết yếu?", "o": ["Mua nhà và sửa lại cho thuê.", "Tiết kiệm dùng để mua nhà.", "Bảo toàn tài sản hiện có.", "Dành khoản lớn để tiết kiệm."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D15-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và trả lời câu hỏi 23,24\nKhi biết có một căn nhà cũ bán với giá rẻ, anh T liền lên kế hoạch dự trù tài chính, mua lại căn nhà đó để sửa chữa và cho thuê với giá hợp lí. Cách thức này vừa giúp gia đình anh có thêm nguồn thu nhập vừa giữ được tài sản hiện có của anh. Bên cạnh đó, anh T dành một khoản lớn thu nhập cho mục tiêu tiết kiệm. Anh chi tiêu ở mức tối thiểu cho sinh hoạt hằng ngày với các nhu cầu thiết yếu. Anh quan niệm rằng chỉ có tiết kiệm mới có thể thực hiện được mục tiêu mua nhà, mua xe,... Vì vậy, anh hạn chế giao tiếp, không mở rộng quan hệ xã hội để tránh các khoản chi không cần thiết, không mang lại cho anh lợi ích gì.\nViệc làm nào dưới đây thể hiện anh T đã biết bổ thu nguồn thu nhập cho gia đình?", "o": ["Tập trung vào tiền tiết kiệm.", "Giảm chi tiêu thiết yếu.", "Hạn chế giao tiếp bạn bè.", "Mua nhà rồi cho thuê lại."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D15-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Vị thế của Việt Nam trên thế giới đã được củng cố toàn diện trong giai đoạn 2011 - 2022. Cùng với quá trình hội nhập kinh tế quốc tế mạnh mẽ, đến năm 2020, Việt Nam có 30 đối tác chiến lược và đối tác chiến lược toàn diện; có quan hệ ngoại giao với 189/193 nước, có quan hệ kinh tế với 160 nước và 70 vùng lãnh thổ. Đến năm 2022, tổng số quan hệ kinh tế - thương mại của Việt Nam đã nâng lên thành 230 nước và vùng lãnh thổ. Với việc thực hiện chủ trương hội nhập quốc tế toàn diện với trọng tâm là hội nhập kinh tế quốc tế, vị thế của đất nước tiếp tục được cải thiện đáng kể. Có thể khẳng định, hội nhập kinh tế quốc tế đóng góp quan trọng vào việc mở rộng và đưa quan hệ của nước ta với các đối tác đi vào chiều sâu, tạo thế đan xen lợi ích, góp phần gìn giữ môi trường hòa bình, ổn định để phát triển đất nước; nâng cao uy tín và vị thế của Việt Nam trên trường quốc tế.", "o": ["Việc thiết lập quan hệ đối tác chiến lược và chiến lực toàn diện là thể hiện hình thức hội nhập kinh tế quốc tế ở cấp độ khu vực.", "Hội nhập kinh tế quốc tế không góp phần thúc đẩy sự tăng trưởng GDP hàng năm ở Việt Nam.", "Nước ta đang phát triển vì vậy khi hội nhập kinh tế quốc tế Việt Nam phải chấp nhận từ bỏ lợi ích của mình để hội nhập.", "Hội nhập kinh tế quốc tế góp phần đưa hàng hóa của Việt Nam đến với các thị trường trên thế giới."], "a": [false, false, false, true], "e": "Đáp án: a) Sai; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần II câu 1 · khoá: file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D15-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Năm 1979, một cuộc cách mạng nổi dậy ở Nicaragua thành công đưa Phong trào Sadino lên nắm quyền. Hoa Kỳ từ lâu đã chống đối Sadino, nên sau khi lực lượng Sadino lên nắm quyền, chính quyền Tổng thống Carter nhanh chóng hành động, ủng hộ tài chính cho phe đối lập để chống đối chính phủ của Phong trào Sadino ở Nicaragua. Khi ông Ronald Reagan làm Tổng thống, ông gia tăng hỗ trợ cho các nhóm Contras chống Sandino, thông qua ủng hộ tài chính, huấn luyện quân sự với âm mưu bạo động lật đổ chính phủ Sandino ở Nicaragua. Nicagua kiện Hoa Kỳ lên Toà án Công lí quốc tế. Năm 1986, Toà án Công lí quốc tế ra phán quyết, rằng Hoa Kỳ đã không tuân thủ trách nhiệm đối với pháp luật quốc tế.", "o": ["Tòa án công lý quốc tế là cơ quan tư pháp trong hệ thống pháp luật quốc tế.", "Việc Hoa Kỳ can thiệp ủng hộ tài chính cho phe đối lập để chống đối chính phủ của Phong trào Sadino ở Nicaragua la vi phạm nguyên tắc sử dụng vũ lực trong quan hệ quốc tế.", "Hoạt động ủng hộ tài chính, huấn luyện quan sự với âm mưu bạo động lật đổ chính phủ Sandino ở Nicaragua của Hoa Kỳ là vi phạm nghĩa vụ hợp tác với các quốc gia khác.", "Việc Toà án Công lí quốc tế ra phán quyết khẳng định Hoa Kỳ đã vi phạm luật pháp quốc tế là thể hiện vai trò của pháp luật quốc tế đối với các quốc gia."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần II câu 2 · khoá: file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D15-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Ông S là giám đốc công ty cổ phần sản xuất hàng công nghiệp. Trong quá trình sản xuất, ông đã chỉ đạo công ty làm mọi cách để giảm chi phí sản xuất nhằm tăng lợi nhuận cho công ty, kể cả việc bỏ qua trách nhiệm của công ty về bảo vệ môi trường như thải khí thải vượt quá mức quy định và xả nước thải chưa qua xử lí vào nguồn nước, gây ảnh hưởng nghiêm trọng đến sức khoẻ và đời sống của người dân khu vực xung quanh. Đối với sản phẩm của công ty, khi sản phẩm có chỗ đứng trong thị trường, ông S chỉ đạo công ty thay đổi một số lính kiện có giá rẻ hơn để lấp ráp vào sản phẩm, làm giảm chi phí sản xuất, tăng lợi nhuận cho công ty. Đối với người lao động, công ty đã ký hợp đồng thời vụ với một số lao động phổ thông để không phải đóng bảo hiểm xã hội cho họ đồng thời tạo điều kiện để họ được tự do di chuyển sang công ty khác nếu cần.", "o": ["Giám đốc S chưa thực hiện tốt trách nhiệm pháp lý và trách nhiệm đạo đức trong quá trình hoạt động sản xuất kinh doanh.", "Việc bỏ qua yếu tố về môi trường cũng như lắp ráp sản phẩm có giá rẻ hơn để tối ưu hóa lợi nhuận là phù hợp với trách nhiệm kinh tế của doanh nghiệp.", "Việc tạo điều để người lao động ký hợp đồng thời vụ và không phải đóng bảo hiểm xã hội là thể hiện trách nhiệm đạo đức của doanh nghiệp.", "Để xây dựng uy tín và thương hiệu cho công ty, ông S nên trích lợi nhuận để tham gia các hoạt động từ thiện nhân đạo."], "a": [true, false, false, false], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Sai.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần II câu 3 · khoá: file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D15-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Trên cùng địa bàn một huyện có anh D là chủ hai doanh nghiệp kinh doanh thức ăn chăn nuôi; anh K là giám đốc một công ty tư nhân có chị P là kế toán, còn anh V là nhân viên của anh K. Để tăng vốn kinh doanh, anh K chỉ đạo chị P là kế toán kê khai không đầy đủ số tiền thuế phải nộp của công ty nên anh K đã bị cơ quan chức năng xử phạt. Nghi ngờ anh V là tố cáo hành vi của mình, anh K cố tình trì hoãn đóng bảo hiểm xã hội cho anh V như đã cam kết. Bức xúc, anh V tự ý nghỉ việc ở công ty của anh K và sang làm việc cho anh D. Một lần chứng kiến anh D bị cơ quan chức năng xử phạt về hành vi cung cấp sản phẩm không đảm bảo đúng tiêu chuẩn đã công bố, anh V đã kể lại sự việc cho vợ mình là chị T. Vô tình phát hiện việc anh D bị xử phạt, chị P đã viết và đăng bài xuyên tạc về doanh nghiệp của anh D lên mạng xã hội khiến lượng khách hàng của anh D giảm sút", "o": ["Anh D và anh K đều được thực hiện quyền của công dân về kinh doanh.", "Anh K thực hiện tốt nghĩa vụ kinh doanh nhưng vi phạm nghĩa vụ nộp thuế đối.", "Anh K vừa vi phạm trách nhiệm kinh tế vừa vi phạm trách nhiệm pháp lý của doanh nghiệp khi tiến hành kinh doanh.", "Anh K và anh D đều chưa thực hiện tốt nghĩa vụ kinh doanh."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần II câu 4 · khoá: file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}]}, {"id": "TN-D16", "loai": "tn", "khoi": 12, "hoc_ki": 2, "so_de": 16, "ten": "Đề luyện thi tốt nghiệp số 16", "pham_vi": "Đề nguồn của giáo viên, giữ NGUYÊN chữ của đề (chỉ bỏ lỗi sao chép) · «10 ĐỀ» Đề 6 · file nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm 4 lựa chọn + 4 câu đúng/sai (mỗi câu 4 ý)", "cham": {"tong": 10, "tn": 0.25, "ds": [0, 0.1, 0.25, 0.5, 1.0]}, "status": "cho_duyet", "khoa": {"đã giải lại, khớp khoá": 28}, "sua": "", "cau": [{"id": "TN-D16-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chủ thể nào sau đây có vai trò điều tiết và tạo điều kiện thuận lợi cho các ngành kinh tế hoạt động sản xuất kinh doanh?", "o": ["Chủ thể nhà nước.", "Chủ thể tiêu dùng.", "Chủ thể sản xuất.", "Chủ thể trung gian."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D16-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Sử dụng pháp luật là việc các cá nhân, tổ chức sử dụng đúng các quyền của mình, làm những gì mà pháp luật", "o": ["đã bãi bỏ.", "chưa cho phép.", "cho phép làm.", "tuyệt đối cấm."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D16-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc một số lao động mất việc khi nền kinh tế rơi vào thời kì khủng hoảng, trì trệ được gọi là", "o": ["thất nghiệp tạm thời", "thất nghiệp chu kì", "thất nghiệp cơ cấu.", "thất nghiệp tự nguyện."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D16-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Biết đánh giá cơ hội kinh doanh, lựa chọn và chớp cơ hội kinh doanh là biểu hiện cho năng lực nào của người kinh doanh?", "o": ["Năng lực thực hiện trách nhiệm với xã hội.", "Năng lực chuyên môn.", "Năng lực định hướng chiến lược.", "Năng lực nắm bắt cơ hội."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D16-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bất kỳ công dân nào nếu có đủ các điều kiện theo quy định của pháp luật đều bình đẳng về cơ hội học tập là thể hiện công dân bình đẳng về", "o": ["tập tục.", "quyền.", "trách nhiệm.", "nghĩa vụ."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 5 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D16-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong hội nghị tổng kết cuối năm, một số người dân xã S đã yêu cầu kế toán xã giải trình về khoản thu, chi quỹ \"Đền ơn đáp nghĩa\". Người dân xã S đã thực hiện đúng quyền dân chủ nào dưới đây?", "o": ["Tham gia quản lí nhà nước và xã hội.", "Tự do ngôn luận.", "Chủ động kiểm toán ngân sách quốc gia.", "Độc lập phán quyết."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 6 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D16-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Cụm từ GNI là một trong những chỉ tiêu thể hiện tốc độ tăng trưởng kinh tế, điều này thể hiện nội dung nào dưới đây?", "o": ["Tổng thu nhập quốc dân.", "Tổng thu nhập quốc dân theo đầu người.", "Tổng sản phẩm quốc nội theo đầu người.", "Tổng sản phẩm quốc nội."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D16-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Loại hình bảo hiểm do Nhà nước tổ chức nhằm bảo đảm thay thế hoặc bù đắp một phần thu nhập của người lao động khi họ bị giảm hoặc mất thu nhập do ốm, đau, thai sản, tai nạn lao động, bệnh nghề nghiệp, hết tuổi lao động dựa trên cơ sở mức đóng vào quỹ bảo hiểm xã hội của người lao động trước đó là loại hình bảo hiểm nào dưới đây?", "o": ["Bảo hiểm xã hội.", "Bảo hiểm dân sự.", "Bảo hiểm con người.", "Bảo hiểm thương mại."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D16-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quyền sở hữu tài sản không bao gồm quyền nào sau đây", "o": ["Quyền tước đoạt.", "Quyền sử dụng.", "Quyền chiếm hữu.", "Quyền định đoạt."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D16-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Loại hình doanh nghiệp có từ 2 đến 50 thành viên là loại hình doanh nghiệp nào dưới đây?", "o": ["Công ty cổ phần.", "Doanh nghiệp tư nhân.", "Công ty trách nhiệm hữu hạn một thành viên.", "Công ty trách nhiệm hữu hạn hai thành viên trở lên"], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D16-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong hệ thống pháp luật của nước Việt Nam hiện nay, Hiến pháp năm 2013 giữ vị trí, vai trò như thế nào?", "o": ["Luật cơ bản của Nhà nước.", "Pháp luật cơ bản của Nhà nước.", "Luật thiết yếu của Nhà nước.", "Luật thứ cấp của Nhà nước."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D16-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật hiện hành, người có hành vi xâm phạm tài sản của người khác sẽ chịu trách nhiệm pháp lý nào?", "o": ["Phạt tiền từ 1.000.000₫ đến 3.000.000₫.", "Phạt tù từ 06 tháng đến 03 năm.", "Cải tạo không giam giữ từ 12 tháng đến 18 tháng.", "Phạt tù từ 03 năm đến 07 năm."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 12 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D16-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Pháp luật quy định không ai bị bắt, nếu không có quyết định của Toà án, quyết định phê chuẩn của Viện kiểm sát, trừ trường hợp", "o": ["đã có chứng cứ rõ ràng, đầy đủ.", "gây khó khăn cho việc điều tra.", "phạm tội quả tang hoặc đang bị truy nã.", "cần ngăn chặn ngay người phạm tội bỏ trốn."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 13 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D16-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi tham gia vào thị trường lao động, người bán sức lao động và người mua sức lao động thỏa thuận nội dung nào dưới đây?", "o": ["Tiền công, tiền lương.", "Điều kiện đi nước ngoài.", "Điều kiện xuất khẩu lao động.", "Tiền môi giới lao động."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D16-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Sự khác nhau giữa việc cạnh tranh lành mạnh và cạnh tranh không lành mạnh là gì?", "o": ["Chúng đều là cạnh tranh không có sự khác nhau nào hết.", "Cạnh tranh lành mạnh tạo được ra giá trị tích cực thúc đẩy nhu cầu của xã hội, cạnh tranh không lành mạnh có thể có các ảnh hưởng tiêu cực đến đời sống xã hội.", "Việc cạnh tranh lành mạnh được khuyến khích để tạo ra môi trường cạnh tranh trong nền kinh tế thị trường.", "Cạnh tranh không lành mạnh nên bị lên án, phê phán."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D16-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin\nvà trả lời các câu hỏi bên dưới 16, 17\nBà H là lao động tự do sống trên địa bàn tỉnh Y. Sau một thời gian khám bệnh và điều trị tại bệnh viện K, bà H cầm trên tay hóa đơn, chứng từ thanh toán bảo hiểm y tế với số tiền 80 triệu đồng. Kết quả sau khi điều trị, bà đã được thanh toán gần một nửa chi phí điều trị gần 50 triệu đồng, thuộc đối tượng đồng chi trả 20%. Bà xúc động nói thêm: “Nhờ có sự tư vấn của cán bộ bảo hiểm xã hội, cách đây 5 tháng tôi có mua một tấm thẻ bảo hiểm y tế nay nhờ có tấm thẻ BHYT này mà tôi không trở thành gánh nặng tài chính của các con khi ốm đau, đến bây giờ bản thân tôi mới thấm thía cái câu khẩu hiệu: “BHYT đóng góp khi lành để dành khi ốm. Có thẻ BHYT, mình được lợi rất nhiều về viện phí, chất lượng khám chữa bệnh cũng tương đương với dịch vụ, tôi mong rằng mọi người nên tham gia BHYT để được bảo vệ và chăm sóc sức khỏe, bản thân, gia đình một cách tốt nhất”.\nLoại hình bảo hiểm mà bà H tham gia có đặc điểm là", "o": ["bắt buộc.", "được tài trợ.", "được vĩnh viễn.", "tự nguyện."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D16-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nhờ có tham gia loại hình bảo hiểm đã mang lại lợi ích gì dưới đây cho bà H khi gặp rủi ro về ốm đau?", "o": ["Khám chữa bệnh chất lượng cao.", "Giảm gánh nặng tài chính gia đình.", "Được hỗ trợ tiền sau khi ra viện.", "Được khám miễn phí suốt đời."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D16-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi thực hiện việc quản lý thu chi trong gia đình sẽ giúp mỗi gia đình có thể chủ động", "o": ["tự do chi tiêu theo sở thích.", "ứng phó các tình huống rủi ro.", "chi tiêu ngoài kế hoạch đã định.", "tạo ra các quỹ ngoài kế hoạch."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D16-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi thống nhất tỷ lệ phân chia các khoản chi tiêu, các gia đình không cần phân chi tỷ lệ cho nội dung nào dưới đây?", "o": ["Chi thiết yếu.", "Chi nộp thuế nhà đất.", "Chi không thiết yếu.", "Chi tiết kiệm."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D16-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào dưới đây thực hiện đúng quy định của pháp luật về bảo vệ tài nguyên thiên nhiên?", "o": ["Sử dụng tiết kiệm điện, nước, khoáng sản,…", "Săn bắn, buôn bán động vật quý hiếm.", "Dùng mìn, kích điện để đánh bắt cá.", "Phá rừng nguyên sinh để trồng cà phê."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 20 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D16-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi vi phạm quy định của pháp luật về quyền và nghĩa vụ của công dân trong bảo vệ di sản văn hóa, môi trường và tài nguyên thiên nhiên phải chịu", "o": ["trách nhiệm dân sự, trách nhiệm hành chính, trách nhiệm kỉ luật", "trách nhiệm hành chính, trách nhiệm kỉ luật", "trách nhiệm dân sự, trách nhiệm hành chính.", "trách nhiệm dân sự, trách nhiệm hành chính, trách nhiệm kỉ luật, trách nhiệm hình sự."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D16-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22, 23, 24\nHội nhập kinh tế quốc tế đã tạo điều kiện cho Việt Nam đa dạng hóa các mặt hàng xuất khẩu. Trong đó, cà phê là một trong những sản phẩm thế mạnh của Việt Nam. Chỉ tính riêng trong nửa đầu năm 2024, Việt Nam đã xuất khẩu ước tính 1,1 triệu tấn cà phê với giá trị đạt 2,5 tỷ đô la Mỹ, tăng 35% về lượng và 45% về giá trị so với cùng kỳ năm trước. Tuy nhiên, một lô hàng của công ty cổ phần X bị phát hiện chứa chất bảo quản vượt mức cho phép. Phía đối tác yêu cầu công ty X bồi thường toàn bộ giá trị lô hàng nhưng công ty này không chấp nhận vì trong hợp đồng không quy định điều khoản này.\nTrong thông tin trên, hội nhập kinh tế quốc tế đem lại lợi ích nào sau đây cho các doanh nghiệp trong hoạt động xuất khẩu cà phê tại Việt Nam?", "o": ["Tăng giá trị xuất khẩu và nâng cao thương hiệu quốc gia.", "Đạt giá trị xuất khẩu 2,5 tỷ đô la Mỹ trong năm 2024.", "Tiếp cận thị trường và tăng giá trị xuất khẩu là 35%.", "Tạo cơ hội để các doanh nghiệp Việt Nam tham gia vào chuỗi cung ứng toàn cầu."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D16-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22, 23, 24\nHội nhập kinh tế quốc tế đã tạo điều kiện cho Việt Nam đa dạng hóa các mặt hàng xuất khẩu. Trong đó, cà phê là một trong những sản phẩm thế mạnh của Việt Nam. Chỉ tính riêng trong nửa đầu năm 2024, Việt Nam đã xuất khẩu ước tính 1,1 triệu tấn cà phê với giá trị đạt 2,5 tỷ đô la Mỹ, tăng 35% về lượng và 45% về giá trị so với cùng kỳ năm trước. Tuy nhiên, một lô hàng của công ty cổ phần X bị phát hiện chứa chất bảo quản vượt mức cho phép. Phía đối tác yêu cầu công ty X bồi thường toàn bộ giá trị lô hàng nhưng công ty này không chấp nhận vì trong hợp đồng không quy định điều khoản này.\nTheo quy định của pháp luật Việt Nam, hành vi vi phạm của công ty cổ phần X phải chịu trách nhiệm pháp lý nào sau đây?", "o": ["Buộc thu hồi sản phẩm và thay đổi quy trình sản xuất.", "Đền bù cho đối tác toàn bộ giá trị của lô hàng bị trả lại.", "Xử phạt hành chính và áp dụng hình phạt bổ sung theo quy định.", "Tước quyền xuất khẩu mặt hàng cà phê trong thời gian quy định."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D16-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22, 23, 24\nHội nhập kinh tế quốc tế đã tạo điều kiện cho Việt Nam đa dạng hóa các mặt hàng xuất khẩu. Trong đó, cà phê là một trong những sản phẩm thế mạnh của Việt Nam. Chỉ tính riêng trong nửa đầu năm 2024, Việt Nam đã xuất khẩu ước tính 1,1 triệu tấn cà phê với giá trị đạt 2,5 tỷ đô la Mỹ, tăng 35% về lượng và 45% về giá trị so với cùng kỳ năm trước. Tuy nhiên, một lô hàng của công ty cổ phần X bị phát hiện chứa chất bảo quản vượt mức cho phép. Phía đối tác yêu cầu công ty X bồi thường toàn bộ giá trị lô hàng nhưng công ty này không chấp nhận vì trong hợp đồng không quy định điều khoản này.\nTrong trường hợp trên, công ty cổ phần X nên lựa chọn phương thức giải quyết đầu tiên nào sau đây phù hợp với nguyên tắc hợp tác quốc tế với phía đối tác?", "o": ["Thương lượng với các bên liên quan để đạt thỏa thuận.", "Đàm phán trực tiếp với đại diện của tổ chức quốc tế.", "Đưa tranh chấp ra Tòa án quốc tế để giải quyết.", "Đơn phương đình chỉ hợp đồng thương mại để giảm thiệt hại."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D16-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Vào tháng 11/2023, Việt Nam công bố kế hoạch tham gia Tổ chức Hợp tác và Phát triển Kinh tế (OECD). Mục tiêu là cải thiện chính sách kinh tế, thương mại, và phát triển bền vững nhằm đáp ứng các tiêu chuẩn quốc tế. Kế hoạch bao gồm tăng cường phát triển năng lượng tái tạo và giảm phụ thuộc vào nhiên liệu hóa thạch. Một doanh nghiệp tại Việt Nam đã nhanh chóng đầu tư vào lĩnh vực năng lượng mặt trời và gió để đáp ứng các tiêu chí môi trường của OECD.", "o": ["Kế hoạch tham gia OECD của Việt Nam là biểu hiện của hội nhập đa phương.", "Việc đầu tư vào năng lượng tái tạo giúp doanh nghiệp đáp ứng các tiêu chuẩn phát triển bền vững mà OECD đề ra.", "Đầu tư vào năng lượng tái tạo là một trong những cách thực hiện chiến lược phát triển doanh nghiệp trong dài hạn.", "Kể từ năm 2025, mọi doanh nghiệp tại Việt Nam phải tuân thủ toàn bộ tiêu chí của OECD về phát triển bền vững."], "a": [true, true, true, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần II câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D16-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Chị H mở một cửa hàng kinh doanh nhỏ tại địa phương, chủ yếu bán sản phẩm thủ công từ nguyên liệu tái chế. Hằng tháng, chị nộp thuế thu nhập cá nhân và thuế giá trị gia tăng đúng hạn. Doanh thu bình quân của cửa hàng là 150 triệu đồng/tháng. Trong khi đó, anh K, một người bạn của chị, chủ yếu bán sản phẩm qua mạng xã hội và không kê khai thuế vì cho rằng kinh doanh trực tuyến nhỏ lẻ không cần đóng thuế.", "o": ["Chị H thực hiện đầy đủ nghĩa vụ thuế, thể hiện trách nhiệm công dân.", "Với doanh thu 150 triệu đồng/tháng, chị H chỉ cần nộp thuế giá trị gia tăng mà không cần nộp thuế thu nhập cá nhân.", "Anh K không kê khai thuế là vi phạm quy định pháp luật về thuế đối với kinh doanh trực tuyến.", "Kinh doanh trực tuyến nhỏ lẻ dưới 100 triệu đồng/năm được miễn thuế, theo quy định pháp luật hiện hành."], "a": [true, false, true, true], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần II câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D16-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Công ty Y do bà A làm giám đốc chuyên sản xuất đồ nội thất từ gỗ tái chế. Năm 2023, công ty áp dụng mô hình kinh tế tuần hoàn, sử dụng chất thải từ sản xuất để tái chế thành nguyên liệu đầu vào, góp phần giảm lượng rác thải ra môi trường. Đồng thời, công ty xây dựng hệ thống xử lý nước thải đạt tiêu chuẩn quốc gia và hỗ trợ đào tạo nghề cho lao động địa phương. Nhờ các biện pháp này, công ty Y đã mở rộng thị trường ra nước ngoài, nâng cao lợi nhuận và tạo nhiều việc làm cho người lao động.", "o": ["Việc công ty Y áp dụng mô hình kinh tế tuần hoàn là thực hiện trách nhiệm xã hội về môi trường.", "Hỗ trợ đào tạo nghề cho lao động địa phương là trách nhiệm pháp lý của công ty Y.", "Thực hiện tốt nghĩa vụ bảo vệ môi trường gắn liền với trách nhiệm nhân văn của doanh nghiệp Y.", "Công ty Y mở rộng thị trường ra nước ngoài để tăng lợi nhuận là không liên quan đến trách nhiệm xã hội."], "a": [true, false, false, false], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Sai.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần II câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D16-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau Năm 2001, Việt Nam gia nhập Công ước Viên năm 1969 về Luật điều ước. Điều 26 Công ước Viên về Luật điều ước quốc tế năm 1969 quy định nguyên tắc Pacta sunt servanda quy định “mọi điều ước đã có hiệu lực đều ràng buộc các bên tham gia điều ước và phải được các bên thi hành với thiện ý”. Nguyên tắc này đã được chuyển hóa vào quy định của luật kí kết, gia nhập và thực hiện điều ước quốc tế năm 2025: “Nhà nước Cộng hòa xã hội chủ nghĩa Việt Nam tuân thủ điều ước quốc tế mà Cộng hòa xã hội chủ nghĩa Việt Nam là thành viên”. (khoản 6 Điều 3)", "o": ["Việt Nam gia nhập Công ước viên năm 1969 về Luật điều ước là một trong những minh chứng thể hiện lập trường của Việt Nam đối với việc nghiêm chỉnh tuân thủ điều ước quốc tế.", "Việt Nam gia nhập Công ước viên năm 1969 về Luật điều ước sẽ tạo ra mối quan hệ biện chứng giữa pháp luật Việt Nam với pháp luật quốc tế.", "Luật này áp dụng đối với tổ chức, cá nhân Việt Nam, cá nhân, tổ chức nước ngoài và người Việt Nam định cư ở nước ngoài đang hoạt động tại Việt Nam.", "Điều ước quốc tế mà Việt Nam đã kí kết hoặc gia nhập có giá trị pháp lí ưu tiên hơn so với pháp luật trong nước."], "a": [true, true, true, true], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần II câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}]}, {"id": "TN-D17", "loai": "tn", "khoi": 12, "hoc_ki": 2, "so_de": 17, "ten": "Đề luyện thi tốt nghiệp số 17", "pham_vi": "Đề nguồn của giáo viên, giữ NGUYÊN chữ của đề (chỉ bỏ lỗi sao chép) · «10 ĐỀ» Đề 7 · file nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm 4 lựa chọn + 4 câu đúng/sai (mỗi câu 4 ý)", "cham": {"tong": 10, "tn": 0.25, "ds": [0, 0.1, 0.25, 0.5, 1.0]}, "status": "cho_duyet", "khoa": {"đã giải lại, khớp khoá": 28}, "sua": "", "cau": [{"id": "TN-D17-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chủ thể nào dưới đây đóng vai trò quản lý toàn bộ nền kinh tế quốc dân?", "o": ["Chủ thể trung gian.", "Chủ thể nhà nước.", "Chủ thể tiêu dùng.", "Chủ thể sản xuất."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D17-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, công dân thực hiện hành vi nào dưới đây là sử dụng pháp luật?", "o": ["Đăng ký nghĩa vụ quân sự khi đến tuổi.", "Không sử dụng điện thoại khi điều khiển xe máy.", "Lựa chọn nghề nghiệp, công việc và nơi làm việc.", "Thực hiện thủ tục cấp căn cước công dân."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D17-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây thể hiện vai trò của sản xuất kinh doanh?", "o": ["Giải quyết việc làm.", "Giải quyết thủ tục đăng kí kinh doanh.", "Tạo ra lực lượng lao động.", "Thúc đẩy giá cả thị trường."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D17-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào dưới đây nói về đặc điểm và vị trí của Hiến pháp nước Cộng hoà xã hội chủ nghĩa Việt Nam?", "o": ["Hiến pháp là luật cơ bản của Nhà nước.", "Hiến pháp là văn bản pháp luật mang tính biểu tượng.", "Hiến pháp là công cụ duy nhất để thực hiện pháp luật.", "Hiến pháp là văn bản quy định chi tiết, cụ thể về quyền học tập."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D17-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Cạnh tranh lành mạnh thúc đẩy những người sản xuất", "o": ["đưa ra các biện pháp hợp lý hóa sản xuất, nâng cao hiệu quả.", "sử dụng thủ đoạn phi pháp, triệt tiêu đối thủ.", "tung tin bịa đặt giảm uy tín, chất lượng hàng hóa đối thủ.", "không ngừng hủy hoại tài nguyên môi trường."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 5 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D17-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mức độ tăng của giá cả ở một con số hằng năm dưới 10% thuộc loại hình lạm phát nào dưới đây?", "o": ["Lạm phát vừa phải.", "Lạm phát phi mã.", "Siêu lạm phát.", "Lạm phát tượng trưng."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 6 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D17-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi cung lao động cao hơn số lượng việc làm thì sẽ dẫn đến tình trạng nào dưới đây?", "o": ["Thiếu việc làm cho người cần tìm việc.", "Thiếu sản phẩm vật chất cho xã hội.", "Thiếu nguồn lực lao động.", "Không mất cân đối trong sản xuất."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D17-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây phản ánh tầm quan trọng của việc xây dựng ý tưởng kinh doanh?", "o": ["Nâng tầm thương hiệu quốc gia.", "Lành mạnh hóa và thúc đẩy thị trường.", "Giảm thiểu nguy cơ lạm phát.", "Đem lại lợi nhuận cho chủ thể kinh doanh."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D17-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Thành phố A tiến hành cải tạo, sửa chữa vỉa hè cho người đi bộ, nhưng thiết kế lại không chú ý xây dựng thêm đường trượt dành cho người khuyết tật đi xe lăn. Việc làm của thành phố A chưa", "o": ["thực hiện quyền bình đẳng của công dân về hưởng quyền.", "thể hiện sự bình đẳng của công dân về nghĩa vụ.", "thể hiện hoạt động từ thiện dành cho người khuyết tật, khiếm thị.", "thể hiện sự ưu tiên về hưởng quyền của công dân."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D17-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, Uỷ ban nhân dân cấp xã phải công khai báo cáo tình hình thực hiện ngân sách một cách minh bạch, rõ ràng cho nhân dân được biết, theo dõi và giám sát. Tuy nhiên, ông T là Chủ tịch Uỷ ban nhân dân xã X lại không thực hiện việc công khai báo cáo tình hình thực hiện ngân sách xã. Hành vi của ông T đã vi phạm quyền và nghĩa vụ của công dân trong tham gia quản lý nhà nước và xã hội dẫn đến nhiều hậu quả tiêu cực như", "o": ["làm giảm lòng tin của công dân vào sự quản lý của Nhà nước.", "gây tổn thất về tinh thần, danh dự, uy tín của công dân.", "vi phạm quyền tự do của công dân.", "ông T sẽ bị xử lý hành chính và truy cứu trách nhiệm hình sự."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D17-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây thể hiện quyền tham gia quản lý nhà nước và xã hội của công dân ở phạm vi cả nước?", "o": ["Công dân tham gia ý kiến trước khi cơ quan có thẩm quyền quyết định.", "Công dân tham gia đóng góp ý kiến, xây dựng các văn bản quy phạm pháp luật.", "Công dân bàn bạc và quyết định mức đóng góp xây dựng đường của thôn.", "Công dân tham gia giám sát hoạt động của chính quyền theo quy định của pháp luật."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D17-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tổ bầu cử số 4 (xã Y) mở hòm phiếu để kiểm tra phiếu bầu. Kết quả kiểm phiếu cho thấy số phiếu bầu đại biểu Hội đồng nhân dân xã thu về nhiều hơn số phiếu phát ra. Qua xác minh, Ủy ban bầu cử xã phát hiện ông G (ứng cử viên đại biểu Hội đồng nhân dân) đã đề nghị ông T (Tổ trưởng Tổ bầu cử số 4) lấy một số phiếu bầu mang về nhà rồi gạch tên những ứng cử viên khác, để lại tên mình và bỏ vào thùng phiếu. Trong trường hợp này hành vi của của ông G và ông T đã gây ra hậu quả như thế nào?", "o": ["Làm sai lệch kết quả bầu cử và lãng phí ngân sách nhà nước.", "Là nhân tố duy nhất gây nên tình trạng bất ổn trong xã hội.", "Ảnh hưởng đến sức khỏe, tính mạng, danh dự của người dân.", "Cản trở công dân thực hiện bầu cử, làm giảm tỷ lệ tham gia bầu cử."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 12 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D17-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nhận định nào dưới đây đúng về tăng trưởng kinh tế?", "o": ["Phát triển kinh tế là một chỉ tiêu của tăng trưởng kinh tế.", "Tăng trưởng kinh tế có phạm vi toàn diện hơn phát triển kinh tế.", "Tăng trưởng kinh tế bao hàm phát triển kinh tế.", "Tăng trưởng kinh tế phản ánh sự thay đổi về mặt lượng của nền kinh tế."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 13 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D17-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi nộp thuế, công dân cần thực hiện việc nào sau đây?", "o": ["Kê khai thuế chính xác.", "Được cung cấp thông tin để nộp thuế.", "Trì hoãn nộp hồ sơ khai thuế.", "Trì hoãn việc nộp thuế."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D17-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Thềm lục địa của một quốc gia ven biển bao gồm đáy biển và lòng đất dưới đáy biển bên ngoài lãnh hải của quốc gia đó đến một giới hạn theo quy định. Nội dung này được quy định tại văn bản quốc tế nào dưới đây?", "o": ["Công ước về đa dạng sinh học biển (CBD).", "Hiệp ước Nam Cực (Antarctic Treaty).", "Hiến pháp hòa bình về biển (UN Charter).", "Công ước của Liên hợp quốc về Luật biển năm 1982 (UNCLOS)."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D17-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào dưới đây không đúng về vai trò của bảo hiểm?", "o": ["Bảo hiểm giúp người tham gia được nhận bồi thường, trợ cấp góp phần ổn định đời sống.", "Bảo hiểm thất nghiệp chỉ có ý nghĩa đối với người bị mất việc làm thời kì dịch bệnh.", "Bảo hiểm thương mại góp phần ổn định tài chính, giảm bớt nỗi lo cho người tham gia.", "Bảo hiểm đóng góp vào ngân sách giúp Nhà nước ổn định xã hội, thúc đẩy kinh tế phát triển."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D17-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không phải chính sách an sinh xã hội?", "o": ["Chính sách xuất nhập khẩu.", "Chính sách bảo hiểm xã hội.", "Chính sách trợ giúp xã hội.", "Chính sách giải quyết việc làm."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D17-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào đưới đây thể hiện việc không tôn trọng tài sản của người khác?", "o": ["Trả lại của rơi cho người đánh mất.", "Sử dụng tài sản mượn mà không trả.", "Bảo vệ tài sản của người khác khỏi bị huỷ hoại.", "Thông báo cho cơ quan có trách nhiệm khi nhặt được của rơi."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D17-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong hơn 1 tháng giá xăng dầu tăng 2 lần mỗi lần tăng trên 10%. Các hãng taxi vẫn chưa quyết định tăng giá chủ yếu vì đang “nhìn nhau”, cắn răng chịu lỗ để giữ thị phần, giá cước tăng quá cao so với hãng khác thì sợ mất khách. Ông T, Phó giám đốc Sở Công thương cho biết: \"Trong đợt tăng giá xăng dầu trước, giá cả trên địa bàn A tăng bình quân 10% - 15%. Dự báo đợt này cũng tăng bình quân ở mức đó, thậm chí có những mặt hàng tăng 20% - 25%, nhưng chủ yếu là những mặt hàng có giá trị thấp”. Chị L đi chợ cho biết, khi hay tin giá xăng tăng chị đã điều chỉnh thực đơn bữa ăn, tính toán lại cho kỹ từng bó rau, miếng thịt để không bị hụt tiền ăn trong ngày vì khi đó giá các mặt hàng thiết yếu cũng sẽ tăng. Nội dung nào dưới đây là biểu hiện của việc thực hiện quản lý thu, chi trong gia đình?", "o": ["Chị L điều chỉnh thực đơn bữa ăn.", "Điều chỉnh giá cả các mặt hàng thiết yếu.", "Giá xăng dầu tăng trên 10%.", "Hãng taxi vẫn chưa quyết định tăng giá."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D17-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào sau đây phù hợp với quy định pháp luật về quyền và nghĩa vụ của công dân trong bảo vệ môi trường và tài nguyên thiên nhiên?", "o": ["Anh A không dùng thiết bị che chắn khi xây dựng công trình nhà ở.", "Bạn M tìm hiểu thông tin về các hiện vật trong bảo tàng.", "Ông T tập kết rác thải sinh hoạt đến nơi quy định.", "Anh P có hành vi phá hoại hiện vật khi tham quan khu di tích."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 20 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D17-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 21, 22\nTrải qua hơn 35 năm đổi mới, Việt Nam đã có quá trình hội nhập kinh tế quốc tế mạnh mẽ và có tác động sâu sắc đến quá trình xây dựng nền kinh tế độc lập tự chủ của đất nước. Quá trình hội nhập quốc tế ấn tượng thông qua việc ký kết các hiệp định thương mại tự do (FTA). Trong số đó, có một số FTA đáng chú ý như:\n-\tHiệp định Đối tác Toàn diện và Tiến bộ xuyên Thái Bình Dương (CPTPP. CPTPP tạo điều kiện cho Việt Nam tiếp cận các thị trường mới và nâng cao tiêu chuẩn và quy tắc thương mại.\n-\tKhu vực Mậu dịch Tự do ASEAN (AFTA. AFTA thúc đẩy cải thiện tiêu chuẩn và quy tắc thương mại trong khu vực và tạo điều kiện thuận lợi cho thương mại và đầu tư.\n-\tFTA Việt Nam - Hàn Quốc (VKFTA nhằm thúc đẩy quan hệ thương mại và đã tạo điều kiện thuận lợi cho việc tiếp cận thị trường, mở ra cơ hội kinh doanh giữa 2 nước.\nTrích Tạp chí tài chính online “Ảnh hưởng của hội nhập kinh tế quốc tế đối với xây dựng nền kinh tế độc lập, tự chủ ở Việt Nam” ngày 17/03/2024\nViệt Nam hội nhập kinh tế quốc tế dựa trên cơ sở cùng có lợi và tuân thủ", "o": ["việc ký kết các hiệp định.", "việc tiếp cận các thị trường mới.", "chuẩn mực quốc tế chung.", "chuẩn mực quốc gia riêng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D17-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 21, 22\nTrải qua hơn 35 năm đổi mới, Việt Nam đã có quá trình hội nhập kinh tế quốc tế mạnh mẽ và có tác động sâu sắc đến quá trình xây dựng nền kinh tế độc lập tự chủ của đất nước. Quá trình hội nhập quốc tế ấn tượng thông qua việc ký kết các hiệp định thương mại tự do (FTA). Trong số đó, có một số FTA đáng chú ý như:\n-\tHiệp định Đối tác Toàn diện và Tiến bộ xuyên Thái Bình Dương (CPTPP. CPTPP tạo điều kiện cho Việt Nam tiếp cận các thị trường mới và nâng cao tiêu chuẩn và quy tắc thương mại.\n-\tKhu vực Mậu dịch Tự do ASEAN (AFTA. AFTA thúc đẩy cải thiện tiêu chuẩn và quy tắc thương mại trong khu vực và tạo điều kiện thuận lợi cho thương mại và đầu tư.\n-\tFTA Việt Nam - Hàn Quốc (VKFTA nhằm thúc đẩy quan hệ thương mại và đã tạo điều kiện thuận lợi cho việc tiếp cận thị trường, mở ra cơ hội kinh doanh giữa 2 nước.\nTrích Tạp chí tài chính online “Ảnh hưởng của hội nhập kinh tế quốc tế đối với xây dựng nền kinh tế độc lập, tự chủ ở Việt Nam” ngày 17/03/2024\nTrong các hiệp định thương mại tự do (FTA) được nhắc đến trong thông tin trên, đâu là hình thức hội nhập kinh tế song phương của Việt Nam?", "o": ["FTA giữa các quốc gia thành viên của ASEAN.", "Hiệp định Đối tác Toàn diện và Tiến bộ xuyên Thái Bình Dương.", "FTA Việt Nam – WTO.", "FTA Việt Nam - Hàn Quốc (VKFTA)."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D17-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 23, 24\nVới ước mơ xây dựng thành công chuỗi cửa hàng phân phối thực phẩm sạch trên địa bàn huyện X, sau khi tham khảo một số mô hình cũng như kiến thức cơ bản về lĩnh vực kinh doanh này, anh H đã lên kế hoạch chi tiết để thực hiện ý tưởng kinh doanh của mình. Qua tư vấn của bạn bè, anh H đã dự liệu được những rủi ro, khó khăn tiềm ẩn để có giải pháp khắc phục. Anh cũng đã lên kế hoạch chi tiết việc bán hàng, tiếp thị, quảng cáo để quảng bá giới thiệu sản phẩm đến khách hàng. Nhờ có kế hoạch kinh doanh tốt anh H xây dựng thành công thương hiệu của mình trên địa bàn huyện X, anh cũng mở rộng các cửa hàng để hình thành\nchuỗi cửa hàng chất lượng cao.\nAnh H đã xác định ý tưởng kinh doanh của mình dựa vào yếu tố nào dưới đây?", "o": ["Ước mơ xây dựng thành công chuỗi cửa hàng phân phối thực phẩm sạch.", "Dự liệu được những rủi ro tiềm ẩn để có giải pháp khắc phục.", "Xây dựng thành công thương hiệu trên địa bàn huyện X.", "Lên kế hoạch chi tiết việc bán hàng, tiếp thị, quảng cáo giới thiệu sản phẩm."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D17-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 23, 24\nVới ước mơ xây dựng thành công chuỗi cửa hàng phân phối thực phẩm sạch trên địa bàn huyện X, sau khi tham khảo một số mô hình cũng như kiến thức cơ bản về lĩnh vực kinh doanh này, anh H đã lên kế hoạch chi tiết để thực hiện ý tưởng kinh doanh của mình. Qua tư vấn của bạn bè, anh H đã dự liệu được những rủi ro, khó khăn tiềm ẩn để có giải pháp khắc phục. Anh cũng đã lên kế hoạch chi tiết việc bán hàng, tiếp thị, quảng cáo để quảng bá giới thiệu sản phẩm đến khách hàng. Nhờ có kế hoạch kinh doanh tốt anh H xây dựng thành công thương hiệu của mình trên địa bàn huyện X, anh cũng mở rộng các cửa hàng để hình thành\nchuỗi cửa hàng chất lượng cao.\nNội dung nào cho thấy anh H lập kế hoạch kinh doanh là điều cần thiết?", "o": ["Anh H nhận được nhiều sự quan tâm, tư vấn của bạn bè trong ngành.", "Anh H tham khảo một số mô hình cũng như kiến thức cơ bản về lĩnh vực kinh doanh.", "Anh H xây dựng thành công thương hiệu của mình, mở rộng quy mô sản xuất kinh doanh.", "Anh H đăng kí kinh doanh với cơ quan nhà nước có thẩm quyền."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D17-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Sau khi tốt nghiệp đại học ngành công nghệ sinh học, với lợi thế là nhà gần các trường đại học, lại có diện tích đất lớn, chị D quyết định lập nghiệp bằng con đường kinh doanh sản phẩm cây cảnh mi ni với mong muốn sau hai năm sẽ thành lập một doanh nghiệp phân phối các sản phẩm này. Đây là lĩnh vực kinh doanh không đòi hỏi vốn lớn, không cần nhiều lao động trong khi thị trường là các bạn sinh viên có nhu cầu khá cao về loại sản phẩm này. Sau khi nghiên cứu thị trường, phân tích nhu cầu khách hàng, chị lên ý tưởng kinh doanh và tiến hành các bước lập kế hoạch kinh doanh của mình. Nhận thấy ý tưởng kinh doanh khả thi chị quyết định thực hiện việc kinh doanh. Do chưa xây dựng phương án phòng ngừa, ứng phó với các rủi ro tiềm ẩn, thời gian đầu chưa có nhiều kinh nghiệm, nên sản phẩm chị cung cấp nhiều cây gặp sâu bệnh chết, vốn bỏ ra tuy được bảo toàn nhưng lợi nhuận không cao.", "o": ["Chị D nghiên cứu thị trường, phân tích nhu cầu khách hàng là thực hiện bước “Lập mục tiêu và chiến lược kinh doanh” trong việc lập kế hoạch kinh doanh.", "Chị D không cần xây dựng phương án phòng ngừa, ứng phó với các rủi ro tiềm ẩn khi lập kế hoạch kinh doanh vì thiệt hại là điều không thể tránh trong kinh doanh.", "Chị D xác định ý tưởng kinh doanh cây cảnh mi ni của mình dựa vào lợi thế nội tại của bản thân.", "Chị D nên tuân thủ các bước lập kế hoạch kinh doanh để đảm bảo việc kinh doanh của mình hiệu quả."], "a": [false, false, true, true], "e": "Đáp án: a) Sai; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần II câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D17-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Doanh nghiệp V kinh doanh trong ngành xuất khẩu thuỷ hải sản do ông K làm giám đốc. Doanh nghiệp quan tâm tạo việc làm thường xuyên cho người lao động với mức lương, thưởng tương xứng và xây dựng một môi trường lao động an toàn, thông thoáng bảo đảm sức khoẻ. Vì vậy năng suất lao động của doanh nghiệp khá cao, sản phẩm bảo đảm chất lượng theo cam kết, được khách hàng rất tin tưởng. Trong nhiều năm qua, doanh nghiệp thường xuyên thực hiện hoạt động quyên góp từ thiện giúp đỡ nhân dân các vùng gặp khó khăn, hoạn nạn. Doanh nghiệp đã phát động phong trào “Vì miền Trung thân yêu” và nhận được sự ủng hộ nhiệt tình của đông đảo cán bộ nhân viên đóng góp công sức để chia sẻ phần nào khó khăn với bà con miền Trung vượt qua những cơn lũ lụt. Vì không cạnh tranh được về chất lượng sản phẩm cũng như uy tín của doanh nghiệp V nên ông T giám đốc doanh nghiệp B đã chỉ đạo nhân viên của mình tung tin đồn sai sự thật về đời tư của ông K để hạ uy tín của doanh nghiệp V.", "o": ["Ông T chỉ đạo nhân viên của mình tung tin đồn sai sự thật về đời tư của ông K để hạ uy tín của doanh nghiệp V là hành vi cạnh tranh không lành mạnh, vi phạm trách nhiệm kinh tế của doanh nghiệp.", "Em đồng tình với việc doanh nghiệp V đã phát động phong trào ủng hộ miền Trung thân yêu vì đây là việc làm phù hợp với trách nhiệm pháp lí của doanh nghiệp.", "Ông K thực hiện tốt trách nhiệm công dân khi tham gia điều hành doanh nghiệp.", "Doanh nghiệp V quan tâm đảm bảo cho người lao động việc làm với mức lương, thưởng tương xứng là phù hợp với trách nhiệm kinh tế của doanh nghiệp."], "a": [false, false, true, true], "e": "Đáp án: a) Sai; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần II câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D17-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Điều 69, Luật Hôn nhân và gia đình năm 2014 quy định: \"Không được phân biệt đối xử với con trên cơ sở giới hoặc theo tình trạng hôn nhân của cha mẹ; không được lạm dụng sức lao động của con chưa thành niên, con đã thành niên mất năng lực hành vi dân sự hoặc không có khả năng lao động; không được xúi giục, ép buộc con làm việc trái pháp luật, trái đạo đức xã hội\"", "o": ["Em sẽ tố cáo nếu chứng kiến hành vi lạm dụng sức lao động của con chưa thành niên.", "Cha mẹ lạm dụng sức lao động của con chưa thành niên là không vi phạm pháp luật.", "Cha mẹ của em có quyền yêu cầu con tham gia mọi hoạt động lao động để rèn luyện sức khoẻ và tăng cường tính tự lập.", "Hành vi vi phạm quyền, nghĩa vụ giữa cha mẹ và con có thể khiến con không được chăm sóc, nuôi dưỡng đúng cách, ảnh hưởng đến thể chất, sức khoẻ, tinh thần và sức khoẻ của con."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần II câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D17-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Năm 2018, Maysa (người Lào) đến Việt Nam sinh sống và học tập tại Đại học Khoa học xã hội nhân văn thành phố Hồ Chí Minh. Ngày 25/ 8/2023 Maysa lập gia đình và đã nhập quốc tịch Việt Nam.", "o": ["Từ 25/ 8/2023 Maysa là công dân Việt Nam.", "Maysa có quyền tham gia vào các hoạt động sản xuất kinh doanh theo quy định pháp luật Việt Nam.", "Maysa có thể tham gia các hoạt động như viết bài đăng báo, nghiên cứu khoa học tại Việt Nam.", "Sau thời điểm 25/8/2023 Maysa bị hạn chế về các quyền chính trị ở Việt Nam."], "a": [true, true, true, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần II câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}]}, {"id": "TN-D18", "loai": "tn", "khoi": 12, "hoc_ki": 2, "so_de": 18, "ten": "Đề luyện thi tốt nghiệp số 18", "pham_vi": "Đề nguồn của giáo viên, giữ NGUYÊN chữ của đề (chỉ bỏ lỗi sao chép) · «10 ĐỀ» Đề 8 · file nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm 4 lựa chọn + 4 câu đúng/sai (mỗi câu 4 ý)", "cham": {"tong": 10, "tn": 0.25, "ds": [0, 0.1, 0.25, 0.5, 1.0]}, "status": "cho_duyet", "khoa": {"đã giải lại, khớp khoá": 28}, "sua": "", "cau": [{"id": "TN-D18-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chủ thể kinh tế nào dưới đây thực hiện kết nối các quan hệ mua và bán, sản xuất và tiêu dùng?", "o": ["Chủ thể nhà nước.", "Chủ thể tiêu dùng.", "Chủ thể sản xuất.", "Chủ thể trung gian."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D18-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào dưới đây của công dân thể hiện hình thức tuân thủ pháp luật?", "o": ["Xét xử các hành vi vi phạm pháp luật hình sự.", "Không nộp thuế đầy đủ theo quy định.", "Hỗ trợ việc cấp đổi căn cước công dân.", "Không tàng trữ trái phép chất ma túy."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D18-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Sản xuất kinh doanh không có vai trò nào dưới đây?", "o": ["Cung cấp hàng hóa cho người tiêu dùng.", "Cung cấp sản phẩm đầu vào cho sản xuất.", "Điều tiết các hoạt động xã hội.", "Thúc đẩy phát triển kinh tế."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D18-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong hệ thống pháp luật nước Cộng hòa xã hội chủ nghĩa Việt Nam, văn bản pháp luật nào có giá trị pháp lý cao nhất?", "o": ["Hiến pháp.", "Luật hành chính.", "Luật tổ chức Quốc hội.", "Luật tổ chức Hội đồng nhân dân."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D18-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Cạnh tranh lành mạnh thúc đẩy những người sản xuất", "o": ["đưa ra các biện pháp hợp lý hóa sản xuất, nâng cao hiệu quả.", "sử dụng thủ đoạn phi pháp, triệt tiêu đối thủ.", "tung tin bịa đặt giảm uy tín, chất lượng hàng hóa đối thủ.", "không ngừng hủy hoại tài nguyên môi trường."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 5 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D18-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi mức độ tăng giá của hàng hóa và dịch vụ ở hai con số phản ánh lạm phát của nền kinh tế đó ở mức độ", "o": ["lạm phát vừa phải.", "lạm phát phi mã.", "siêu lạm phát.", "không đáng kể."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 6 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D18-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi cung lao động thấp hơn số lượng việc làm thì sẽ dẫn đến tình trạng nào dưới đây?", "o": ["Thừa lao động phục vụ cho sản xuất kinh doanh.", "Thiếu sản phẩm vật chất cho xã hội.", "Thiếu nguồn lực lao động.", "Không mất cân đối trong sản xuất."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D18-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào sau đây nói về tầm quan trọng của việc xây dựng ý tưởng kinh doanh?", "o": ["Những suy nghĩ, hành động sáng tạo, có tính khả thi.", "Tăng lợi thế cạnh tranh trong kinh doanh.", "Tạo ra tính chủ động và hiệu quả trong hoạt động kinh doanh.", "Đáp ứng sự biến động của thị trường."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D18-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chị X làm đơn khiếu nại về quyết định xử phạt hành chính của tổ công tác cảnh sát giao thông khi nhận thấy quyết định này đã phạt mức tiền cao hơn so với quy định của luật giao thông đường bộ. Việc làm của chị X thể hiện ý nghĩa nào của quyền bình đẳng công dân trước pháp luật?", "o": ["Bảo vệ quyền và lợi ích tối thiểu của con người.", "Bảo vệ nghĩa vụ chính đáng của công dân.", "Bảo hiểm được lợi ích chính đáng của công dân.", "Bảo kê được quyền và lợi ích tối thiểu của con người."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D18-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Thôn của anh H tổ chức họp lấy ý kiến nhân dân về nội dung xây dựng nhà văn hoá mới. Anh H đã rủ anh M là hàng xóm cùng đi tham gia cuộc họp. Nhưng anh M lại từ chối với lí do bận việc gia đình và cũng không có đóng góp ý kiến gì. Trong trường hợp này hành vi của anh M không gây ra hậu quả nào sau đây?", "o": ["Anh M làm ảnh hưởng trật tự quản lý hành chính.", "Anh M không phát huy được vai trò, tính tích cực trong tham gia quản lý nhà nước và xã hội.", "Anh M làm ảnh hưởng đến hiệu quả của việc họp bàn xây dựng nhà văn hoá mới.", "Anh M không biết, không hiểu thông tin về dự án xây dựng nhà văn hoá mới."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D18-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây thể hiện quyền tham gia quản lý nhà nước và xã hội của công dân ở phạm vi cả nước?", "o": ["Công dân tham gia ý kiến trước khi cơ quan có thẩm quyền quyết định.", "Công dân tham gia biểu quyết, quyết định vấn đề quan trọng khi nhà nước trưng cầu ý dân.", "Công dân bàn bạc và quyết định mức đóng góp xây dựng đường của thôn.", "Công dân tham gia giám sát họat động của chính quyền theo quy định của pháp luật."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D18-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào sau đây vi phạm quyền bất khả xâm phạm về thân thể của công dân?", "o": ["Đánh người gây thương tích.", "Đặt điều nói xấu, vu khống người khác.", "Giam giữ người trái phép.", "Đi xe máy gây tai nạn cho người khác."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 12 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D18-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những chỉ tiêu của tăng trưởng kinh tế là", "o": ["sự gia tăng GDP/người.", "tăng tỉ trọng công nghiệp, giảm tỉ trọng nông nghiệp.", "chỉ số phát triển con người HDI tăng.", "chỉ số đói nghèo giảm."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 13 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D18-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, trường hợp nào sau đây thể hiện quyền về nộp thuế của công dân?", "o": ["Kê khai nhằm tăng số tiền được hoàn thuế.", "Sử dụng không hợp pháp hóa đơn chứng từ.", "Khởi kiện quyết định xử lí về thuế.", "Cưỡng chế thi hành quyết định hành chính thuế."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D18-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nhận định nào dưới đây đúng khi nói về bảo hiểm?", "o": ["Bảo hiểm là một trong những trụ cột đảm bảo an sinh xã hội cho người dân.", "Bảo hiểm y tế do nhà nước thực hiện mang tính lợi nhuận.", "Bảo hiểm hoạt động theo nguyên tắc “số ít bù số đông”", "Bảo hiểm không góp phần làm tăng thu ngân sách nhà nước."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D18-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không phải là cơ sở hình thành biên giới quốc gia?", "o": ["Điều ước quốc tế mà Việt Nam kí kết hoặc gia nhập.", "Sự thỏa thuận giữa Việt Nam và quốc gia khác.", "Nguyện vọng của một bộ phận người dân.", "Quy định của pháp luật Việt Nam."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D18-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Ở nước ta hiện nay, chính sách nào dưới đây không phải chính sách cơ bản của hệ thống an sinh xã hội?", "o": ["Chính sách giải quyết việc làm.", "Chính sách giáo dục và đào tạo.", "Chính sách trợ giúp xã hội.", "Chính sách bảo hiểm xã hội."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D18-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, khi mượn tài sản của người khác, công dân phải có nghĩa vụ", "o": ["giữ gìn, bảo quản tài sản mượn.", "khai thác công dụng, hưởng lợi tức từ tài sản.", "chuyển giao tài sản mượn cho người khác.", "thông báo cho cơ quan chức năng về tài sản mượn."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D18-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào sau đây không phản ánh đúng sự cần thiết của việc lập kế hoạch kinh doanh?", "o": ["Giúp chủ thể kinh doanh xác định được mục tiêu, chiến lược, thị trường.", "Tăng khả năng huy động vốn cho chủ thể kinh doanh.", "Là yếu tố đảm bảo chắc chắn cho sự thành công của hoạt động kinh doanh.", "Giúp chủ thể kinh doanh chủ động thực hiện và điều chỉnh kế hoạch."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D18-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc làm nào sau đây phù hợp khi học sinh đến tham quan di tích danh lam thắng cảnh?", "o": ["Khắc tên mình lên các bức tường di tích để lưu dấu ấn cá nhân.", "Ghi chép cẩn thận các thông tin để hiểu rõ hơn về lịch sử của di tích.", "Tụ tập ồn ào, không quan tâm đến các hướng dẫn và quy định tham quan.", "Mang thức ăn, nước uống vào khuôn viên di tích và để lại rác bừa bãi."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 20 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D18-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 21, 22\nTrong những năm qua, hội nhập kinh tế quốc tế của Việt Nam đã đạt được một số thành tựu nhất định, đóng góp chung vào sự phát triển kinh tế - xã hội của đất nước. Tổng kim ngạch xuất, nhập khẩu năm 2018 ước đạt 475 tỷ USD, trong đó xuất khẩu đạt 239 tỷ USD, tăng 11,2% so với năm 2017. Hàng hóa Việt Nam đã tiếp tục khai thác các thị trường truyền thống\nvà mở rộng tìm kiếm, phát triển thêm nhiều thị trường mới. Vốn đầu tư trực tiếp nước ngoài (FDI), hiện cả nước có khoảng 334 tỷ USD vốn đăng ký với hơn 26.600 dự án còn hiệu lực. FDI đã đóng góp lớn trong việc gia tăng năng lực sản xuất và xuất khẩu của Việt Nam. Đến nay, khu vực FDI chiếm khoảng 25% tổng vốn đầu tư toàn xã hội, trên 70% tổng kim ngạch xuất khẩu của cả nước.\n(Theo tạp chí Viện Khoa Học Xã Hội Việt Nam số 7 năm 2019)\nThông tin trên thể hiện nội dung nào dưới đây của hội nhập kinh tế quốc tế?", "o": ["Khái niệm hội nhập kinh tế quốc tế .", "Sự cần thiết của hội nhập kinh tế quốc tế.", "Các hình thức hội nhập kinh tế quốc tế.", "Trách nhiệm của công dân đối với hội nhập kinh tế quốc tế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D18-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 21, 22\nTrong những năm qua, hội nhập kinh tế quốc tế của Việt Nam đã đạt được một số thành tựu nhất định, đóng góp chung vào sự phát triển kinh tế - xã hội của đất nước. Tổng kim ngạch xuất, nhập khẩu năm 2018 ước đạt 475 tỷ USD, trong đó xuất khẩu đạt 239 tỷ USD, tăng 11,2% so với năm 2017. Hàng hóa Việt Nam đã tiếp tục khai thác các thị trường truyền thống\nvà mở rộng tìm kiếm, phát triển thêm nhiều thị trường mới. Vốn đầu tư trực tiếp nước ngoài (FDI), hiện cả nước có khoảng 334 tỷ USD vốn đăng ký với hơn 26.600 dự án còn hiệu lực. FDI đã đóng góp lớn trong việc gia tăng năng lực sản xuất và xuất khẩu của Việt Nam. Đến nay, khu vực FDI chiếm khoảng 25% tổng vốn đầu tư toàn xã hội, trên 70% tổng kim ngạch xuất khẩu của cả nước.\n(Theo tạp chí Viện Khoa Học Xã Hội Việt Nam số 7 năm 2019)\nLợi ích nào của hội nhập kinh tế quốc tế đối với Việt Nam chưa được đề cập trong thông tin trên?", "o": ["gia tăng năng lực sản xuất và xuất khẩu của Việt Nam.", "mở rộng thị trường cho hàng hóa Việt Nam.", "thu hút vốn đầu tư nước ngoài.", "tận dụng tiến bộ khoa học công nghệ."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D18-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 23, 24\nNhận thấy quê hương mình rất phong phú về các loại thảo mộc và nhu cầu thị trường về dòng sản phẩm thiên nhiên ngày càng tăng lên, ông T đã xây dựng kế hoạch kinh doanh mĩ\nphẩm chiết xuất từ thiên nhiên. Sau khi đánh giá những thuận lợi và khó khăn, ông T nhận thấy kế hoạch kinh doanh của mình rất khả thi. Nhờ xây dựng kế hoạch kinh doanh tốt, đánh giá đúng cơ hội, đối tượng khách hàng tiềm năng,… nên việc kinh doanh của ông T đã đạt được những thành công, tăng khả năng huy động vốn, mở rộng quy mô sản xuất kinh doanh.\nÔng T xác định định hướng kinh doanh của mình dựa vào yếu tố nào dưới đây?", "o": ["Nhu cầu thị trường về dòng sản phẩm thiên nhiên ngày càng tăng lên.", "Việc kinh doanh của ông T đã đạt được những thành công ban đầu.", "Nhiều người có nhu cầu kinh doanh mĩ phẩm chiết xuất từ thiên nhiên.", "Ông T là người kinh doanh mĩ phẩm chiết xuất từ thiên nhiên đầu tiên."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D18-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 23, 24\nNhận thấy quê hương mình rất phong phú về các loại thảo mộc và nhu cầu thị trường về dòng sản phẩm thiên nhiên ngày càng tăng lên, ông T đã xây dựng kế hoạch kinh doanh mĩ\nphẩm chiết xuất từ thiên nhiên. Sau khi đánh giá những thuận lợi và khó khăn, ông T nhận thấy kế hoạch kinh doanh của mình rất khả thi. Nhờ xây dựng kế hoạch kinh doanh tốt, đánh giá đúng cơ hội, đối tượng khách hàng tiềm năng,… nên việc kinh doanh của ông T đã đạt được những thành công, tăng khả năng huy động vốn, mở rộng quy mô sản xuất kinh doanh.\nNội dung nào cho thấy ông T lập kế hoạch kinh doanh là điều cần thiết?", "o": ["Nhận thấy quê hương mình rất phong phú về các loại thảo mộc.", "Thấy kế hoạch kinh doanh của mình rất khả thi.", "Khả năng huy động vốn tăng lên, mở rộng quy mô sản xuất kinh doanh.", "Đăng kí kinh doanh với cơ quan nhà nước có thẩm quyền."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D18-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Anh Q đã làm việc được 12 tháng theo hợp đồng lao động có thời hạn 24 tháng cho một công ty. Anh Q và công ty nơi anh Q làm việc đã tham gia và đóng đầy đủ bảo hiểm xã hội và bảo hiểm thất nghiệp nhưng không đóng bảo hiểm y tế. Do bị bệnh, anh Q phải nhập viện điều trị dài ngày nên anh đã làm đơn xin nghỉ việc chấm dứt hợp đồng lao động ở công ty. Vừa mất nguồn thu nhập vừa phải điều trị bệnh dài ngày nên cuộc sống của anh và gia đình vô cùng khó khăn.", "o": ["Anh Q và công ty nơi anh Q làm việc đã vi phạm quy định của Luật Bảo hiểm y tế.", "Anh Q cho rằng anh không tham gia BHYT nhưng có tham gia BHXH nên anh vẫn được quỹ BHYT chi trả một phần chi phí điều trị.", "Anh Q cần làm hồ sơ gửi đến Trung tâm Dịch vụ việc làm thuộc Sở Lao Động – Thương binh và Xã hội mới được nhận khoản trợ cấp thất nghiệp.", "Anh Q cần nhanh chóng tham gia bảo hiểm y tế bắt buộc vì anh còn phải điều trị bệnh dài ngày."], "a": [true, false, true, false], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần II câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D18-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Anh N thành lập doanh nghiệp tư nhân chuyên bán hàng và cung cấp dịch vụ công nghệ thông tin được cơ quan nhà nước có thẩm quyền cấp giấy chứng nhận đăng kí doanh nghiệp. Trước kì nộp thuế, anh luôn chủ động đến cơ quan thuế để được cung cấp đầy đủ thông tin tài liệu liên quan đến quyền và nghĩa vụ nộp thuế. Anh N nghiêm chỉnh chấp hành chế độ kế toán thống kê, ghi chép đầy đủ doanh số bán hàng, kê khai đầy đủ, kịp thời, chính xác số tiền thuế phải nộp, đóng thuế đầy đủ và đúng hạn.", "o": ["Doanh nghiệp tư nhân của anh N vi phạm quyền về kinh doanh.", "Nghĩa vụ mà doanh nghiệp tư nhân của anh N đã thực hiện là nghĩa vụ nộp thuế.", "Một trong các quyền mà doanh nghiệp của anh N được hưởng là tự chủ đăng kí kinh doanh.", "Doanh nghiệp của anh N đã thực hiện nghĩa vụ bảo đảm quyền và lợi ích hợp pháp của người lao động."], "a": [false, true, true, false], "e": "Đáp án: a) Sai; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần II câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D18-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Bà M có con gái là chị H, con trai là anh A và con dâu là chị B. Nghi ngờ anh A tham gia đánh bạc trực tuyến, chị B bí mật rút tiền tiết kiệm của hai vợ chồng rồi nhờ mẹ đẻ chị là bà Q giữ hộ. Vốn coi thường anh A không có thu nhập ổn định nên bà Q đã khuyên con gái góp vốn cùng bà kinh doanh nhu yếu phẩm và được chị B đồng ý. Biết chuyện, chị H bịa đặt và đưa thông tin sai lệch về chị B lên mạng xã hội đồng thời cùng bà M đến nhà bà Q vu khống bà Q lừa đảo chiếm đoạt tài sản của vợ chồng anh A nên giữa hai bên xảy ra xô xát.", "o": ["Em sẽ tố cáo hành vi chị B rút tiền tiết kiệm của hai vợ chồng rồi nhờ mẹ đẻ là bà Q giữ hộ vì vi phạm quyền và nghĩa vụ giữa vợ và chồng trong quan hệ nhân thân.", "Anh A không vi phạm quyền và nghĩa vụ giữa vợ và chồng.", "Em và cộng đồng mạng ủng hộ bà M và chị B vì bà Q lừa đảo chiếm đoạt tài sản của vợ chồng anh A là vi phạm quyền, nghĩa vụ công dân trong gia đình về quan hệ nhân thân.", "Hành vi của chị B, chị H và bà Q cùng vi phạm quyền và nghĩa vụ của công dân trong gia đình."], "a": [false, true, false, true], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần II câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D18-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Tại TP. Hồ Chí Minh, một sự kiện \"Ngày hội môi trường\" được tổ chức nhằm nâng cao nhận thức cộng đồng về bảo vệ môi trường. Sự kiện thu hút sự tham gia của học sinh, sinh viên, các tổ chức xã hội và các công ty trong khu vực. Các hoạt động như dọn dẹp công viên, trồng cây xanh và thu gom rác thải được thực hiện, nhưng cũng có những ý kiến trái chiều cho rằng các hoạt động này chỉ mang tính hình thức và không tạo ra sự thay đổi lâu dài. Tuy nhiên, sự kiện đã góp phần nâng cao ý thức cộng đồng về bảo vệ môi trường, đặc biệt là sự tham gia của các bạn trẻ trong việc thực hiện các hành động cụ thể.", "o": ["Công dân có thể tham gia vào các hoạt động bảo vệ môi trường nếu họ thấy cần thiết, nhưng không bắt buộc.", "Các hoạt động bảo vệ môi trường chỉ có ý nghĩa nếu chúng được thực hiện theo kế hoạch dài hạn và có sự tham gia của chính quyền địa phương.", "Em sẽ tham gia vào các sự kiện bảo vệ môi trường như \"Ngày hội môi trường\" vì đó là trách nhiệm của công dân, không chỉ của các tổ chức và doanh nghiệp.", "Các sự kiện bảo vệ môi trường không thực sự có hiệu quả nếu không có sự can thiệp từ các cơ quan chính phủ."], "a": [false, false, true, false], "e": "Đáp án: a) Sai; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần II câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}]}, {"id": "TN-D19", "loai": "tn", "khoi": 12, "hoc_ki": 2, "so_de": 19, "ten": "Đề luyện thi tốt nghiệp số 19", "pham_vi": "Đề nguồn của giáo viên, giữ NGUYÊN chữ của đề (chỉ bỏ lỗi sao chép) · «10 ĐỀ» Đề 9 · file nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm 4 lựa chọn + 4 câu đúng/sai (mỗi câu 4 ý)", "cham": {"tong": 10, "tn": 0.25, "ds": [0, 0.1, 0.25, 0.5, 1.0]}, "status": "cho_duyet", "khoa": {"đã giải lại, khớp khoá": 27, "đã tự giải lại": 1}, "sua": "Khoá đã rà 16/11/2026 cùng đề «học kì II» lớp 12: Câu đúng/sai 2 (dây cáp ngầm, khoan thềm lục địa): vị trí cách đường cơ sở 150 hải lý còn nằm trong thềm lục địa (tối thiểu 200 hải lý) nên ý a Đúng — khớp với các ý b, c, d đều nói «vùng thềm lục địa của TA» (đề nguồn ghi a Sai).", "cau": [{"id": "TN-D19-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong các hoạt động kinh tế, hoạt động nào đóng vai trò trung gian, kết nối người sản xuất với người tiêu dùng?", "o": ["Hoạt động tiêu dùng", "Hoạt động phân phối - trao đổi", "Hoạt động sản xuất - vận chuyển", "Hoạt động sản xuất - tiêu thụ"], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D19-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong quá trình cho vay có sự chênh lệch giữa chi phí sử dụng tiền mặt và chi phí sử dụng dịch vụ tín dụng được gọi là gì ?", "o": ["Tiền dịch vụ.", "Tiền lãi.", "Tiền gốc.", "Tiền phát sinh."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D19-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Người đứng đầu nhà nước, thay mặt nước Cộng hoà xã hội chủ nghĩa Việt Nam về đối nội và đối ngoại, thống lĩnh lực lượng vũ trang nhân dân là", "o": ["Chủ tịch nước.", "Chủ tịch Quốc hội.", "Thủ tướng chính phủ.", "Tổng bí thư"], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D19-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Những quy tắc xử sự chung được áp dụng nhiều lần, ở nhiều nơi đối với tất cả mọi người là thể hiện đặc điểm nào dưới đây của pháp luật?", "o": ["Tính chặt chẽ về hình thức.", "Tính kỉ luật nghiêm minh.", "Tính quy phạm phổ biến.", "Tính quyền lực, bắt buộc chung."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D19-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong nền kinh tế thị trường, nếu công nghệ và kĩ thuật chưa được ứng dụng phổ biến thì năng suất lao động giảm và chi phí lao động sản xuất ra hàng hoá tăng từ đó sẽ ảnh hưởng như thế nào đối với cung hàng hóa?", "o": ["Cung giảm xuống.", "Cung tăng lên.", "Cung không đổi.", "Cung bằng cầu."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 5 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D19-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Là sự thỏa thuận giữa người bán sức lao động và người mua sức lao động về tiền công, tiền lương và các điều kiện làm việc khác là nội dung của khái niệm", "o": ["thị trường lao động.", "thị trường tài chính.", "thị trường tiền tệ.", "thị trường công nghệ"], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 6 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D19-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tình trạng người lao động mong muốn có việc làm nhưng chưa tìm được việc làm là nội dung của khái niệm", "o": ["thất nghiệp.", "lạm phát.", "thu nhập.", "khủng hoảng."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D19-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Các nguồn giúp tạo ý tưởng kinh doanh của chủ thể sản xuất kinh doanh xuất phát từ yếu tố nào dưới đây?", "o": ["Lợi thế nội tại và cơ hội bên ngoài.", "Điểm yếu nội tại và khó khăn bên ngoài.", "Mâu thuẫn của chủ thể sản xuất.", "Khó khăn của chủ thể sản xuất."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D19-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, quyền bình đẳng giữa các dân tộc trong lĩnh vực chính trị thể hiện ở việc các dân tộc trong cộng đồng dân tộc Việt Nam đều có quyền", "o": ["tham gia phát triển du lịch cộng đồng.", "hỗ trợ chi phí học tập đại học.", "khám chữa bệnh theo quy định .", "tham gia quản lý nhà nước và xã hội."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D19-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào dưới đây của công dân không thể hiện quyền bình đẳng của công dân trong hoạt động tín ngưỡng tôn giáo?", "o": ["Đạo pháp dân tộc.", "Tốt đời đẹp đạo.", "Buôn thần bán thánh.", "Kính chúa yêu nước."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D19-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, tại thời điểm tổ chức bầu cử, cử tri không vi phạm quyền và nghĩa vụ của công dân về bầu cử khi", "o": ["độc lập lựa chọn ứng cử viên.", "công khai nội dung đã viết vào phiếu bầu.", "tự ý bỏ phiếu thay người khác.", "ủy quyền thực hiện nghĩa vụ bầu cử."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D19-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, trong những trường hợp cần thiết, việc kiểm soát điện thoại, điện tín của công dân chỉ được tiến hành bởi", "o": ["người có thẩm quyền.", "lực lượng bưu chính.", "cơ quan ngôn luận.", "phóng viên báo chí."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 12 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D19-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mối quan hệ giữa tăng trưởng kinh tế và phát triển bền vững được thể hiện ở nội dung nào dưới đây?", "o": ["Tăng trưởng kinh tế và phát triển bền vững không liên quan đến nhau.", "Tăng trưởng kinh tế không gây ảnh hưởng đến phát triển bền vững.", "Tăng trưởng kinh tế quan trọng nhưng không đảm bảo phát triển bền vững.", "Tăng trưởng kinh tế là điều kiện tiên quyết để đạt được phát triển bền vững."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 13 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D19-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong trường hợp sau, người dân trên địa bàn xã B đã được hưởng chính sách an sinh xã hội nào? Trường hợp. Năm 2022, do hậu quả của thiên tai, gây thiệt hại nghiêm trọng về người và tài sản, chính quyền xã B đã kịp thời trợ cấp cho các hộ gia đình và cá nhân bị ảnh hưởng, nhờ đó, người dân đã sớm ổn định lại cuộc sống.", "o": ["Chính sách việc làm, thu nhập và giảm nghèo.", "Chính sách dịch vụ xã hội cơ bản.", "Chính sách bảo hiểm xã hội.", "Chính sách trợ giúp xã hội."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D19-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công dân phải kinh doanh đúng ngành, nghề ghi trong giấy chứng nhận đăng kí kinh doanh là nội dung quy định về nghĩa vụ nào dưới đây?", "o": ["Nghĩa vụ của công dân về sản xuất, kinh doanh.", "Nghĩa vụ của công dân về kinh doanh.", "Bảo vệ lợi ích hợp pháp của người tiêu dùng.", "Tuân thủ quy định của pháp luật về bảo vệ môi trường."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D19-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 16, 17, 18\nVề kinh tế, từng bước thực hiện tăng trưởng xanh, phát triển năng lượng sạch; thực hiện sản xuất và tiêu dùng bền vững. Tăng trưởng kinh tế giai đoạn 2016 - 2020 đạt trung bình 7%/năm, nâng mức thu nhập bình quân đầu người hằng năm tính theo GDP tăng lên 3.200 - 3.500 USD (so với mức 2.100 USD năm 2015). Lạm phát giữ ở mức dưới 5%. Thực hiện tiến bộ và công bằng xã hội; thực hiện tốt các chính sách an sinh xã hội; năm 2014 đã có 1,4 triệu người tham gia bảo hiểm xã hội, trên 8,5 triệu người tham gia bảo hiểm thất nghiệp, trên 72% dân số tham gia bảo hiểm y tế. Đời sống nhân dân được cải thiện. Thu nhập bình quân đầu người đạt 2.052 USD/người (2014). Tuổi thọ trung bình đạt 73,5 tuổi (2015). Hoàn thành nhiều mục tiêu Thiên niên kỷ.\nCụm từ GDP/người là một trong những chỉ tiêu thể hiện tốc độ tăng trưởng kinh tế nó thể hiện nội dung nào dưới đây?", "o": ["Tổng sản phẩm quốc nội.", "Tổng sản phẩm quốc dân theo đầu người.", "Tổng sản phẩm quốc dân.", "Tổng sản phẩm quốc nội theo đầu người."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D19-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 16, 17, 18\nVề kinh tế, từng bước thực hiện tăng trưởng xanh, phát triển năng lượng sạch; thực hiện sản xuất và tiêu dùng bền vững. Tăng trưởng kinh tế giai đoạn 2016 - 2020 đạt trung bình 7%/năm, nâng mức thu nhập bình quân đầu người hằng năm tính theo GDP tăng lên 3.200 - 3.500 USD (so với mức 2.100 USD năm 2015). Lạm phát giữ ở mức dưới 5%. Thực hiện tiến bộ và công bằng xã hội; thực hiện tốt các chính sách an sinh xã hội; năm 2014 đã có 1,4 triệu người tham gia bảo hiểm xã hội, trên 8,5 triệu người tham gia bảo hiểm thất nghiệp, trên 72% dân số tham gia bảo hiểm y tế. Đời sống nhân dân được cải thiện. Thu nhập bình quân đầu người đạt 2.052 USD/người (2014). Tuổi thọ trung bình đạt 73,5 tuổi (2015). Hoàn thành nhiều mục tiêu Thiên niên kỷ.\nNội dung nào dưới đây không phải là chỉ tiêu để đánh giá sự phát triển kinh tế của Việt Nam trong thông tin trên?", "o": ["Thực hiện chính sách an sinh xã hội.", "Công tác giải quyết việc làm, bảo hiểm.", "Thu nhập bình quân đầu người (GDP/người)", "Tỷ lệ lạm phát và tăng giá hàng tiêu dùng."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D19-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 16, 17, 18\nVề kinh tế, từng bước thực hiện tăng trưởng xanh, phát triển năng lượng sạch; thực hiện sản xuất và tiêu dùng bền vững. Tăng trưởng kinh tế giai đoạn 2016 - 2020 đạt trung bình 7%/năm, nâng mức thu nhập bình quân đầu người hằng năm tính theo GDP tăng lên 3.200 - 3.500 USD (so với mức 2.100 USD năm 2015). Lạm phát giữ ở mức dưới 5%. Thực hiện tiến bộ và công bằng xã hội; thực hiện tốt các chính sách an sinh xã hội; năm 2014 đã có 1,4 triệu người tham gia bảo hiểm xã hội, trên 8,5 triệu người tham gia bảo hiểm thất nghiệp, trên 72% dân số tham gia bảo hiểm y tế. Đời sống nhân dân được cải thiện. Thu nhập bình quân đầu người đạt 2.052 USD/người (2014). Tuổi thọ trung bình đạt 73,5 tuổi (2015). Hoàn thành nhiều mục tiêu Thiên niên kỷ.\nTốc độ tăng trưởng kinh tế giai 2016 - 2020 đạt trung bình 7%/năm có vai trò như thế nào đối với sự phát triển kinh tế của nước ta trong giai đoạn này?", "o": ["Quyết định nhất.", "Không đáng kể.", "Kìm hãm.", "Động lực."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D19-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 19, 20\nĐầu năm, vợ chồng anh A thống nhất đặt mục tiêu mỗi tháng sẽ dành 60% thu nhập cho các chi tiêu thiết yếu, tiết kiệm 20% thu nhập gia đình để có đủ tiền mua xe máy mới cho vợ nhưng hai tháng nay, anh A bị mất việc, thu nhập gia đình bị giảm sút, kinh tế gia đình eo hẹp mà vợ anh vẫn quyết tâm thực hiện mục tiêu tiết kiệm đã đặt ra bằng cách cắt giảm một số chi tiêu thiết yếu trong gia đình. Để phụ giúp gia đình trong thời gian chưa đi làm trở lại, anh A đã tham gia chạy xe ôm tại bến xe đồng thời nhận giao hàng cho một số cửa hàng trên địa bàn sinh sống. Nhờ đó mà sau một năm vợ chồng anh A đã hoàn thành mục tiêu đặt ra. Khi anh A đã ổn đinh với công việc mới, hai vợ chồng quyết tâm năm năm tới sẽ mua được một mảnh đất để làm cửa hàng cho thuê.\nViệc tham gia chạy xe ôm và giao hàng cho các cửa hàng là hoạt động góp phần tạo ra thu nhập nào dưới đây?", "o": ["Thừa kế.", "Bảo hiểm.", "Thụ động.", "Chủ động."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D19-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 19, 20\nĐầu năm, vợ chồng anh A thống nhất đặt mục tiêu mỗi tháng sẽ dành 60% thu nhập cho các chi tiêu thiết yếu, tiết kiệm 20% thu nhập gia đình để có đủ tiền mua xe máy mới cho vợ nhưng hai tháng nay, anh A bị mất việc, thu nhập gia đình bị giảm sút, kinh tế gia đình eo hẹp mà vợ anh vẫn quyết tâm thực hiện mục tiêu tiết kiệm đã đặt ra bằng cách cắt giảm một số chi tiêu thiết yếu trong gia đình. Để phụ giúp gia đình trong thời gian chưa đi làm trở lại, anh A đã tham gia chạy xe ôm tại bến xe đồng thời nhận giao hàng cho một số cửa hàng trên địa bàn sinh sống. Nhờ đó mà sau một năm vợ chồng anh A đã hoàn thành mục tiêu đặt ra. Khi anh A đã ổn đinh với công việc mới, hai vợ chồng quyết tâm năm năm tới sẽ mua được một mảnh đất để làm cửa hàng cho thuê.\nNội dung nào dưới đây thể hiện việc thực hiện kế hoạch quản lý thu, chi trong gia đình anh A?", "o": ["Điều chỉnh các khoản chi.", "Đặt mục tiêu mua xe.", "Bổ sung các khoản tiết kiệm.", "Tham gia tìm kiếm việc làm."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 20 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D19-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây thể hiện nghĩa vụ của công dân trong việc tham gia bảo vệ di sản văn hóa?", "o": ["Tố cáo hành vi phá hoại di tích.", "Tuyên truyền bảo vệ di tích.", "Phục chế trò chơi dân gian.", "Nghiên cứu loại hình nghệ thuật."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D19-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc người lao động tham gia và được hưởng chế độ bảo hiểm thất nghiệp theo quy định là đã thực hiện quyền của công dân ở nội dung nào dưới đây?", "o": ["Kinh doanh và đóng thuế.", "Chăm sóc bảo vệ sức khỏe.", "Học tập thường xuyên", "Bảo đảm an sinh xã hội."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D19-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 23, 24\nPhát hiện chồng mình là anh D thường qua lại với chị H là người yêu cũ dù chị đã có chồng con, chị M bế con bỏ nhà đi biệt tích. Nắm được sự việc, bà V mẹ chị M, tới nhà bà K nói chuyện, do thiếu kiềm chế, bà V đã có lời lẽ xúc phạm bà K và anh D nên bị con gái bà K mời ra khỏi nhà. Trong thời gian đó, do thường xuyên không được trang bị bảo hộ đạt chuẩn, anh D bị tai nạn phải nằm viện điều trị một tháng. Vì ông T giám đốc công ty nơi anh D làm việc không đồng ý bồi thường số tiền mà anh D yêu cầu nên bà K đã thuê phóng viên viết bài công khai việc ông T có con ngoài giá thú rồi chia sẻ lên mạng khiến uy tín của ông bị ảnh hưởng nghiêm trọng và vợ ông đòi ly hôn.\nTrong thông tin trên những ai dưới đây đã vi phạm quyền và nghĩa vụ giữa vợ và chồng trong quan hệ hôn nhân và gia đình?", "o": ["Chị H, ông T và bà K.", "Ông T, anh D và bà V.", "Anh D, chị H và ông T.", "Anh D, chị H và chị M."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D19-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 23, 24\nPhát hiện chồng mình là anh D thường qua lại với chị H là người yêu cũ dù chị đã có chồng con, chị M bế con bỏ nhà đi biệt tích. Nắm được sự việc, bà V mẹ chị M, tới nhà bà K nói chuyện, do thiếu kiềm chế, bà V đã có lời lẽ xúc phạm bà K và anh D nên bị con gái bà K mời ra khỏi nhà. Trong thời gian đó, do thường xuyên không được trang bị bảo hộ đạt chuẩn, anh D bị tai nạn phải nằm viện điều trị một tháng. Vì ông T giám đốc công ty nơi anh D làm việc không đồng ý bồi thường số tiền mà anh D yêu cầu nên bà K đã thuê phóng viên viết bài công khai việc ông T có con ngoài giá thú rồi chia sẻ lên mạng khiến uy tín của ông bị ảnh hưởng nghiêm trọng và vợ ông đòi ly hôn.\nAnh D và chị H đã vi phạm nội dung nào dưới đây của quyền và nghĩa vụ giữa vợ và chồng trong gia đình?", "o": ["Quyền kết hôn.", "Quyền ly hôn.", "Quyền tài sản.", "Quyền nhân thân."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D19-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Sau khi kết hôn, vợ chồng chị H được bố mẹ chị H tặng cho 2 vợ chồng một ngôi nhà, ngôi nhà đã được cấp giấy chứng nhận quyền sử dụng đất đứng tên 2 vợ chồng. Khi biết điều này, vợ chồng anh trai của chị H đã bày tỏ thái độ bất mãn, phản đối việc làm của bố mẹ vì cho rằng chị H là con gái nên không có quyền hưởng hết và đòi vợ chồng chị H phải đưa cho mình số tiền giá trị bằng nửa ngôi nhà đó. Chị H không đồng ý nên mỗi ngày vợ chồng người anh trai luôn tìm mọi cách để quấy phá làm ảnh hưởng đến cuộc sống riêng tư của gia đình chị H.", "o": ["Vợ chồng anh trai chị H đã được cơ quan có thẩm quyền cấp giấy chứng nhận quyền sử dụng đất.", "Vợ chồng chị H đã thực hiện quyền sử dụng tài sản theo đúng quy định pháp luật.", "Vợ chồng anh trai đến nhà quấy phá cuộc sống riêng tư của gia đình chị H là hành vi sai trái.", "Vợ chồng anh trai được quyền đòi một nửa số tiền tổng trị giá ngôi nhà của vợ chồng chị H."], "a": [false, true, true, false], "e": "Đáp án: a) Sai; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần II câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D19-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Quốc gia HU xúc tiến việc lắp đặt các dây cáp ngầm dưới đáy biển ở vị trí cách đường cơ sở của quốc gia TA 150 hải lý.Trong quá trình lắp đặt, các kỹ sư thi công của HU nhận thấy rằng cần phải cố định các đường dây cáp bằng cách khoan 10 mũi vào đáy biển và họ gửi đề xuất này tới Chính phủ HU. Chính phủ HU đồng ý với đề xuất trên, đồng thời cho phép các kỹ sư thi công thăm dó và thực hiện việc khoan cố định 10 mũi vào lòng đất dưới đáy biển nơi đặt dây cáp ngầm. Khi phát hiện ra hành vi nói trên, TA đã yêu cầu HU dừng ngay hành vi lắp đặt dây cáp cũng như việc khoan vào lòng đất dưới đáy biển trong vùng biển của TA.", "o": ["Vị trí mà HU thực hiện các hành vi nêu trên thuộc vùng thềm lục địa của TA.", "TA yêu cầu HU dừng ngay hành vi lắp đặt dây cáp ngầm cũng như khoan vào lòng đất dưới đáy biển không phù hợp với quy định của luật quốc tế.", "HU tiến hành việc khoan 10 mũi khoan lên vùng thềm lục địa của TA khi không có sự đồng ý của TA là hành vi trái với quy định của pháp luật quốc tế, đồng thời vi phạm đến đặc quyền của TA.", "Quyền của HU lắp đặt dây cáp và ống dẫn ở thềm lục địa của quốc gia ven biển không phải là quyền tự do vô điều kiện mà phải có sự thỏa thuận của TA."], "a": [true, true, true, true], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần II câu 2 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D19-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Công ty B (trụ sở thương mại tại Pháp) liên hệ với chi nhánh Công ty C (trụ sở thương mại Việt Nam) tại Pháp, yêu cầu mua 100 tấn gạo chất lượng cao, giá X xuất xứ Việt Nam. Ngày 14 tháng 2 năm 2019, Công ty C liên hệ trực tiếp với Công ty B để xác nhận lại đơn hàng với các điều khoản mà chi nhánh công ty này ở Pháp đã truyền đạt, thời hạn trả lời vào ngày 20 tháng 02 năm 2019. Ngày 18 tháng 02 năm 2019, Công ty C bị cháy kho hàng nên hàng hóa không còn đủ để thực hiện các hợp đồng mua bán nên Công ty C đã gửi fax đề cập đến tình hình của công ty và tuyên bố không thể giao hàng. Ngày 23 tháng 02 năm 2019, Công ty B hồi đáp yêu cầu công ty C giao hàng vào ngày 30 tháng 2, thanh toán tiền hàng thành 3 đợt. Bên Công ty C không thể giao hàng. Do đó, Công ty B kiện Công ty C ra Tòa án Việt Nam để giải quyết.", "o": ["Chủ thể của hợp đồng thương mại này là Pháp và Việt Nam.", "Hết thời hạn trả lời theo yêu cầu mà công ty C không trả lời thì xem như hợp đồng đã được giao kết.", "Công ty C không giao hàng bởi sự kiện bất khả kháng và đã thông báo cho công ty B nên không phải chịu trách nhiệm bồi thường.", "Công ty B không có cơ sở để kiện công ty C vì những điều khoản của hợp đồng này chưa đầy đủ."], "a": [true, false, true, false], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần II câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D19-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đến nay, nước ta đã có quan hệ chính thức với 189/193 quốc gia và vùng lãnh thổ (trong đó có 4 đối tác chiến lược toàn diện, 17 đối tác chiến lược, 13 đối tác toàn diện); có quan hệ thương mại với 224 đối tác và quan hệ hợp tác với hơn 300 tổ chức quốc tế; đã ký hơn 90 hiệp định thương mại song phương, gần 60 hiệp định khuyến khích và bảo hộ đầu tư; đàm phán, ký kết và thực thi 19 Hiệp định thương mại tự do (FTA) song phương và đa phương với hầu hết các nền kinh tế lớn trên thế giới; trong đó 16 FTA đã có hiệu lực với hơn 60 đối tác, phủ rộng khắp các châu lục với tổng GDP chiếm gần 90% GDP toàn cầu, đưa Việt Nam trở thành một trong những nước dẫn đầu khu vực về tham gia các khuôn khổ hợp tác kinh tế song phương và đa phương.", "o": ["Nước ta có quan hệ hợp tác kinh tế với 189/193 quốc gia và vùng lãnh thổ.", "Việc ký kết các hiệp định thương mại song phương và đa phương giúp Việt Nam mở rộng hoạt động kinh tế đối ngoại.", "Kinh tế đối ngoại là yếu tố giữ vai trò quan trọng góp phần thúc đẩy tăng trưởng và phát triển kinh tế.", "Trong tiến trình hội nhập kinh tế quốc tế, nước ta thường chú trọng đến liên kết với các quốc gia có trình độ phát triển tương đồng."], "a": [true, true, true, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần II câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}]}, {"id": "TN-D20", "loai": "tn", "khoi": 12, "hoc_ki": 2, "so_de": 20, "ten": "Đề luyện thi tốt nghiệp số 20", "pham_vi": "Đề nguồn của giáo viên, giữ NGUYÊN chữ của đề (chỉ bỏ lỗi sao chép) · «10 ĐỀ» Đề 10 · file nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm 4 lựa chọn + 4 câu đúng/sai (mỗi câu 4 ý)", "cham": {"tong": 10, "tn": 0.25, "ds": [0, 0.1, 0.25, 0.5, 1.0]}, "status": "cho_duyet", "khoa": {"đã giải lại, khớp khoá": 27, "đã tự giải lại": 1}, "sua": "Khoá đã rà 16/11/2026 cùng đề «học kì II» lớp 12: Câu 5 (Luật Bình đẳng giới, cản trở người khác tham gia hoạt động giáo dục sức khoẻ): lĩnh vực y tế (B). Ngân hàng bài (B11-10-K09) cùng khoá B; khoá C trong đề này lệch.", "cau": [{"id": "TN-D20-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chủ thể nào đóng vai trò quan trọng trong việc tạo ra hàng hoá cho xã hội, phục vụ nhu cầu tiêu dùng?", "o": ["Chủ thể trung gian.", "Doanh nghiệp Nhà nước.", "Các điểm bán hàng.", "Chủ thể sản xuất."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D20-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Các cá nhân, tổ chức sử dụng đúng đắn các quyền của mình, làm những gì pháp luật cho phép làm là", "o": ["tuân thủ pháp luật.", "sử dụng pháp luật.", "thi hành pháp luật.", "áp dụng pháp luật."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D20-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "thất nghiệp xuất hiện do có sự mất cân đối giữa cung và cầu lao động, sự dịch chuyển cơ cấu giữa các ngành trong nền kinh tế hoặc sự thay đổi phương thức sản xuất trong một ngành được gọi là", "o": ["thất nghiệp thời vụ.", "thất nghiệp cơ cấu.", "thất nghiệp chu kì.", "thất nghiệp tự nguyện."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D20-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc chủ thể sản xuất kinh doanh không ngừng rèn luyện kỹ năng, nâng cao hiểu biết về lĩnh vực mình kinh doanh là thể hiện năng lực nào dưới đây?", "o": ["Năng lực trải nghiệm.", "Năng lực sống thử.", "Năng lực học tập.", "Năng lực lãnh đạo."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D20-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của Luật bình đẳng giới, hành vi cản trở, xúi giục người khác không tham gia các hoạt động giáo dục sức khoẻ vì định kiến giới là hành vi vi phạm pháp luật về bình đẳng giới trong lĩnh vực nào dưới đây?", "o": ["Văn hoá.", "Y tế.", "Giáo dục và đào tạo.", "Hôn nhân và gia đình."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 5 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D20-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, tại thời điểm tổ chức bầu cử, cử tri không vi phạm quyền và nghĩa vụ của công dân về bầu cử khi", "o": ["độc lập lựa chọn ứng cử viên.", "công khai nội dung đã viết vào phiếu bầu.", "tự ý bỏ phiếu thay người khác.", "ủy quyền thực hiện nghĩa vụ bầu cử."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 6 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D20-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Cụm từ GDP/người là một trong những chỉ tiêu thể hiện tốc độ tăng trưởng kinh tế nó thể hiện nội dung nào dưới đây?", "o": ["Tổng sản phẩm quốc dân.", "Tổng sản phẩm quốc nội theo đầu người.", "Tổng sản phẩm quốc dân theo đầu người.", "Tổng sản phẩm quốc nội."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D20-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Loại hình bảo hiểm nào dưới đây, trong đó hoạt động của tổ chức bảo hiểm chấp nhận rủi ro của người được bảo hiểm trên cơ sở bên mua bảo hiểm đóng phí bảo hiểm để tổ chức bảo hiểm bồi thường, trả tiền bảo hiểm khi xảy ra sự kiện bảo hiểm theo thoả thuận trong hợp đồng bảo hiểm đã được hai bên kí kết.", "o": ["Bảo hiểm ý tế.", "Bảo hiểm thất nghiệp.", "Bảo hiểm thương mại.", "Bảo hiểm xã hội."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D20-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, khi chủ sở hữu quyết định từ bỏ quyền sở hữu tài sản của mình là đã thực hiện quyền nào dưới đây?", "o": ["Quyền chiếm hữu.", "Quyền sử dụng.", "Quyền chiếm đoạt.", "Quyền định đoạt."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D20-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hình thức sản xuất kinh doanh với các thành viên có tài sản chung, cùng đóng góp công sức để sản xuất kinh doanh được gọi là gì?", "o": ["Mô hình kinh tế hộ gia đình.", "Mô hình kinh tế khác.", "Mô hình kinh tế hợp tác xã.", "Mô hình kinh tế doanh nghiệp."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D20-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Về mặt kinh tế, Hiến pháp 2013 khẳng định mô hình kinh tế của nước ta hiện nay là mô hình kinh tế thị trường định hướng", "o": ["tư bản chủ nghĩa.", "xã hội chủ nghĩa.", "chuyên chế tư bản.", "cộng sản chủ nghĩa."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D20-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, hành vi nào dưới đây vi phạm quyền bất khả xâm phạm về chỗ ở của công dân?", "o": ["Tự ý mở điện thoại của bạn.", "Đe dọa đánh người.", "Tự ý vào nhà người khác.", "Tung ảnh nóng của bạn lên facebook."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 12 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D20-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định Điều 157 của Bộ luật Hình sự, người nào bắt, giữ hoặc giam người trái pháp luật, nếu không thuộc trường hợp quy định tại Điều 153 và Điều 377 của Bộ luật này, phải chịu trách nhiệm pháp lí nào sau đây?", "o": ["Phạt cải tạo không giam giữ đến 03 năm hoặc phạt tù từ 06 tháng đến 03 năm.", "Phạt cải tạo không giam giữ đến 03 năm hoặc phạt tù từ 02 năm đến 07 năm.", "Phạt cải tạo không giam giữ đến 03 năm hoặc phạt tù từ 07 năm đến 10 năm.", "Phạt cải tạo không giam giữ đến 03 năm hoặc phạt tù từ 05 năm đến 12 năm"], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 13 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D20-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Sự thỏa thuận giữa người bán sức lao động và người mua sức lao động về tiền công, tiền lương và các điều kiện làm việc khác là nội dung của khái niệm nào sau đây?", "o": ["Thị trường lao động.", "Thị trường tài chính.", "Thị trường tiền tệ.", "Thị trường công nghệ."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D20-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Cửa hàng của chị H được cấp giấy phép bán đường sữa, bánh kẹo. Nhận thấy nhu cầu về thức ăn nhanh trên thị trường tăng cao nên chị H đã bán thêm mặt hàng này mà không khai báo cơ quan chức năng. Hành vi của chị H là biểu hiện nào của tính hai mặt trong cạnh tranh?", "o": ["Cạnh tranh trực tuyến.", "cạnh tranh tiêu cực.", "cạnh tranh lành mạnh.", "cạnh tranh không lành mạnh."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D20-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 16, 17\nBà H, ở tỉnh D, sau khi dừng tham gia bảo hiểm xã hội (BHXH) bắt buộc đã bỏ số tiền hơn 40 triệu đồng đóng BHXH tự nguyện những năm còn thiếu để được hưởng lương hưu tâm sự, chia sẻ: “Lúc trước làm việc, tôi cũng có tham gia BHXH, do điều kiện tôi xin nghỉ và đã hưởng một lần. Số tiền nhận khi đó cũng giúp tôi làm được một số việc nhưng cũng chẳng được bao lâu. Đến khi sau này đi làm lại và tham gia BHXH, lúc gần nghỉ việc do hết tuổi lao động, quá trình tham gia BHXH của mình chỉ được 14 năm 02 tháng chưa đủ điều kiện để hưởng chế độ hưu trí. Tôi đã suy nghĩ, rút kinh nghiệm lần trước nên đã quyết định đóng BHXH tự nguyện số năm còn thiếu để hưởng lương hưu”. Tiền lương hưu hàng tháng cũng đủ trang trải cho cuộc sống hàng ngày, mình còn được cấp thẻ bảo hiểm y tế quyền lợi cao hơn so với lúc đi làm để đi khám bệnh, mà lớn tuổi rồi sức khỏe xuống có khi ở bệnh viện nhiều hơn ở nhà. Nên tính ra việc nhận lương hưu nó bảo đảm hơn cho bản thân mình khi về già”.\nBà H là đối tượng đã tham gia những loại hình bảo hiểm nào dưới đây?", "o": ["Bảo hiểm y tế, bảo hiểm xã hội và bảo hiểm thất nghiệp.", "Bảo hiểm thất nghiệp, bảo hiểm xã hội tự nguyện và bắt buộc.", "Bảo hiểm xã hội tự nguyện, bắt buộc và bảo hiểm y tế.", "Bảo hiểm thân thể, tải sản và bảo hiểm thương mại."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D20-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 16, 17\nBà H, ở tỉnh D, sau khi dừng tham gia bảo hiểm xã hội (BHXH) bắt buộc đã bỏ số tiền hơn 40 triệu đồng đóng BHXH tự nguyện những năm còn thiếu để được hưởng lương hưu tâm sự, chia sẻ: “Lúc trước làm việc, tôi cũng có tham gia BHXH, do điều kiện tôi xin nghỉ và đã hưởng một lần. Số tiền nhận khi đó cũng giúp tôi làm được một số việc nhưng cũng chẳng được bao lâu. Đến khi sau này đi làm lại và tham gia BHXH, lúc gần nghỉ việc do hết tuổi lao động, quá trình tham gia BHXH của mình chỉ được 14 năm 02 tháng chưa đủ điều kiện để hưởng chế độ hưu trí. Tôi đã suy nghĩ, rút kinh nghiệm lần trước nên đã quyết định đóng BHXH tự nguyện số năm còn thiếu để hưởng lương hưu”. Tiền lương hưu hàng tháng cũng đủ trang trải cho cuộc sống hàng ngày, mình còn được cấp thẻ bảo hiểm y tế quyền lợi cao hơn so với lúc đi làm để đi khám bệnh, mà lớn tuổi rồi sức khỏe xuống có khi ở bệnh viện nhiều hơn ở nhà. Nên tính ra việc nhận lương hưu nó bảo đảm hơn cho bản thân mình khi về già”.\nNội dung nào dưới đây không thể hiện vai trò của bảo hiểm đối với bà H?", "o": ["Được chăm sóc sức khỏe trọn đời.", "Được hưởng trợ cấp ốm đau.", "Ổn định thu nhập khi về già.", "Được hưởng chế độ tử tuất."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D20-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc cân đối các khoản thu và chi nhằm đáp ứng nhu cầu vật chất, tinh thần của các thành viên sao cho phù hợp với các nguồn thu nhập của gia đình là nội dung của khái niệm nào dưới đây?", "o": ["Quản lí thu, chi nội bộ.", "Quản lí thu, chi đối ngoại.", "Quản lí thu, chi đối nội.", "Quản lí thu, chi trong gia đình."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D20-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không thể hiện sự cần thiết phải quản lý thu, chi trong gia đình?", "o": ["Điều chỉnh hành vi tiêu dùng.", "Thiết lập mục tiêu tài chính.", "Chi tiêu tự do mất kiểm soát.", "Kiểm soát các nguồn thu nhập."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D20-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những quyền của công dân trong bảo vệ và chăm sóc sức khỏe là được", "o": ["từ chối công tác phòng chống dịch truyền nhiễm.", "hướng dẫn chăm sóc sức khỏe bản thân.", "xuyên tạc bệnh lý người khác nếu mâu thuẫn.", "công khai mọi thông tin cá nhân người bệnh."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 20 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D20-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Thanh tra Sở Y tế Y phát hiện phòng khám đa khoa của bà H bán thuốc hết hạn sử dụng với tổng giá trị số thuốc được xác định là 28 triệu đồng. Theo quy định của pháp luật, hành vi bán thuốc hết hạn sử dụng của bà H phải chịu trách nhiệm pháp lí nào sau đây?", "o": ["Cảnh cáo và buộc tiêu hủy toàn bộ số thuốc hết hạn sử dụng.", "Phạt tiền, tước quyền sử dụng chứng chỉ hành nghề có thời hạn và buộc tiêu hủy toàn bộ số thuốc hết hạn sử dụng.", "Phạt tiền, buộc tiêu hủy toàn bộ số thuốc hết hạn sử dụng, thu hồi giấy phép hoạt động đối với phòng khám của bà H.", "Phạt tiền, và buộc tiêu hủy toàn bộ số thuốc hết hạn sử dụng và thu hồi chứng chỉ hành nghề vĩnh viễn đối với bà H."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D20-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22,23,24\nNước X và Y kí kết với nhau hiệp định đầu tư, theo đó nhà đầu tư của nước X và nước Y được hưởng những quyền lợi, ưu đãi và thực hiện những nghĩa vụ trên lãnh thổ của nhau như các nhà đầu tư trong nước mình, không có sự phân biệt đối xử nào. Tuy nhiên, nước X sau đó ban hành luật trái với hiệp định đã kí kết, trong đó hạn chế một số ưu đãi của nhà đầu tư nước Y trên lãnh thổ của mình.\nNhà đầu tư của nước X và nước Y được hưởng những quyền lợi, ưu đãi và thực hiện những nghĩa vụ trên lãnh thổ của nhau như các nhà đầu tư trong nước mình, không có sự phân biệt đối xử nào là thể hiện chế độ", "o": ["đối xử tối huệ quốc.", "đối xử đặc biệt.", "đối xử quốc gia.", "đối xử qua lại."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D20-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22,23,24\nNước X và Y kí kết với nhau hiệp định đầu tư, theo đó nhà đầu tư của nước X và nước Y được hưởng những quyền lợi, ưu đãi và thực hiện những nghĩa vụ trên lãnh thổ của nhau như các nhà đầu tư trong nước mình, không có sự phân biệt đối xử nào. Tuy nhiên, nước X sau đó ban hành luật trái với hiệp định đã kí kết, trong đó hạn chế một số ưu đãi của nhà đầu tư nước Y trên lãnh thổ của mình.\nHiệp định đầu tư giữa nước X và nước Y là thể hiện hình thức hội nhập kinh tế quốc tế", "o": ["song phương.", "khu vực.", "toàn cầu.", "toàn diện."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D20-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22,23,24\nNước X và Y kí kết với nhau hiệp định đầu tư, theo đó nhà đầu tư của nước X và nước Y được hưởng những quyền lợi, ưu đãi và thực hiện những nghĩa vụ trên lãnh thổ của nhau như các nhà đầu tư trong nước mình, không có sự phân biệt đối xử nào. Tuy nhiên, nước X sau đó ban hành luật trái với hiệp định đã kí kết, trong đó hạn chế một số ưu đãi của nhà đầu tư nước Y trên lãnh thổ của mình.\nNước X ban hành luật trái với hiệp định đã ký kết là vi phạm nguyên tắc nào dưới đây của pháp luật quốc tế?", "o": ["Nguyên tắc bình đẳng về chủ quyền các nước.", "Nguyên tắc tận tâm, thiện chí thực hiện cam kết.", "Nguyên tắc giải quyết bằng biện pháp hòa bình.", "Nguyên tắc không can thiệp công việc nội bộ."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D20-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Hiệp định thương mại tự do Việt Nam – Hàn Quốc (VKFTA) được ký kết ngày 5/5/2015 và chính thức có hiệu lực từ ngày 20/12/2015, hiệp định đã mở ra cơ hội thu hút vốn đầu tư nước ngoài từ các doanh nghiệp Hàn Quốc vào Việt Nam. Tính đến nay công ty S đã đầu tư Việt Nam đạt khoảng trên 17 tỷ USD, hàng năm tạo ra trên 170.000 việc làm với mức thu nhập ổn định. Đến nay, công ty S đã xuất khẩu 54,4 tỷ USD, chiếm 25,4% kim ngạch xuất khẩu của cả nước. Bên cạnh đó công ty S luôn chú trọng đến yếu tố con người, ngoài những quy định liên quan đến vấn đề nghỉ ngơi xen kẽ giờ làm việc cho toàn thể nhân viên, công ty S còn đưa ra giải pháp đó là, trong 8 tiếng làm việc chính thức của nhân viên, cứ sau 2 giờ, những nhân viên làm việc trực tiếp tại xưởng sản xuất lại có 10 phút giải lao tại xưởng. Thời gian nghỉ để ăn giữa ca là 60 phút, hàng năm tất cả các nhân viên đều được tham gia chương trình khám sức khỏe tổng quát định kỳ.", "o": ["Hiệp định thương mại tự do Việt Nam – Hàn Quốc là biểu hiện của hình thức hợp tác song phương.", "Đầu tư trực tiếp nước ngoài FDI diễn ra ở cả hình thức hợp tác song phương, khu vực và toàn cầu.", "Công ty S coi trọng yếu tố con người trong phát triển là phù hợp với trách nhiệm đạo đức của doanh nghiệp.", "Công ty S đã thực hiện tốt quyền của công dân trong bảo vệ và chăm sóc sức khỏe."], "a": [true, false, true, false], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần II câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D20-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Nhận thấy nhu cầu về sử dụng rau rạch của người dân ngày càng tăng, chị B quyết định nghỉ việc tại công ty để tiến hành hoạt động kinh doanh rau sạch. Từ số tiền tiết kiệm của chị B và thế chấp ngôi nhà đang ở, mở một cửa hàng ngay tại thị trấn. Với phương châm đặt chất lượng lên hàng đầu, luôn cam kết với khách hàng về chất lượng sản phẩm vì vậy chỉ sau 2 năm đi vào hoạt động, cửa hàng của chị B đã có một lượng khách hàng lớn tin tưởng và thường xuyên sử dụng sản phẩm do cửa hàng cung cấp. Lợi nhuận có được từ việc kinh doanh, ngoài việc trang trải chi phí sinh hoạt cho bản thân và gia đình, chị B còn tích cực tài trợ cho các hoạt động thiện nguyện giúp đỡ các học sinh có hoàn cảnh khó khăn. Để có nguồn nguyên liệu an toàn và ổn định, chị đã hướng dẫn cho bà con nông dân quy trình sản xuất rau sạch và cam kết bao tiêu sản phẩm nhờ đó không chỉ mang lại hiệu quả kinh doanh cho cửa hàng mà còn góp phần giải quyết nhiều việc làm cho lao động nông thôn.", "o": ["Phương châm đặt chất lượng sản phẩm lên hàng đầu, luôn cam kết với khách hàng về chất lượng sản phẩm là thể hiện việc phân tích các điều kiện kinh doanh.", "Cửa hàng kinh doanh của chị B ngày càng hoạt động hiệu quả có nguyên nhân chủ quan là chị luôn thực hiện tốt trách nhiệm kinh doanh.", "Việc chị B giúp đỡ các học sinh có hoàn cảnh có khó khăn trong học tập là phù hợp với trách nhiệm pháp lý của mỗi doanh nghiệp.", "Đánh giá đúng về yếu tố khách hàng và thị trường là yếu tố giúp chị B kinh doanh thành công."], "a": [false, true, false, true], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần II câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D20-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Trên cùng địa bàn một huyện có anh D là chủ doanh nghiệp kinh doanh thức ăn chăn nuôi; anh K là giám đốc một công ty tư nhân. Để tăng vốn kinh doanh, anh K chỉ đạo chị P là kế toán kê khai không đầy đủ số tiền thuế phải nộp của công ty nên anh K đã bị cơ quan chức năng xử phạt. Nghi ngờ anh V là nhân viên tố cáo hành vi của mình, anh K cố tình trì hoãn đóng bảo hiểm xã hội cho anh V như đã cam kết. Bức xúc, anh V tự ý nghỉ việc ở công ty của anh K và sang làm việc cho anh D. Một lần chứng kiến anh D bị cơ quan chức năng xử phạt về hành vi cung cấp sản phẩm không đảm bảo đúng tiêu chuẩn đã công bố, anh V đã kể lại sự việc cho vợ mình là chị T. Sau đó chị T đã viết bài đăng lên mạng xã hội vu khống công ty anh D vi phạm Luật lao động không tổ chức khám sức khỏe định kỳ cho công nhân khiến uy tín của công ty bị ảnh hưởng.", "o": ["Anh D và anh K đều phải chịu trách nhiệm pháp lý về hành vi vi phạm của mình trong kinh doanh.", "Anh D cung cấp sản phẩm không đảm bảo đúng tiêu chuẩn đã công bố là vi phạm trách nhiệm xã hội về pháp lý và kinh tế.", "Hành vi cố tình không đóng bảo hiểm xã hội của anh K cho anh V là vi phạm quyền của công dân về đảm bảo an sinh xã hội.", "Chị P không vi phạm nghĩa vụ của công dân trong việc thực hiện pháp luật về thuế."], "a": [true, true, true, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần II câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}, {"id": "TN-D20-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Nước T và nước V đã ký kết hiệp định thương mại từ nhiều năm trước và cả hai nước đều là thành viên của tổ chức thương mại thế giới (WTO). Trong một lần tàu X là tàu thương mại của nước T đi qua lãnh hải của nước V không phải xin phép, trên cơ sở quyền qua lại vô hại. Đang đi theo tuyến hành lang mà nước V ấn định cho tàu thuyền nước ngoài, tàu X bỗng thay đổi hành trình, không đi theo tuyến đường ấn định nữa. Tại một khu vực khác trong lãnh hải nước V, tàu X dừng lại, chuyển xăng dầu buôn lậu từ tàu của mình sang hai tàu khác. Lực lượng cảnh sát biển nước P đã đuổi theo, bắt giữ tàu X cùng toàn bộ thuỷ thủ trên tàu. Tàu X được đưa vào bờ biển nước P để Xử lí vi phạm.", "o": ["Chỉ các nước có ký hiệp định thương mại với nhau thì tàu thuyền thương mại của hai nước này mới được đi vào khu vực lãnh hải của nhau.", "Việc bắt giữ tàu X cùng toàn bộ thủy thủ tàu là phù hợp với quyền chủ quyền của quốc gia ven biển.", "Hiệp định thương mại giữa nước T và nước V không phải là căn cứ để giải quyết vấn đề xâm phạm chủ quyền quốc gia giữa nước T và nước V.", "Nước T có quyền khởi kiện lên tổ chức WTO để kiện nước V về hành vi bắt giữ tàu thương mại đã vi phạm nguyên tắc tự do hóa thương mại của WTO."], "a": [false, false, true, false], "e": "Đáp án: a) Sai; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần II câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN · đã rà 16/11/2026 (cùng đề «học kì II» lớp 12)"}]}, {"id": "TN-D21", "loai": "tn", "khoi": 12, "hoc_ki": 2, "so_de": 21, "ten": "Đề luyện thi tốt nghiệp số 21", "pham_vi": "Đề nguồn của giáo viên, giữ NGUYÊN chữ của đề (chỉ bỏ lỗi sao chép) · mã 2324, Lâm Đồng (thi thử tốt nghiệp 2025; chuyển từ danh sách HSG) · file nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm 4 lựa chọn + 4 câu đúng/sai (mỗi câu 4 ý)", "cham": {"tong": 10, "tn": 0.25, "ds": [0, 0.1, 0.25, 0.5, 1.0]}, "status": "cho_duyet", "khoa": {"đã giải lại, khớp khoá": 28}, "sua": "Bỏ dòng dẫn nguồn web («Theo https://…») dính cuối đoạn thông tin ở 2 câu (lỗi sao chép; chữ còn lại giữ nguyên). CẦN CÔ XEM (em chưa chắc, KHÔNG sửa khoá): (1) Câu 24 (hành vi dùng chất cấm của công ty X phải chịu trách nhiệm pháp lý nào theo pháp luật Việt Nam): khoá B «bồi thường toàn bộ thiệt hại cho đối tác»; phương án C «xử phạt hành chính, đình chỉ hoạt động, thu hồi giấy phép» cũng có thể được coi là đúng — em chưa chắc, giữ khoá.", "cau": [{"id": "TN-D21-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với tài chính của gia đình, khoản tiền nhằm để phục vụ cho các mối quan hệ xã hội và mua sắm xa xỉ được gọi là khoản chi", "o": ["dự phòng.", "thiết yếu.", "không thiết yếu.", "rất thiết yếu."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx · Phần I câu 1 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D21-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trên thị trường, khi giá cả của một mặt hàng tăng lên, điều gì thường xảy ra với lượng cung của mặt hàng đó?", "o": ["Lượng cung tăng.", "Lượng cung giảm.", "Lượng cung không đổi.", "Lượng cung không xác định."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx · Phần I câu 2 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D21-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công dân không thực hiện các hành vi bị pháp luật cấm là hình thức", "o": ["tuân thủ pháp luật.", "sử dụng pháp luật.", "thi hành pháp luật.", "áp dụng pháp luật."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx · Phần I câu 3 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D21-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của Công pháp quốc tế, lãnh thổ quốc gia được giới hạn bởi các đường biên giới nào sau đây?", "o": ["Biên giới trên bộ, trên biển, trên không và đại dương.", "Biên giới trên bộ, trên biển, trên không và đất liền.", "Biên giới trên bộ, trên biển, trên không và lòng đất.", "Biên giới trên bộ, trên biển, trên không và hải đảo."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx · Phần I câu 4 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D21-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đâu là hoạt động kinh tế mà trong đó hàng hóa, dịch vụ được chuyển từ người sản xuất đến người tiêu dùng?", "o": ["Sản xuất.", "Trao đổi.", "Tiêu dùng.", "Phân phối."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx · Phần I câu 5 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D21-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Năng lực nào được thể hiện khi người kinh doanh biết cách tổ chức, sắp xếp công việc một cách khoa học và hiệu quả?", "o": ["Năng lực quản lý.", "Năng lực lãnh đạo.", "Năng lực học tập.", "Năng lực chuyên môn."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx · Phần I câu 6 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D21-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, công dân thực hiện quyền tham gia quản lý nhà nước và xã hội thông qua hình thức nào sau đây?", "o": ["Tự ý xây dựng công trình công cộng.", "Tự do xuất cảnh không cần giấy tờ.", "Tự do kinh doanh mọi ngành nghề.", "Tham gia ý kiến vào các dự thảo luật."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx · Phần I câu 7 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D21-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hiến pháp là cơ sở để xây dựng và ban hành các văn bản quy phạm pháp luật khác. Điều này thể hiện đặc điểm nào của Hiến pháp?", "o": ["Hiến pháp là đạo luật cơ bản của Nhà nước.", "Hiến pháp có hiệu lực pháp lí lâu dài.", "Hiến pháp có tính ổn định bền vững.", "Hiến pháp có quy trình sửa đổi đặc biệt."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx · Phần I câu 8 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D21-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Pháp luật quy định về quyền của công dân trong học tập thể hiện ở việc công dân được", "o": ["cung cấp đầy đủ thông tin về việc học tập, rèn luyện.", "cung cấp miễn phí mọi dịch vụ hỗ trợ hoạt động giáo dục.", "tự do vui chơi, nghỉ ngơi, giải trí, rèn luyện thân thể.", "tùy ý học ở bất cứ trường đại học nào theo sở thích."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx · Phần I câu 9 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D21-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với mỗi quốc gia, yếu tố nào dưới đây là chỉ tiêu của phát triển kinh tế?", "o": ["Tổng thu nhập quốc dân.", "Tổng sản phẩm quốc nội.", "Chuyển dịch vùng sản xuất.", "Tiến bộ xã hội."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx · Phần I câu 10 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D21-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc nam và nữ được hưởng mức lương ngang nhau cho cùng một công việc là biểu hiện của bình đẳng giới trong lĩnh vực nào?", "o": ["Văn hóa.", "Chính trị.", "Lao động.", "Giáo dục."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx · Phần I câu 11 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D21-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mô hình kinh doanh nào do một cá nhân làm chủ, tự chịu trách nhiệm bằng toàn bộ tài sản của mình về hoạt động của doanh nghiệp?", "o": ["Công ty hợp danh.", "Hợp tác xã.", "Hộ kinh doanh.", "Doanh nghiệp tư nhân."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx · Phần I câu 12 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D21-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Loại thất nghiệp nào dưới đây xảy ra khi người lao động tự nguyện không làm việc để tìm kiếm công việc phù hợp hơn với năng lực và sở thích của mình?", "o": ["Thất nghiệp chu kỳ.", "Thất nghiệp tạm thời.", "Thất nghiệp cơ cấu.", "Thất nghiệp tự nguyện."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx · Phần I câu 13 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D21-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Ông M sở hữu trang trại trồng cây ăn quả. Ngoài việc tự mình canh tác, ông M còn cho một số hộ gia đình khác thuê đất để trồng rau màu. Ông M đã mang tài sản của mình đi thế chấp tại ngân hàng để vay vốn mở rộng sản xuất. Việc ông M có quyền cho thuê, thế chấp tài sản thuộc quyền nào sau đây?", "o": ["Định đoạt tài sản.", "Chiếm hữu tài sản.", "Bảo quản tài sản.", "Sử dụng tài sản."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx · Phần I câu 14 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D21-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, người có hành vi cố ý gây thương tích cho người khác với tỷ lệ tổn thương cơ thể 15% phải chịu trách nhiệm pháp lý nào sau đây?", "o": ["Cải tạo không giam giữ đến 02 năm.", "Cảnh cáo, nhắc nhở trước cơ quan, tổ chức.", "Phạt tù từ 06 tháng đến 03 năm.", "Phạt tiền từ 5.000.000đ đến 10.000.000đ."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx · Phần I câu 15 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D21-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 16, 17\nTheo số liệu thống kê trên Cổng thông tin giám định Bảo hiểm y tế từ ngày 01/01/2021 đến ngày 02/7/2021, cả nước có 75,58 triệu lượt khám, chữa bệnh với số tiền đề nghị cơ quan Bảo hiểm xã hội thanh toán là trên 48.774 tỉ đồng. Trong đó có hơn 68,6 triệu lượt khám, chữa bệnh ngoại trú với số tiền đề nghị thanh toán trên 18.740 tỉ đồng; gần 7 triệu lượt khám, chữa bệnh nội trú với số tiền đề nghị thanh toán trên 30.033 tỉ đồng.\nĐoạn thông tin đề cập đến quyền lợi nào của người tham gia bảo hiểm y tế?", "o": ["Được trợ cấp trong thời gian điều trị bệnh.", "Được miễn đóng phí bảo hiểm y tế.", "Được nghỉ phép trong thời gian điều trị bệnh.", "Được chi trả chi phí khám và điều trị bệnh."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx · Phần I câu 16 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D21-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 16, 17\nTheo số liệu thống kê trên Cổng thông tin giám định Bảo hiểm y tế từ ngày 01/01/2021 đến ngày 02/7/2021, cả nước có 75,58 triệu lượt khám, chữa bệnh với số tiền đề nghị cơ quan Bảo hiểm xã hội thanh toán là trên 48.774 tỉ đồng. Trong đó có hơn 68,6 triệu lượt khám, chữa bệnh ngoại trú với số tiền đề nghị thanh toán trên 18.740 tỉ đồng; gần 7 triệu lượt khám, chữa bệnh nội trú với số tiền đề nghị thanh toán trên 30.033 tỉ đồng.\nVới số tiền thanh toán hơn 48 nghìn tỉ đồng là thể hiện người dân đang được thụ hưởng chính sách an sinh xã hội nào sau đây?", "o": ["Chính sách hỗ trợ việc làm.", "Chính sách trợ giúp xã hội.", "Chính sách hỗ trợ thu nhập.", "Chính sách về bảo hiểm."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx · Phần I câu 17 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D21-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, việc làm nào sau đây của công dân không đúng khi thực hiện quyền bầu cử?", "o": ["Ông M bỏ phiếu thay vợ vì vợ đang điều trị tại bệnh viện.", "Chị V chủ động tìm hiểu các ứng cử viên để viết phiếu bầu.", "Anh Y viết hộ phiếu bầu cho cụ X vì cụ không biết chữ.", "Anh S tự bỏ phiếu bầu của mình vào hòm phiếu."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx · Phần I câu 18 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D21-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi tiến hành xây dựng ý tưởng kinh doanh, các chủ thể không cần quan tâm đến yếu tố nào sau đây?", "o": ["Tính ôn hòa.", "Tính khả thi.", "Tính sáng tạo.", "Tính lợi nhuận."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx · Phần I câu 19 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D21-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, công dân có quyền được bảo vệ, chăm sóc sức khỏe; được bình đẳng trong khám bệnh, chữa bệnh; được", "o": ["tiếp cận với thông tin y tế.", "tự do thay đổi phác đồ điều trị.", "mượn thẻ bảo hiểm để khám bệnh.", "kinh doanh mọi hàng hóa."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx · Phần I câu 20 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D21-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Kế hoạch kinh doanh không bao gồm bước cơ bản nào sau đây?", "o": ["Xác định chiến lược kinh doanh.", "Xác định ý tưởng kinh doanh.", "Xác định mục tiêu kinh doanh.", "Xác định lí tưởng kinh doanh."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx · Phần I câu 21 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D21-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22, 23, 24\nTheo Báo cáo tình hình xuất nhập khẩu Việt Nam năm 2023 của Tổng cục Thống kê, ngành thủy sản Việt Nam đã đạt kim ngạch xuất khẩu 10 tỷ đô la Mỹ, tăng 10% so với năm 2022. Tuy nhiên, Công ty X đã bị phát hiện sử dụng chất cấm trong sản phẩm tôm xuất khẩu sang thị trường Nhật Bản. Cơ quan chức năng Nhật Bản đã yêu cầu công ty X thu hồi toàn bộ sản phẩm và bồi thường thiệt hại. Công ty X ban đầu từ chối, cho rằng việc sử dụng chất cấm là do lỗi của nhà cung cấp thức ăn. Nguồn: Báo cáo tình hình xuất nhập khẩu Việt Nam năm 2023 của Tổng cục Thống kê (trang 25-26).\nNếu Công ty X và đối tác Nhật Bản không đạt được thỏa thuận về việc bồi thường, họ có thể giải quyết tranh chấp thông qua hình thức nào dưới đây?", "o": ["Khởi kiện tại tòa án hoặc trọng tài thương mại quốc tế.", "Tổ chức họp báo công khai thông tin về tranh chấp.", "Yêu cầu cơ quan đại diện ngoại giao can thiệp.", "Khiếu nại lên cơ quan quản lý thị trường."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx · Phần I câu 22 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D21-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22, 23, 24\nTheo Báo cáo tình hình xuất nhập khẩu Việt Nam năm 2023 của Tổng cục Thống kê, ngành thủy sản Việt Nam đã đạt kim ngạch xuất khẩu 10 tỷ đô la Mỹ, tăng 10% so với năm 2022. Tuy nhiên, Công ty X đã bị phát hiện sử dụng chất cấm trong sản phẩm tôm xuất khẩu sang thị trường Nhật Bản. Cơ quan chức năng Nhật Bản đã yêu cầu công ty X thu hồi toàn bộ sản phẩm và bồi thường thiệt hại. Công ty X ban đầu từ chối, cho rằng việc sử dụng chất cấm là do lỗi của nhà cung cấp thức ăn. Nguồn: Báo cáo tình hình xuất nhập khẩu Việt Nam năm 2023 của Tổng cục Thống kê (trang 25-26).\nTrong thông tin trên đã không đề cập đến lợi ích nào sau đây cho các doanh nghiệp thủy sản Việt Nam?", "o": ["Đạt kim ngạch xuất khẩu 10 tỷ đô la Mỹ trong năm 2023.", "Mở rộng thị trường xuất khẩu và tăng kim ngạch xuất khẩu.", "Tạo nhiều việc làm, nâng cao thu nhập cho người lao động.", "Tăng trưởng kim ngạch xuất khẩu 10% so với năm 2022."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx · Phần I câu 23 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D21-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22, 23, 24\nTheo Báo cáo tình hình xuất nhập khẩu Việt Nam năm 2023 của Tổng cục Thống kê, ngành thủy sản Việt Nam đã đạt kim ngạch xuất khẩu 10 tỷ đô la Mỹ, tăng 10% so với năm 2022. Tuy nhiên, Công ty X đã bị phát hiện sử dụng chất cấm trong sản phẩm tôm xuất khẩu sang thị trường Nhật Bản. Cơ quan chức năng Nhật Bản đã yêu cầu công ty X thu hồi toàn bộ sản phẩm và bồi thường thiệt hại. Công ty X ban đầu từ chối, cho rằng việc sử dụng chất cấm là do lỗi của nhà cung cấp thức ăn. Nguồn: Báo cáo tình hình xuất nhập khẩu Việt Nam năm 2023 của Tổng cục Thống kê (trang 25-26).\nTheo quy định của pháp luật Việt Nam, hành vi vi phạm của Công ty X phải chịu trách nhiệm pháp lý nào sau đây?", "o": ["Yêu cầu nhà cung cấp thức ăn bồi thường thiệt hại cho Công ty X.", "Công ty X phải bồi thường toàn bộ thiệt hại cho đối tác theo quy định", "Xử phạt hành chính, đình chỉ hoạt động sản xuất và thu hồi giấy phép kinh doanh.", "Công ty X chỉ cần tạm ngừng xuất khẩu tôm sang thị trường Nhật Bản."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx · Phần I câu 24 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D21-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc thông tin sau: “Năm 2022, Việt Nam và Vương quốc Anh (UK) ký kết Hiệp định Thương mại Tự do Việt Nam - Vương quốc Anh (UKVFTA). Tháng 10/2023, UK thông báo áp dụng Cơ chế Điều chỉnh Biên giới Carbon (CBAM) đối với hàng hóa nhập khẩu, bắt đầu từ năm 2027. Theo đó, các doanh nghiệp xuất khẩu hàng hóa sang UK phải báo cáo lượng khí thải carbon phát sinh trong quá trình sản xuất. CBAM được áp dụng cho 500 sản phẩm thuộc nhóm sản phẩm có nguy cơ rò rỉ carbon cao. Nhận thức được tác động của CBAM, Công ty X đã đầu tư vào công nghệ sản xuất xanh và giảm phát thải carbon”. (Nguồn: Thông tin từ Bộ Công Thương Việt Nam và Chính phủ Vương quốc Anh về UKVFTA và CBAM).", "o": ["Hiệp định UKVFTA thể hiện hình thức hội nhập đa phương.", "Việc đầu tư vào công nghệ sản xuất xanh thể hiện trách nhiệm nhân văn của doanh nghiệp X.", "Công ty X cần xây dựng lộ trình giảm phát thải carbon để đáp ứng yêu cầu của CBAM.", "Đến năm 2027, tất cả hàng hóa của Việt Nam xuất khẩu sang UK đều phải chịu thuế carbon."], "a": [false, false, true, false], "e": "Đáp án: a) Sai; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx · Phần II câu 1 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D21-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc thông tin sau: Ngày 30/11/2023, tàu cá CM do ông Q làm thuyền trưởng, trên tàu có 6 thuyền viên, làm thủ tục xuất bến qua Trạm Kiểm soát Biên phòng đảm bảo thủ tục, giấy tờ theo quy định. Khi ra biển hoạt động, ông Q giao cho ông S (thuyền viên trên tàu) làm thuyền trưởng (nhưng ông S không có văn bằng, chứng chỉ thuyền trưởng), sau đó, ông Q quay vào bờ. Trong thời gian đánh bắt hải sản trên vùng biển giáp ranh giữa nước V và nước T, do hoạt động khai thác kém hiệu quả, ngày 15/12/2023, ông S gọi điện cho ông Q hỏi ý kiến về việc sẽ đưa tàu cá sang vùng lãnh hải của nước T để khai thác hải sản và được sự cho phép của ông Q. Ngày 16/12/2023, khi tàu CM đang khai thác hải sản ở vùng lãnh hải nước T thì bị lực lượng chức năng nước T kiểm tra, bắt giữ. Tại Đồn Biên phòng, ông Q thừa nhận là người trực tiếp quản lý, chỉ đạo điều hành mọi hoạt động của tàu cá CM và đã đồng ý cho ông S đưa tàu cá CM sang vùng lãnh hải nước T khai thác thủy sản trái phép.", "o": ["Trong trường hợp tàu CM bị lực lượng chức năng nước T bắt giữ, nước V có thể yêu cầu trả lại tàu và thuyền viên ngay lập tức để nước V xử lý mà không cần đàm phán.", "Theo Công ước Liên Hợp Quốc về Luật Biển năm 1982 (UNCLOS 1982), khi một tàu cá vi phạm vùng biển của quốc gia khác, quốc gia đó có quyền bắt giữ và xử lý theo luật pháp của họ.", "Hành vi của tàu cá CM là vi phạm quyền chủ quyền quốc gia của nước T.", "Nếu tàu CM không đánh bắt hải sản, chỉ đi qua không gây hại trong vùng lãnh hải của nước T mà không xin phép thì không vi phạm về chủ quyền của nước T."], "a": [false, true, false, true], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx · Phần II câu 2 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D21-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc thông tin sau: Từ ngày 17 đến 18/10/2024, Bảo hiểm xã hội Việt Nam phối hợp các địa phương, nhà tài trợ, đặc biệt là 4 ngân hàng: Nông nghiệp và Phát triển nông thôn Việt Nam, TMCP Đầu tư và phát triển Việt Nam, TMCP Ngoại thương Việt Nam, TMCP Công thương Việt Nam tổ chức trao tặng 1.202 sổ bảo hiểm xã hội, 9.260 thẻ bảo hiểm y tế đến tận tay người dân có hoàn cảnh khó khăn bị ảnh hưởng bởi bão số 3 (bão Yagi). Đây là hoạt động đặc biệt nhằm phát huy truyền thống đoàn kết, “tương thân, tương ái”, “lá lành đùm lá rách” của người Việt Nam. Chương trình trao tặng này triển khai tại 26 tỉnh, thành phố bị ảnh hưởng của bão số 3, với tổng kinh phí gần 16 tỷ đồng. Đồng thời, Bảo hiểm xã hội Việt Nam cũng trao 350 triệu đồng ủng hộ đồng bào bị thiệt hại bởi bão số 3 tới Ủy ban Trung ương Mặt trận Tổ quốc Việt Nam.", "o": ["Các chính sách trên đã giúp người dân bị ảnh hưởng bão số 3 sớm vượt qua khó khăn, ổn định cuộc sống.", "Việc Bảo hiểm xã hội Việt Nam trao 350 triệu đồng ủng hộ đồng bào bị thiệt hại bởi bão số 3 là thực hiện chính sách hỗ trợ việc làm, thu nhập và giảm nghèo.", "Thông tin trên đã cho thấy nguyên tắc ai cũng được quyền hưởng và được đảm bảo an sinh xã hội.", "Thông tin trên đã nhắc tới chính sách bảo hiểm và trợ giúp xã hội trong hệ thống an sinh xã hội."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx · Phần II câu 3 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D21-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc thông tin sau: Trong những năm qua, sản xuất và xuất khẩu nông sản đã tạo nên những dấu ấn quan trọng, giúp khẳng định vị thế của Việt Nam trên bản đồ xuất khẩu nông sản thế giới. Nếu năm 2010, các mặt hàng nông sản chính được xuất khẩu đến 72 quốc gia và vùng lãnh thổ, thì đến năm 2020 đã được xuất khẩu đến 180 quốc gia, vùng lãnh thổ. Trong đó, hai thị trường xuất khẩu nông sản lớn nhất của Việt Nam là Hoa Kỳ (chiếm 27,46% tổng giá trị xuất khẩu năm 2020) và Trung Quốc (chiếu 20,9%). Cùng thời gian này, Việt Nam còn xuất khẩu nông sản sang các thị trường đối tác lớn khác như EU (9,15%), ASEAN (8,58%), Nhật Bản (8,34%), Hàn Quốc (5,02%), Anh (2%), Úc (1,68%), Canada (1,62%). (Nguồn: Giải pháp xuất khẩu bền vững cho nông sản Việt Nam, Tạp chí Công Thương, 2022)", "o": ["Dịch vụ thu ngoại tệ của Việt Nam tăng đáng kể thông qua việc xuất khẩu nông sản từ năm 2010 đến năm 2020.", "Năm 2020 Việt Nam xuất khẩu nông sản đến 180 quốc gia, vùng lãnh thổ thể hiện hình thức đầu tư quốc tế.", "Trung Quốc và Hoa Kỳ là hai thị trường xuất khẩu nông sản lớn nhất của Việt Nam.", "Từ năm 2010 đến 2020, tăng thêm 108 quốc gia, vùng lãnh thổ nhập khẩu nông sản của Việt Nam."], "a": [false, false, true, true], "e": "Đáp án: a) Sai; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 2324 - LÂM ĐỒNG (mã 2324).docx · Phần II câu 4 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}]}, {"id": "TN-D22", "loai": "tn", "khoi": 12, "hoc_ki": 2, "so_de": 22, "ten": "Đề luyện thi tốt nghiệp số 22", "pham_vi": "Đề nguồn của giáo viên, giữ NGUYÊN chữ của đề (chỉ bỏ lỗi sao chép) · mã 7043, Hải Dương (thi thử tốt nghiệp 2025; chuyển từ danh sách HSG) · file nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm 4 lựa chọn + 4 câu đúng/sai (mỗi câu 4 ý)", "cham": {"tong": 10, "tn": 0.25, "ds": [0, 0.1, 0.25, 0.5, 1.0]}, "status": "cho_duyet", "khoa": {"đã giải lại, khớp khoá": 28}, "sua": "Đề này từng nằm trong danh sách HSG (HSG-07); ghi chú khi rà: Sửa lỗi sao chép: câu 21 phương án A bị tách nhầm vào đề bài (và dính chữ «Mã đề thi 7043»); em trả phương án A về đúng chỗ, giữ nguyên chữ. Bỏ dòng dẫn nguồn web («Theo https://…») dính cuối đoạn thông tin ở 4 câu (lỗi sao chép; chữ còn lại giữ nguyên). CẦN CÔ XEM (em chưa chắc, KHÔNG sửa khoá): (1) Câu đúng/sai 4 ý b («quán cà phê doanh thu 135 triệu đồng/năm nên không phải nộp thuế»): khoá Sai theo ngưỡng miễn thuế hộ kinh doanh của đề (2025); ngưỡng này đã thay đổi theo luật thuế mới (2025–2026), em chưa tra văn bản gốc nên cô đối chiếu trước khi dùng.", "cau": [{"id": "TN-D22-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, người nộp thuế có quyền nào dưới đây?", "o": ["Nộp thuế đầy đủ, đúng hạn.", "Kê khai chính xác, trung thực.", "Hưởng các ưu đãi về thuế.", "Chấp hành chế độ kế toán."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx · Phần I câu 1 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D22-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những nguyên nhân dẫn đến hiện tượng cạnh tranh giữa các chủ thể kinh tế là do có sự khác nhau về", "o": ["nguồn gốc nhân thân.", "quan hệ tài sản.", "giá trị thặng dư.", "điều kiện sản xuất."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx · Phần I câu 2 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D22-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào dưới đây là sai về các yêu cầu khi lập kế hoạch thu, chi trong gia đình?", "o": ["Ưu tiên cắt giảm các khoản chi tiêu thiết yếu.", "Xác định được mục tiêu tài chính.", "Thường xuyên kiểm tra ngân sách và thu nhập.", "Bỏ thói quen chi tiêu không hợp lý."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx · Phần I câu 3 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D22-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Loại hình bảo hiểm do Nhà nước tổ chức mà người tham gia được lựa chọn mức đóng, phương thức đóng phù hợp với mức thu nhập của mình và Nhà nước có chính sách hỗ trợ tiền đóng để người tham gia hưởng chế độ hưu trí và tử tuất là loại hình bảo hiểm", "o": ["xã hội bắt buộc.", "y tế tự nguyện.", "xã hội tự nguyện.", "y tế bắt buộc."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx · Phần I câu 4 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D22-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật hiện hành, người có hành vi có tổ chức bắt, giữ hoặc giam người khác trái pháp luật phải chịu trách nhiệm pháp lý nào sau đây?", "o": ["Phạt tù từ 05 năm đến 12 năm.", "Phạt tiền từ 2000.000 đồng đến 5000.000 đồng.", "Phạt tù từ 02 năm đến 07 năm.", "Cải tạo không giam giữ từ 18 tháng đến 36 tháng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx · Phần I câu 5 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D22-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quá trình một quốc gia thực hiện gắn kết nền kinh tế của mình với nền kinh tế các quốc gia khác trong khu vực và trên thế giới trên cơ sở cùng có lợi và tuân thủ quy định chung là nội dung của khái niệm nào dưới đây?", "o": ["Thương mại quốc tế.", "Hội nhập kinh tế quốc tế.", "Tăng trưởng kinh tế.", "Phát triển kinh tế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx · Phần I câu 6 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D22-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mô hình sản xuất kinh doanh nào dưới đây mà các cổ đông tham gia hoạt động chịu trách nhiệm về các khoản nợ và nghĩa vụ tài sản của doanh nghiệp trong phạm vi số vốn đã góp vào doanh nghiệp?", "o": ["Hộ sản xuất kinh doanh.", "Công ty cổ phần.", "Công ty tư nhân.", "Công ty nhà nước."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx · Phần I câu 7 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D22-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Xét về mặt cơ cấu tổ chức, bộ máy nhà nước Cộng hòa xã hội chủ nghĩa Việt Nam không bao gồm cơ quan, tổ chức nào sau đây ?", "o": ["Ủy ban nhân dân.", "Hội chữ thập đỏ.", "Chính phủ.", "Quốc hội."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx · Phần I câu 8 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D22-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những đặc điểm của Hiến pháp nước Cộng hòa xã hội chủ nghĩa Việt Nam là", "o": ["không bao giờ thay đổi.", "luật cụ thể của nhà nước.", "luật cơ bản của nhà nước.", "có tính tạm thời."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx · Phần I câu 9 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D22-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hoạt động tạo ra thu nhập và không bị pháp luật cấm, có ý nghĩa quan trọng đối với mỗi người, giúp duy trì và cải thiện cuộc sống là nội dung của khái niệm nào sau đây?", "o": ["Lao động.", "Việc làm.", "Học tập.", "Ngành nghề."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx · Phần I câu 10 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D22-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong nền kinh tế hàng hóa, chủ thể nào dưới đây là các cá nhân, tổ chức đóng vai trò cầu nối giữa người sản xuất với người tiêu dùng?", "o": ["Trung gian.", "Tiêu dùng.", "Nhà nước.", "Sản xuất."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx · Phần I câu 11 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D22-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không phải là nguyên nhân dẫn đến lạm phát?", "o": ["Cầu có xu hướng tăng lên.", "Lượng hàng hóa tăng.", "Lượng tiền lưu thông tăng.", "Chi phí sản xuất tăng lên."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx · Phần I câu 12 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D22-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi cố ý gây thương tích cho người khác là xâm phạm đến quyền nào sau đây của công dân?", "o": ["Được pháp luật bảo hộ về tính mạng, sức khỏe.", "Được pháp luật bảo hộ về danh dự và nhân phẩm.", "Bất khả xâm phạm về thân thể.", "Bất khả xâm phạm về chỗ ở."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx · Phần I câu 13 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D22-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công dân báo cho cơ quan có thẩm quyền về hành vi vi phạm pháp luật gây thiệt hại đến lợi ích hợp pháp của công dân, tổ chức và cơ quan nhà nước là thực hiện quyền", "o": ["khiếu nại.", "truy tố.", "tố cáo.", "bãi nại."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx · Phần I câu 14 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D22-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tăng trưởng kinh tế là sự gia tăng về quy mô sản lượng của một nền kinh tế", "o": ["trong một thời gian nhất định so với thời kì gốc.", "so với mức tăng trưởng chung của kinh tế thế giới.", "trong nhiều năm, nhiều thập kỉ liên tiếp.", "so với các nền kinh tế khác trên thế giới."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx · Phần I câu 15 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D22-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hằng năm, Nhà nước đã dành hàng trăm nghìn tỷ đồng hỗ trợ cho các đối tượng có thu nhập thấp vay để mua nhà là thể hiện chính sách an sinh xã hội nào dưới đây?", "o": ["Trợ giúp xã hội.", "Bảo hiểm xã hội.", "Việc làm và giảm nghèo.", "Dịch vụ xã hội cơ bản."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx · Phần I câu 16 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D22-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những bước thực hiện xây dựng kế hoạch thu, chi hợp lý ở mỗi gia đình là", "o": ["đảm bảo nhu cầu vật chất và tinh thần đầy đủ.", "xác định các nguồn thu nhập trong gia đình.", "thỏa mãn các nhu cầu của các thành viên.", "đảm bảo môi trường sống có lợi cho gia đình."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx · Phần I câu 17 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D22-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Luật bình đẳng giới năm 2006 quy định, việc nam nữ bình đẳng trong tham gia hoạt động xã hội là nội dung cơ bản về bình đẳng giới trên lĩnh vực", "o": ["kinh tế.", "gia đình.", "chính trị.", "văn hóa."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx · Phần I câu 18 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D22-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong các nguồn giúp tạo ý tưởng kinh doanh dưới đây, yếu tố nào không thuộc về cơ hội bên ngoài của các chủ thể sản xuất kinh doanh?", "o": ["Khả năng huy động các nguồn lực.", "Chính sách vĩ mô của nhà nước.", "Sự cạnh tranh giữa các chủ thể.", "Nhu cầu của thị trường hàng hóa."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx · Phần I câu 19 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D22-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin sau:\nNăm 2019, Quỹ BHYT đã chi trả cho 186 triệu lượt người khám bệnh, chữa bệnh bằng BHYT. Nhiều trường hợp được Quỹ BHYT chi trả chi phí khám, chữa bệnh lên đến hàng tỷ đồng. Cả nước hiện có trên 3,1 triệu người hưởng chế độ hưu trí và trợ cấp BHXH hằng tháng. Quỹ BHXH chi trả các chế độ ốm đau, thai sản, tai nạn lao động, bệnh nghề nghiệp mỗi năm cho từ 6- 10 triệu lượt người.\nViệc có hơn 3,1 triệu người hưởng chế độ hưu trí và trợ cấp BHXH hằng tháng thể hiện vai trò nào dưới đây của an sinh xã hội?", "o": ["Tăng cường sự cạnh tranh giữa các cá nhân trong việc đóng góp vào Quỹ BHXH.", "Bảo đảm đời sống tối thiểu cho người cao tuổi và người không còn khả năng lao động.", "Bảo đảm cho người lao động được tăng lương hưu thông qua mức đóng BHXH cao hơn.", "Khuyến khích người lao động lựa chọn chế độ hưu trí tự nguyện thay vì bắt buộc"], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx · Phần I câu 20 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D22-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin sau:\nNăm 2019, Quỹ BHYT đã chi trả cho 186 triệu lượt người khám bệnh, chữa bệnh bằng BHYT. Nhiều trường hợp được Quỹ BHYT chi trả chi phí khám, chữa bệnh lên đến hàng tỷ đồng. Cả nước hiện có trên 3,1 triệu người hưởng chế độ hưu trí và trợ cấp BHXH hằng tháng. Quỹ BHXH chi trả các chế độ ốm đau, thai sản, tai nạn lao động, bệnh nghề nghiệp mỗi năm cho từ 6- 10 triệu lượt người.\nBảo hiểm y tế mang lại lợi ích nào dưới đây cho người tham gia khi bị ốm đau?", "o": ["Được khám miễn phí suốt đời.", "Được hỗ trợ tiền sau ra viện.", "Lựa chọn dịch vụ chất lượng cao.", "Giảm gánh nặng tài chính gia đình."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx · Phần I câu 21 · khoá: chỉ có ĐÁP ÁN (đề không gạch chân) · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D22-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin sau:\nTính chung thời kì thực hiện Chiến lược phát triển kinh tế xã hội 10 năm (2011 - 2020), tăng trưởng GDP của Việt Nam đạt khoảng 5,9%/năm, thuộc nhóm các nước tăng trưởng cao trong khu vực. Quy mô GDP tăng gấp 2,4 lần, từ 116 tỉ USD năm 2010 lên 268,4 tỉ USD vào năm 2020. GDP bình quân đầu người tăng từ 1.331 USD năm 2010 lên khoảng 2.750 USD năm 2020. Về hoạt động kinh tế đối ngoại với việc ký kết Hiệp định Thương mại tự do giữa Việt Nam và Liên minh châu Âu (EVFTA), Việt Nam đã cơ bản hoàn thành những mục tiêu quan trọng nhất trong Chiến lược đàm phán hiệp định thương mại tự do giai đoạn 2010 - 2020. EVFTA hứa hẹn sẽ tạo ra một thị trường chung rộng lớn cho hàng hóa và dịch vụ giữa Việt Nam và EU, giúp các doanh nghiệp Việt Nam tiếp cận hàng triệu người tiêu dùng châu Âu. Đặc biệt, ngành thủy sản được kỳ vọng sẽ có những bước phát triển vượt bậc nhờ việc giảm thuế quan và các quy định thuận lợi hơn. Tuy nhiên, để tận dụng tối đa lợi ích của hiệp định này, Việt Nam cần vượt qua một thử thách lớn: vấn đề “thẻ vàng” thủy sản. “Thẻ vàng” là một cảnh báo mà Ủy ban châu Âu (EC) đưa ra đối với các quốc gia có hoạt động khai thác thủy sản bất hợp pháp. Điều này đồng nghĩa với việc hải sản Việt Nam xuất khẩu sang EU sẽ phải đối mặt với những kiểm tra nghiêm ngặt hơn.\nTheo quy định của pháp luật Việt Nam, tùy theo tính chất, mức độ của hành vi được coi là khai thác thủy sản bất hợp pháp thì người vi phạm có thể phải chịu trách nhiệm pháp lí nào sau đây?", "o": ["Cấm đi khỏi nơi cư trú và không được hành nghề một tháng.", "Tịch thu toàn bộ phương tiện vi phạm trong vòng một năm.", "Tịch thu giấy phép khai thác thủy sản vĩnh viễn.", "Xử phạt hành chính hoặc truy cứu trách nhiệm hình sự."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx · Phần I câu 22 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D22-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin sau:\nTính chung thời kì thực hiện Chiến lược phát triển kinh tế xã hội 10 năm (2011 - 2020), tăng trưởng GDP của Việt Nam đạt khoảng 5,9%/năm, thuộc nhóm các nước tăng trưởng cao trong khu vực. Quy mô GDP tăng gấp 2,4 lần, từ 116 tỉ USD năm 2010 lên 268,4 tỉ USD vào năm 2020. GDP bình quân đầu người tăng từ 1.331 USD năm 2010 lên khoảng 2.750 USD năm 2020. Về hoạt động kinh tế đối ngoại với việc ký kết Hiệp định Thương mại tự do giữa Việt Nam và Liên minh châu Âu (EVFTA), Việt Nam đã cơ bản hoàn thành những mục tiêu quan trọng nhất trong Chiến lược đàm phán hiệp định thương mại tự do giai đoạn 2010 - 2020. EVFTA hứa hẹn sẽ tạo ra một thị trường chung rộng lớn cho hàng hóa và dịch vụ giữa Việt Nam và EU, giúp các doanh nghiệp Việt Nam tiếp cận hàng triệu người tiêu dùng châu Âu. Đặc biệt, ngành thủy sản được kỳ vọng sẽ có những bước phát triển vượt bậc nhờ việc giảm thuế quan và các quy định thuận lợi hơn. Tuy nhiên, để tận dụng tối đa lợi ích của hiệp định này, Việt Nam cần vượt qua một thử thách lớn: vấn đề “thẻ vàng” thủy sản. “Thẻ vàng” là một cảnh báo mà Ủy ban châu Âu (EC) đưa ra đối với các quốc gia có hoạt động khai thác thủy sản bất hợp pháp. Điều này đồng nghĩa với việc hải sản Việt Nam xuất khẩu sang EU sẽ phải đối mặt với những kiểm tra nghiêm ngặt hơn.\nTrong thông tin trên, hội nhập kinh tế quốc tế đem lại lợi ích nào sau đây cho các doanh nhiệp xuất khẩu thủy sản tại Việt Nam?", "o": ["Có một thị trường chung rộng lớn.", "Xóa bỏ các quy định về thuế quan.", "GDP bình quân đầu người tăng.", "Quy mô GDP tăng gấp 2,4 lần."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx · Phần I câu 23 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D22-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin sau:\nTính chung thời kì thực hiện Chiến lược phát triển kinh tế xã hội 10 năm (2011 - 2020), tăng trưởng GDP của Việt Nam đạt khoảng 5,9%/năm, thuộc nhóm các nước tăng trưởng cao trong khu vực. Quy mô GDP tăng gấp 2,4 lần, từ 116 tỉ USD năm 2010 lên 268,4 tỉ USD vào năm 2020. GDP bình quân đầu người tăng từ 1.331 USD năm 2010 lên khoảng 2.750 USD năm 2020. Về hoạt động kinh tế đối ngoại với việc ký kết Hiệp định Thương mại tự do giữa Việt Nam và Liên minh châu Âu (EVFTA), Việt Nam đã cơ bản hoàn thành những mục tiêu quan trọng nhất trong Chiến lược đàm phán hiệp định thương mại tự do giai đoạn 2010 - 2020. EVFTA hứa hẹn sẽ tạo ra một thị trường chung rộng lớn cho hàng hóa và dịch vụ giữa Việt Nam và EU, giúp các doanh nghiệp Việt Nam tiếp cận hàng triệu người tiêu dùng châu Âu. Đặc biệt, ngành thủy sản được kỳ vọng sẽ có những bước phát triển vượt bậc nhờ việc giảm thuế quan và các quy định thuận lợi hơn. Tuy nhiên, để tận dụng tối đa lợi ích của hiệp định này, Việt Nam cần vượt qua một thử thách lớn: vấn đề “thẻ vàng” thủy sản. “Thẻ vàng” là một cảnh báo mà Ủy ban châu Âu (EC) đưa ra đối với các quốc gia có hoạt động khai thác thủy sản bất hợp pháp. Điều này đồng nghĩa với việc hải sản Việt Nam xuất khẩu sang EU sẽ phải đối mặt với những kiểm tra nghiêm ngặt hơn.\nBiện pháp nào sau đây không áp dụng để khắc phục tình trạng “Thẻ vàng thủy sản” của Việt Nam?", "o": ["Dừng hoạt động xuất khẩu", "Tuyên truyền với ngư dân.", "Thương lượng với phía EU.", "Tăng cường kiểm soát tàu cá."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx · Phần I câu 24 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D22-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Trên địa bàn thành phố X, có gia đình bà G kinh doanh dịch vụ nhà ở cho thuê. Do bị lừa đảo qua mạng với số tiền lớn, bà G buộc phải bán toàn bộ mảnh đất cùng các tài sản gắn liền trên đất cho anh S. Sau khi nhận chuyển nhượng từ bà G, anh S đã cải tạo lại một phần diện tích khu sinh hoạt chung của các phòng trọ, đồng thời thông báo về việc tăng giá thuê phòng và tiền dịch vụ điện nước khiến nhiều hộ gia đình rất bức xúc và không đồng ý. Nhiều lần liên lạc với bà G không được, chị T là lao động tự do thuê trọ đã viết bài xuyên tạc bà G và anh S cấu kết để làm ăn phi pháp sau đó đăng lên mạng xã hội làm ảnh hưởng đến cuộc sống của anh S. Yêu cầu chị T gỡ bài không được, anh S đã đập phá đồ đạc đồng thời đuổi chị T ra khỏi phòng trọ và chấm dứt hợp đồng với chị T.", "o": ["Anh S không vi phạm nghĩa vụ tôn trọng tài sản của công dân.", "Các gia đình thuê phòng trọ của anh S cần điều chỉnh lại kế hoạch thu chi trong gia đình theo đó tăng khoản chi tiêu thiết yếu, giảm khoản tiết kiệm để phù hợp với thực tế.", "Anh S có quyền chiếm hữu, sử dụng và định đoạt đối với tất cả các tài sản mà bà G đã chuyển giao cho mình.", "Theo quy định của pháp luật, bà G và anh S đồng thời là chủ sở hữu hợp pháp đối với các phòng trọ đang cho thuê."], "a": [false, true, true, false], "e": "Đáp án: a) Sai; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx · Phần II câu 1 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D22-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Nhật Bản là đối tác lớn của Việt Nam. Năm 1992, kim ngạch thương mại hai chiều đạt 1,3 tỷ USD, năm 2002 đạt 4,9 tỷ USD, đến năm 2012 đã tăng lên 24,7 tỷ USD và đặc biệt năm 2022 đã đạt đến 47,6 tỷ USD; cán cân thương mại tương đối cân bằng, khoảng 0,8 tỷ USD nghiêng về phía Việt Nam. Nhật Bản cũng là nhà đầu tư nước ngoài lớn nhất ở Việt Nam. Nếu như năm 2002 có 48 dự án với 102 triệu USD, thì đến năm 2012 đã có 317 dự án với 5,13 tỷ USD và lũy kế đến năm 2022 có 4.978 dự án với tổng số vốn đầu tư đăng ký đạt hơn 68,89 tỷ USD, tập trung vào các lĩnh vực như sản xuất, chế tạo, xây dựng và kinh doanh bất động sản..., với hai hình thức chính là 100% vốn nước ngoài và hình thức hợp đồng BOT. Vốn vay ưu đãi và vốn viện trợ không hoàn lại (vốn ODA) của Nhật Bản dành cho Việt Nam chiếm 30% tổng số vốn ODA của cộng đồng quốc tế cho Việt Nam, với số vốn cam kết khoảng 29,3 tỷ USD.", "o": ["Các lĩnh vực mà Nhật Bản đầu tư vào Việt Nam năm 2022 góp phần giúp các doanh nghiệp Việt Nam xác định được chiến lược kinh doanh phù hợp.", "Việc Nhật Bản cung cấp ODA cho Việt Nam đặt ra yêu cầu Việt Nam phải nâng cao năng lực quản lý, sử dụng vốn hiệu quả và minh bạch.", "ODA là nguồn vốn đầu tư trực tiếp nước ngoài, góp phần hỗ trợ phát triển hạ tầng và cải thiện chất lượng sống tại các nước nhận viện trợ như Việt Nam.", "Sự tăng trưởng của kim ngạch thương mại giữa hai nước chứng tỏ hoạt động đầu tư quốc tế phát triển."], "a": [false, true, false, false], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Sai.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx · Phần II câu 2 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D22-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Anh Q có quốc tịch Đức đã đến Việt Nam sinh sống và làm việc được 2 năm. Vì là bạn quen qua mạng nên khi anh S quốc tịch Anh tới Việt Nam du lịch, anh Q đã cho anh S ở chung. Anh S rất thích nhạc Việt nên cuối tuần anh S rủ anh Q mở nhạc nghe. Tiếng nhạc làm ảnh hưởng đến giấc ngủ trưa nên chị H và anh K là vợ chồng nhà kế bên yêu cầu 2 anh giảm âm lượng. Do bất đồng ngôn ngữ nên anh K đã lao vào đánh anh Q bị thương. Thấy vậy, anh S vội ném chai bia vào đầu của anh K khiến anh phải nhập viện điều trị.", "o": ["Anh Q không được coi là công dân Việt Nam vì anh là người nước ngoài đang tạm trú ở Việt Nam.", "Anh S và anh Q được hưởng chế độ đãi ngộ quốc gia cho người nước ngoài ở Việt Nam.", "Anh Q và anh S có quyền yêu cầu được bảo hộ công dân từ quốc gia Việt Nam.", "Anh S không phải chịu trách nhiệm pháp lí ở Việt Nam."], "a": [true, true, false, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Sai.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx · Phần II câu 3 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D22-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Chị N đã tìm hiểu các quán cà phê thành công khác và phát hiện ra rằng nhiều quán hiện tại có menu khá đơn giản hoặc giá cả không phù hợp với túi tiền sinh viên. Vì vậy, chị N quyết định xây dựng một thực đơn đặc biệt, kết hợp giữa chất lượng cao cấp và các loại bánh mới lạ với giá cả hợp lý. Chị cũng chọn một địa điểm gần các trường đại học lớn để dễ dàng thu hút khách hàng. Nhờ có một bản kế hoạch kinh doanh rõ ràng, sau một thời gian hoạt động, chị N đã thu được kết quả khả quan, doanh thu năm đầu tiên đạt 135 triệu đồng. Để phát triển kinh doanh hiệu quả hơn, chị N đã có một số ý tưởng tiếp thị giảm giá vào các ngày lễ và ưu đãi dành cho khách hàng thân thiết. Chị dự tính trong 2 năm sẽ phát triển thêm 2 cơ sở ở các huyện lân cận.", "o": ["Việc chị N nghiên cứu thị trường là một trong các bước quan trọng khi lập kế hoạch kinh doanh.", "Quán cà phê của chị có quy mô nhỏ và doanh thu 135 triệu đồng/ năm nên chị N không phải nộp thuế.", "Chị N xác định ý tưởng kinh doanh thông qua việc dự tính trong 2 năm sẽ phát triển thêm 2 cơ sở ở các huyện lân cận.", "Việc chị N lựa chọn địa điểm gần các trường đại học để kinh doanh thể hiện quyền được hỗ trợ vốn và mặt bằng của công dân."], "a": [true, false, false, false], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Sai.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 7043 - HẢI DƯƠNG.docx · Phần II câu 4 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}]}, {"id": "TN-D23", "loai": "tn", "khoi": 12, "hoc_ki": 2, "so_de": 23, "ten": "Đề luyện thi tốt nghiệp số 23", "pham_vi": "Đề nguồn của giáo viên, giữ NGUYÊN chữ của đề (chỉ bỏ lỗi sao chép) · Phú Yên 2025 (thi thử tốt nghiệp 2025; chuyển từ danh sách HSG) · file nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm 4 lựa chọn + 4 câu đúng/sai (mỗi câu 4 ý)", "cham": {"tong": 10, "tn": 0.25, "ds": [0, 0.1, 0.25, 0.5, 1.0]}, "status": "cho_duyet", "khoa": {"đã giải lại, khớp khoá": 28}, "sua": "Nối lại ý a bị tách khỏi đoạn dẫn ở 2 câu đúng/sai (lỗi sao chép; chữ giữ nguyên).", "cau": [{"id": "TN-D23-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong các hoạt động kinh tế cơ bản của đời sống xã hội, hoạt động có vai trò định hướng, tạo động lực cho hoạt động sản xuất phát triển là", "o": ["hoạt động trung gian.", "hoạt động phân phối.", "hoạt động trao đổi.", "hoạt động tiêu dùng."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx · Phần I câu 1 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D23-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi không đội mũ bảo hiểm khi tham gia giao thông bằng xe đạp điện là công dân không thực hiện pháp luật theo hình thức nào dưới đây?", "o": ["Áp dụng pháp luật.", "Thi hành pháp luật.", "Tuân thủ pháp luật.", "Sử dụng pháp luật."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx · Phần I câu 2 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D23-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong nền kinh tế, do có yếu tố tác động làm tổng cầu tăng cao nhưng tổng cung không thay đổi dẫn đến mức giá chung tăng lên, từ đó sẽ gây ra hiện tượng", "o": ["lạm phát.", "thất nghiệp.", "khủng hoảng.", "suy thoái."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx · Phần I câu 3 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D23-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc người sản xuất kinh doanh tổ chức, thiết lập và hoàn thiện các mối quan hệ trong kinh doanh là thể hiện năng lực kinh doanh nào dưới đây?", "o": ["Năng lực chuyên môn.", "Năng lực giao tiếp.", "Năng lực quản lý.", "Năng lực lãnh đạo."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx · Phần I câu 4 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D23-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo Luật Bình đẳng giới năm 2006, nam nữ bình đẳng về tiêu chuẩn, độ tuổi khi được đề bạt, bổ nhiệm giữ các chức danh trong các ngành, nghề có tiêu chuẩn chức danh thuộc quyền bình đẳng giới trong lĩnh vực nào dưới đây?", "o": ["Chính trị.", "Kinh tế.", "Lao động.", "Gia đình."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx · Phần I câu 5 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D23-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, hoạt động nào dưới đây của công dân không gắn với việc thực hiện quyền tham gia quản lý nhà nước và xã hội?", "o": ["Bày tỏ bức xúc về tình trạng ngập lụt của thành phố với cán bộ.", "Giám sát quá trình giải quyết khiếu nại về đền bù đất đai ở địa phương.", "Theo dõi hoạt động văn hoá nghệ thuật mùa hè của thành phố.", "Đóng góp ý kiến vào quá trình xây dựng kế hoạch tái định cư của địa phương."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx · Phần I câu 6 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D23-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chuyển dịch cơ cấu ngành kinh tế theo hướng tích cực thể hiện ở sự gia tăng tỉ trọng của các ngành nào trong GDP?", "o": ["Công nghiệp và nông nghiệp.", "Nông nghiệp và dịch vụ.", "Công nghiệp và dịch vụ.", "Nông nghiệp và thương mại."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx · Phần I câu 7 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D23-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Loại hình bảo hiểm nào dưới đây do Nhà nước tổ chức mà người lao động và người sử dụng lao động phải tham gia?", "o": ["Bảo hiểm xã hội tự nguyện.", "Bảo hiểm nhân thọ.", "Bảo hiểm xã hội bắt buộc.", "Bảo hiểm thương mại."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx · Phần I câu 8 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D23-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Người mượn hoặc thuê tài sản của người khác phải giữ gìn cẩn thận, trả lại cho chủ sở hữu đúng hạn, nếu hỏng phải sửa chữa, bồi thường là nội dung nghĩa vụ nào dưới đây về tài sản?", "o": ["Nghĩa vụ giữ gìn tài sản của cá nhân.", "Nghĩa vụ tôn trọng tài sản của người khác.", "Nghĩa vụ bảo vệ tài sản của chủ sở hữu.", "Nghĩa vụ bồi thường thiệt hại cho chủ sở hữu."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx · Phần I câu 9 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D23-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mô hình sản xuất kinh doanh nào dưới đây tồn tại dưới dạng là một tổ chức kinh tế tập thể, đồng sở hữu, được thành lập trên tinh thần tự nguyện vì lợi ích chung của các thành viên?", "o": ["Công ty hợp danh.", "Công ty cổ phần.", "Kinh tế hợp tác xã.", "Kinh tế hộ gia đình."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx · Phần I câu 10 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D23-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của Hiến pháp 2013, cơ quan hành chính cao nhất của nước Cộng hòa xã hội chủ nghĩa Việt Nam là", "o": ["Chủ tịch nước.", "Quốc hội.", "Chính phủ.", "Tòa án."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx · Phần I câu 11 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D23-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật hiện hành, người có hành vi đuổi trái pháp luật người khác ra khỏi chỗ ở của họ phải chịu trách nhiệm pháp lý nào sau đây?", "o": ["Cải tạo không giam giữ đến 3 năm.", "Cảnh cáo, nhắc nhở tại địa phương.", "Phạt tiền từ 2.000.000đ đến 5.000.000đ.", "Phạt tù từ 3 tháng đến 2 năm."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx · Phần I câu 12 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D23-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, hành vi nào sau đây vi phạm quyền bất khả xâm phạm về thân thể của công dân?", "o": ["Giam, giữ người để yêu cầu trả nợ.", "Đánh người gây thương tích nghiêm trọng.", "Hành vi nói xấu, vu khống người khác.", "Bắt người đang cướp giật tài sản."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx · Phần I câu 13 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D23-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Thị trường lao động là nơi thực hiện các quan hệ xã hội giữa người lao động làm thuê và", "o": ["người bán sức lao động.", "người sử dụng sức lao động.", "người có sức lao động.", "người chủ doanh nghiệp."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx · Phần I câu 14 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D23-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trước thực tế thị trường tràn ngập hàng Trung Quốc mẫu mã đẹp, giá rẻ, các doanh nghiệp Việt Nam muốn giành lại thị trường nội địa, tăng sức cạnh tranh cho hàng hoá trong nước buộc phải đầu tư máy móc, hợp tác với các đối tác nước ngoài trong đào tạo nhân lực chất lượng cao là biểu hiện của hình thức cạnh tranh nào dưới đây?", "o": ["Cạnh tranh có chiêu trò.", "Cạnh tranh lành mạnh.", "Cạnh tranh không lành mạnh.", "Cạnh tranh giành giật."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx · Phần I câu 15 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D23-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 16, 17\nChị H tâm sự với chị V tư vấn viên bảo hiểm rằng: Chị là chủ xưởng sản xuất mây tre đan tư\nnhân, không thuộc diện đóng bảo hiểm xã hội bắt buộc, giờ đây chị rất lo lắng; vì tuổi già sau\nnày chị không có lương hưu trong khi cuộc sống với bao điều bất trắc không ai lường trước\nđược; giá như chị có một khoản bảo hiểm nào đó để phòng thân đảm bảo tuổi già, không phải\nlo toan tài chính thì tốt. Chị V đã tư vấn gói bảo hiểm xã hội tự nguyện dành cho người từ đủ\n15 tuổi trở lên, quyền lợi mà chị H được hưởng là chế độ hưu trí và chế độ tử tuất, bên cạnh đó\nchị còn được cấp thẻ bảo hiểm y tế suốt những năm hưởng lương hưu với quyền lợi cao hơn so\nvới lúc đi làm để đi khám bệnh, mà lớn tuổi rồi sức khỏe xuống có khi ở bệnh viện nhiều hơn\nở nhà. Nên tính ra việc nhận lương hưu bảo đảm hơn cho bản thân khi về già. Khi được tư vấn\nkỹ càng chị H đã quyết định tham gia các gói bảo hiểm mà chị V đã tư vấn.\nChị H đã tham gia các loại hình bảo hiểm nào dưới đây?", "o": ["Bảo thất nghiệp và bảo hiểm xã hội bắt buộc.", "Bảo hiểm xã hội bắt buộc và bảo hiểm y tế.", "Bảo hiểm xã hội tự nguyện và bảo hiểm y tế.", "Bảo hiểm hưu trí và bảo hiểm xã hội tự nguyện."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx · Phần I câu 16 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D23-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 16, 17\nChị H tâm sự với chị V tư vấn viên bảo hiểm rằng: Chị là chủ xưởng sản xuất mây tre đan tư\nnhân, không thuộc diện đóng bảo hiểm xã hội bắt buộc, giờ đây chị rất lo lắng; vì tuổi già sau\nnày chị không có lương hưu trong khi cuộc sống với bao điều bất trắc không ai lường trước\nđược; giá như chị có một khoản bảo hiểm nào đó để phòng thân đảm bảo tuổi già, không phải\nlo toan tài chính thì tốt. Chị V đã tư vấn gói bảo hiểm xã hội tự nguyện dành cho người từ đủ\n15 tuổi trở lên, quyền lợi mà chị H được hưởng là chế độ hưu trí và chế độ tử tuất, bên cạnh đó\nchị còn được cấp thẻ bảo hiểm y tế suốt những năm hưởng lương hưu với quyền lợi cao hơn so\nvới lúc đi làm để đi khám bệnh, mà lớn tuổi rồi sức khỏe xuống có khi ở bệnh viện nhiều hơn\nở nhà. Nên tính ra việc nhận lương hưu bảo đảm hơn cho bản thân khi về già. Khi được tư vấn\nkỹ càng chị H đã quyết định tham gia các gói bảo hiểm mà chị V đã tư vấn.\nTừ những thông tin trên cho thấy vai trò của bảo hiểm xã hội tự nguyện với chị H là?", "o": ["Được hưởng chế độ hưu trí, chế độ tử tuất và bảo hiểm y tế .", "Được hưởng trợ cấp ốm đau, trợ cấp thất nghiệp và chế độ hưu trí.", "Được hưởng chế độ hưu trí, tai nạn lao động và bệnh nghề nghiệp.", "Được hưởng chế độ tử tuất, chế độ hưu trí, thai sản và ốm đau."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx · Phần I câu 17 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D23-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi lập kế hoạch quản lý thu chi trong gia đình, việc thống nhất các khoản chi thiết yếu và không thiết yếu cần đảm bảo nguyên tắc nào dưới đây?", "o": ["Ưu tiên cho khoản không thiết yếu.", "Dành toàn bộ cho khoản không thiết yếu.", "Dành toàn bộ cho khoản thiết yếu.", "Ưu tiên cho khoản chi tiêu thiết yếu."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx · Phần I câu 18 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D23-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không phải là căn cứ để xây dựng kế hoạch quản lý thu, chi trong gia đình?", "o": ["Các khoản chi tiêu trong gia đình.", "Các mối quan hệ trong gia đình.", "Mục tiêu tài chính trong gia đình.", "Các nguồn thu nhập trong gia đình."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx · Phần I câu 19 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D23-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chính sách miễn, giảm học phí của Nhà nước đã tạo điều kiện giúp đỡ nhiều học sinh có hoàn cảnh khó khăn được học tập góp phần tạo điều kiện để công dân thực hiện quyền học tập ở nội dung nào dưới đây?", "o": ["Học thường xuyên, học suốt đời.", "Định hướng đổi mới giáo dục.", "Học bất cứ ngành, nghề nào.", "Công bằng xã hội trong giáo dục."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx · Phần I câu 20 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D23-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bác sĩ T vì sơ ý mà làm lộ tình trạng bệnh, thông tin và hồ sơ bệnh án của anh K khiến anh bị ảnh hưởng nhẹ về tinh thần. Theo quy định của pháp luật, hành vi của bác sĩ T phải chịu trách nhiệm pháp lý nào dưới đây?", "o": ["Cảnh cáo và cấm bác sĩ T hành nghề một thời gian.", "Thu hồi chứng chỉ hành nghề của bác sĩ T.", "Xử phạt hành chính với hành vi của bác sĩ T.", "Truy cứu trách nhiệm hình sự với bác sĩ T."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx · Phần I câu 21 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D23-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22, 23, 24\nViệt Nam và Nhật Bản chính thức thiết lập quan hệ ngoại giao ngày 21-9-1973. Sau hơn 5 thập\nkỷ vun đắp và xây dựng, Việt Nam - Nhật Bản là hình mẫu tiêu biểu cho sự hợp tác hiệu quả,\nchân thành, với tiềm năng và triển vọng hết sức rộng mở. Trên cơ sở đó, công ty A (tại Việt\nNam) và Công ty C (tại Nhật Bản) ký kết hợp đồng mua bán 500 tấn (+/-5%) hạt giống lúa với\nđơn giá 150 USD/tấn, giao hàng theo điều kiện FOB tại cảng TP. Hồ Chí Minh. Nhưng khi\ncông ty A nhận hàng tại cảng TP. Hồ Chí Minh, có một số lô hàng bị hư hỏng do điều kiện bảo\nquản không tốt trong quá trình vận chuyển. Sau khi giám định, Công ty A yêu cầu Công ty C\nbồi thường thiệt hại nhưng không được chấp nhận.\nSự hợp tác của Việt Nam và Nhật Bản thể hiện hội nhập kinh tế quốc tế ở cấp độ", "o": ["song phương.", "đa phương.", "toàn cầu.", "khu vực."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx · Phần I câu 22 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D23-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22, 23, 24\nViệt Nam và Nhật Bản chính thức thiết lập quan hệ ngoại giao ngày 21-9-1973. Sau hơn 5 thập\nkỷ vun đắp và xây dựng, Việt Nam - Nhật Bản là hình mẫu tiêu biểu cho sự hợp tác hiệu quả,\nchân thành, với tiềm năng và triển vọng hết sức rộng mở. Trên cơ sở đó, công ty A (tại Việt\nNam) và Công ty C (tại Nhật Bản) ký kết hợp đồng mua bán 500 tấn (+/-5%) hạt giống lúa với\nđơn giá 150 USD/tấn, giao hàng theo điều kiện FOB tại cảng TP. Hồ Chí Minh. Nhưng khi\ncông ty A nhận hàng tại cảng TP. Hồ Chí Minh, có một số lô hàng bị hư hỏng do điều kiện bảo\nquản không tốt trong quá trình vận chuyển. Sau khi giám định, Công ty A yêu cầu Công ty C\nbồi thường thiệt hại nhưng không được chấp nhận.\nTheo thỏa thuận giữa các bên trong hợp đồng, hành vi vi phạm của Công ty C phải chịu trách nhiệm pháp lí nào sau đây?", "o": ["Buộc thu hồi toàn bộ lô hàng và bồi thường thiêt hại.", "Đền bù cho Công ty A 100% giá trị lô hàng.", "Thu hồi và bồi thường thiệt hại số lô hàng bị hư hỏng.", "Hủy bỏ hợp đồng và chấm dứt hợp tác."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx · Phần I câu 23 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D23-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22, 23, 24\nViệt Nam và Nhật Bản chính thức thiết lập quan hệ ngoại giao ngày 21-9-1973. Sau hơn 5 thập\nkỷ vun đắp và xây dựng, Việt Nam - Nhật Bản là hình mẫu tiêu biểu cho sự hợp tác hiệu quả,\nchân thành, với tiềm năng và triển vọng hết sức rộng mở. Trên cơ sở đó, công ty A (tại Việt\nNam) và Công ty C (tại Nhật Bản) ký kết hợp đồng mua bán 500 tấn (+/-5%) hạt giống lúa với\nđơn giá 150 USD/tấn, giao hàng theo điều kiện FOB tại cảng TP. Hồ Chí Minh. Nhưng khi\ncông ty A nhận hàng tại cảng TP. Hồ Chí Minh, có một số lô hàng bị hư hỏng do điều kiện bảo\nquản không tốt trong quá trình vận chuyển. Sau khi giám định, Công ty A yêu cầu Công ty C\nbồi thường thiệt hại nhưng không được chấp nhận.\nHợp đồng được ký kết của công ty A và công ty C sẽ thuộc loại hợp đồng nào dưới đây?", "o": ["Thương mại quốc tế.", "Đa quốc gia.", "Pháp nhân quốc tế.", "Kinh doanh quốc tế."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx · Phần I câu 24 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D23-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Năm 2023, Hiệp định Đối tác Kinh tế Toàn diện Khu vực (RCEP) giữa 15 quốc gia châu Á - Thái Bình Dương chính thức có hiệu lực. Theo đó, RCEP tập trung vào giảm thuế quan, tạo thuận lợi thương mại và đầu tư, cũng như nâng cao khả năng cạnh tranh trong khu vực. Để tận dụng cơ hội từ RCEP, công ty A, một doanh nghiệp xuất khẩu hàng dệt may, đã triển khai chương trình cải tiến dây chuyền sản xuất nhằm tiết giảm chi phí, nâng cao chất lượng và đáp ứng các tiêu chuẩn lao động quốc tế. Đồng thời, công ty cũng đầu tư mạnh mẽ vào công nghệ để đảm bảo tính minh bạch và truy xuất nguồn gốc hàng hóa theo yêu cầu của RCEP.", "o": ["Hiệp định RCEP là hình thức hội nhập khu vực.", "Việc đầu tư vào công nghệ minh bạch và truy xuất nguồn gốc thể hiện trách nhiệm của doanh nghiệp trong việc tuân thủ các quy định quốc tế.", "Cải tiến dây chuyền sản xuất của công ty A là bước đánh giá cơ hội, rủi ro, đề ra biện pháp xử lý trong lập kế hoạch kinh doanh.", "Theo RCEP, mọi quốc gia thành viên đều bắt buộc phải cắt giảm hoàn toàn các loại thuế quan đối với hàng hóa nhập khẩu ngay từ năm đầu tiên có hiệu lực."], "a": [true, true, true, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx · Phần II câu 1 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D23-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Anh M là bác sĩ chuyên khoa tại bệnh viện X, ngoài thời gian làm việc tại cơ quan, anh đã làm hồ sơ và được cấp phép mở phòng khám tư nhân, trong quá trình thăm khám anh kê thuốc và trực tiếp bán thuốc cho bệnh nhân. Con trai anh M là cháu H hiện đang học Đại học kinh tế cũng trực tiếp bán thuốc tân dược bằng hình thức bán hàng trên các trang mạng xã hội. Công việc kinh doanh ngày càng tiến triển tốt nên anh M đã đề nghị và được chị G sang nhượng lại cửa hàng mà chị đang thuê của bà V để làm kho chứa hàng và mở rộng việc bán thuốc. Vì nhiều tháng không được chị G thanh toán tiền nhà theo thỏa thuận, bà V đã đơn phương chấm dứt hợp đồng và yêu cầu trả lại cửa hàng để cho người khác thuê. Tuy nhiên, anh M không đồng ý với lý do đã ký hợp đồng với chị G và thanh toán đủ 2 năm thuê nhà. Bức xúc, bà V đã cùng con tới phá cửa và tịch thu toàn bộ hàng hóa trong kho để gây sức ép buộc anh M phải trả lại cửa hàng.", "o": ["Anh M và con trai không vi phạm nghĩa vụ của công dân khi tiến hành kinh doanh.", "Anh M thuê kho chứa hàng để mở rộng việc bán thuốc là bước xác định chiến lược kinh doanh.", "Chị G và bà V đều chưa thực hiện đúng nghĩa vụ tôn trọng tài sản của công dân.", "Theo quy định của pháp luật, H có thể bị xử phạt hành chính và bị thu hồi giấy phép kinh doanh."], "a": [false, true, true, false], "e": "Đáp án: a) Sai; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx · Phần II câu 2 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D23-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "X là doanh nghiệp đi đầu trong lĩnh vực xây dựng. Trải qua 26 năm hình thành và phát triển, doanh nghiệp luôn tự hào là đơn vị chưa bao giờ nợ lương, thưởng, thuế và bảo hiểm xã hội cho người lao động, nợ quá hạn ngân hàng. Nhiều năm doanh nghiệp luôn đề ra và thực hiện đúng cam kết về vấn đề bảo hành 10 năm đối với các công trình xây dựng do doanh nghiệp thực hiện. Bên cạnh hoàn thành vượt tiến độ các dự án, năm 2023, doanh nghiệp đạt mức doanh thu gần 4.000 tỷ đồng, là đơn vị nộp thuế thu nhập doanh nghiệp lớn nhất tỉnh Q. Năm 2024 nhằm giúp người dân an tâm sinh sống, doanh nghiệp quyết định đầu tư hơn 33 tỷ đồng để xây dựng 56 ngôi nhà kiên cố tặng bà con vùng bị ảnh hưởng bởi lũ lụt.", "o": ["Cam kết bảo hành 10 năm đối với các công trình do doanh nghiệp xây dựng là thực hiện trách nhiệm pháp lý của doanh nghiệp.", "Doanh nghiệp X thực hiện tốt nghĩa vụ về kinh doanh trong quá trình hoạt động.", "Doanh nghiệp chưa bao giờ nợ lương, thưởng của người lao động là thực hiện trách nhiệm đạo đức.", "Việc doanh nghiệp xây dựng nhà cho bà con vùng lũ lụt là tham gia đảm bảo quyền và nghĩa vụ của công dân về an sinh xã hội."], "a": [false, true, false, true], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx · Phần II câu 3 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}, {"id": "TN-D23-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Có 4 chiếc tàu thủy nước ngoài là tàu N, X, Y, Z, đi vào vùng biển thuộc chủ quyền của Việt Nam. Trong đó tàu X là tàu quân sự, Z là tàu đánh bắt hải sản, tàu N và tàu Y là tàu dân sự. Tàu N đi vào vùng lãnh hải Việt Nam, sau đó tàu N đi tiếp vào vùng nội thủy của nước ta, tàu Y thì đi qua không gây hại trong vùng lãnh hải, cả hai tàu chỉ thông báo nhưng không xin phép cơ quan nhà nước có thẩm quyền Việt Nam. Tàu Z đánh bắt hải sản tại vùng biển cách đảo Cồn Cỏ (Quảng Trị) khoảng 10 hải lý trong lãnh hải Việt Nam. Tàu X neo đậu tại nơi trú đậu của Việt Nam ở bên ngoài nội thủy nhưng không phải theo thỏa thuận giữa các cơ quan có thẩm quyền của Việt Nam với quốc gia mà tàu X đang mang cờ.", "o": ["Tàu N và tàu Y đi vào vùng lãnh hải và nội thủy Việt Nam theo nguyên tắc đi qua không gây hại nên chỉ cần thông báo không cần xin phép các cơ quan chức năng Việt Nam.", "Theo quy định của Công ước Luật Biển năm 1982 và Luật Biển Việt Nam, tàu X được đi vào vùng nội thủy của quốc gia Việt Nam mà không cần xin phép.", "Tàu Z đánh bắt hải sản trong lãnh hải Việt Nam khi chưa được cho phép là vi phạm Công ước Luật Biển năm 1982 và Luật Biển Việt Nam.", "Trong vùng đặc quyền kinh tế và thềm lục địa, quốc gia ven biển có quyền nghiên cứu khoa học và giữ gìn môi trường biển."], "a": [false, false, true, true], "e": "Đáp án: a) Sai; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: 11_ĐỀ GV (có đáp án) - HSG - PHÚ YÊN 2025.docx · Phần II câu 4 · khoá: khớp gạch chân và ĐÁP ÁN · EM ĐÃ TỰ GIẢI LẠI 17/11/2026, KHỚP"}]}, {"id": "TN-D24", "loai": "tn", "khoi": 12, "hoc_ki": 2, "so_de": 24, "ten": "Đề luyện thi tốt nghiệp số 24", "pham_vi": "Đề nguồn của giáo viên, giữ NGUYÊN chữ của đề (chỉ bỏ lỗi sao chép) · mã 401, Nam Định (khảo sát học kì II 2024-2025; chuyển từ danh sách HSG; khoá do em tự giải lại toàn bộ vì file nguồn gắn nhầm khoá đề khác) · file nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm 4 lựa chọn + 4 câu đúng/sai (mỗi câu 4 ý)", "cham": {"tong": 10, "tn": 0.25, "ds": [0, 0.1, 0.25, 0.5, 1.0]}, "status": "cho_duyet", "khoa": {"đã tự giải lại": 28}, "sua": "Đề này từng nằm trong danh sách HSG (HSG-14); ghi chú khi rà: Đề «Mã 401 – Sở Nam Định» trong kho bị gắn nhầm khoá của một đề khác cùng mã 401 (gần như mọi đáp án sai). Em tự giải lại toàn bộ 24 câu trắc nghiệm và 4 câu đúng/sai. Nối lại ý a bị tách khỏi đoạn dẫn ở 1 câu đúng/sai (lỗi sao chép; chữ giữ nguyên).", "cau": [{"id": "TN-D24-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Sự tăng trưởng kinh tế gắn liền với sự chuyển dịch cơ cấu kinh tế hợp lí, đảm bảo tiến bộ xã hội là", "o": ["tăng trưởng kinh tế.", "tổng sản phẩm quốc nội.", "phát triển kinh tế.", "phát triển xã hội."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx · Phần I câu 1 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D24-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Từ năm học 2025-2026 Bộ Chính trị quyết định về việc miễn toàn bộ học phí cho học sinh từ bậc mầm non đến hết bậc trung học phổ thông công lập là thể hiện nội dung của chính sách an sinh xã hội nào sau đây?", "o": ["Chính sách bảo đảm các dịch vụ xã hội cơ bản.", "Chính sách trợ giúp xã hội thường xuyên.", "Chính sách trợ giúp xóa đói, giảm nghèo.", "Chính sách hỗ trợ thu nhập và giảm nghèo."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx · Phần I câu 2 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D24-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Ngày 28-7-1995, Việt Nam trở thành thành viên thứ 7 của ASEAN là biểu hiện của hình thức hội nhập kinh tế quốc tế nào sau đây?", "o": ["Khu vực.", "Toàn quốc.", "Toàn cầu.", "Song phương."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx · Phần I câu 3 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D24-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào sau đây sai về vai trò của tăng trưởng và phát triển kinh tế?", "o": ["Tạo điều kiện giải quyết việc làm cho đất nước.", "Để mọi công dân có thu nhập bằng nhau.", "Tạo điều kiện củng cố quốc phòng anh ninh.", "Góp phần giải quyết tình trạng đói nghèo."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx · Phần I câu 4 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D24-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 5, 6\nĐầu năm 2024, sau khi hoàn thành khóa đào tạo nghề, chị D ký hợp đồng lao động không xác định thời hạn với Công ty X – doanh nghiệp hoạt động trong lĩnh vực sản xuất. Ngay sau đó, công ty đã thực hiện đầy đủ thủ tục tham gia bảo hiểm xã hội, bảo hiểm y tế và bảo hiểm thất nghiệp cho chị theo quy định. Trong quá trình làm việc, do thường xuyên tiếp xúc với môi trường độc hại, đến giữa năm 2025, chị D không may mắc bệnh nghề nghiệp. Nhờ tham gia đầy đủ bảo hiểm, chị được hưởng trợ cấp từ Quỹ tai nạn lao động, bệnh nghề nghiệp, giúp chị có điều kiện điều trị bệnh và ổn định cuộc sống. Ngoài ra, chị D sẽ được hưởng các chế độ khác của bảo hiểm như: ốm đau, thai sản, hưu trí và tử tuất, góp phần bảo đảm an sinh lâu dài.\nTrong trường hợp của chị D, nội dung nào sau đây vừa thể hiện vai trò của bảo hiểm xã hội vừa thể hiện vai trò của chính sách an sinh xã hội đối với người lao động?", "o": ["Được miễn trừ trách nhiệm kỷ luật.", "Được hỗ trợ khi gặp phải rủi ro.", "Được hỗ trợ ký hợp đồng lao động.", "Được miễn trừ tham gia bảo hiểm."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx · Phần I câu 5 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D24-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 5, 6\nĐầu năm 2024, sau khi hoàn thành khóa đào tạo nghề, chị D ký hợp đồng lao động không xác định thời hạn với Công ty X – doanh nghiệp hoạt động trong lĩnh vực sản xuất. Ngay sau đó, công ty đã thực hiện đầy đủ thủ tục tham gia bảo hiểm xã hội, bảo hiểm y tế và bảo hiểm thất nghiệp cho chị theo quy định. Trong quá trình làm việc, do thường xuyên tiếp xúc với môi trường độc hại, đến giữa năm 2025, chị D không may mắc bệnh nghề nghiệp. Nhờ tham gia đầy đủ bảo hiểm, chị được hưởng trợ cấp từ Quỹ tai nạn lao động, bệnh nghề nghiệp, giúp chị có điều kiện điều trị bệnh và ổn định cuộc sống. Ngoài ra, chị D sẽ được hưởng các chế độ khác của bảo hiểm như: ốm đau, thai sản, hưu trí và tử tuất, góp phần bảo đảm an sinh lâu dài.\nCăn cứ theo tình huống, loại hình bảo hiểm mà doanh nghiệp và chị D cùng tham gia theo quy định của pháp luật là", "o": ["bảo hiểm thương mại.", "bảo hiểm xã hội tự nguyện.", "bảo hiểm dân sự bắt buộc.", "bảo hiểm xã hội bắt buộc."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx · Phần I câu 6 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D24-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào sau đây không thể hiện trong kế hoạch kinh doanh?", "o": ["Điều kiện thực hiện hoạt động kinh doanh.", "Mục tiêu và chiến lược kinh doanh.", "Xác định định hướng kinh doanh.", "Thông tin chi tiết về cá nhân lập kế hoạch."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx · Phần I câu 7 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D24-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bản trình bày các nội dung cơ bản như định hướng, mục tiêu, nguồn lực, tài chính, kế hoạch bán hàng… nhằm giúp chủ thể kinh doanh xác định nhiệm vụ và lộ trình thực hiện mục tiêu được gọi là", "o": ["kế hoạch tài chính.", "quản lý kinh doanh.", "kế hoạch kinh doanh.", "quản lý tài chính."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx · Phần I câu 8 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D24-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Doanh nghiệp X luôn nỗ lực vượt qua khó khăn để kinh doanh có hiệu quả, không chỉ đem lại lợi nhuận mà còn góp phần tạo ra nhiều việc làm với mức thu nhập ổn định cho người lao động là đã góp phần thực hiện tốt trách nhiệm xã hội nào dưới đây của doanh nghiệp?", "o": ["Trách nhiệm kinh tế.", "Trách nhiệm tiêu dùng.", "Trách nhiệm nhân văn.", "Trách nhiệm pháp lý."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx · Phần I câu 9 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D24-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 10, 11\nSau khi kết hôn, anh V và chị D đặt mục tiêu mua nhà và ra ở riêng sau 5 năm. Để hiện thực hóa kế hoạch này, họ thống nhất áp dụng “quy tắc 50–30–20” trong quản lý thu–chi gia đình, theo đó: 50% tổng thu nhập dành cho chi tiêu thiết yếu (ăn uống, y tế, giáo dục, sinh hoạt hằng ngày…); 30% dành cho tiết kiệm, dự phòng và mua nhà; 20% còn lại dành cho giải trí và giao tiếp xã hội. Mặc dù phải thu hẹp một số mối quan hệ xã hội, vợ chồng anh V vẫn rất vui và tự tin vào khả năng đạt được mục tiêu tài chính đã đề ra.\nTrong kế hoạch thu, chi gia đình của anh V, mức 20% thu nhập dành cho hoạt động giải trí và giao tiếp xã hội được xem là loại chi tiêu nào sau đây?", "o": ["Chi tiêu không thiết yếu.", "Chi tiêu rất quan trọng.", "Mục tiêu tài chính gia đình.", "Chi tiêu thiết yếu."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx · Phần I câu 10 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D24-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 10, 11\nSau khi kết hôn, anh V và chị D đặt mục tiêu mua nhà và ra ở riêng sau 5 năm. Để hiện thực hóa kế hoạch này, họ thống nhất áp dụng “quy tắc 50–30–20” trong quản lý thu–chi gia đình, theo đó: 50% tổng thu nhập dành cho chi tiêu thiết yếu (ăn uống, y tế, giáo dục, sinh hoạt hằng ngày…); 30% dành cho tiết kiệm, dự phòng và mua nhà; 20% còn lại dành cho giải trí và giao tiếp xã hội. Mặc dù phải thu hẹp một số mối quan hệ xã hội, vợ chồng anh V vẫn rất vui và tự tin vào khả năng đạt được mục tiêu tài chính đã đề ra.\nTrong kế hoạch thu, chi của vợ chồng anh V, nội dung nào sau đây thể hiện việc xác định mục tiêu tài chính của gia đình?", "o": ["Tham gia hoạt động xã hội.", "Xây dựng sổ theo dõi thu chi.", "Mua nhà và ra ở riêng sau 5 năm.", "Tham gia hoạt động giải trí."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx · Phần I câu 11 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D24-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong quá trình điều hành công ty X sản xuất thực phẩm chức năng, bà H tự quyết định mọi hoạt động kinh doanh. Tuy nhiên, khi cơ quan chức năng kiểm tra, công ty X đã bị phát hiện vi phạm nghiêm trọng về chất lượng nên bị đình chỉ hoạt động và xử phạt hành chính. Trong trường hợp này, bà H đã vi phạm nghĩa vụ nào trong kinh doanh?", "o": ["Bảo vệ tài nguyên, môi trường.", "Bảo vệ an ninh, quốc phòng.", "Thực hiện pháp luật về thuế.", "Bảo vệ quyền lợi người tiêu dùng."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx · Phần I câu 12 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D24-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những thước đo để đánh giá mức tăng trưởng kinh tế của một quốc gia là dựa vào", "o": ["số các doanh nghiệp được đăng ký.", "chỉ số phát triển con người.", "chỉ số giảm nghèo đa chiều.", "tổng thu nhập quốc dân."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx · Phần I câu 13 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D24-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào sau đây vi phạm quyền và nghĩa vụ của công dân trong học tập?", "o": ["Chủ động cung cấp thông tin học tập.", "Làm sai lệch kết quả học tập.", "Tố cáo hành vi vi phạm trong học tập.", "Đấu tranh bảo vệ quyền lợi người học."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx · Phần I câu 14 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D24-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hệ thống nguyên tắc và quy phạm pháp luật được các quốc gia và các chủ thể khác của pháp luật quốc tế thoả thuận xây dựng, dựa trên cơ sở tự nguyện và bình đẳng, nhằm điều chỉnh các quan hệ giữa các quốc gia và chủ thể đó trong mọi lĩnh vực của quan hệ quốc tế là nội dung của khái niệm nào sau đây?", "o": ["Pháp luật của các quốc gia.", "Pháp luật quốc tế.", "Pháp luật đối ngoại.", "Pháp luật giữa các quốc gia."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx · Phần I câu 15 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D24-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, trong hôn nhân và gia đình, vợ và chồng có quyền và nghĩa vụ ngang nhau trong việc", "o": ["lựa chọn hành vi bạo lực.", "áp đặt mọi quan điểm riêng.", "sở hữu tài sản chung.", "bài trừ quyền tự do tín ngưỡng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx · Phần I câu 16 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D24-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Họat động của các cơ quan nhà nước có thẩm quyền đại diện cho nhà nước thực hiện sự giúp đỡ về mọi mặt cho công dân nước mình đang ở nước ngoài gọi là", "o": ["an ninh công dân.", "bảo hộ công dân.", "giám sát công dân.", "quản lí công dân."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx · Phần I câu 17 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D24-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào sau đây là nghĩa vụ của công dân trong bảo vệ, chăm sóc sức khỏe?", "o": ["Chi trả chi phí khám bệnh.", "Tự chủ chăm sóc sức khoẻ.", "Không bị tra tấn, cực hình.", "Tư vấn khám, chữa bệnh."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx · Phần I câu 18 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D24-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong thực tiễn quan hệ quốc tế, chế độ đãi ngộ tối huệ quốc được áp dụng đối với bộ phận dân cư nào sau đây?", "o": ["Công dân của nước sở tại.", "Công dân người nước ngoài.", "Người không có quốc tịch.", "Người mang hai quốc tịch."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx · Phần I câu 19 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D24-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Sự thoả thuận giữa các bên tham gia nhằm xoá bỏ hầu hết hàng rào thuế quan và phi thuế quan nhưng vẫn duy trì chính sách thuế quan riêng của mỗi bên đối với các nước ngoài hiệp định là thể hiện mức độ hội nhập kinh tế quốc tế nào sau đây?", "o": ["Hiệp định thương mại tự do.", "Thoả thuận thương mại ưu đãi.", "Thị trường chung.", "Liên minh kinh tế."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx · Phần I câu 20 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D24-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quyền của chủ thể tự mình nắm giữ, quản lý, chi phối trực tiếp tài sản của mình là quyền", "o": ["sử dụng tài sản.", "định đoạt tài sản.", "cho mượn tài sản.", "chiếm hữu tài sản."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx · Phần I câu 21 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D24-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hằng năm trường trung học phổ thông B thường tổ chức cho học sinh hoạt động trải nghiệm hướng nghiệp theo kế hoạch giáo dục của nhà trường tại các khu di tích lịch sử - văn hoá là góp phần thực hiện quyền của công dân trong bảo vệ di sản văn hóa ở nội dung nào sau đây?", "o": ["Tham gia phục dựng giá trị di sản.", "Khai thác nguồn lợi kinh tế của di sản.", "Tiếp cận và hưởng thụ giá trị di sản.", "Tôn tạo và bổ sung các di sản mới."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx · Phần I câu 22 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D24-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào sau đây không phải là nguyên tắc cơ bản của pháp luật quốc tế?", "o": ["Hợp tác thiện chí với các quốc gia khác", "Giải quyết tranh chấp bằng sử dụng vũ lực.", "Tận tâm thực hiện các cam kết quốc tế.", "Bình đẳng về chủ quyền các quốc gia."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx · Phần I câu 23 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D24-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật khi tiến hành hoạt động kinh doanh, mọi công dân bắt buộc phải thực hiện nghĩa vụ nào sau đây?", "o": ["Nộp thuế đầy đủ theo quy định.", "Thành lập quỹ bảo trợ xã hội.", "Lắp đặt hệ thống phần mềm quản lí.", "Cổ phần hóa tài sản doanh nghiệp."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx · Phần I câu 24 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D24-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Sau khi được cơ quan chức năng cấp phép, bà Y đã ký hợp đồng thuê căn nhà của ông M đang ở trong thời hạn 5 năm để mở cửa hàng kinh doanh. Trong quá trình chuẩn bị kinh doanh, bà Y đã tự ý đầu tư cải tạo, sửa chữa, cơi nới lại ngôi nhà, đồng thời lắp đặt thêm nhiều thiết bị nhằm phục vụ cho hoạt động kinh doanh mới mà không có thỏa thuận trước với ông M. Do việc cải tạo, lắp đặt này không đúng với các điều khoản trong hợp đồng, ông M đã yêu cầu bà Y bồi thường một khoản tiền do vi phạm hợp đồng, đồng thời buộc bà phải ký bản cam kết sẽ hoàn trả lại mặt bằng đúng hiện trạng ban đầu sau khi hợp đồng hết hạn. Sau khi khai trương, cửa hàng của bà Y ngày càng đông khách. Để đáp ứng nhu cầu phục vụ, bà đã ký hợp đồng lao động với chị N làm nhân viên bán hàng và ông K làm người trông xe cho khách.", "o": ["Việc ông M yêu cầu bà Y bồi thường và cam kết trả lại mặt bằng không phải là hành vi xâm phạm đến quyền sở hữu tài sản của người khác, mà là việc thực hiện quyền hợp pháp của một chủ sở hữu khi tài sản của mình bị sử dụng sai mục đích hoặc trái thỏa thuận.", "Chị N và ông K là người lao động làm việc cho hộ kinh doanh cá thể nên không bắt buộc phải tham gia bảo hiểm xã hội.", "Chỉ bà Y là người trực tiếp thực hiện hoạt động kinh doanh (như mở cửa hàng, thuê người lao động...), nên theo quy định của pháp luật, bà Y mới là người có nghĩa vụ đăng ký kinh doanh. Trong khi đó, ông M chỉ là bên cho thuê tài sản nên không phát sinh nghĩa vụ đăng ký kinh doanh trong trường hợp này.", "Trong trường hợp này, bà Y là bên thuê căn nhà, nên chỉ có quyền chiếm hữu và sử dụng căn nhà theo đúng mục đích, thời hạn và phạm vi đã thỏa thuận trong hợp đồng."], "a": [true, false, true, true], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx · Phần II câu 1 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D24-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Nhờ sự hội nhập quốc tế, nguồn vốn đầu tư trực tiếp nước ngoài (FDI) vào Việt Nam tăng mạnh qua các năm, từ 10 tỉ USD (năm 1995) lên 38 tỉ USD (năm 2019). Năm 2019, Việt Nam xếp thứ 21 về thu hút vốn FDI toàn thế giới, đứng thứ ba ở khu vực, chỉ sau Singapore và Indonesia. Khu vực FDI góp phần không nhỏ trong việc tạo việc làm cho người lao động. Theo Tổng cục Thống kê (2019), kết quả Điều tra Lao động - Việc làm quý I năm 2019, khu vực doanh nghiệp FDI đã và đang tạo công ăn việc làm cho 3,8 triệu người lao động, chiếm trên 7% trong tổng lực lượng lao động (trên 54 triệu lao động), chiếm trên 15% trong tổng lao động làm công ăn lương (25,3 triệu người) ở Việt Nam. Bên cạnh tạo việc làm trực tiếp, khu vực FDI cũng gián tiếp tạo việc làm cho rất nhiều lao động trong các ngành công nghiệp phụ trợ hay các doanh nghiệp khác nằm trong chuỗi cung ứng hàng hoá cho các doanh nghiệp FDI.", "o": ["Tổng thu nhập của các doanh nghiệp FDI nêu trong thông tin trên sẽ được tính vào GDP của Việt Nam, qua đó góp phần thúc đẩy tăng trưởng kinh tế quốc gia.", "Thông tin trên cho thấy hoạt động kinh tế quốc tế của Việt Nam trong quá trình hội nhập kinh tế đã có những bước phát triển nhất định.", "Thành tựu này đóng vai trò quan trọng trong việc hỗ trợ Nhà nước ta thực hiện hiệu quả các chính sách về giải quyết việc làm, nâng cao thu nhập, giảm nghèo, đồng thời thúc đẩy gia tăng số người tham gia bảo hiểm xã hội bắt buộc.", "Tiền lương hằng tháng do doanh nghiệp FDI chi trả cho người lao động theo hợp đồng lao động có thể được xem là một dạng thu nhập thụ động, góp phần vào việc ổn định nguồn tài chính của gia đình họ."], "a": [true, true, true, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx · Phần II câu 2 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D24-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Theo báo cáo của Tổng cục Thống kê, tính đến tháng 12/2023, tổng số khách du lịch nội địa trong năm 2023 ước đạt 108 triệu lượt người, một con số ấn tượng phản ánh sự phục hồi mạnh mẽ của ngành du lịch trong bối cảnh hậu COVID-19. Lượng khách quốc tế đến Việt Nam cũng đạt 12,6 triệu lượt, cho thấy sự hấp dẫn của đất nước trong mắt du khách quốc tế. Doanh thu từ dịch vụ lưu trú và ăn uống ước tính đạt 673,5 nghìn tỷ đồng, trong khi doanh thu từ du lịch lữ hành đạt khoảng 37,8 nghìn tỷ đồng, góp phần quan trọng vào nền kinh tế quốc dân. Bên cạnh sự phát triển của ngành du lịch, chính sách đối ngoại rộng mở đã tạo điều kiện cho gần 160 nghìn lao động Việt Nam làm việc ở hơn 40 quốc gia và vùng lãnh thổ trong năm 2023. Với thu nhập ổn định, họ không chỉ cải thiện đời sống cá nhân mà còn gửi về nước hơn 3 tỷ USD kiều hối mỗi năm, đóng góp vào sự phát triển kinh tế và ổn định tài chính của đất nước.", "o": ["Khoản kiều hối do các lao động của người Việt Nam gửi về trong thông tin trên sẽ được tính vào tổng thu nhập quốc gia, góp phần vào sự phát triển kinh tế bền vững của đất nước.", "Thông tin đã đề cập đến một loại hình dịch vụ thu ngoại tệ thuộc hình thức hoạt động kinh tế đối ngoại, thành tựu của nó đã khẳng định quá trình hội nhập kinh tế của Việt Nam ngày càng phát triển.", "Thông tin đã đề cập đến thành tựu của một trong các nhóm chính sách an sinh xã hội của Nhà nước Việt Nam, góp phần giúp người dân có nền tảng vững chắc để phòng ngừa rủi ro có thể xảy ra trong cuộc sống.", "Theo các quy định quốc tế và pháp luật Việt Nam, du khách nước ngoài khi nhập cảnh hợp pháp sẽ là người cư trú tạm thời và chịu sự quản lý của pháp luật Việt Nam trong thời gian lưu trú."], "a": [true, true, false, true], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx · Phần II câu 3 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "TN-D24-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Tổ chức Thương mại Thế giới (WTO) được thành lập và đi vào hoạt động từ ngày 01/01/1995, với mục tiêu thiết lập và duy trì một nền thương mại toàn cầu tự do, thuận lợi và minh bạch. Khi tham gia WTO, các quốc gia thành viên được hưởng các quy định liên quan đến tự do thương mại hàng hóa, dịch vụ, quyền sở hữu trí tuệ và đầu tư. Sau nhiều năm đàm phán song phương và đa phương với các thành viên cùng tổ chức WTO, đến ngày 11/01/2007, Việt Nam chính thức trở thành thành viên thứ 150, đánh dấu một bước ngoặt trong tiến trình hội nhập kinh tế quốc tế, đồng thời mở ra cả những cơ hội và thách thức đối với các doanh nghiệp Việt Nam.", "o": ["Khi tham gia tổ chức kinh tế này, các quốc gia sẽ cùng nhau xây dựng một thị trường chung, đồng thời phối hợp hoạch định chính sách phát triển kinh tế và thực hiện các mục tiêu chung của toàn liên minh.", "Gia nhập WTO và chủ động thực hiện các cam kết không chỉ giúp Việt Nam thu hút đầu tư quốc tế, mà còn mở rộng thị trường cho các doanh nghiệp trong nước, qua đó thúc đẩy mạnh mẽ tăng trưởng kinh tế và phát triển quốc gia.", "Sau khi gia nhập WTO, Việt Nam phải cụ thể hóa các quy định về thuế và điều kiện kinh doanh đã cam kết vào các văn bản quy phạm pháp luật trong nước. Đây chính là quá trình hiện thực hóa nguyên tắc minh bạch của WTO, với các cam kết mang tính ràng buộc và ổn định, góp phần tạo ra một môi trường kinh doanh minh bạch và công bằng.", "Các doanh nghiệp Việt Nam cần chủ động thích ứng với các quy định thương mại của từng quốc gia trong khuôn khổ WTO nhằm tiếp cận và mở rộng thị trường, thúc đẩy sự phát triển của doanh nghiệp, góp phần nâng cao thu nhập cho người lao động – đó cũng chính là trách nhiệm mang tính nhân văn của doanh nghiệp."], "a": [false, true, true, true], "e": "Đáp án: a) Sai; b) Đúng; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: 15_ĐỀ GV (có đáp án) - MÃ 401 - SỞ NAM ĐỊNH 2024-2025.docx · Phần II câu 4 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}]}];
